-- =============================================================================
-- 403 — LE CATALOGUE DES CONTRÔLES BLANCS : 2de (allemand, anglais, arts-plastiques, emc)
--
-- 294 sujets écrits d'avance et relus : pour chaque fiche, un sujet
-- Facile, un Moyen, un Difficile, chacun avec son barème sur 20 et son corrigé
-- type (`contenu.corrige`, jamais envoyé à l'élève avant sa copie). L'IA ne fait
-- plus que les corriger ; elle ne rédige que « Un autre sujet ».
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main. Source : contenu/controles/.
--    Regénérer : node node_modules/jiti/lib/jiti-cli.mjs scripts/controles-sql.ts --num 403 --niveau 2de --matieres allemand,anglais,arts-plastiques,emc
--
--   allemand.jumelles           108 sujets · 36 fiches
--   allemand.m1                  36 sujets · 12 fiches
--   anglais.11r                  36 sujets · 12 fiches
--   anglais.jumelles             36 sujets · 12 fiches
--   anglais.m1                   39 sujets · 13 fiches
--   arts-plastiques.15r           9 sujets · 3 fiches
--   emc.15r                      27 sujets · 9 fiches
--   emc.jumelles                  3 sujets · 1 fiches
--
-- L'identifiant d'un sujet est dérivé de (fiche, niveau) : rejouer la migration
-- met le sujet à jour au lieu de le dupliquer. Une fiche absente est sautée.
--
-- PRÉREQUIS : 360 puis 364. Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

INSERT INTO public.chapter_exercices
  (id, chapter_id, style, contenu, difficulte, origine, created_by)
SELECT
  md5('exercice-catalogue:' || v.chapter_id::text || ':' || v.difficulte::text)::uuid,
  v.chapter_id,
  v.style,
  v.contenu,
  v.difficulte,
  'catalogue',
  NULL
FROM (VALUES
  ('5b6e33d3-fa43-50b9-b4d2-16f08e6808cf'::uuid, 1, 'traduction', $exo${"titre":"Conjuguer au présent","consigne":"Conjugue chaque verbe au présent, à la personne demandée, puis réponds à la question.","enonce":"**1. Conjugue** au présent :\n\na) *spielen* (du)\nb) *arbeiten* (er)\nc) *heißen* (du)\nd) *fahren* (er)\ne) *lesen* (du)\nf) *geben* (sie, elle)\ng) *sammeln* (ich)\nh) *finden* (ihr)\n\n**2.** Le changement de voyelle d’un verbe fort (*fahren → fährt*) touche-t-il aussi *wir* et *sie* (ils) ? Donne un exemple.","bareme":[{"critere":"Terminaisons régulières justes : spielst","points":2},{"critere":"Aménagements justes : arbeitet, heißt, sammle, findet","points":8},{"critere":"Verbes forts justes : fährt, liest, gibt","points":6},{"critere":"Réponse : changement aux 2e et 3e personnes du singulier seulement, avec exemple","points":4}],"dureeMin":7,"corrige":"**1.**\na) *du spielst*\nb) *er arbeitet* (radical en -t : on intercale un e)\nc) *du heißt* (radical en -ß : le -st perd son s)\nd) *er fährt* (verbe fort a → ä)\ne) *du liest* (e → ie ; radical en -s : -st perd son s)\nf) *sie gibt* (e → i)\ng) *ich sammle* (radical en -el : le e tombe à la 1re personne)\nh) *ihr findet* (radical en -d : on intercale un e)\n\n**2.** Non : le changement de voyelle ne touche que les **2e et 3e personnes du singulier**. Exemple : *du fährst, er fährt*, mais *wir fahren, sie fahren*."}$exo$::jsonb),
  ('5b6e33d3-fa43-50b9-b4d2-16f08e6808cf'::uuid, 2, 'traduction', $exo${"titre":"Lena se présente","consigne":"Complète la présentation de Lena au présent, puis traduis les deux phrases.","enonce":"**Situation.** Lena écrit à sa correspondante française.\n\n> Ich (1. heißen) Lena. Ich (2. lernen) seit drei Jahren Französisch. Mein Bruder Paul (3. lesen) jeden Abend und er (4. sprechen) gut Englisch. Meine Schwester (5. arbeiten) in Köln. Morgen (6. fahren) wir nach Berlin. Und du? (7. Schlafen) du am Wochenende lange?\n\n1. Écris les **sept verbes** conjugués.\n2. **Traduis** en allemand :\na) J’apprends l’allemand depuis deux ans.\nb) Demain, je vais à Munich (en train).\n3. Pourquoi n’utilise-t-on pas le futur dans la phrase b) ?","bareme":[{"critere":"Les sept formes justes : heiße, lerne, liest, spricht, arbeitet, fahren, Schläfst","points":10},{"critere":"Traduction a) au présent avec seit : Ich lerne seit zwei Jahren Deutsch","points":4},{"critere":"Traduction b) au présent, verbe en 2e position : Morgen fahre ich nach München","points":3},{"critere":"Explication : l’adverbe de temps suffit à dire l’avenir","points":3}],"dureeMin":10,"corrige":"**1.**\n1) *heiße*\n2) *lerne* (présent avec *seit*)\n3) *liest* (e → ie)\n4) *spricht* (e → i)\n5) *arbeitet* (e intercalé)\n6) *fahren* (pluriel : pas de changement de voyelle)\n7) *Schläfst* (a → ä)\n\n**2.**\na) *Ich lerne seit zwei Jahren Deutsch.* — avec *seit*, l’allemand emploie le **présent**, comme le français ; le parfait serait une faute.\nb) *Morgen fahre ich nach München.* — le verbe reste en **2e position**, le sujet passe derrière.\n\n**3.** Avec un adverbe de temps (*morgen*), le **présent suffit** à exprimer l’avenir et c’est la tournure la plus naturelle ; le futur en *werden* ne sert que sans repère temporel ou pour insister."}$exo$::jsonb),
  ('5b6e33d3-fa43-50b9-b4d2-16f08e6808cf'::uuid, 3, 'traduction', $exo${"titre":"Le courriel plein de fautes","consigne":"Corrige chaque faute en expliquant la règle, puis rédige un court message en allemand.","enonce":"**Document.** Courriel de Hugo, élève de 3e, à son correspondant.\n\n> Hallo Jonas! Ich habe seit zwei Jahren Deutsch gelernt. Mein Vater fahrt jeden Tag nach Paris. Du arbeitst viel, oder? Du heißst Jonas Müller, richtig? Meine Freunde und ich fähren oft ans Meer. Morgen ich spiele Fußball.\n\n1. Hugo a fait **six fautes**, une par phrase après *Hallo Jonas!*. Recopie chaque phrase **corrigée**.\n2. Pour chaque faute, **nomme la règle** en quelques mots.\n3. **Production** (5 lignes environ) : présente-toi à Jonas. Utilise au moins un verbe fort à la 2e ou 3e personne, une phrase avec *seit* et une phrase qui parle de demain au présent.","bareme":[{"critere":"Les six phrases corrigées : lerne seit, fährt, arbeitest, heißt, fahren, Morgen spiele ich","points":6},{"critere":"Règles nommées : seit + présent, verbe fort, e intercalé, s supprimé, pluriel sans inflexion, verbe en 2e position","points":6},{"critere":"Production : terminaisons et verbes forts justes","points":4},{"critere":"Production : seit + présent et avenir au présent avec adverbe, verbe en 2e position","points":4}],"dureeMin":17,"corrige":"**1 et 2.**\n- *Ich **lerne** seit zwei Jahren Deutsch.* — avec *seit*, on emploie le **présent**, pas le parfait.\n- *Mein Vater **fährt** jeden Tag nach Paris.* — *fahren* est un verbe fort : a → ä aux 2e et 3e personnes du singulier.\n- *Du **arbeitest** viel, oder?* — radical en -t : on intercale un **e**.\n- *Du **heißt** Jonas Müller, richtig?* — radical en -ß : le -st perd son **s**.\n- *Meine Freunde und ich **fahren** oft ans Meer.* — sujet *wir* : le changement de voyelle ne touche **pas** le pluriel.\n- ***Morgen spiele ich** Fußball.* — le verbe conjugué est en **2e position** ; l’adverbe de temps suffit à dire l’avenir.\n\n**3.** Exemple : *Hallo Jonas! Ich heiße Hugo und ich lerne seit vier Jahren Deutsch. Mein Bruder liest viel und er spricht Spanisch. Meine Mutter fährt jeden Tag zur Arbeit. Morgen spiele ich Tennis.* Le correcteur vérifie les terminaisons, un verbe fort bien conjugué, *seit* + présent et un avenir au présent avec le verbe en 2e position."}$exo$::jsonb),
  ('9ac65504-f599-5b22-b227-603400d2217b'::uuid, 1, 'traduction', $exo${"titre":"Les formes du prétérit","consigne":"Donne la forme du prétérit, puis indique la famille de chaque verbe.","enonce":"**1. Mets au prétérit** :\n\na) *spielen* (ich)\nb) *gehen* (er)\nc) *kommen* (sie, elle)\nd) *sein* (ich)\ne) *haben* (er)\nf) *können* (wir)\ng) *bringen* (er)\nh) *nehmen* (ich)\n\n**2.** Pour *spielen*, *gehen* et *bringen*, indique la **famille** (faible, fort, mixte) et explique comment se forme leur prétérit.","bareme":[{"critere":"Les huit formes justes : spielte, ging, kam, war, hatte, konnten, brachte, nahm","points":12},{"critere":"Familles justes : spielen faible, gehen fort, bringen mixte","points":4},{"critere":"Formation expliquée : -te ; voyelle changée sans terminaison ; radical modifié + -te","points":4}],"dureeMin":7,"corrige":"**1.**\na) *ich spielte*\nb) *er ging*\nc) *sie kam*\nd) *ich war*\ne) *er hatte*\nf) *wir konnten* (modal : pas d’inflexion au prétérit)\ng) *er brachte*\nh) *ich nahm*\n\nAux 1re et 3e personnes du singulier, les formes sont identiques (*ich ging / er ging*).\n\n**2.**\n- *spielen* : verbe **faible** → radical + **-te** + terminaisons (*spielte*).\n- *gehen* : verbe **fort** → voyelle changée, **aucune terminaison** aux 1re et 3e personnes (*ging*).\n- *bringen* : verbe **mixte** → radical modifié + terminaisons faibles (*brachte*)."}$exo$::jsonb),
  ('9ac65504-f599-5b22-b227-603400d2217b'::uuid, 2, 'traduction', $exo${"titre":"Le samedi de Max","consigne":"Réécris le récit au prétérit, complète la phrase au plus-que-parfait, puis explique ton choix.","enonce":"**Situation.** Pour le journal du collège, tu dois raconter le samedi de Max. Voici tes notes, au présent :\n\n> Am Samstag geht Max in die Stadt. Er sieht seinen Freund Tim. Sie trinken einen Kaffee und sprechen lange. Dann kauft Max ein Buch. Am Abend schreibt er seiner Oma. Er ist sehr zufrieden.\n\n1. **Réécris** le récit au **prétérit**.\n2. Complète au plus-que-parfait : *Nachdem Max das Buch gekauft (…), ging er nach Hause.*\n3. Pourquoi faut-il employer le prétérit, et non le parfait, dans un article de journal ?","bareme":[{"critere":"Formes fortes justes : ging, sah, tranken, sprachen, schrieb, war","points":9},{"critere":"Forme faible juste : kaufte ; terminaisons du pluriel justes","points":3},{"critere":"Plus-que-parfait juste : hatte","points":3},{"critere":"Explication : prétérit = temps du récit écrit ; parfait = oral et lettre","points":5}],"dureeMin":11,"corrige":"**1.** *Am Samstag **ging** Max in die Stadt. Er **sah** seinen Freund Tim. Sie **tranken** einen Kaffee und **sprachen** lange. Dann **kaufte** Max ein Buch. Am Abend **schrieb** er seiner Oma. Er **war** sehr zufrieden.*\n\n- *gehen → ging*, *sehen → sah*, *trinken → trank* (pluriel *tranken*), *sprechen → sprach* (*sprachen*), *schreiben → schrieb* : verbes forts.\n- *kaufen → kaufte* : verbe faible.\n- *sein → war*.\n\n**2.** *Nachdem Max das Buch gekauft **hatte**, ging er nach Hause.* — prétérit de *haben* + participe II : l’achat est **antérieur** au retour.\n\n**3.** Un article de journal est un **texte narratif écrit** : on y raconte au **prétérit**. Le parfait est le passé de l’oral et de la lettre ; mélanger les deux dans un même récit fait désordre."}$exo$::jsonb),
  ('9ac65504-f599-5b22-b227-603400d2217b'::uuid, 3, 'traduction', $exo${"titre":"Une journée d’hiver","consigne":"Conjugue le récit, traduis, puis justifie les choix de temps avec les règles du cours.","enonce":"**Document.** Début d’une nouvelle, verbes à l’infinitif.\n\n> Es (1. sein) kalt. Anna (2. bleiben) zu Hause und (3. schreiben) einen Brief. Nachdem sie den Brief geschrieben (4. haben), (5. gehen) sie zur Post. Dort (6. finden) sie ihren Freund Paul. Er (7. wollen) einen Kaffee trinken. Sie (8. trinken) zusammen einen Kaffee und (9. denken) an die Ferien.\n\n1. Conjugue les **neuf verbes** : prétérit partout, plus-que-parfait pour (4).\n2. **Traduis** en allemand, pour la suite de la nouvelle : *Il faisait nuit et Anna était fatiguée. Elle ne pouvait pas dormir.*\n3. Pourquoi l’imparfait français devient-il ici un prétérit ? Aurait-on dit la même chose dans un dialogue ?\n4. À l’oral, Anna dit *Ich bin müde gewesen*. Est-ce faux ? Que dirait-on plutôt ?","bareme":[{"critere":"Formes justes : war, blieb, schrieb, ging, fand, wollte, tranken, dachten","points":6},{"critere":"Plus-que-parfait juste (hatte) et antériorité expliquée","points":3},{"critere":"Traduction juste : Es war dunkel (Nacht) und Anna war müde. Sie konnte nicht schlafen","points":5},{"critere":"Règle de registre : prétérit dans un récit écrit, parfait dans un dialogue","points":4},{"critere":"Ich war müde, ce que tout le monde dit (sein survit au prétérit à l’oral)","points":2}],"dureeMin":17,"corrige":"**1.** *Es **war** kalt. Anna **blieb** zu Hause und **schrieb** einen Brief. Nachdem sie den Brief geschrieben **hatte**, **ging** sie zur Post. Dort **fand** sie ihren Freund Paul. Er **wollte** einen Kaffee trinken. Sie **tranken** zusammen einen Kaffee und **dachten** an die Ferien.*\n\n(*denken → dachte* est un verbe mixte ; *wollen → wollte* un modal ; le plus-que-parfait *hatte geschrieben* marque ce qui s’est passé **avant** le départ pour la poste.)\n\n**2.** *Es war Nacht (Es war dunkel) und Anna war müde. Sie konnte nicht schlafen.* — *sein → war*, *können → konnte*.\n\n**3.** L’allemand oppose parfait et prétérit par le **registre**, pas par l’aspect : dans un **récit écrit**, tout passé se dit au prétérit, y compris ce que le français met à l’imparfait. Dans un **dialogue**, on aurait employé le **parfait** (sauf pour *sein, haben, werden* et les modaux).\n\n**4.** Ce n’est pas faux, mais tout le monde dit ***Ich war müde*** : *sein*, *haben*, *werden* et les modaux restent au prétérit même à l’oral."}$exo$::jsonb),
  ('0a6938bf-8709-5ce1-a842-8502ea1b406b'::uuid, 1, 'traduction', $exo${"titre":"Participes et auxiliaires","consigne":"Forme le participe II de chaque verbe, puis choisis l’auxiliaire.","enonce":"**1. Donne le participe II** :\n\na) *spielen* · b) *machen* · c) *sehen* · d) *fahren* · e) *studieren* · f) *besuchen* · g) *einkaufen* · h) *aufstehen*\n\n**2. Choisis l’auxiliaire** (*haben* ou *sein*) et complète :\n\na) Ich … nach Hause gegangen.\nb) Wir … Pizza gegessen.\nc) Er … sofort eingeschlafen.\nd) Sie … zu Hause geblieben.\ne) Ihr … Fußball gespielt.\nf) Was … passiert?","bareme":[{"critere":"Participes justes : gespielt, gemacht, gesehen, gefahren, studiert, besucht, eingekauft, aufgestanden","points":10},{"critere":"Auxiliaires justes : bin, haben, ist, ist, habt, ist","points":10}],"dureeMin":8,"corrige":"**1.**\na) *gespielt* · b) *gemacht* (faibles : ge- + radical + -t)\nc) *gesehen* · d) *gefahren* (forts : ge- + radical + -en)\ne) *studiert* (en -ieren : pas de ge-)\nf) *besucht* (préverbe inséparable : pas de ge-)\ng) *eingekauft* · h) *aufgestanden* (préverbe séparable : le ge- s’intercale)\n\n**2.**\na) Ich **bin** nach Hause gegangen. (déplacement)\nb) Wir **haben** Pizza gegessen.\nc) Er **ist** sofort eingeschlafen. (changement d’état)\nd) Sie **ist** (ou **sind**) zu Hause geblieben. (*bleiben* prend sein)\ne) Ihr **habt** Fußball gespielt.\nf) Was **ist** passiert? (*passieren* prend sein)"}$exo$::jsonb),
  ('0a6938bf-8709-5ce1-a842-8502ea1b406b'::uuid, 2, 'traduction', $exo${"titre":"Le week-end de Jonas","consigne":"Mets le message de Jonas au parfait, en respectant l’ordre des mots, puis complète la subordonnée.","enonce":"**Situation.** Jonas raconte son week-end à son ami Ben, dans un message. Ses notes sont au présent :\n\n> Am Samstag stehe ich um 9 Uhr auf. Dann fahre ich mit dem Zug nach Hamburg. Dort besuche ich meine Oma. Wir essen Kuchen und spielen Karten. Am Abend bleibe ich bei ihr.\n\n1. **Réécris** le message au **parfait**.\n2. Complète au parfait : *Ich bin müde, weil ich viel (lernen).*\n3. Pourquoi Jonas raconte-t-il au parfait et pas au prétérit ?","bareme":[{"critere":"Auxiliaires justes : bin aufgestanden, bin gefahren, bin geblieben ; habe besucht, haben gegessen/gespielt","points":8},{"critere":"Participes justes (aufgestanden, gefahren, besucht, gegessen, gespielt, geblieben)","points":5},{"critere":"Participe en fin de phrase, auxiliaire en 2e position ; subordonnée : gelernt habe","points":4},{"critere":"Explication : le parfait est le passé de la conversation et du message","points":3}],"dureeMin":11,"corrige":"**1.** *Am Samstag **bin** ich um 9 Uhr **aufgestanden**. Dann **bin** ich mit dem Zug nach Hamburg **gefahren**. Dort **habe** ich meine Oma **besucht**. Wir **haben** Kuchen **gegessen** und Karten **gespielt**. Am Abend **bin** ich bei ihr **geblieben**.*\n\n- *aufstehen* (changement d’état), *fahren* (déplacement), *bleiben* → **sein**.\n- *besuchen* : inséparable, pas de ge- ; *aufstehen* : séparable, ge- intercalé.\n- Auxiliaire en **2e position**, participe **à la fin**.\n\n**2.** *Ich bin müde, weil ich viel **gelernt habe**.* — en subordonnée, l’auxiliaire va **à la toute fin**, après le participe.\n\n**3.** Un message à un ami, c’est de la **conversation** écrite : on raconte au **parfait**. Le prétérit est le temps du récit écrit (roman, presse)."}$exo$::jsonb),
  ('0a6938bf-8709-5ce1-a842-8502ea1b406b'::uuid, 3, 'traduction', $exo${"titre":"La copie à corriger","consigne":"Repère les phrases fausses et corrige-les en citant la règle, puis traduis et explique.","enonce":"**Document.** Sept phrases tirées de la copie de Léo.\n\n> a) Ich habe nach Berlin gefahren.\n> b) Er hat mit seiner Oma getelefoniert.\n> c) Wir haben im Supermarkt geeinkauft.\n> d) Ich habe das Auto in die Garage gefahren.\n> e) Ich bin müde, weil ich habe den ganzen Tag gearbeitet.\n> f) Was ist gestern passiert?\n> g) Sie hat früh eingeschlafen.\n\n1. **Deux** phrases sont justes : lesquelles ? Justifie.\n2. **Corrige** les cinq autres en citant la règle.\n3. **Traduis**, pour un message à un ami : *Hier, je suis resté à la maison et j’ai lu un livre. Ma sœur s’est endormie tôt.*\n4. *Il pleuvait* se traduit-il de la même façon dans un dialogue et dans un roman ? Explique.","bareme":[{"critere":"Phrases justes identifiées (d et f) et justifiées : emploi transitif ; passieren prend sein","points":4},{"critere":"Corrections : bin gefahren, telefoniert, eingekauft, gearbeitet habe, ist eingeschlafen","points":6},{"critere":"Traduction juste : bin geblieben, habe gelesen, ist eingeschlafen, participes en fin","points":6},{"critere":"Registre expliqué : parfait dans un dialogue, prétérit dans un roman","points":4}],"dureeMin":17,"corrige":"**1.** **d)** est juste : *fahren* est employé **transitivement** (il a un complément, *das Auto*), il prend donc **haben**. **f)** est juste : *passieren* fait partie des six verbes à part qui prennent **sein**.\n\n**2.**\na) *Ich **bin** nach Berlin gefahren.* — déplacement d’un point à un autre : **sein**.\nb) *Er hat mit seiner Oma **telefoniert**.* — verbe en -ieren : **pas de ge-**.\nc) *Wir haben im Supermarkt **eingekauft**.* — préverbe séparable : le ge- **s’intercale**.\ne) *…, weil ich den ganzen Tag **gearbeitet habe**.* — en subordonnée, l’auxiliaire va **à la toute fin**.\ng) *Sie **ist** früh eingeschlafen.* — changement d’état : **sein**.\n\n**3.** *Gestern bin ich zu Hause geblieben und habe ein Buch gelesen. Meine Schwester ist früh eingeschlafen.* — *bleiben* et *einschlafen* prennent sein ; *lesen* (fort) donne *gelesen*.\n\n**4.** Non. L’allemand distingue parfait et prétérit par le **registre** : dans un **dialogue**, *Es hat geregnet* (parfait) ; dans un **roman**, *Es regnete* (prétérit). Le français, lui, oppose imparfait et passé composé par l’**aspect**."}$exo$::jsonb),
  ('2359e022-15b6-50e4-9ed4-6d25d2e43450'::uuid, 1, 'traduction', $exo${"titre":"Werden au futur","consigne":"Mets les phrases au Futur I, puis indique ce qu’exprime werden dans chaque phrase de la partie 2.","enonce":"**1. Mets au Futur I** :\n\na) Ich helfe dir.\nb) Du kommst nicht.\nc) Er schreibt einen Brief.\nd) Wir spielen Fußball.\ne) Ihr lernt viel.\nf) Sie (ils) fahren nach Wien.\n\n**2.** Que signifie *werden* dans chaque phrase : « devenir », futur ou passif ?\n\na) *Er wird Arzt.*\nb) *Das Haus wird gebaut.*\nc) *Er wird kommen.*","bareme":[{"critere":"Formes de werden justes : werde, wirst, wird, werden, werdet, werden","points":6},{"critere":"Infinitif placé en fin de phrase dans les six phrases","points":6},{"critere":"Les trois valeurs identifiées d’après ce qui suit werden","points":8}],"dureeMin":7,"corrige":"**1.**\na) *Ich **werde** dir **helfen**.*\nb) *Du **wirst** nicht **kommen**.*\nc) *Er **wird** einen Brief **schreiben**.*\nd) *Wir **werden** Fußball **spielen**.*\ne) *Ihr **werdet** viel **lernen**.*\nf) *Sie **werden** nach Wien **fahren**.*\n\n*werden* conjugué en 2e position, **infinitif à la fin**.\n\n**2.** C’est ce qui **suit** *werden* qui tranche :\na) un **nom** → « **devenir** » : il devient médecin.\nb) un **participe II** → **passif** : la maison est construite.\nc) un **infinitif** → **futur** : il viendra."}$exo$::jsonb),
  ('2359e022-15b6-50e4-9ed4-6d25d2e43450'::uuid, 2, 'traduction', $exo${"titre":"Les projets d’Emma","consigne":"Choisis entre présent et futur, justifie, puis traite la subordonnée et la supposition.","enonce":"**Situation.** Emma écrit à son amie Clara.\n\n> a) Morgen (fahren) ich nach Hamburg.\n> b) Keine Sorge, ich (helfen) dir! (une promesse, sans repère de temps)\n> c) Die Prüfung (sein) nicht einfach. (une prédiction)\n> d) Nächste Woche (schreiben) ich die Mathearbeit.\n\n1. Pour chaque phrase, choisis **présent** ou **Futur I**, conjugue et justifie.\n2. Complète au futur : *Ich hoffe, dass Tim (kommen).*\n3. Clara répond : *« Tim antwortet nicht. Er wird wohl krank sein. »* Traduis la seconde phrase et explique le piège.","bareme":[{"critere":"a) fahre et d) schreibe au présent, justifiés par l’adverbe de temps","points":5},{"critere":"b) werde helfen et c) wird sein au futur, justifiés (promesse, prédiction)","points":5},{"critere":"Subordonnée juste : dass Tim kommen wird (werden à la fin)","points":4},{"critere":"Supposition traduite : Il doit être malade ; ce n’est pas un futur","points":6}],"dureeMin":11,"corrige":"**1.**\na) *Morgen **fahre** ich nach Hamburg.* — **présent** : l’adverbe *morgen* suffit à dire l’avenir.\nb) *Ich **werde** dir **helfen**!* — **futur** : une promesse, sans repère de temps.\nc) *Die Prüfung **wird** nicht einfach **sein**.* — **futur** : une prédiction.\nd) *Nächste Woche **schreibe** ich die Mathearbeit.* — **présent** : *nächste Woche* précise l’avenir.\n(Le futur en a et d n’est pas faux, seulement plus lourd.)\n\n**2.** *Ich hoffe, dass Tim kommen **wird**.* — en subordonnée, les deux morceaux se rejoignent à la fin et c’est *werden* qui ferme.\n\n**3.** *« Il **doit** être malade. »* Ce futur renforcé par *wohl* exprime une **hypothèse sur le présent**, pas l’avenir ; traduire « il sera malade » est un contresens."}$exo$::jsonb),
  ('2359e022-15b6-50e4-9ed4-6d25d2e43450'::uuid, 3, 'traduction', $exo${"titre":"Les mille visages de werden","consigne":"Analyse et traduis chaque phrase, transforme la subordonnée, puis rédige tes projets.","enonce":"**1. Analyse et traduis** : pour chaque phrase, dis ce qu’exprime *werden* (devenir, futur, passif, supposition, insistance), puis traduis.\n\na) *Sie wird Lehrerin.*\nb) *Die Stadt wird renoviert.*\nc) *Er wird wohl zu Hause sein.*\nd) *Er wird es vergessen haben.*\ne) *Du wirst jetzt aufräumen!*\nf) *Das wird nicht einfach sein.*\n\n**2. Transforme** en subordonnée introduite par *dass* : *Ich glaube: Er wird morgen kommen.*\n\n**3. Production** (5 lignes environ) : écris tes projets pour les prochaines vacances. Emploie au moins **deux** fois le présent avec un adverbe de temps, et **deux** fois le Futur I (une promesse, une prédiction).","bareme":[{"critere":"Valeurs identifiées d’après ce qui suit werden (devenir, passif, supposition, Futur II, insistance, prédiction)","points":6},{"critere":"Traductions justes, sans contresens sur c) et d)","points":5},{"critere":"Subordonnée juste : dass er morgen kommen wird","points":3},{"critere":"Production : présent avec adverbe et Futur I bien formé (werden + infinitif final)","points":6}],"dureeMin":17,"corrige":"**1.**\na) Nom après *werden* → **devenir** : *Elle devient professeure.*\nb) Participe II → **passif** : *La ville est rénovée.*\nc) Futur + *wohl* → **supposition** sur le présent : *Il doit être à la maison.*\nd) Futur II → **supposition** sur le passé : *Il a dû l’oublier.*\ne) Futur → **insistance**, presque une menace : *Tu vas ranger, maintenant !*\nf) Futur → **prédiction** : *Ça ne sera pas facile.*\n\n**2.** *Ich glaube, dass er morgen kommen **wird**.* — *werden* conjugué ferme la subordonnée, après l’infinitif.\n\n**3.** Exemple : *Nächsten Sommer fahre ich nach Österreich. Am ersten Tag besuche ich Wien. Ich werde dir jeden Tag schreiben, versprochen! Das wird bestimmt toll sein.* Le correcteur vérifie le présent avec *nächsten Sommer, morgen…*, le verbe en 2e position, et deux Futur I justes (*werde… schreiben*, *wird… sein*), infinitif en fin de phrase."}$exo$::jsonb),
  ('4dd6a4d6-28fe-5659-ab7f-ab81505be639'::uuid, 1, 'traduction', $exo${"titre":"Donner un ordre à chacun","consigne":"Forme l’impératif demandé, sans oublier le pronom quand il le faut.","enonce":"**1. Forme l’impératif** de *kommen* pour **du**, **ihr** et **Sie**.\n\n**2. Forme l’impératif** pour **du** :\n\na) *geben* (mir das Buch)\nb) *fahren* (langsam)\nc) *arbeiten* (mehr)\nd) *lesen* (den Text)\ne) *nehmen* (den Bus)\n\n**3.** Donne l’impératif de *sein* (*ruhig sein*) pour **du**, **ihr** et **Sie**.","bareme":[{"critere":"kommen juste : Komm! Kommt! Kommen Sie!","points":5},{"critere":"Formes du juste : Gib! Fahr! Arbeite! Lies! Nimm!","points":10},{"critere":"sein juste : Sei ruhig! Seid ruhig! Seien Sie ruhig!","points":5}],"dureeMin":7,"corrige":"**1.** *Komm!* (du : radical, sans terminaison ni pronom) · *Kommt!* (ihr : forme du présent, sans pronom) · *Kommen Sie!* (Sie : infinitif + pronom).\n\n**2.**\na) *Gib mir das Buch!* — l’alternance e → i se **garde**.\nb) *Fahr langsam!* — l’alternance a → ä se **perd** (pas « Fähr »).\nc) *Arbeite mehr!* — le -e final est **obligatoire** après -t.\nd) *Lies den Text!* — e → ie gardé.\ne) *Nimm den Bus!* — e → i gardé.\n\n**3.** *Sei ruhig!* · *Seid ruhig!* · *Seien Sie ruhig!* — *sein* est à part."}$exo$::jsonb),
  ('4dd6a4d6-28fe-5659-ab7f-ab81505be639'::uuid, 2, 'traduction', $exo${"titre":"Le départ en classe verte","consigne":"Transforme chaque consigne en impératif, à la personne indiquée, en ajoutant bitte quand c’est demandé.","enonce":"**Situation.** Le jour du départ en classe verte, Frau Keller, la professeure, et les élèves se donnent des consignes.\n\n1. À ton camarade Paul (**du**) :\na) *aufstehen* (+ bitte)\nb) *mich heute Abend anrufen*\nc) *langsam fahren* (à vélo)\n\n2. À toute la classe (**ihr**) :\nd) *leise sein*\ne) *die Koffer nehmen*\n\n3. À Frau Keller (**Sie**) :\nf) *die Tür zumachen* (+ bitte)\n\n4. À tout le groupe, toi compris (**wir**) :\ng) *gehen*\n\n5. Où se place le préverbe séparable à l’impératif ? Appuie-toi sur a), b) et f).","bareme":[{"critere":"Formes du justes : Steh bitte auf! Ruf mich heute Abend an! Fahr langsam!","points":6},{"critere":"Formes ihr justes : Seid leise! Nehmt die Koffer!","points":4},{"critere":"Formes Sie et wir justes : Machen Sie bitte die Tür zu! Gehen wir!","points":4},{"critere":"Règle : verbe en 1re position, préverbe séparable rejeté à la fin","points":6}],"dureeMin":11,"corrige":"**1.**\na) *Steh bitte auf!*\nb) *Ruf mich heute Abend an!*\nc) *Fahr langsam!* (a → ä se perd)\n\n**2.**\nd) *Seid leise!* (*sein* est à part)\ne) *Nehmt die Koffer!* (forme du présent, sans pronom)\n\n**3.**\nf) *Machen Sie bitte die Tür zu!* (infinitif + *Sie*)\n\n**4.**\ng) *Gehen wir!* (« allons-y »)\n\n**5.** Le verbe **ouvre** la phrase, en première position, et le préverbe séparable (*auf*, *an*, *zu*) part **à la fin** de la phrase. *bitte* se place juste après le verbe (ou le pronom *Sie*)."}$exo$::jsonb),
  ('4dd6a4d6-28fe-5659-ab7f-ab81505be639'::uuid, 3, 'traduction', $exo${"titre":"Ordres secs, ordres polis","consigne":"Adoucis, corrige et analyse les ordres, en justifiant avec les règles du cours.","enonce":"**Document 1.** Mot laissé par Anna à son frère Tom :\n\n> Mach das Fenster zu! Räum dein Zimmer auf! Gib mir mein Buch!\n\n**Document 2.** Cinq ordres écrits par un élève :\n\n> a) Fähr langsam! · b) Gebe mir das! · c) Arbeit! · d) Kommst du! · e) Sei ruhig, Herr Braun!\n\n1. Tom trouve le mot d’Anna **hostile**. Explique pourquoi, puis **réécris-le** avec *bitte*, *mal* ou *doch* (une particule différente par phrase).\n2. **Corrige** les cinq ordres du document 2 en expliquant chaque faute.\n3. Anna veut demander à sa voisine, Frau Schulz, de l’aider, le plus poliment possible. Écris la phrase.\n4. Quel est le registre de *Nicht rauchen!* et de *Du wirst jetzt lernen!* ?","bareme":[{"critere":"Explication : sans particules un impératif paraît sec ; trois phrases adoucies justes","points":5},{"critere":"Corrections : Fahr! Gib mir das! Arbeite! Komm! Seien Sie ruhig, Herr Braun!","points":7},{"critere":"Demande très polie juste : Könnten Sie mir helfen?","points":4},{"critere":"Registres : infinitif = panneaux, consignes ; futur = menaçant","points":4}],"dureeMin":16,"corrige":"**1.** Sans les petits mots *bitte, mal, doch*, un impératif allemand paraît **sec**, parfois hostile. Réécriture possible : *Mach bitte das Fenster zu! Räum doch dein Zimmer auf! Gib mir mal mein Buch!* — *bitte* ajoute la politesse, *doch* l’insistance amicale, *mal* la légèreté.\n\n**2.**\na) ***Fahr** langsam!* — l’alternance a → ä se **perd** à l’impératif.\nb) ***Gib** mir das!* — l’alternance e → i se **garde**.\nc) ***Arbeite**!* — -e final **obligatoire** après -t.\nd) ***Komm**!* — pour *du* : radical sans terminaison, **sans pronom**.\ne) ***Seien Sie** ruhig, Herr Braun!* — on vouvoie un adulte : forme *Sie*, avec le pronom ; *sein* est à part.\n\n**3.** *Könnten Sie mir bitte helfen, Frau Schulz?* — la question au **subjonctif II** est le registre **très poli**.\n\n**4.** *Nicht rauchen!* : l’infinitif seul, registre des **panneaux et consignes**. *Du wirst jetzt lernen!* : le futur, registre **menaçant**."}$exo$::jsonb),
  ('032feacc-974b-505b-a485-923ed367cc33'::uuid, 1, 'traduction', $exo${"titre":"Wäre, hätte, würde","consigne":"Donne la forme de subjonctif II, puis mets les phrases au subjonctif II.","enonce":"**1. Donne le subjonctif II** (1re personne du singulier) de :\n\na) *sein* · b) *haben* · c) *können* · d) *müssen* · e) *wissen* · f) *mögen* · g) *werden*\n\n**2. Mets au subjonctif II** avec *würde* + infinitif :\n\na) Ich fahre gern nach Berlin.\nb) Wir spielen gern Tennis.\n\n**3.** À partir de quel temps se forment les formes simples ? Donne un exemple.","bareme":[{"critere":"Les sept formes justes : wäre, hätte, könnte, müsste, wüsste, möchte, würde","points":10},{"critere":"würde + infinitif final juste dans les deux phrases","points":6},{"critere":"Formation expliquée : prétérit + inflexion + -e, avec exemple","points":4}],"dureeMin":7,"corrige":"**1.**\na) *wäre* · b) *hätte* · c) *könnte* · d) *müsste* · e) *wüsste* · f) *möchte* · g) *würde*\n\n**2.**\na) *Ich **würde** gern nach Berlin **fahren**.*\nb) *Wir **würden** gern Tennis **spielen**.*\n*würde* est la construction **par défaut** pour la plupart des verbes ; l’infinitif va à la fin.\n\n**3.** Les formes simples se forment sur le **prétérit**, avec **inflexion** et un *-e* : *war → wäre*, *hatte → hätte*, *konnte → könnte*."}$exo$::jsonb),
  ('032feacc-974b-505b-a485-923ed367cc33'::uuid, 2, 'traduction', $exo${"titre":"Au café, et si…","consigne":"Rends les demandes polies, puis transforme les faits en hypothèses irréelles.","enonce":"**Situation.** Au café, à Munich, Jules parle trop sèchement au serveur.\n\n1. Rends chaque phrase **polie** avec le subjonctif II :\na) *Ich will einen Kaffee.*\nb) *Können Sie mir helfen?*\nc) *Ich will zahlen.*\n\n2. En sortant, Jules se plaint. **Transforme** chaque paire de phrases en une hypothèse irréelle avec *wenn* :\nd) *Ich habe keine Zeit. Ich komme nicht mit.*\ne) *Das Wetter ist schlecht. Wir gehen nicht schwimmen.*\nf) *Ich habe kein Geld. Ich kaufe das Fahrrad nicht.*\n\n3. Pourquoi *Ich will einen Kaffee* est-il maladroit ?","bareme":[{"critere":"Demandes polies : Ich hätte gern einen Kaffee ; Könnten Sie mir helfen? ; Ich möchte bitte zahlen","points":6},{"critere":"Subordonnées justes : wenn + subjonctif II, verbe à la fin (hätte, wäre)","points":5},{"critere":"Principales justes : würde + infinitif, verbe en tête après la subordonnée","points":5},{"critere":"Explication : le présent de wollen sonne comme un ordre","points":4}],"dureeMin":11,"corrige":"**1.**\na) *Ich **hätte** gern einen Kaffee.* (ou *Ich **möchte** einen Kaffee.*)\nb) ***Könnten** Sie mir helfen?*\nc) *Ich **möchte** bitte zahlen.*\nPour la politesse, on préfère la **forme simple**.\n\n**2.**\nd) *Wenn ich Zeit **hätte**, **würde** ich **mitkommen**.*\ne) *Wenn das Wetter schön **wäre**, **würden** wir schwimmen **gehen**.* (ou *nicht schlecht wäre*)\nf) *Wenn ich Geld **hätte**, **würde** ich das Fahrrad **kaufen**.*\nDans la subordonnée, le verbe conjugué est **à la fin** ; la principale commence par le verbe (*würde*).\n\n**3.** *Ich will einen Kaffee* sonne comme un **ordre** ; *Ich hätte gern einen Kaffee* comme une **demande**. Le subjonctif II est la forme quotidienne de la politesse."}$exo$::jsonb),
  ('032feacc-974b-505b-a485-923ed367cc33'::uuid, 3, 'traduction', $exo${"titre":"Si j’avais une année libre","consigne":"Transforme, complète, identifie les modes, puis rédige un paragraphe à l’irréel.","enonce":"**1. Supprime** *wenn* dans ces phrases, sans changer leur sens :\na) *Wenn ich Zeit hätte, würde ich kommen.*\nb) *Wenn das Wetter schön wäre, würden wir wandern.*\n\n**2. Complète** avec le subjonctif II :\nc) *Er tut so, als ob er alles (wissen).*\nd) *Sie spricht, als ob sie Deutsche (sein).*\ne) Ton ami est toujours fatigué. Donne-lui un **conseil** : *Du (sollen) mehr schlafen.*\n\n**3.** Dans un journal, tu lis : *Der Minister sagte, er sei krank.* Quel est le mode de *sei* ? À quoi sert-il ?\n\n**4. Production** (5 lignes environ) : *Wenn ich ein Jahr frei hätte…* Raconte ce que tu ferais. Emploie au moins **quatre** subjonctifs II (dont une forme simple et *würde*) et une phrase sans *wenn*.","bareme":[{"critere":"Phrases sans wenn justes : Hätte ich Zeit, würde ich kommen ; Wäre das Wetter schön, würden wir wandern","points":4},{"critere":"Formes justes : wüsste, wäre, solltest","points":4},{"critere":"Subjonctif I reconnu : discours indirect de la presse","points":3},{"critere":"Production : quatre subjonctifs II justes (forme simple et würde), verbe à la fin après wenn","points":6},{"critere":"Production : une phrase sans wenn, verbe en première place","points":3}],"dureeMin":17,"corrige":"**1.**\na) ***Hätte** ich Zeit, würde ich kommen.*\nb) ***Wäre** das Wetter schön, würden wir wandern.*\nQuand *wenn* disparaît, le verbe prend la **première place** : tournure élégante, valorisée à l’écrit.\n\n**2.**\nc) *…, als ob er alles **wüsste**.* — après *als ob*, le subjonctif II est de règle.\nd) *…, als ob sie Deutsche **wäre**.*\ne) *Du **solltest** mehr schlafen.* — *solltest* exprime le **conseil**.\n\n**3.** *sei* est un **subjonctif I** : il sert au **discours indirect de la presse** (on rapporte les paroles du ministre sans les prendre à son compte). Il suffit de le reconnaître.\n\n**4.** Exemple : *Wenn ich ein Jahr frei hätte, würde ich um die Welt reisen. Ich würde zuerst nach Kanada fliegen. Dort könnte ich Englisch lernen. Hätte ich genug Geld, würde ich auch Japan besuchen. Das wäre toll!* Le correcteur vérifie au moins une forme simple (*hätte, wäre, könnte…*), *würde* + infinitif final, le verbe à la fin après *wenn*, et une phrase sans *wenn* avec le verbe en tête."}$exo$::jsonb),
  ('890d4c78-95a3-54aa-a1ea-179146d5a587'::uuid, 1, 'traduction', $exo${"titre":"Cinq phrases à ponctuer","consigne":"Recopie chaque phrase en plaçant les virgules là où l'allemand les exige, puis réponds à la question 2.","enonce":"**1. Recopie en ajoutant les virgules nécessaires.**\n\n1. Ich weiß dass du morgen kommst.\n2. Er ist müde aber glücklich.\n3. Ich kaufe Brot Milch und Käse.\n4. Sie lernt Deutsch um in Wien zu studieren.\n5. Das Buch das ich lese ist spannend.\n\n**2.** Dans la phrase 3, explique en une phrase pourquoi on ne met pas de virgule devant *und*.","bareme":[{"critere":"Virgules justes devant dass, aber et um… zu (phrases 1, 2, 4)","points":9},{"critere":"Relative enchâssée encadrée de deux virgules (phrase 5)","points":4},{"critere":"Énumération de la phrase 3 sans virgule devant und","points":3},{"critere":"Explication juste de l'absence de virgule devant und","points":4}],"dureeMin":6,"corrige":"**1. Phrases corrigées**\n\n1. *Ich weiß, dass du morgen kommst.* — virgule obligatoire devant une subordonnée.\n2. *Er ist müde, aber glücklich.* — virgule devant *aber*.\n3. *Ich kaufe Brot, Milch und Käse.* — virgule entre Brot et Milch, **pas** devant *und*.\n4. *Sie lernt Deutsch, um in Wien zu studieren.* — le groupe *um… zu* exige la virgule.\n5. *Das Buch, das ich lese, ist spannend.* — la relative enchâssée est encadrée des **deux** côtés.\n\n**2.** En allemand, la virgule marque une frontière grammaticale : *und* relie deux éléments de même rang dans une énumération, et en principe on ne met pas de virgule devant *und* (ni devant *oder*)."}$exo$::jsonb),
  ('890d4c78-95a3-54aa-a1ea-179146d5a587'::uuid, 2, 'traduction', $exo${"titre":"Le message de Léa à corriger","consigne":"Léa a écrit ce message sans respecter l'orthographe allemande. Recopie-le en corrigeant les majuscules, la ponctuation, les guillemets et les s / ß, puis réponds à la question 2.","enonce":"**1. Recopie le texte corrigé.**\n\n> gestern habe ich im park meinen freund tom getroffen. er sagt „ich komme morgen mit.“ ich hoffe dass er pünktlich ist. wir wollen die strasse entlang bis zum fluß laufen.\n\n**2.** Explique en français pourquoi on écrit *Straße* avec ß, mais *Fluss* avec ss.","bareme":[{"critere":"Majuscules aux noms communs (Park, Freund, Straße, Fluss) et en début de phrase","points":6},{"critere":"Deux-points avant le discours direct et guillemets allemands conservés","points":4},{"critere":"Virgule devant la subordonnée en dass","points":3},{"critere":"Graphies Straße et Fluss corrigées","points":3},{"critere":"Explication juste : ß après voyelle longue, ss après voyelle brève","points":4}],"dureeMin":10,"corrige":"**1. Texte corrigé**\n\n> *Gestern habe ich im Park meinen Freund Tom getroffen. Er sagt: „Ich komme morgen mit.“ Ich hoffe, dass er pünktlich ist. Wir wollen die Straße entlang bis zum Fluss laufen.*\n\nPoints attendus :\n- Majuscule à **tous** les noms communs : *Park*, *Freund*, *Straße*, *Fluss* (et bien sûr au prénom *Tom* et en début de phrase : *Gestern*, *Er*, *Ich*, *Wir*).\n- Deux-points avant le discours direct (*Er sagt:*), guillemets ouverts en bas et fermés en haut, et majuscule au début de la parole rapportée (*Ich komme…*).\n- Virgule obligatoire devant *dass*.\n\n**2.** On écrit **ß** après une voyelle longue ou une diphtongue : le *a* de *Straße* est long. On écrit **ss** après une voyelle brève : le *u* de *Fluss* est bref. *Fluß* est donc une faute (ancienne orthographe)."}$exo$::jsonb),
  ('890d4c78-95a3-54aa-a1ea-179146d5a587'::uuid, 3, 'traduction', $exo${"titre":"Thème : ponctuer et écrire juste","consigne":"Traduis les quatre phrases en allemand en respectant la ponctuation et les majuscules allemandes, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. Il dit : « Je sais qu'elle vient. »\n2. Madame Weber, je vous remercie.\n3. La ville que je visite est belle mais chère.\n4. J'apprends l'allemand pour lire des livres.\n\n*Aide : danken + datif ; besuchen = visiter ; schön = beau ; teuer = cher ; das Buch, die Bücher.*\n\n**2.** Quelle est la différence de sens entre *Können Sie mir helfen?* et *Können sie mir helfen?* Explique pourquoi.","bareme":[{"critere":"Virgules justes : dass, relative enchâssée, aber, um… zu","points":6},{"critere":"Deux-points et guillemets allemands au discours direct","points":3},{"critere":"Majuscules : noms communs, Ihnen de politesse","points":4},{"critere":"Ordre des mots et formes verbales corrects","points":3},{"critere":"Explication de la différence Sie / sie","points":4}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n\n1. *Er sagt: „Ich weiß, dass sie kommt.“*\n2. *Frau Weber, ich danke Ihnen.*\n3. *Die Stadt, die ich besuche, ist schön, aber teuer.*\n4. *Ich lerne Deutsch, um Bücher zu lesen.*\n\nPoints attendus :\n- Phrase 1 : deux-points avant la parole, guillemets „…“, virgule devant *dass*, *sie* (elle) en minuscule.\n- Phrase 2 : *danken* régit le datif : *Ihnen*, avec **majuscule** car c'est le vouvoiement.\n- Phrase 3 : relative encadrée de deux virgules, verbe *besuche* à la fin de la relative, virgule devant *aber*.\n- Phrase 4 : virgule devant *um… zu*, infinitif avec *zu* en fin de phrase.\n\n**2.** *Können Sie mir helfen?* = « Pouvez-vous m'aider ? » (vouvoiement, une personne à qui l'on parle). *Können sie mir helfen?* = « Peuvent-ils (ou peuvent-elles) m'aider ? ». À l'écrit, seule la majuscule distingue le *Sie* de politesse du *sie* de la 3e personne : l'oublier change le destinataire de la phrase."}$exo$::jsonb),
  ('e784b9c4-b74b-551e-b1ab-4289cdf67844'::uuid, 1, 'traduction', $exo${"titre":"Changer le début de la phrase","consigne":"Réécris chaque phrase en la commençant par l'élément en gras. Attention à la place du verbe conjugué.","enonce":"**Réécris en commençant par l'élément en gras.**\n\n1. Ich fahre **morgen** nach Berlin.\n2. Wir spielen **am Samstag** Fußball.\n3. Er hat **gestern** einen Film gesehen.\n4. Ich stehe **um sieben Uhr** auf.\n5. Meine Schwester muss **heute Abend** arbeiten.","bareme":[{"critere":"Verbe conjugué en deuxième position et sujet placé derrière (inversion)","points":12},{"critere":"Second morceau du verbe (participe, infinitif, préverbe) laissé en fin de phrase","points":8}],"dureeMin":6,"corrige":"**Phrases attendues**\n\n1. *Morgen fahre ich nach Berlin.*\n2. *Am Samstag spielen wir Fußball.*\n3. *Gestern hat er einen Film gesehen.*\n4. *Um sieben Uhr stehe ich auf.*\n5. *Heute Abend muss meine Schwester arbeiten.*\n\nPoints attendus :\n- Règle V2 : le verbe conjugué reste le **deuxième groupe**. Dès qu'un autre élément que le sujet ouvre la phrase, le sujet passe **derrière** le verbe (inversion). *Morgen ich fahre…* est faux.\n- Parenthèse verbale : *gesehen* (participe), *auf* (préverbe) et *arbeiten* (infinitif après le modal) restent à la toute fin."}$exo$::jsonb),
  ('e784b9c4-b74b-551e-b1ab-4289cdf67844'::uuid, 2, 'traduction', $exo${"titre":"Cinq phrases à traduire dans le bon ordre","consigne":"Traduis en allemand. Soigne la place du verbe et l'ordre des compléments.","enonce":"**Traduis en allemand.**\n\n1. Demain, je dois travailler.\n2. Hier, Paul a acheté un vélo.\n3. Je donne le livre à l'enfant.\n4. Je le donne à l'enfant.\n5. Nous allons demain en train à Munich.\n\n*Aide : kaufen (gekauft) ; das Fahrrad ; das Buch ; das Kind ; fahren ; mit dem Zug ; München.*","bareme":[{"critere":"Verbe en deuxième position et inversion après Morgen / Gestern","points":6},{"critere":"Infinitif et participe rejetés en fin de phrase","points":5},{"critere":"Ordre datif puis accusatif, et pronom es placé devant le datif","points":5},{"critere":"Ordre temps, manière, lieu (TeKaMoLo) dans la phrase 5","points":4}],"dureeMin":10,"corrige":"**Traduction modèle**\n\n1. *Morgen muss ich arbeiten.*\n2. *Gestern hat Paul ein Fahrrad gekauft.*\n3. *Ich gebe dem Kind das Buch.*\n4. *Ich gebe es dem Kind.*\n5. *Wir fahren morgen mit dem Zug nach München.*\n\nPoints attendus :\n- 1 et 2 : l'adverbe de temps occupe la première place, le verbe conjugué suit, puis le sujet (inversion). L'infinitif *arbeiten* et le participe *gekauft* ferment la phrase.\n- 3 : deux groupes nominaux → **datif puis accusatif** (*dem Kind das Buch*).\n- 4 : l'accusatif est un **pronom** → il passe devant (*es dem Kind*). *Ich gebe dem Kind es* est faux.\n- 5 : TeKaMoLo : temps (*morgen*), manière (*mit dem Zug*), lieu (*nach München*)."}$exo$::jsonb),
  ('e784b9c4-b74b-551e-b1ab-4289cdf67844'::uuid, 3, 'traduction', $exo${"titre":"Le week-end de Jonas","consigne":"À partir des notes, écris un petit texte de cinq phrases au présent, sauf une phrase au parfait. Au moins trois phrases doivent commencer par un autre élément que le sujet. Puis réponds à la question 2.","enonce":"**1. Rédige le texte à partir de ces notes.**\n\n- samedi : se lever à 8 heures (*aufstehen*)\n- ensuite : prendre le train pour Hambourg avec sa sœur\n- là-bas : devoir acheter un cadeau pour sa grand-mère (*müssen*)\n- dimanche : visiter le port — **au parfait** (*den Hafen besuchen*)\n- le soir : rentrer à la maison (*zurückkommen, nach Hause*)\n\n**2.** Choisis une de tes phrases qui commence par un complément de temps et explique en français la règle de la place du verbe qu'elle applique.","bareme":[{"critere":"Verbe conjugué en deuxième position dans chaque phrase, avec inversion","points":6},{"critere":"Parenthèse verbale : préverbe, infinitif du modal et participe en fin de phrase","points":6},{"critere":"Ordre des compléments (temps, manière, lieu) respecté","points":3},{"critere":"Explication juste de la règle V2 et de l'inversion","points":5}],"dureeMin":16,"corrige":"**1. Texte modèle**\n\n*Am Samstag steht Jonas um acht Uhr auf. Dann fährt er mit seiner Schwester mit dem Zug nach Hamburg. Dort muss er ein Geschenk für seine Großmutter kaufen. Am Sonntag hat er den Hafen besucht. Am Abend kommt er nach Hause zurück.*\n\nPoints attendus :\n- Chaque phrase ouverte par *Am Samstag*, *Dann*, *Dort*, *Am Sonntag*, *Am Abend* : verbe en 2e position, sujet **derrière**.\n- Préverbes *auf* et *zurück* en fin de phrase ; *kaufen* après le modal *muss* en fin de phrase ; participe *besucht* en fin de phrase après *hat*.\n- Compléments dans l'ordre temps → manière → lieu : *mit dem Zug nach Hamburg*.\n- Toute formulation équivalente correcte est acceptée (ex. *nimmt den Zug nach Hamburg*).\n\n**2.** Exemple : *Am Sonntag hat er den Hafen besucht.* Dans une déclarative, le verbe conjugué occupe toujours la deuxième place (le deuxième **groupe**, pas le deuxième mot). Comme le complément de temps *Am Sonntag* occupe la première place, le sujet *er* passe derrière le verbe : c'est l'inversion. Le participe *besucht* ferme la phrase."}$exo$::jsonb),
  ('3693080b-ebed-515a-b479-248cabe48cb3'::uuid, 1, 'traduction', $exo${"titre":"Trouver la bonne question","consigne":"Écris la question qui correspond à chaque réponse. La partie en gras est ce que l'on demande ; pour la phrase 1, pose une question fermée.","enonce":"**Écris la question (tutoie la personne).**\n\n1. Ja, ich komme morgen.\n2. Ich wohne **in Köln**.\n3. Ich fahre **nach Wien**.\n4. **Mein Bruder** ruft an.\n5. Ich sehe **den Lehrer**.","bareme":[{"critere":"Mot interrogatif juste (wo, wohin, wer, wen)","points":10},{"critere":"Place du verbe : 1re position (question fermée), 2e après le mot en w-","points":6},{"critere":"Conjugaison à la 2e personne et point d'interrogation","points":4}],"dureeMin":7,"corrige":"**Questions attendues**\n\n1. *Kommst du morgen?* — question fermée : verbe en **première** position.\n2. *Wo wohnst du?* — *wo* : le lieu où l'on est, **sans** mouvement.\n3. *Wohin fährst du?* — *wohin* : la destination, **avec** mouvement.\n4. *Wer ruft an?* — *wer* : qui (sujet, nominatif).\n5. *Wen siehst du?* — *wen* : qui (COD, accusatif de *wer*).\n\nPoints attendus : dans les questions ouvertes, le verbe reste en deuxième position, juste après le mot interrogatif ; *wer* se décline (*wen* à l'accusatif) ; ne pas confondre *wo* et *wohin*."}$exo$::jsonb),
  ('3693080b-ebed-515a-b479-248cabe48cb3'::uuid, 2, 'traduction', $exo${"titre":"Des questions indirectes","consigne":"Transforme chaque question directe en question indirecte avec l'amorce donnée, puis réponds à la question 2.","enonce":"**1. Transforme en question indirecte.**\n\n1. Kommt Lisa heute? → *Ich frage mich, …*\n2. Wann beginnt der Film? → *Weißt du, …*\n3. Warum lernst du Deutsch? → *Sag mir, …*\n4. Wo wohnt dein Onkel? → *Ich weiß nicht, …*\n\n**2.** Pourquoi serait-il faux d'écrire *Ich frage mich, wenn Lisa heute kommt* ?","bareme":[{"critere":"Choix de ob pour la question fermée, mot en w- conservé ailleurs","points":6},{"critere":"Verbe conjugué rejeté à la fin de la subordonnée","points":8},{"critere":"Virgules et ponctuation finale correctes","points":3},{"critere":"Explication de l'opposition ob / wenn","points":3}],"dureeMin":10,"corrige":"**1. Phrases attendues**\n\n1. *Ich frage mich, ob Lisa heute kommt.*\n2. *Weißt du, wann der Film beginnt?*\n3. *Sag mir, warum du Deutsch lernst.*\n4. *Ich weiß nicht, wo dein Onkel wohnt.*\n\nPoints attendus :\n- La question indirecte est une subordonnée : virgule devant, et verbe conjugué **à la fin** (*kommt*, *beginnt*, *lernst*, *wohnt*).\n- Sans mot interrogatif (question fermée), on emploie *ob*.\n- Le point d'interrogation disparaît, sauf quand la principale elle-même est une question (phrase 2 : *Weißt du…?*).\n\n**2.** Le « si » d'une question indirecte exprime une **alternative** (oui ou non) : il se traduit par *ob*. *Wenn* introduit une **condition** ou un **moment** ; l'employer ici serait une faute de sens."}$exo$::jsonb),
  ('3693080b-ebed-515a-b479-248cabe48cb3'::uuid, 3, 'traduction', $exo${"titre":"Dialogue avant le concert","consigne":"Traduis ce dialogue en allemand (thème), puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n— Tu ne viens pas au concert ?\n— Si ! Mais je ne sais pas quand il commence.\n— À huit heures. À qui penses-tu ?\n— À Mia. Et toi, à quoi penses-tu ?\n— Aux vacances !\n\n*Aide : mitkommen ; zum Konzert ; beginnen ; denken an + accusatif ; die Ferien (pluriel).*\n\n**2.** Explique en français pourquoi on répond *Doch!* à la première question, et pourquoi on dit *an wen* pour Mia mais *woran* pour les vacances.","bareme":[{"critere":"Doch employé pour contredire la question négative","points":3},{"critere":"Question indirecte avec wann et verbe en fin de subordonnée","points":5},{"critere":"An wen pour une personne, woran pour une chose","points":5},{"critere":"Place du verbe dans les questions fermées et ouvertes","points":4},{"critere":"Explication juste de doch et de wo(r) + préposition","points":3}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n\n— *Kommst du nicht zum Konzert mit?* (ou *Du kommst nicht mit zum Konzert?*)\n— *Doch! Aber ich weiß nicht, wann es beginnt.*\n— *Um acht Uhr. An wen denkst du?*\n— *An Mia. Und woran denkst du?*\n— *An die Ferien!*\n\nPoints attendus :\n- *Doch!* et non *Ja!* pour dire « si ».\n- *…, wann es beginnt* : virgule, verbe à la fin ; *es* reprend *das Konzert* (neutre).\n- *An wen denkst du?* (personne : préposition + *wen*) ; *Woran denkst du?* (chose : *wo(r)-* soudé à la préposition).\n- Question ouverte : verbe en 2e position après le mot interrogatif.\n\n**2.** Face à une question **négative**, *ja* est impossible : pour contredire la négation, l'allemand répond *doch* (comme « si » en français). Pour interroger sur une **chose**, l'allemand soude *wo(r)-* et la préposition (*woran*) ; pour une **personne**, il garde la préposition suivie de *wen* ou *wem* (*an wen*)."}$exo$::jsonb),
  ('d591234c-8ff1-580f-8fe7-bdc1d4fe344f'::uuid, 1, 'traduction', $exo${"titre":"Nicht ou kein ?","consigne":"Mets chaque phrase à la forme négative en choisissant entre nicht et kein.","enonce":"**Mets à la forme négative.**\n\n1. Ich habe ein Fahrrad.\n2. Ich kenne den Mann.\n3. Er trinkt Kaffee.\n4. Das Buch ist interessant.\n5. Wir haben Freunde in Berlin.\n6. Ich gehe ins Kino.","bareme":[{"critere":"Choix juste entre nicht et kein pour chaque phrase","points":10},{"critere":"Déclinaison de kein (keinen, keine au pluriel)","points":4},{"critere":"Place de nicht (après le COD défini, devant l'attribut et le lieu)","points":6}],"dureeMin":7,"corrige":"**Phrases attendues**\n\n1. *Ich habe kein Fahrrad.* — nom précédé de *ein* → *kein*.\n2. *Ich kenne den Mann nicht.* — article défini → *nicht*, placé **après** le COD défini.\n3. *Er trinkt keinen Kaffee.* — nom sans article → *kein*, décliné à l'accusatif masculin : *keinen*.\n4. *Das Buch ist nicht interessant.* — on nie l'attribut : *nicht* **devant** lui.\n5. *Wir haben keine Freunde in Berlin.* — pluriel sans article → *keine* (kein a un pluriel).\n6. *Ich gehe nicht ins Kino.* — lieu directionnel : *nicht* **devant**.\n\nRègle : *kein* devant un nom précédé de *ein* ou sans article ; *nicht* devant un article défini, un possessif, un verbe, un adjectif."}$exo$::jsonb),
  ('d591234c-8ff1-580f-8fe7-bdc1d4fe344f'::uuid, 2, 'traduction', $exo${"titre":"Cinq négations à traduire","consigne":"Traduis en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. Je ne l'ai pas vu hier. (*le* = un homme)\n2. Il ne travaille plus.\n3. Je ne pars pas demain, mais aujourd'hui.\n4. Personne ne vient.\n5. Je ne vois rien.\n\n*Aide : sehen (gesehen) ; arbeiten ; fahren ; kommen.*\n\n**2.** Un élève écrit *Ich sehe nicht nichts*. Explique en français pourquoi c'est faux.","bareme":[{"critere":"Mots négatifs justes : nicht mehr, niemand, nichts","points":6},{"critere":"Place de nicht : devant le participe, devant le mot nié","points":6},{"critere":"Rectification avec sondern","points":4},{"critere":"Explication : une seule négation suffit en allemand","points":4}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n\n1. *Ich habe ihn gestern nicht gesehen.* — négation de toute la phrase : *nicht* le plus à droite possible, devant le participe.\n2. *Er arbeitet nicht mehr.* — « ne… plus » = *nicht mehr*.\n3. *Ich fahre nicht morgen, sondern heute.* — on nie un seul mot : *nicht* **devant** *morgen* ; après une négation, on rectifie avec *sondern* (pas *aber*).\n4. *Niemand kommt.*\n5. *Ich sehe nichts.*\n\n**2.** En allemand, deux négations ne s'additionnent pas pour renforcer : **une seule suffit**. *Nichts* porte déjà la négation (« rien »), il ne faut donc pas ajouter *nicht*. La phrase juste est *Ich sehe nichts*."}$exo$::jsonb),
  ('d591234c-8ff1-580f-8fe7-bdc1d4fe344f'::uuid, 3, 'traduction', $exo${"titre":"Paul répond non à tout","consigne":"Paul est de mauvaise humeur : il répond non à toutes les questions de sa mère. Écris ses réponses en phrases complètes, puis réponds à la question 2.","enonce":"**1. Écris les réponses négatives de Paul.**\n\n1. Hast du einen Hund gesehen?\n2. Hast du deine Hausaufgaben gemacht?\n3. Ist dein Freund nett?\n4. Fährst du nach Berlin? — *Paul rectifie : il va à Hambourg.*\n5. Wohnst du noch in Köln?\n6. Kommt jemand mit?\n\n**2.** Justifie en français ton choix entre *nicht* et *kein* dans les réponses 1 et 2.","bareme":[{"critere":"Choix nicht / kein juste et kein décliné (keinen)","points":6},{"critere":"Place de nicht : après le COD défini, devant l'attribut et le lieu","points":5},{"critere":"Emploi de sondern, nicht mehr et niemand","points":5},{"critere":"Justification juste des réponses 1 et 2","points":4}],"dureeMin":15,"corrige":"**1. Réponses modèles**\n\n1. *Nein, ich habe keinen Hund gesehen.*\n2. *Nein, ich habe meine Hausaufgaben nicht gemacht.*\n3. *Nein, er ist nicht nett.*\n4. *Nein, ich fahre nicht nach Berlin, sondern nach Hamburg.*\n5. *Nein, ich wohne nicht mehr in Köln.*\n6. *Nein, niemand kommt mit.*\n\nPoints attendus :\n- 1 : *einen Hund* → *keinen Hund* (accusatif masculin).\n- 2 : COD avec possessif → *nicht*, placé après le COD et devant le participe *gemacht*.\n- 3 : *nicht* devant l'attribut.\n- 4 : *nicht* devant le lieu directionnel, rectification par *sondern*.\n- 5 : « ne… plus » = *nicht mehr*. 6 : *niemand*, sans autre négation.\n\n**2.** Réponse 1 : le nom est précédé de l'article indéfini *einen* → on nie avec *kein*, qui se décline comme *ein* (*keinen*). Réponse 2 : le nom est précédé d'un possessif (*meine*) → on nie avec *nicht*, jamais avec *kein*."}$exo$::jsonb),
  ('cd20efcc-f2f3-50de-a18a-9236871967ab'::uuid, 1, 'traduction', $exo${"titre":"Relier deux phrases","consigne":"Relie les deux phrases avec la conjonction donnée. Attention à la place du verbe.","enonce":"**Relie avec la conjonction entre parenthèses.**\n\n1. Ich bleibe zu Hause. Ich bin krank. (*weil*)\n2. Ich weiß. Er kommt morgen. (*dass*)\n3. Sie geht spazieren. Es regnet. (*obwohl*)\n4. Er ruft an. Er hat Zeit. (*wenn*)","bareme":[{"critere":"Verbe conjugué rejeté à la fin de chaque subordonnée","points":12},{"critere":"Virgule devant la subordonnée","points":4},{"critere":"Reste de la phrase et sujet correctement placés","points":4}],"dureeMin":6,"corrige":"**Phrases attendues**\n\n1. *Ich bleibe zu Hause, weil ich krank bin.*\n2. *Ich weiß, dass er morgen kommt.*\n3. *Sie geht spazieren, obwohl es regnet.*\n4. *Er ruft an, wenn er Zeit hat.*\n\nPoints attendus : une subordonnée se reconnaît à la conjonction en tête et au **verbe conjugué à la toute fin** (*bin*, *kommt*, *regnet*, *hat*). La virgule devant la subordonnée est obligatoire. Le sujet suit directement la conjonction (*weil ich…*, *dass er…*). *Ich bleibe zu Hause, weil ich bin krank* est la faute à éviter."}$exo$::jsonb),
  ('cd20efcc-f2f3-50de-a18a-9236871967ab'::uuid, 2, 'traduction', $exo${"titre":"Quand, parce que : quatre traductions","consigne":"Traduis en allemand. Soigne le choix de la conjonction et la place des verbes.","enonce":"**Traduis en allemand.**\n\n1. Quand j'étais petit, j'habitais à Munich.\n2. Je reste à la maison parce que je dois travailler.\n3. Il est fatigué parce qu'il a travaillé.\n4. Quand il pleut, je lis.\n\n*Aide : klein ; wohnen (prétérit wohnte) ; München ; zu Hause bleiben ; müde ; regnen ; lesen (er liest).*","bareme":[{"critere":"Choix de als pour un fait unique du passé, wenn pour la répétition","points":5},{"critere":"Verbe final en subordonnée, modal et auxiliaire en dernier","points":6},{"critere":"Subordonnée en tête : verbe de la principale juste après la virgule","points":6},{"critere":"Virgules correctes","points":3}],"dureeMin":10,"corrige":"**Traduction modèle**\n\n1. *Als ich klein war, wohnte ich in München.* (*habe ich in München gewohnt* accepté)\n2. *Ich bleibe zu Hause, weil ich arbeiten muss.*\n3. *Er ist müde, weil er gearbeitet hat.*\n4. *Wenn es regnet, lese ich.*\n\nPoints attendus :\n- 1 : « quand » pour une période **unique** du passé → *als*, jamais *wann* ni *wenn*.\n- 4 : « quand » au présent, à valeur répétée → *wenn*.\n- 2 : avec un modal, c'est le **modal conjugué** qui ferme la subordonnée, après l'infinitif (*arbeiten muss*).\n- 3 : au temps composé, l'**auxiliaire** ferme la subordonnée, après le participe (*gearbeitet hat*).\n- 1 et 4 : la subordonnée en tête occupe la première position ; le verbe de la principale suit **immédiatement** la virgule (*wohnte ich*, *lese ich*)."}$exo$::jsonb),
  ('cd20efcc-f2f3-50de-a18a-9236871967ab'::uuid, 3, 'traduction', $exo${"titre":"Pourquoi j'apprends l'allemand","consigne":"Écris à ton correspondant un message de six phrases pour lui expliquer pourquoi tu apprends l'allemand. Emploie weil, denn, dass, obwohl et damit, et place au moins une subordonnée en tête de phrase. Puis réponds à la question 2.","enonce":"**1. Rédige ton message (six phrases).**\n\nIdées possibles : étudier plus tard en Allemagne, ce que disent tes parents de l'allemand, la grammaire difficile mais le cours agréable, lire des livres en allemand, un professeur qui parle lentement, une visite de ton correspondant l'été prochain.\n\n**2.** Choisis une de tes phrases avec *weil* et une avec *denn*. Explique en français la différence de construction entre les deux.","bareme":[{"critere":"Cinq conjonctions employées avec le bon sens","points":5},{"critere":"Verbe conjugué à la fin après weil, dass, obwohl, damit","points":6},{"critere":"Subordonnée en tête suivie du verbe de la principale","points":3},{"critere":"Ordre normal conservé après denn","points":3},{"critere":"Explication juste de la différence weil / denn","points":3}],"dureeMin":18,"corrige":"**1. Message modèle**\n\n*Ich lerne Deutsch, weil ich später in Berlin studieren möchte. Mein Vater sagt, dass Deutsch in Europa sehr wichtig ist. Obwohl die Grammatik schwer ist, macht mir der Unterricht Spaß. Ich lese auch deutsche Bücher, denn ich will meinen Wortschatz verbessern. Meine Lehrerin spricht langsam, damit wir alles verstehen. Wenn du mich im Sommer besuchst, können wir zusammen Deutsch sprechen.*\n\nPoints attendus :\n- Verbe (ou modal) conjugué à la fin après *weil*, *dass*, *obwohl*, *damit*, *wenn* : *möchte*, *ist*, *verstehen*, *besuchst*.\n- *Obwohl…* et *Wenn…* en tête : le verbe de la principale suit la virgule (*macht mir*, *können wir*).\n- *denn* : ordre normal, verbe en 2e position (*denn ich will…*).\n- *damit* (but avec un autre sujet), *obwohl* (concession) employés avec le bon sens. Toute production correcte et variée est acceptée.\n\n**2.** *weil* est une conjonction de **subordination** : elle envoie le verbe conjugué à la fin (*weil ich… studieren möchte*). *denn* est une conjonction de **coordination** : elle ne touche pas à l'ordre des mots, le verbe reste en deuxième position (*denn ich will…*). Le sens (la cause) est le même."}$exo$::jsonb),
  ('b462d66b-b245-59dd-b171-d0f387a69259'::uuid, 1, 'traduction', $exo${"titre":"Le bon pronom relatif","consigne":"Complète chaque phrase avec le pronom relatif qui convient, puis justifie les phrases 2 et 4.","enonce":"**1. Complète avec le pronom relatif.**\n\n1. Der Mann, ___ dort steht, ist mein Onkel.\n2. Die Frau, ___ ich helfe, ist alt.\n3. Das Buch, ___ ich lese, ist spannend.\n4. Die Kinder, mit ___ ich spiele, sind nett.\n5. Der Junge, ___ Vater Arzt ist, heißt Tim.\n6. Die Stadt, ___ ich besuche, ist schön.\n\n**2.** Justifie en une phrase chacun le pronom des phrases 2 et 4 (genre et cas).","bareme":[{"critere":"Genre et nombre repris de l'antécédent","points":6},{"critere":"Cas donné par la fonction dans la relative (dont der, denen, dessen)","points":10},{"critere":"Justification juste des phrases 2 et 4","points":4}],"dureeMin":7,"corrige":"**1. Réponses**\n\n1. *der* — masculin, sujet → nominatif.\n2. *der* — féminin, complément de *helfen* qui régit le **datif** → *der*.\n3. *das* — neutre, COD → accusatif *das*.\n4. *denen* — pluriel, après *mit* qui régit le datif → datif pluriel *denen*.\n5. *dessen* — masculin, complément du nom *Vater* → génitif *dessen*, sans article devant *Vater*.\n6. *die* — féminin, COD → accusatif *die*.\n\n**2.** Phrase 2 : *Frau* est féminin (genre venu d'avant), et dans la relative le pronom est complément de *helfen*, qui régit le datif (cas venu d'après) → *der*. Phrase 4 : *Kinder* est au pluriel, et la préposition *mit* impose le datif → *denen*, l'une des trois formes qui diffèrent de l'article."}$exo$::jsonb),
  ('b462d66b-b245-59dd-b171-d0f387a69259'::uuid, 2, 'traduction', $exo${"titre":"Deux phrases, une relative","consigne":"Relie chaque paire de phrases par une subordonnée relative.","enonce":"**Relie par une relative.**\n\n1. Das ist der Film. Ich habe den Film gestern gesehen.\n2. Ich kenne die Lehrerin. Sie wohnt in unserer Straße.\n3. Hier ist mein Freund. Ich fahre mit ihm nach Wien.\n4. Das ist die Frau. Ihr Auto ist kaputt.\n5. Du sagst alles. Das ist richtig. → commence par *Alles, …*","bareme":[{"critere":"Pronom relatif juste (den, die, dem, deren, was)","points":8},{"critere":"Préposition placée devant le relatif","points":3},{"critere":"Verbe conjugué à la fin de la relative","points":5},{"critere":"Virgules obligatoires autour de la relative","points":4}],"dureeMin":10,"corrige":"**Phrases attendues**\n\n1. *Das ist der Film, den ich gestern gesehen habe.* — masculin, COD → *den* ; l'auxiliaire *habe* ferme la relative.\n2. *Ich kenne die Lehrerin, die in unserer Straße wohnt.* — féminin, sujet → *die*.\n3. *Hier ist mein Freund, mit dem ich nach Wien fahre.* — la préposition reste **devant** le relatif et commande le datif.\n4. *Das ist die Frau, deren Auto kaputt ist.* — génitif féminin *deren*, sans article devant *Auto*.\n5. *Alles, was du sagst, ist richtig.* — après *alles*, le relatif est *was*, jamais *das*.\n\nDans toutes les phrases : virgules obligatoires, verbe conjugué **à la fin** de la relative."}$exo$::jsonb),
  ('b462d66b-b245-59dd-b171-d0f387a69259'::uuid, 3, 'traduction', $exo${"titre":"Lukas et son club de football","consigne":"Traduis le texte en allemand (thème), puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n> Lukas est un garçon qui habite à Hambourg. Le club dans lequel il joue au football est connu. Son entraîneur, à qui il fait confiance, est sévère. La fille dont le frère joue aussi s'appelle Emma. Lukas gagne souvent, ce qui plaît à ses parents.\n\n*Aide : der Verein ; der Trainer ; vertrauen + datif ; streng ; das Mädchen ; gewinnen ; gefallen + datif ; bekannt.*\n\n**2.** Explique en français pourquoi on écrit *dessen* (et non *deren*) devant *Bruder*, et *dem* devant *er vertraut*.","bareme":[{"critere":"Pronoms relatifs justes : der, in dem, dem, dessen","points":6},{"critere":"Relatif was après une phrase entière","points":3},{"critere":"Verbe à la fin de chaque relative et virgules","points":5},{"critere":"Vocabulaire et reste de la phrase corrects","points":2},{"critere":"Justification de dessen et de dem","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n> *Lukas ist ein Junge, der in Hamburg wohnt. Der Verein, in dem er Fußball spielt, ist bekannt. Sein Trainer, dem er vertraut, ist streng. Das Mädchen, dessen Bruder auch spielt, heißt Emma. Lukas gewinnt oft, was seinen Eltern gefällt.*\n\nPoints attendus :\n- *der* : masculin (Junge), sujet → nominatif.\n- *in dem* : la préposition reste devant le relatif ; *in* + datif (lieu où l'on est).\n- *dem* : masculin (Trainer), complément de *vertrauen* qui régit le datif.\n- *dessen* : génitif, sans article devant *Bruder*.\n- *was* : le relatif reprend toute la phrase précédente.\n- Chaque relative : virgules et verbe conjugué à la fin (*wohnt*, *spielt*, *vertraut*, *spielt*, *gefällt*). Relative enchâssée encadrée de deux virgules.\n\n**2.** Le pronom prend le **genre de l'antécédent** : *Mädchen* est **neutre** (diminutif en -chen), donc génitif neutre *dessen* ; *deren* serait féminin ou pluriel. Pour *dem* : l'antécédent *Trainer* est masculin, et dans la relative le pronom est complément de *vertrauen*, qui régit le datif → *dem*."}$exo$::jsonb),
  ('41d699ab-7ab2-5f49-8f3b-cf3dd9cc9818'::uuid, 1, 'traduction', $exo${"titre":"Passer au passif","consigne":"Mets chaque phrase au passif présent. Garde l'agent quand il est nommé.","enonce":"**Mets au passif présent.**\n\n1. Man baut ein Haus.\n2. Der Lehrer korrigiert die Hefte.\n3. Man repariert das Auto.\n4. Die Mutter kocht die Suppe.\n\n*Rappel : le COD de la phrase active devient le sujet de la phrase passive.*","bareme":[{"critere":"werden conjugué et accordé au nouveau sujet (wird, werden)","points":8},{"critere":"Participe II rejeté en fin de phrase","points":6},{"critere":"Agent introduit par von + datif (vom Lehrer, von der Mutter)","points":6}],"dureeMin":7,"corrige":"**Phrases attendues**\n\n1. *Ein Haus wird gebaut.*\n2. *Die Hefte werden vom Lehrer korrigiert.*\n3. *Das Auto wird repariert.*\n4. *Die Suppe wird von der Mutter gekocht.*\n\nPoints attendus :\n- Le passif d'action se construit avec **werden** (jamais *sein*) + participe II à la fin.\n- *werden* s'accorde avec le nouveau sujet : *die Hefte* est pluriel → *werden*.\n- *man* disparaît : pas d'agent. Une personne agent est introduite par *von* + datif : *vom Lehrer* (von dem), *von der Mutter*.\n- Participes : *gebaut*, *korrigiert*, *repariert* (verbes en -ieren, sans ge-), *gekocht*."}$exo$::jsonb),
  ('41d699ab-7ab2-5f49-8f3b-cf3dd9cc9818'::uuid, 2, 'traduction', $exo${"titre":"Le passif à tous les temps","consigne":"Réponds aux quatre questions.","enonce":"1. Mets *Das Haus wird gebaut* au **prétérit**, puis au **parfait**.\n2. Mets *Der Brief wird geschrieben* au **parfait**.\n3. Traduis : « Le travail doit être fait aujourd'hui. » (*die Arbeit, machen*)\n4. Explique en français la différence de sens entre *Die Tür wird geschlossen* et *Die Tür ist geschlossen*.","bareme":[{"critere":"Prétérit du passif avec wurde","points":4},{"critere":"Parfait du passif avec ist + participe + worden","points":6},{"critere":"Passif avec modal : muss + participe + werden","points":5},{"critere":"Distinction juste entre passif d'action et passif d'état","points":5}],"dureeMin":10,"corrige":"1. Prétérit : *Das Haus wurde gebaut.* Parfait : *Das Haus ist gebaut worden.*\n2. *Der Brief ist geschrieben worden.*\n3. *Die Arbeit muss heute gemacht werden.* — le modal se conjugue, le passif passe à l'infinitif (*gemacht werden*).\n4. *Die Tür wird geschlossen* = passif d'**action** : quelqu'un est en train de fermer la porte (le film). *Die Tür ist geschlossen* = passif d'**état** : la porte est fermée, c'est un résultat acquis (la photo).\n\nPoint essentiel : au parfait du passif, le participe de *werden* perd son ge- : **worden**. *geworden* est réservé au verbe *werden* au sens de « devenir » (*Er ist Arzt geworden*). L'auxiliaire du parfait passif est toujours *sein* (*ist… worden*)."}$exo$::jsonb),
  ('41d699ab-7ab2-5f49-8f3b-cf3dd9cc9818'::uuid, 3, 'traduction', $exo${"titre":"L'histoire d'un pont","consigne":"Traduis ce petit article en allemand en employant le passif, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n> Le pont de la ville a été construit en 1890. En 2020, il a été détruit par une tempête. Aujourd'hui, il est reconstruit par une entreprise allemande. Il doit être terminé en 2027. Ici, on travaille jour et nuit.\n\n*Aide : die Brücke (féminin) ; bauen ; zerstören ; der Sturm ; die Firma ; wieder aufbauen (wieder aufgebaut) ; fertigstellen (fertiggestellt) ; Tag und Nacht. Pour « on travaille », utilise le passif impersonnel.*\n\n**2.** Réécris la dernière phrase avec *man*, puis explique pourquoi tu as employé *durch* pour la tempête et *von* pour l'entreprise.","bareme":[{"critere":"Temps du passif justes : wurde / ist … worden, wird + participe","points":6},{"critere":"Passif avec modal : muss … fertiggestellt werden","points":3},{"critere":"Passif impersonnel : Hier wird … gearbeitet","points":3},{"critere":"Agent : durch + accusatif et von + datif","points":4},{"critere":"Phrase avec man et explication von / durch","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n> *Die Brücke der Stadt wurde 1890 gebaut. 2020 ist sie durch einen Sturm zerstört worden. Heute wird sie von einer deutschen Firma wieder aufgebaut. Sie muss 2027 fertiggestellt werden. Hier wird Tag und Nacht gearbeitet.*\n\nPoints attendus :\n- *wurde gebaut* (prétérit) ou *ist gebaut worden* (parfait) acceptés pour les deux premières phrases ; au parfait : **worden**, jamais *geworden*.\n- *sie* reprend *die Brücke* (féminin).\n- *wird… wieder aufgebaut* : présent du passif, participe en fin de phrase.\n- *muss… fertiggestellt werden* : modal + infinitif passif.\n- *Hier wird… gearbeitet* : passif impersonnel d'un verbe sans COD.\n- Une date seule s'emploie sans préposition (*1890*, *2020*) ; *im Jahr 1890* accepté.\n\n**2.** *Hier arbeitet man Tag und Nacht.* (ou *Man arbeitet hier Tag und Nacht.*)\n*von* + datif introduit une personne ou une force qui agit : l'entreprise fait le travail. *durch* + accusatif introduit un **moyen** ou un intermédiaire, comme un phénomène naturel (*durch ein Erdbeben*, *durch einen Sturm*)."}$exo$::jsonb),
  ('5c40007f-ccb0-5043-9b02-006edf5845e2'::uuid, 1, 'traduction', $exo${"titre":"Avec ou sans zu ?","consigne":"Complète avec zu quand il le faut, ou écris l'infinitif entre parenthèses à la bonne forme.","enonce":"**Complète (mets un tiret si zu est impossible).**\n\n1. Ich versuche, pünktlich ___ sein.\n2. Ich kann gut ___ schwimmen.\n3. Er hat keine Lust, ins Kino ___ gehen.\n4. Wir gehen heute ___ schwimmen.\n5. Es ist wichtig, früh ___ (*aufstehen*).\n6. Vergiss nicht, Brot ___ (*einkaufen*).","bareme":[{"critere":"zu présent après versuchen, Lust haben, es ist wichtig, vergessen","points":8},{"critere":"Pas de zu après un modal et un verbe de mouvement","points":6},{"critere":"zu intercalé en un seul mot : aufzustehen, einzukaufen","points":6}],"dureeMin":6,"corrige":"**Réponses**\n\n1. *Ich versuche, pünktlich zu sein.* — *versuchen* appelle *zu*.\n2. *Ich kann gut schwimmen.* — **pas** de *zu* après un modal.\n3. *Er hat keine Lust, ins Kino zu gehen.* — *Lust haben* appelle *zu*.\n4. *Wir gehen heute schwimmen.* — **pas** de *zu* après un verbe de mouvement.\n5. *Es ist wichtig, früh aufzustehen.* — avec un préverbe séparable, *zu* s'intercale entre le préverbe et le radical, en **un seul mot**.\n6. *Vergiss nicht, Brot einzukaufen.* — même règle : *einzukaufen*.\n\nÀ retenir : *zu* se place juste devant l'infinitif, en fin de groupe ; les modaux, *sehen*, *hören*, *lassen* et les verbes de mouvement le refusent."}$exo$::jsonb),
  ('5c40007f-ccb0-5043-9b02-006edf5845e2'::uuid, 2, 'traduction', $exo${"titre":"But, privation, substitution","consigne":"Relie chaque paire de phrases avec um… zu, damit, ohne… zu ou statt… zu, selon l'indication.","enonce":"**Relie les phrases.**\n\n1. Ich spare Geld. Ich will ein Fahrrad kaufen. (*but*)\n2. Ich erkläre es dir. Du verstehst es. (*but*)\n3. Er geht weg. Er sagt nichts. (*privation : « sans »*)\n4. Sie sieht fern. Sie sollte arbeiten. (*substitution : « au lieu de »*)\n5. Ich stehe früh auf. Ich rufe meine Oma an. (*but*)","bareme":[{"critere":"Choix du bon outil pour chaque phrase","points":6},{"critere":"damit quand le sujet change (phrase 2) avec verbe final","points":5},{"critere":"zu bien placé, dont anzurufen en un seul mot","points":5},{"critere":"Virgule obligatoire devant chaque groupe","points":4}],"dureeMin":11,"corrige":"**Phrases attendues**\n\n1. *Ich spare Geld, um ein Fahrrad zu kaufen.*\n2. *Ich erkläre es dir, damit du es verstehst.*\n3. *Er geht weg, ohne etwas zu sagen.*\n4. *Sie sieht fern, statt zu arbeiten.* (*anstatt* accepté)\n5. *Ich stehe früh auf, um meine Oma anzurufen.*\n\nPoints attendus :\n- *um… zu* exige que les deux propositions aient le **même sujet** (phrases 1 et 5).\n- Phrase 2 : le sujet change (*ich* / *du*) → *damit*, subordonnée avec le verbe à la fin (*verstehst*).\n- Phrase 3 : « ne rien dire » → *ohne etwas zu sagen* (« sans rien dire »).\n- Phrase 5 : *anrufen* est séparable → *anzurufen*.\n- Virgule obligatoire devant *um… zu*, *ohne… zu*, *statt… zu* et *damit*. Le groupe infinitif n'a jamais de sujet propre."}$exo$::jsonb),
  ('5c40007f-ccb0-5043-9b02-006edf5845e2'::uuid, 3, 'traduction', $exo${"titre":"Thème : six groupes infinitifs","consigne":"Traduis les six phrases en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. J'ai beaucoup à faire.\n2. Ce travail doit être fait aujourd'hui. (*utilise sein + zu*)\n3. Il est parti sans fermer la porte.\n4. J'apprends l'allemand pour pouvoir parler avec ma correspondante.\n5. Mes parents travaillent pour que nous puissions partir en vacances.\n6. J'ai envie d'aller nager.\n\n*Aide : tun ; die Arbeit ; gehen (ist gegangen) ; die Tür schließen ; die Brieffreundin ; in Urlaub fahren ; Lust haben ; schwimmen gehen.*\n\n**2.** Explique en français pourquoi tu as employé *um… zu* dans la phrase 4 et *damit* dans la phrase 5.","bareme":[{"critere":"haben + zu et sein + zu justes (phrases 1 et 2)","points":4},{"critere":"ohne… zu et Lust haben… zu construits correctement","points":4},{"critere":"um… zu avec modal et damit avec verbe final","points":5},{"critere":"Virgules et place de zu","points":3},{"critere":"Explication juste um… zu / damit (même sujet ou non)","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n1. *Ich habe viel zu tun.* — *haben* + *zu* : valeur active (avoir à faire).\n2. *Diese Arbeit ist heute zu machen.* — *sein* + *zu* : valeur passive (doit être fait).\n3. *Er ist gegangen, ohne die Tür zu schließen.*\n4. *Ich lerne Deutsch, um mit meiner Brieffreundin sprechen zu können.*\n5. *Meine Eltern arbeiten, damit wir in Urlaub fahren können.*\n6. *Ich habe Lust, schwimmen zu gehen.*\n\nPoints attendus : virgule devant *ohne… zu*, *um… zu*, *damit* ; *zu* juste devant le dernier infinitif (*sprechen zu können*, *schwimmen zu gehen*) ; dans la phrase 5, le modal *können* ferme la subordonnée.\n\n**2.** Phrase 4 : le sujet est le même dans les deux propositions (*ich* apprend, *ich* veux parler) → groupe infinitif *um… zu*. Phrase 5 : le sujet change (*meine Eltern* travaillent, *wir* partons) → *um… zu* est impossible, il faut une subordonnée avec *damit* et un sujet exprimé."}$exo$::jsonb),
  ('0b721c74-364b-580f-bbdd-2330179abf8b'::uuid, 1, 'traduction', $exo${"titre":"Der, die ou das ?","consigne":"Donne l'article défini et l'article indéfini de chaque nom, puis justifie trois de tes réponses par un repère de genre.","enonce":"**1. Donne l'article défini et l'article indéfini (nominatif singulier).**\n\nMädchen · Zeitung · Montag · Freiheit · Lehrer · Essen · Frühling · Päckchen\n\n**2.** Pour *Mädchen*, *Zeitung* et *Montag*, donne en une phrase le repère qui permet de trouver le genre.","bareme":[{"critere":"Articles définis justes (der, die, das)","points":8},{"critere":"Articles indéfinis justes (ein, eine)","points":4},{"critere":"Repères de genre justes pour les trois noms","points":8}],"dureeMin":7,"corrige":"**1. Réponses**\n\n- *das Mädchen / ein Mädchen*\n- *die Zeitung / eine Zeitung*\n- *der Montag / ein Montag*\n- *die Freiheit / eine Freiheit*\n- *der Lehrer / ein Lehrer*\n- *das Essen / ein Essen*\n- *der Frühling / ein Frühling*\n- *das Päckchen / ein Päckchen*\n\n**2.** Repères :\n- *Mädchen* : tous les diminutifs en *-chen* et *-lein* sont **neutres** — la grammaire l'emporte sur le sens (même chose pour *Päckchen*).\n- *Zeitung* : les noms en *-ung* sont **féminins** (comme ceux en *-heit* : *Freiheit*).\n- *Montag* : les jours, mois et saisons sont **masculins** (comme *Frühling*, qui se termine aussi en *-ling*).\nAutres repères acceptés : *Lehrer* en *-er* masculin ; *Essen* infinitif substantivé neutre."}$exo$::jsonb),
  ('0b721c74-364b-580f-bbdd-2330179abf8b'::uuid, 2, 'traduction', $exo${"titre":"Article ou pas d'article ?","consigne":"Complète le texte avec l'article qui convient, ou avec Ø quand il n'en faut pas. Puis réponds à la question 2.","enonce":"**1. Complète le texte.**\n\n> Mein Vater ist ___ Lehrer. ___ Schule, in der er arbeitet, ist groß. Am Morgen trinkt er ___ Kaffee. ___ Mädchen neben ihm ist meine Schwester. Sie hat ___ Katze. ___ Katze heißt Mimi. Im Sommer fahren wir nach ___ Deutschland. Im Garten spielen ___ Kinder.\n\n*(Kinder : des enfants, sens indéfini.)*\n\n**2.** Dans *Das ist meine Schwester*, *das* est-il un article ? Explique.","bareme":[{"critere":"Genres justes des articles (Die Schule, Das Mädchen, eine / Die Katze)","points":6},{"critere":"Absence d'article : métier, matière, nom de pays","points":6},{"critere":"Pas d'article indéfini au pluriel","points":3},{"critere":"Explication de das démonstratif invariable","points":5}],"dureeMin":10,"corrige":"**1. Texte complété**\n\n> *Mein Vater ist Ø Lehrer. Die Schule, in der er arbeitet, ist groß. Am Morgen trinkt er Ø Kaffee. Das Mädchen neben ihm ist meine Schwester. Sie hat eine Katze. Die Katze heißt Mimi. Im Sommer fahren wir nach Ø Deutschland. Im Garten spielen Ø Kinder.*\n\nPoints attendus :\n- Métier après *sein* : pas d'article (*Er ist Lehrer*).\n- Nom de matière : pas d'article (*Kaffee*, « du café »).\n- La plupart des noms de pays : pas d'article (*nach Deutschland*).\n- *ein* n'a **pas de pluriel** : « des enfants » = *Kinder*.\n- *das Mädchen* est neutre (-chen) ; *die Schule*, *die Katze* féminins.\n\n**2.** Non : dans *Das ist meine Schwester*, *das* est un **démonstratif invariable** (« ça, c'est ma sœur »). Il ne s'accorde à rien, même si *Schwester* est féminin ; un article serait suivi d'un nom qu'il détermine."}$exo$::jsonb),
  ('0b721c74-364b-580f-bbdd-2330179abf8b'::uuid, 3, 'traduction', $exo${"titre":"Thème : genres et pièges","consigne":"Traduis les phrases en allemand, puis justifie trois de tes choix.","enonce":"**1. Traduis en allemand.**\n\n1. La jeune fille est ma cousine.\n2. Elle est étudiante.\n3. Le soleil brille, la lune est invisible.\n4. Une journée à Berlin coûte cher.\n5. Des enfants jouent dans la rue.\n6. Ça, c'est la solution !\n\n*Aide : Mädchen ; die Cousine ; die Studentin ; Sonne ; Mond ; scheinen ; unsichtbar ; Tag ; teuer sein ; auf der Straße ; Lösung.*\n\n**2.** Justifie en français : l'article de *Mädchen*, l'absence d'article devant *Studentin*, et l'article de *Lösung*.","bareme":[{"critere":"Genres justes : das Mädchen, die Sonne, der Mond, die Lösung","points":6},{"critere":"Absence d'article : métier après sein, indéfini pluriel","points":4},{"critere":"Das démonstratif invariable et ein Tag","points":3},{"critere":"Phrases correctes (verbe, accord, ordre)","points":2},{"critere":"Trois justifications justes","points":5}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n\n1. *Das Mädchen ist meine Cousine.*\n2. *Sie ist Studentin.*\n3. *Die Sonne scheint, der Mond ist unsichtbar.*\n4. *Ein Tag in Berlin ist teuer.*\n5. *Kinder spielen auf der Straße.*\n6. *Das ist die Lösung!*\n\nPoints attendus :\n- *die Sonne* (le soleil) et *der Mond* (la lune) : genres inverses du français.\n- *Sie ist Studentin* : pas d'article devant un métier ou un statut après *sein*.\n- « Des enfants » : pas d'article indéfini au pluriel.\n- *Das ist…* : démonstratif invariable.\n- *Sie* reprend *das Mädchen* : accepté aussi, car il s'agit d'une personne ; *es* est grammaticalement possible.\n\n**2.** *das Mädchen* : tous les diminutifs en *-chen* sont neutres. *Studentin* : après *sein*, un métier ou un statut s'emploie sans article (« elle est **une** étudiante » ne se dit pas). *die Lösung* : les noms en *-ung* sont féminins."}$exo$::jsonb),
  ('a6ba17af-0e6b-5120-b425-98e1e8f102c3'::uuid, 1, 'traduction', $exo${"titre":"Le bon cas, la bonne forme","consigne":"Complète avec la forme correcte du déterminant entre parenthèses.","enonce":"**Complète.**\n\n1. Ich sehe ___ (der) Mann.\n2. Ich helfe ___ (die) Frau.\n3. Ich gebe ___ (das) Kind ein Buch.\n4. Er kauft ___ (ein) Hund.\n5. Das ist das Auto ___ (der) Vater___.\n6. Wir spielen mit ___ (die, pluriel) Kinder___.","bareme":[{"critere":"Accusatifs justes (den, einen)","points":5},{"critere":"Datifs justes (der, dem, den)","points":8},{"critere":"Génitif des Vaters avec -s","points":4},{"critere":"-n du datif pluriel : Kindern","points":3}],"dureeMin":7,"corrige":"**Réponses**\n\n1. *Ich sehe den Mann.* — COD masculin → accusatif *den*.\n2. *Ich helfe der Frau.* — *helfen* : datif féminin *der*.\n3. *Ich gebe dem Kind ein Buch.* — COI neutre → datif *dem*.\n4. *Er kauft einen Hund.* — COD masculin → *einen*.\n5. *Das ist das Auto des Vaters.* — complément du nom → génitif *des*, et le nom masculin prend *-s*.\n6. *Wir spielen mit den Kindern.* — *mit* + datif ; au datif pluriel, l'article est *den* **et** le nom prend *-n*.\n\nRappel : le masculin est le seul genre qui change entre nominatif et accusatif (*der → den*, *ein → einen*)."}$exo$::jsonb),
  ('a6ba17af-0e6b-5120-b425-98e1e8f102c3'::uuid, 2, 'traduction', $exo${"titre":"Possessifs et déterminants en der-","consigne":"Complète chaque phrase, puis indique le cas du groupe complété et sa fonction.","enonce":"**Complète, puis donne le cas et la fonction.**\n\n1. Ich besuche ___ (mein) Großvater.\n2. Ich schenke ___ (meine) Mutter Blumen.\n3. ___ (dieser) Film gefällt mir.\n4. Kennst du ___ (diese) Frau?\n5. ___ (jeder) Kind bekommt ein Geschenk.\n6. Ich spreche mit ___ (unsere, pluriel) Nachbarn.","bareme":[{"critere":"Formes justes des six déterminants","points":10},{"critere":"Cas et fonction correctement identifiés","points":6},{"critere":"Orthographe des terminaisons et des noms","points":4}],"dureeMin":11,"corrige":"**Réponses**\n\n1. *meinen Großvater* — accusatif, COD de *besuchen* ; le possessif se décline comme *ein* : *meinen*.\n2. *meiner Mutter* — datif, COI (on offre **à** sa mère).\n3. *Dieser Film* — nominatif, sujet de *gefällt*.\n4. *diese Frau* — accusatif, COD ; au féminin, accusatif = nominatif.\n5. *Jedes Kind* — nominatif, sujet ; *jeder* prend les terminaisons de l'article défini (*das* → *jedes*).\n6. *unseren Nachbarn* — datif pluriel après *mit* ; *unser* garde son e.\n\nRappel : *kein* et les possessifs se déclinent comme *ein* ; *dieser*, *jeder*, *welcher* comme l'article défini."}$exo$::jsonb),
  ('a6ba17af-0e6b-5120-b425-98e1e8f102c3'::uuid, 3, 'traduction', $exo${"titre":"Thème : les quatre cas en action","consigne":"Traduis les cinq phrases en allemand, puis indique le cas de chaque groupe nominal souligné.","enonce":"**1. Traduis en allemand.**\n\n1. Le frère de **mon amie** offre un livre à **son père**.\n2. Je n'ai pas de **voiture**.\n3. Nous parlons avec **les voisins**.\n4. **Chaque élève** connaît **ce professeur**.\n5. La maison de **la famille** est grande.\n\n*Aide : die Freundin ; schenken ; sein Vater ; das Auto ; der Nachbar (pluriel die Nachbarn) ; der Schüler ; der Lehrer ; die Familie.*\n\n**2.** Donne le cas des sept groupes en gras et justifie-le par leur fonction.","bareme":[{"critere":"Nominatifs et accusatifs justes (kein Auto, diesen Lehrer)","points":4},{"critere":"Datifs justes (seinem Vater, den Nachbarn)","points":5},{"critere":"Génitifs justes (meiner Freundin, der Familie)","points":5},{"critere":"Déterminants en der- et kein bien déclinés","points":3},{"critere":"Cas identifiés et justifiés par la fonction","points":3}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n1. *Der Bruder meiner Freundin schenkt seinem Vater ein Buch.*\n2. *Ich habe kein Auto.*\n3. *Wir sprechen mit den Nachbarn.*\n4. *Jeder Schüler kennt diesen Lehrer.*\n5. *Das Haus der Familie ist groß.*\n\n**2. Cas des groupes en gras**\n- *meiner Freundin* : **génitif** féminin, complément du nom *Bruder*.\n- *seinem Vater* : **datif**, COI de *schenken*.\n- *kein Auto* : **accusatif** neutre, COD (même forme qu'au nominatif).\n- *den Nachbarn* : **datif pluriel** après *mit* (le nom a déjà son -n).\n- *Jeder Schüler* : **nominatif**, sujet.\n- *diesen Lehrer* : **accusatif** masculin, COD — *dieser* prend les terminaisons de l'article.\n- *der Familie* : **génitif** féminin, complément du nom *Haus* ; au féminin, pas de marque sur le nom."}$exo$::jsonb),
  ('41574001-1a64-565f-b3f3-6308e6006bfa'::uuid, 1, 'traduction', $exo${"titre":"Remplacer par un pronom","consigne":"Remplace le groupe en gras par le pronom personnel qui convient.","enonce":"**Remplace le groupe en gras par un pronom.**\n\n1. **Der Tisch** ist alt.\n2. Ich sehe **den Lehrer**.\n3. Ich helfe **meiner Schwester**.\n4. **Die Lampe** ist neu.\n5. Wir danken **den Eltern**.\n6. Ich kaufe **das Buch**.","bareme":[{"critere":"Genre grammatical conservé (er pour der Tisch, sie pour die Lampe)","points":8},{"critere":"Cas juste : ihn, ihr, ihnen, es","points":8},{"critere":"Phrases correctement recopiées (majuscule, ordre)","points":4}],"dureeMin":6,"corrige":"**Réponses**\n\n1. *Er ist alt.* — *der Tisch* est masculin → *er*, même pour un objet.\n2. *Ich sehe ihn.* — masculin, COD → accusatif *ihn*.\n3. *Ich helfe ihr.* — féminin, *helfen* régit le datif → *ihr*.\n4. *Sie ist neu.* — *die Lampe* est féminin → *sie*.\n5. *Wir danken ihnen.* — pluriel, *danken* régit le datif → *ihnen*.\n6. *Ich kaufe es.* — neutre, COD → *es*.\n\nRègle : le pronom garde le **genre grammatical** du nom et prend le **cas** de sa fonction. Traduire mécaniquement une chose par *es* est une faute : en allemand, une table est « il »."}$exo$::jsonb),
  ('41574001-1a64-565f-b3f3-6308e6006bfa'::uuid, 2, 'traduction', $exo${"titre":"Deux pronoms dans la phrase","consigne":"Remplace les deux compléments par des pronoms (phrases 1 à 3), puis traduis les phrases 4 et 5.","enonce":"**Remplace les deux compléments par des pronoms.**\n\n1. Ich gebe dem Kind das Buch.\n2. Er schenkt seiner Mutter die Blumen.\n3. Wir zeigen den Gästen das Haus.\n\n**Traduis.**\n\n4. Hier, mon père m'a appelé. (*commence par Gestern ; anrufen*)\n5. Je vous remercie, Monsieur Braun. (*vouvoiement ; danken + datif*)","bareme":[{"critere":"Formes des pronoms justes (es, ihm, sie, ihr, ihnen, mich)","points":6},{"critere":"Ordre des deux pronoms : accusatif puis datif","points":6},{"critere":"Pronom placé juste après le verbe, avant le sujet nominal","points":4},{"critere":"Ihnen de politesse avec majuscule","points":4}],"dureeMin":10,"corrige":"1. *Ich gebe es ihm.*\n2. *Er schenkt sie ihr.*\n3. *Wir zeigen es ihnen.*\n4. *Gestern hat mich mein Vater angerufen.*\n5. *Ich danke Ihnen, Herr Braun.*\n\nPoints attendus :\n- Avec deux groupes nominaux, l'ordre est datif puis accusatif ; avec deux **pronoms**, c'est **accusatif puis datif** : *es ihm*, *sie ihr*, *es ihnen*. *Ich gebe ihm es* est faux.\n- *das Buch* → *es* ; *die Blumen* (pluriel) → *sie* ; *seiner Mutter* → *ihr* ; *den Gästen* → *ihnen*.\n- Phrase 4 : les pronoms remontent juste après le verbe conjugué ; en cas d'inversion, le pronom *mich* peut précéder le sujet nominal *mein Vater*.\n- Phrase 5 : *Sie* de politesse → datif *Ihnen*, toujours avec majuscule."}$exo$::jsonb),
  ('41574001-1a64-565f-b3f3-6308e6006bfa'::uuid, 3, 'traduction', $exo${"titre":"Une lettre à Anna","consigne":"Traduis la lettre en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n> Chère Anna, merci pour ta lettre ! Je l'ai lue hier. Mon frère te salue. Il a un nouveau vélo : il est rouge. Mes parents t'invitent : tu peux venir chez nous en été. Est-ce que tu veux leur écrire ?\n\n*Aide : Liebe Anna ; danke für + accusatif ; der Brief ; lesen (gelesen) ; grüßen ; ein neues Fahrrad ; einladen (séparable) ; zu uns ; im Sommer ; schreiben + datif.*\n\n**2.** Explique en français pourquoi « je **l'**ai lue » se traduit par *ihn* et « **il** est rouge » par *es*.","bareme":[{"critere":"Pronoms reprenant le genre du nom : ihn (Brief), es (Fahrrad)","points":5},{"critere":"Cas justes : dich, ihnen, uns","points":5},{"critere":"Place des pronoms et du préverbe ein en fin de phrase","points":3},{"critere":"Phrases correctes (verbes, possessifs, ponctuation)","points":3},{"critere":"Explication juste du choix ihn / es","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n> *Liebe Anna, danke für deinen Brief! Ich habe ihn gestern gelesen. Mein Bruder grüßt dich. Er hat ein neues Fahrrad: Es ist rot. Meine Eltern laden dich ein: Du kannst im Sommer zu uns kommen. Willst du ihnen schreiben?*\n\nPoints attendus :\n- *deinen Brief* : *für* + accusatif, masculin.\n- *ihn* : reprend *der Brief* (masculin), COD → accusatif.\n- *dich* : COD de *grüßen* et de *einladen* ; le préverbe *ein* ferme la phrase.\n- *es* : reprend *das Fahrrad* (neutre), sujet.\n- *ihnen* : datif pluriel (« à eux »), COI de *schreiben* ; minuscule, car ce n'est pas le vouvoiement.\n- Majuscule au début de la phrase après les deux-points (*Es ist rot*, *Du kannst*) acceptée ou minuscule tolérée.\n\n**2.** Le pronom allemand garde le **genre grammatical** du nom qu'il remplace, pas celui du français. *Der Brief* (la lettre) est masculin : on le reprend par *ihn* à l'accusatif. *Das Fahrrad* (le vélo) est neutre : on le reprend par *es*."}$exo$::jsonb),
  ('65318149-e09d-5271-a9c8-888224569afe'::uuid, 1, 'traduction', $exo${"titre":"Dieser, et das ou dass","consigne":"Complète les phrases 1 à 5 avec la bonne forme de dieser, puis les phrases 6 et 7 avec das ou dass.","enonce":"**Complète avec dieser à la bonne forme.**\n\n1. ___ Mann ist mein Nachbar.\n2. Ich kenne ___ Frau nicht.\n3. Ich wohne in ___ Haus.\n4. Kaufst du ___ Rock? (*der Rock*)\n5. Das Auto ___ Mannes ist neu.\n\n**Complète avec das ou dass.**\n\n6. Ich glaube, ___ er kommt.\n7. ___ ist mein Bruder.","bareme":[{"critere":"Formes de dieser justes selon genre et cas","points":12},{"critere":"Choix juste entre das et dass","points":8}],"dureeMin":6,"corrige":"**Réponses**\n\n1. *Dieser Mann* — nominatif masculin.\n2. *diese Frau* — accusatif féminin.\n3. *in diesem Haus* — datif neutre (lieu où l'on est).\n4. *diesen Rock* — accusatif masculin.\n5. *dieses Mannes* — génitif masculin.\n6. *Ich glaube, dass er kommt.* — conjonction qui introduit une subordonnée.\n7. *Das ist mein Bruder.* — démonstratif invariable.\n\nPoints attendus : *dieser* se décline comme l'article défini (*der → dieser*, *den → diesen*, *dem → diesem*, *des → dieses*). Test pour *das* / *dass* : si l'on peut remplacer par *dieses*, c'est *das* avec un seul s ; sinon, c'est la conjonction *dass*."}$exo$::jsonb),
  ('65318149-e09d-5271-a9c8-888224569afe'::uuid, 2, 'traduction', $exo${"titre":"Celui-là, le même","consigne":"Réponds aux cinq questions.","enonce":"**Complète la réponse avec le démonstratif accentué.**\n\n1. — Kennst du Peter? — Ja, ___ kenne ich gut!\n2. — Magst du die Lehrerin? — Ja, ___ mag ich.\n3. — Hilfst du den Nachbarn? — Ja, ___ helfe ich gern.\n\n4. Réécris pour dire clairement qu'il s'agit du frère **de Paul** : *Ich traf Paul und seinen Bruder.*\n5. Traduis : « Nous habitons dans la même maison. » et « Elle a la même robe que moi. » Explique en une phrase pourquoi tu n'emploies pas le même mot.","bareme":[{"critere":"Démonstratifs accentués justes (den, die, denen)","points":6},{"critere":"Emploi de dessen pour lever l'ambiguïté","points":4},{"critere":"derselbe décliné et der gleiche employés à bon escient","points":6},{"critere":"Explication juste : identique ou semblable","points":4}],"dureeMin":10,"corrige":"1. *Den kenne ich gut!* — masculin, COD → *den*.\n2. *Die mag ich.* — féminin, COD → *die*.\n3. *Denen helfe ich gern.* — pluriel, *helfen* + datif → *denen* (forme propre au démonstratif).\n4. *Ich traf Paul und dessen Bruder.* — *dessen* désigne sans équivoque le frère de Paul (*seinen* pouvait renvoyer au sujet).\n5. *Wir wohnen in demselben Haus.* / *Sie hat das gleiche Kleid wie ich.*\n\nExplication : *derselbe* désigne un objet **identique**, unique (une seule maison) ; *der gleiche* désigne un objet **semblable** (deux robes pareilles). Dans *derselbe*, les deux morceaux se déclinent : *dem-* comme l'article (datif après *in*), *-selben* comme un adjectif faible."}$exo$::jsonb),
  ('65318149-e09d-5271-a9c8-888224569afe'::uuid, 3, 'traduction', $exo${"titre":"Dialogue dans la cour","consigne":"Traduis ce dialogue en allemand en employant les démonstratifs, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n— Tu vois ce garçon ?\n— Celui-là ? Je le connais : c'est le frère de Lisa.\n— Et la jeune fille à côté de lui ?\n— Celle-là, je ne la connais pas. Mais Lisa et sa sœur (la sœur de Lisa) habitent dans la même rue que moi.\n— Ce sont mes amies !\n\n*Aide : der Junge (accusatif den Jungen) ; das Mädchen ; neben + datif ; die Straße ; die Freundin.*\n\n**2.** Explique en français ton choix de *das* pour « celle-là » et de *deren* pour « sa sœur ».","bareme":[{"critere":"dieser et démonstratifs accentués justes (diesen, den, das)","points":5},{"critere":"deren pour lever l'ambiguïté sur la sœur","points":3},{"critere":"derselben Straße décliné au datif","points":3},{"critere":"Das sind … : verbe accordé avec ce qui suit","points":3},{"critere":"Justification de das et de deren","points":6}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n— *Siehst du diesen Jungen?*\n— *Den da? Den kenne ich: Das ist der Bruder von Lisa.* (*Lisas Bruder* accepté)\n— *Und das Mädchen neben ihm?*\n— *Das kenne ich nicht. Aber Lisa und deren Schwester wohnen in derselben Straße wie ich.*\n— *Das sind meine Freundinnen!*\n\nPoints attendus :\n- *diesen Jungen* : accusatif masculin ; *Den* : démonstratif accentué, masculin accusatif.\n- *Das ist…* et *Das sind…* : *das* invariable, le verbe s'accorde avec ce qui suit (*sind* devant un pluriel).\n- *in derselben Straße* : lieu où l'on est → datif, *der-* + *-selben*.\n- *neben ihm* : datif (localisation).\n\n**2.** *Das* : le démonstratif reprend le genre du nom ; *Mädchen* est **neutre**, donc *das* à l'accusatif, même s'il s'agit d'une fille. *deren* : génitif féminin du démonstratif, il renvoie sans équivoque à Lisa ; *ihre Schwester* serait possible mais moins précis dans une phrase à plusieurs personnes. C'est un usage soigné, apprécié à l'écrit."}$exo$::jsonb),
  ('8cae8614-321f-5290-bd1f-f11f5b8e14d2'::uuid, 1, 'traduction', $exo${"titre":"Huit pluriels","consigne":"Donne le pluriel de chaque nom avec son article, puis indique pour trois d'entre eux le schéma de pluriel.","enonce":"**1. Donne le pluriel avec l'article.**\n\nder Tag · das Kind · die Frau · der Lehrer · das Auto · die Lehrerin · der Sohn · das Buch\n\n**2.** Pour *Frau*, *Lehrer* et *Auto*, nomme le schéma de pluriel (terminaison ajoutée ou absence de terminaison).","bareme":[{"critere":"Huit pluriels justes, Umlaut compris","points":14},{"critere":"Article die au pluriel pour tous les noms","points":2},{"critere":"Schémas justes pour les trois noms","points":4}],"dureeMin":6,"corrige":"**1. Pluriels**\n\n- *die Tage* (-e)\n- *die Kinder* (-er)\n- *die Frauen* (-en)\n- *die Lehrer* (aucune terminaison)\n- *die Autos* (-s)\n- *die Lehrerinnen* (-nen : le n est doublé)\n- *die Söhne* (-e avec Umlaut)\n- *die Bücher* (-er avec Umlaut)\n\nAu pluriel, l'article défini est **die** pour les trois genres.\n\n**2.** *Frau* : schéma en **-(e)n**, celui de presque tous les féminins, sans inflexion. *Lehrer* : **aucune terminaison** (masculin en -er). *Auto* : **-s**, schéma des emprunts et abréviations."}$exo$::jsonb),
  ('8cae8614-321f-5290-bd1f-f11f5b8e14d2'::uuid, 2, 'traduction', $exo${"titre":"Tout au pluriel","consigne":"Mets chaque phrase entièrement au pluriel (sujet, verbe et complément).","enonce":"**Mets au pluriel.**\n\n1. Das Kind spielt mit dem Ball.\n2. Die Zeitung liegt auf dem Tisch.\n3. Der Lehrer spricht mit der Schülerin.\n4. Das Auto steht vor dem Haus.\n\n*Aide : der Ball → die Bälle ; der Tisch → die Tische ; das Haus → die Häuser ; die Schülerin → die Schülerinnen.*","bareme":[{"critere":"Pluriels des noms justes","points":8},{"critere":"-n du datif pluriel ajouté, sauf après -s (Autos)","points":6},{"critere":"Verbes accordés et articles die / den justes","points":6}],"dureeMin":11,"corrige":"**Phrases attendues**\n\n1. *Die Kinder spielen mit den Bällen.*\n2. *Die Zeitungen liegen auf den Tischen.*\n3. *Die Lehrer sprechen mit den Schülerinnen.*\n4. *Die Autos stehen vor den Häusern.*\n\nPoints attendus :\n- Sujets au pluriel avec *die* : *Kinder*, *Zeitungen*, *Lehrer* (sans terminaison), *Autos*.\n- Verbes à la 3e personne du pluriel : *spielen*, *liegen*, *sprechen*, *stehen*.\n- Datif pluriel : article *den*, et le nom prend **-n** s'il n'en a pas déjà un : *Bällen*, *Tischen*, *Häusern* ; *Schülerinnen* et *Zeitungen* finissent déjà par n.\n- Exception : pas de -n après un pluriel en -s (*mit den Autos*)."}$exo$::jsonb),
  ('8cae8614-321f-5290-bd1f-f11f5b8e14d2'::uuid, 3, 'traduction', $exo${"titre":"Thème : singuliers et pluriels trompeurs","consigne":"Traduis les phrases en allemand, puis explique trois pièges.","enonce":"**1. Traduis en allemand.**\n\n1. Mon père porte des lunettes.\n2. Les enfants jouent avec les chats des voisins.\n3. La police arrive avec deux voitures.\n4. Les fruits sont frais.\n5. Les gens sont gentils.\n\n*Aide : tragen ; die Katze ; der Nachbar (pluriel die Nachbarn) ; kommen ; das Auto ; frisch ; nett.*\n\n**2.** Explique en français les trois pièges des phrases 1, 3 et 4.","bareme":[{"critere":"eine Brille et das Obst au singulier, verbe accordé","points":5},{"critere":"Pluriels justes : Kinder, Katzen, Nachbarn, Autos, Leute","points":5},{"critere":"Datif pluriel et génitif pluriel corrects","points":4},{"critere":"Explication des trois pièges","points":6}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n\n1. *Mein Vater trägt eine Brille.*\n2. *Die Kinder spielen mit den Katzen der Nachbarn.*\n3. *Die Polizei kommt mit zwei Autos.*\n4. *Das Obst ist frisch.*\n5. *Die Leute sind nett.*\n\nPoints attendus :\n- *mit den Katzen* : datif pluriel (le nom finit déjà par n) ; *der Nachbarn* : génitif pluriel (article *der*).\n- *die Leute* n'existe qu'au pluriel : verbe *sind*.\n- *die Polizei* est un singulier : verbe *kommt*.\n\n**2. Les pièges**\n- Phrase 1 : l'allemand met au **singulier** ce que le français met au pluriel : « des lunettes » = *eine Brille*.\n- Phrase 3 : *Autos* est un pluriel en -s : au datif pluriel, il ne prend **pas** de -n (*mit zwei Autos*).\n- Phrase 4 : *das Obst* n'existe qu'au singulier : « les fruits sont » → *das Obst ist*."}$exo$::jsonb),
  ('e2bff273-a6cc-5595-8dc6-22a8f6168ae5'::uuid, 1, 'traduction', $exo${"titre":"L'attribut ne bouge pas","consigne":"Corrige l'erreur de chaque phrase, puis réponds à la question 2.","enonce":"**1. Corrige chaque phrase.**\n\n1. Die Frau ist alte.\n2. Das Wetter ist schönes.\n3. Die Kinder sind müden.\n4. Das Haus wird großes.\n5. Er singt schöne.\n\n**2.** Dans *Ein alter Mann ist gekommen* et *Der Mann ist alt*, pourquoi l'adjectif n'a-t-il pas la même forme ?","bareme":[{"critere":"Cinq phrases corrigées avec l'adjectif à sa forme nue","points":12},{"critere":"Explication juste : épithète déclinée, attribut invariable","points":8}],"dureeMin":6,"corrige":"**1. Phrases corrigées**\n\n1. *Die Frau ist alt.*\n2. *Das Wetter ist schön.*\n3. *Die Kinder sind müde.* (*müde* se termine déjà par e : c'est sa forme nue)\n4. *Das Haus wird groß.*\n5. *Er singt schön.* — ici, *schön* est un **adverbe** : l'allemand n'a pas de terminaison d'adverbe, le mot reste invariable.\n\nAprès *sein*, *werden* et *bleiben*, l'adjectif attribut reste à sa forme nue : ni -e, ni -er, rien.\n\n**2.** Tout dépend de la **place** de l'adjectif. Dans *Ein alter Mann*, il est **épithète** (devant le nom) : il se décline toujours. Dans *Der Mann ist alt*, il est **attribut** (après le verbe *sein*) : il ne se décline jamais."}$exo$::jsonb),
  ('e2bff273-a6cc-5595-8dc6-22a8f6168ae5'::uuid, 2, 'traduction', $exo${"titre":"Thème : attributs et adverbes","consigne":"Traduis les cinq phrases en allemand.","enonce":"**Traduis en allemand.**\n\n1. La maison est grande et belle.\n2. Ma sœur devient impatiente.\n3. Il chante bien.\n4. Je trouve ce film intéressant.\n5. Le train est plus rapide que la voiture.\n\n*Aide : das Haus ; ungeduldig ; singen ; schön ; der Film ; interessant ; der Zug ; schnell ; das Auto.*","bareme":[{"critere":"Adjectifs attributs invariables après sein et werden","points":8},{"critere":"Adverbe invariable (schön ou gut)","points":3},{"critere":"finden + COD + attribut invariable","points":4},{"critere":"Comparatif en -er suivi de als","points":5}],"dureeMin":10,"corrige":"**Traduction modèle**\n\n1. *Das Haus ist groß und schön.*\n2. *Meine Schwester wird ungeduldig.*\n3. *Er singt schön.* (*gut* accepté)\n4. *Ich finde diesen Film interessant.*\n5. *Der Zug ist schneller als das Auto.*\n\nPoints attendus :\n- Phrases 1 et 2 : l'attribut ne s'accorde pas, même au féminin (*ungeduldig*, pas *ungeduldige*).\n- Phrase 3 : l'allemand n'a pas de terminaison d'adverbe comme -ment : le même mot sert d'adjectif et d'adverbe.\n- Phrase 4 : *finden* + COD appelle un attribut, invariable ; *diesen Film* à l'accusatif.\n- Phrase 5 : la terminaison -er est la marque du **comparatif**, pas un accord ; « que » = *als*."}$exo$::jsonb),
  ('e2bff273-a6cc-5595-8dc6-22a8f6168ae5'::uuid, 3, 'traduction', $exo${"titre":"Le portrait de Klara","consigne":"À partir de la fiche, écris le portrait de Klara en six phrases. Emploie les adjectifs comme attributs (après sein, werden, bleiben) et au moins un comparatif. Puis réponds à la question 2.","enonce":"**1. Écris le portrait (six phrases).**\n\n**Fiche de Klara**\n- ta meilleure amie, 15 ans\n- grande et sportive\n- parfois impatiente\n- reste calme pendant les examens\n- chante bien\n- plus rapide que son frère\n\n*Aide : groß ; sportlich ; ungeduldig ; ruhig ; die Prüfung ; singen ; schnell ; der Bruder.*\n\n**2.** Un camarade écrit *Klara ist große*. Explique-lui son erreur en français.","bareme":[{"critere":"Attributs invariables après sein et bleiben","points":7},{"critere":"Adverbe invariable pour chanter","points":2},{"critere":"Comparatif avec als correct","points":3},{"critere":"Phrases correctes : verbe en 2e position, inversion","points":4},{"critere":"Explication juste de l'erreur","points":4}],"dureeMin":15,"corrige":"**1. Portrait modèle**\n\n*Meine beste Freundin heißt Klara. Sie ist fünfzehn Jahre alt. Sie ist groß und sportlich. Manchmal ist sie ungeduldig, aber in den Prüfungen bleibt sie ruhig. Sie singt schön. Sie ist schneller als ihr Bruder.*\n\nPoints attendus :\n- *groß*, *sportlich*, *ungeduldig*, *ruhig* : attributs après *sein* ou *bleiben* → forme nue, sans terminaison.\n- *singt schön* (ou *gut*) : adverbe invariable.\n- *schneller als* : comparatif en -er + *als*.\n- Inversion après *Manchmal* et *in den Prüfungen* (verbe en 2e position).\n- *Meine beste Freundin* : épithète déclinée devant le nom, acceptée.\n\n**2.** Après *sein*, l'adjectif est **attribut** : il ne se décline jamais, même quand le sujet est féminin. Il faut écrire *Klara ist groß*. La terminaison n'apparaît que si l'adjectif est placé **devant** le nom (*eine große Freundin*)."}$exo$::jsonb),
  ('c67f55af-d749-5c3e-8d7c-071159577f1c'::uuid, 1, 'traduction', $exo${"titre":"Les terminaisons de l'épithète","consigne":"Complète la terminaison de chaque adjectif.","enonce":"**Complète la terminaison (nominatif sauf indication).**\n\n1. der alt__ Mann\n2. ein alt__ Mann\n3. ein alt__ Haus\n4. mit dem neu__ Auto\n5. kalt__ Kaffee (sans déterminant)\n6. eine schön__ Blume\n\n*Rappel : der Mann, das Haus, das Auto, der Kaffee, die Blume.*","bareme":[{"critere":"Déclinaison faible après der / dem (-e, -en)","points":6},{"critere":"Déclinaison mixte après ein / eine (-er, -es, -e)","points":8},{"critere":"Déclinaison forte sans déterminant (-er)","points":6}],"dureeMin":7,"corrige":"**Réponses**\n\n1. *der alte Mann* — faible : *der* marque déjà le cas → -e.\n2. *ein alter Mann* — mixte : *ein* ne marque pas le masculin → l'adjectif prend -er.\n3. *ein altes Haus* — mixte : *ein* ne marque pas le neutre → -es.\n4. *mit dem neuen Auto* — faible au datif → -en.\n5. *kalter Kaffee* — forte : aucun déterminant, l'adjectif prend la marque de l'article (*der* → -er).\n6. *eine schöne Blume* — *eine* marque déjà le féminin → terminaison faible -e.\n\nPrincipe : la marque du cas apparaît **une fois** dans le groupe ; si le déterminant la porte, l'adjectif se contente de -e ou -en."}$exo$::jsonb),
  ('c67f55af-d749-5c3e-8d7c-071159577f1c'::uuid, 2, 'traduction', $exo${"titre":"Le nouvel ami","consigne":"Complète les terminaisons du texte, puis justifie deux de tes choix.","enonce":"**1. Complète les terminaisons.**\n\n> Ich habe einen neu__ Freund. Er wohnt in einem groß__ Haus mit einem schön__ Garten. Sein klein__ Bruder spielt mit einem rot__ Ball. Er hat ein teu__ Fahrrad (*teuer*). Morgen fahren wir mit dem neu__ Zug nach Berlin.\n\n*Rappel : der Freund, das Haus, der Garten, der Bruder, der Ball, das Fahrrad, der Zug.*\n\n**2.** Justifie en français la terminaison de *klein__ Bruder* et celle de *teu__ Fahrrad*.","bareme":[{"critere":"Terminaisons -en justes à l'accusatif et au datif","points":8},{"critere":"Nominatif masculin après sein : kleiner","points":3},{"critere":"Forme teures, sans le e de teuer","points":3},{"critere":"Faible après dem : neuen","points":3},{"critere":"Deux justifications justes","points":3}],"dureeMin":11,"corrige":"**1. Texte complété**\n\n> *Ich habe einen neuen Freund. Er wohnt in einem großen Haus mit einem schönen Garten. Sein kleiner Bruder spielt mit einem roten Ball. Er hat ein teures Fahrrad. Morgen fahren wir mit dem neuen Zug nach Berlin.*\n\nPoints attendus :\n- *einen neuen* (accusatif masculin), *einem großen*, *einem schönen*, *einem roten* (datif) : le déterminant marque le cas → -en.\n- *dem neuen Zug* : déclinaison faible au datif → -en.\n\n**2.** *kleiner Bruder* : *Bruder* est masculin et sujet (nominatif) ; le possessif *sein* se décline comme *ein* et ne marque rien au nominatif masculin → l'adjectif prend la marque -er. *teures Fahrrad* : *Fahrrad* est neutre, COD (accusatif) ; *ein* ne marque pas le neutre → -es ; et *teuer* perd son e devant la terminaison : *teures*, jamais *teueres*."}$exo$::jsonb),
  ('c67f55af-d749-5c3e-8d7c-071159577f1c'::uuid, 3, 'traduction', $exo${"titre":"Thème : le vieil homme de la montagne","consigne":"Traduis le texte en allemand, puis explique ta méthode pour deux groupes nominaux.","enonce":"**1. Traduis en allemand.**\n\n> Un vieil homme habite dans une petite maison au pied d'une haute montagne. Il boit du café froid et mange du bon pain. Sa fille porte une robe rose. Le vieil homme aime les longues promenades.\n\n*Aide : alt ; klein ; am Fuß + génitif ; hoch ; der Berg ; kalt ; gut ; das Brot ; die Tochter ; tragen ; rosa ; das Kleid ; lang ; der Spaziergang (pluriel die Spaziergänge) ; lieben.*\n\n**2.** Explique en français comment tu as trouvé la terminaison de *kalt…* devant *Kaffee* et la forme de *hoch* devant *Berg*.","bareme":[{"critere":"Déclinaisons mixte et faible justes (alter, kleinen, alte)","points":5},{"critere":"Déclinaison forte sans déterminant (kalten, gutes, lange)","points":5},{"critere":"Irréguliers et invariables : hohen, rosa","points":4},{"critere":"Méthode expliquée : cas et genre, puis déterminant","points":6}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n\n> *Ein alter Mann wohnt in einem kleinen Haus am Fuß eines hohen Berges. Er trinkt kalten Kaffee und isst gutes Brot. Seine Tochter trägt ein rosa Kleid. Der alte Mann liebt lange Spaziergänge.*\n\nPoints attendus :\n- *ein alter Mann* (nominatif, mixte) ; *einem kleinen Haus* (datif) ; *eines hohen Berges* (génitif) ; *der alte Mann* (faible).\n- *kalten Kaffee*, *gutes Brot*, *lange Spaziergänge* : aucun déterminant → déclinaison forte, terminaisons de l'article défini (*den*, *das*, *die*).\n- *hoch* perd son c : *hohen*.\n- *rosa* est invariable : *ein rosa Kleid*.\n- *an einem hohen Berg* accepté pour « au pied de ».\n\n**2.** Méthode : repérer d'abord le **cas et le genre**, puis regarder le déterminant. *Kaffee* est masculin, COD → accusatif ; il n'y a aucun déterminant, donc l'adjectif porte la marque de l'article *den* → *kalten*. *Berg* est masculin, au génitif après *eines*, qui marque déjà le cas → terminaison -en ; et *hoch* perd son c devant une terminaison → *hohen*."}$exo$::jsonb),
  ('5b05b29b-e67a-511e-b421-791e84f8f39c'::uuid, 1, 'traduction', $exo${"titre":"Sein ou ihr ?","consigne":"Complète chaque phrase avec le possessif qui convient, bien décliné, puis réponds à la question 2 en français.","enonce":"**1. Complète avec le possessif.**\n\n1. Anna besucht ___ Großmutter. *(sa grand-mère, à elle)*\n2. Peter ruft ___ Vater an. *(son père, à lui — accusatif)*\n3. Das Kind spielt mit ___ Hund. *(son chien — datif)*\n4. Wir fahren mit ___ Auto. *(notre voiture — datif, das Auto)*\n5. Die Kinder und ___ Eltern kommen heute. *(leurs parents)*\n6. Herr Klein, ist das ___ Buch? *(votre livre, politesse)*\n\n**2.** Explique en une ou deux phrases pourquoi on écrit *ihre* dans la phrase 1 et *seinen* dans la phrase 2.","bareme":[{"critere":"Radical juste selon le possesseur : ihr- (1, 5), sein- (2, 3), unser- (4), Ihr- avec majuscule (6)","points":8},{"critere":"Terminaisons justes selon l'objet possédé : ihre, seinen, seinem, unserem, ihre, Ihr","points":8},{"critere":"Explication : radical commandé par le possesseur, terminaison par le genre et le cas du nom","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Anna besucht **ihre** Großmutter. — possesseur féminin (Anna) → *ihr-* ; *Großmutter* féminin → *-e*.\n2. Peter ruft **seinen** Vater an. — possesseur masculin → *sein-* ; *Vater* masculin à l'accusatif → *-en*.\n3. Das Kind spielt mit **seinem** Hund. — *Kind* est neutre → *sein-* ; *mit* + datif masculin → *-em*.\n4. Wir fahren mit **unserem** Auto. — *unser* garde son e ; datif neutre → *-em*.\n5. Die Kinder und **ihre** Eltern kommen heute. — *ihr* = leur ; pluriel nominatif → *-e*.\n6. Herr Klein, ist das **Ihr** Buch? — vouvoiement → *Ihr* avec majuscule ; *Buch* neutre nominatif → pas de terminaison.\n\n**2.** Le **radical** dépend du **possesseur** : Anna est une femme → *ihr-*, Peter est un homme → *sein-*. La **terminaison** dépend du **nom possédé** : *Großmutter* est féminin → *ihre* ; *Vater* est masculin et COD (accusatif) → *seinen*. Le possessif se décline comme *ein* / *kein*."}$exo$::jsonb),
  ('5b05b29b-e67a-511e-b421-791e84f8f39c'::uuid, 2, 'traduction', $exo${"titre":"Léna présente sa famille","consigne":"Léna prépare une présentation de sa famille pour son correspondant allemand. Traduis ses phrases en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. Mon frère et sa copine habitent à Berlin.\n2. Ma sœur aime son chat.\n3. Nos voisins et leur fils viennent ce soir.\n4. Les enfants, où est votre professeur ?\n5. Les enfants, j'ai vu votre mère.\n6. Le matin, je me lave les mains.\n\n*Aide : die Freundin = la copine ; die Katze = le chat ; der Nachbar, die Nachbarn = le voisin ; der Sohn = le fils ; der Lehrer = le professeur ; ich habe … gesehen = j'ai vu ; heute Abend = ce soir ; morgens = le matin ; waschen = laver.*\n\n**2.** Dans les phrases 4 et 5, le possessif change de forme. Explique pourquoi.","bareme":[{"critere":"Radical sein- / ihr- choisi selon le possesseur (phrases 1, 2, 3)","points":6},{"critere":"Terminaisons justes selon le genre et le cas : seine, ihre, ihr Sohn, euer, eure","points":6},{"critere":"Phrase 6 construite avec le datif et l'article : mir die Hände","points":4},{"critere":"Explication : euer devient eur- devant une terminaison","points":4}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n\n1. *Mein Bruder und **seine** Freundin wohnen in Berlin.* — possesseur masculin → *sein-* ; *Freundin* féminin → *-e*.\n2. *Meine Schwester liebt **ihre** Katze.* — possesseur féminin → *ihr-* ; *Katze* féminin accusatif → *-e*.\n3. *Unsere Nachbarn und **ihr** Sohn kommen heute Abend.* — *ihr* = leur ; *Sohn* masculin nominatif → pas de terminaison.\n4. *Kinder, wo ist **euer** Lehrer?* — *euer* sans terminaison (masculin nominatif).\n5. *Kinder, ich habe **eure** Mutter gesehen.* — *Mutter* féminin → terminaison *-e* → *eure*.\n6. *Morgens wasche ich **mir die** Hände.* (ou *Ich wasche mir morgens die Hände.*) — avec les parties du corps, l'allemand emploie l'article + un datif, pas le possessif.\n\n**2.** *euer* perd son second e dès qu'il reçoit une terminaison : *euer Lehrer* (pas de terminaison) mais *eure Mutter*, *euren Vater*. À l'inverse, *unser* garde son e : *unsere Nachbarn*."}$exo$::jsonb),
  ('5b05b29b-e67a-511e-b421-791e84f8f39c'::uuid, 3, 'traduction', $exo${"titre":"Le texte de Sophie à corriger","consigne":"Lis le texte de Sophie, corrige ses fautes en justifiant, puis traduis les phrases de la question 3.","enonce":"**Document — Sophie parle de son frère Paul**\n\n> Mein Bruder Paul hat einen Hund. Ihr Hund heißt Rex. Paul spielt jeden Tag mit sein Hund. Nach dem Spiel wasche ich meine Hände. Meine Eltern und ihre Freunde kommen am Samstag. „Ist das dein Ball?“ – „Nein, das ist nicht mein, das ist Pauls Ball.“\n\n1. Le texte contient **quatre** fautes sur le possessif. Relève-les, corrige-les et justifie chaque correction.\n2. Un camarade pense que *ihre Freunde* est aussi une faute. A-t-il raison ? Explique.\n3. Traduis en allemand :\n   - a. Julia et son frère aiment leur chien.\n   - b. — À qui est ce livre ? — C'est le mien.\n\n*Aide : der Ball ; das Buch ; lieben = aimer.*","bareme":[{"critere":"Les quatre fautes relevées et corrigées : Sein Hund, seinem Hund, mir die Hände, meiner","points":8},{"critere":"Justifications : possesseur, datif après mit, tournure article + datif, possessif employé seul","points":4},{"critere":"ihre Freunde reconnu correct : ihr = leur, pluriel","points":3},{"critere":"Traductions justes : ihr Bruder, ihren Hund, Wessen, meins","points":5}],"dureeMin":16,"corrige":"**1. Les quatre fautes**\n- *Ihr Hund* → **Sein Hund** : le possesseur est Paul, un homme → radical *sein-*.\n- *mit sein Hund* → **mit seinem Hund** : *mit* impose le datif ; *Hund* masculin → *-em*.\n- *wasche ich meine Hände* → **wasche ich mir die Hände** : avec les parties du corps, l'allemand n'emploie pas le possessif mais l'article + un pronom au datif.\n- *das ist nicht mein* → **das ist nicht meiner** : employé seul, le possessif prend les terminaisons de l'article défini ; *Ball* est masculin (*der*) → *meiner*.\n\n**2.** Non. *ihre Freunde* est correct : *ihr* signifie ici **leur** (les amis de mes parents), et *Freunde* est un pluriel → terminaison *-e*.\n\n**3.**\n- a. *Julia und **ihr** Bruder lieben **ihren** Hund.* — Julia est une femme → *ihr Bruder* ; « leur chien » → *ihr-*, *Hund* masculin accusatif → *ihren*.\n- b. *— **Wessen** Buch ist das? — Das ist **meins** (meines).* — *Buch* neutre (*das*) → possessif seul *mein(e)s*."}$exo$::jsonb),
  ('5790341b-1018-523f-896d-1d96708b2992'::uuid, 1, 'traduction', $exo${"titre":"À qui est-ce ?","consigne":"Transforme chaque groupe avec von en génitif, puis réponds à la question 2 par une phrase complète.","enonce":"**1. Transforme au génitif.** Utilise le génitif saxon pour les noms propres, le génitif ordinaire pour les autres.\n\n1. das Auto von Peter\n2. das Fahrrad von Anna\n3. das Haus von dem Vater\n4. die Tasche von der Lehrerin\n5. das Zimmer von dem Kind\n6. die Spielsachen von den Kindern\n\n**2.** Pose la question qui correspond à « à qui est ce cahier ? » en allemand, puis réponds que c'est le cahier de Maria. *(das Heft = le cahier)*","bareme":[{"critere":"Génitif saxon sans article ni apostrophe : Peters Auto, Annas Fahrrad","points":5},{"critere":"Masculin et neutre : des + nom en -(e)s (des Vaters, des Kindes)","points":6},{"critere":"Féminin et pluriel : der sans marque sur le nom (der Lehrerin, der Kinder)","points":5},{"critere":"Question avec Wessen et réponse Marias Heft","points":4}],"dureeMin":6,"corrige":"**1.**\n1. **Peters Auto** — nom propre placé devant, -s sans apostrophe, aucun article.\n2. **Annas Fahrrad**\n3. **das Haus des Vaters** — masculin : article *des*, le nom prend *-s*.\n4. **die Tasche der Lehrerin** — féminin : article *der*, aucune marque sur le nom.\n5. **das Zimmer des Kindes** — neutre : *des*, le nom prend *-es* (ou *des Kinds*, plus rare).\n6. **die Spielsachen der Kinder** — pluriel : *der*, aucune marque.\n\n**2.** *Wessen Heft ist das?* — *Das ist **Marias** Heft.* (*Wessen?* = de qui ?, la question du génitif.)"}$exo$::jsonb),
  ('5790341b-1018-523f-896d-1d96708b2992'::uuid, 2, 'traduction', $exo${"titre":"Les vacances de Tom","consigne":"Complète le récit de Tom avec la préposition qui convient et l'article au génitif, puis traduis les groupes de la question 2.","enonce":"**1. Complète avec *wegen, trotz, während* ou *statt*, et l'article au génitif.**\n\n1. ___ d__ Ferien fahre ich nach Hamburg. *(pendant)*\n2. ___ d__ Regens spielen wir Fußball. *(malgré)*\n3. ___ d__ Sturms bleibt das Museum geschlossen. *(à cause de — der Sturm)*\n4. ___ ein__ Kaffees trinke ich einen Tee. *(au lieu de)*\n5. Das Haus mein__ Großmutter liegt außerhalb d__ Stadt.\n\n**2.** Traduis chaque groupe de deux façons : **a.** le vélo de Lisa ; **b.** la voiture de mon père. Pour chaque groupe, indique laquelle des deux formes est la plus soignée, à l'écrit.","bareme":[{"critere":"Prépositions justes : Während, Trotz, Wegen, Statt","points":6},{"critere":"Articles et noms au génitif justes : der Ferien, des Regens, des Sturms, eines Kaffees, meiner, der Stadt","points":6},{"critere":"Deux traductions justes de chaque groupe (génitif et von + datif)","points":5},{"critere":"Registre identifié : le génitif est plus soigné que von + datif","points":3}],"dureeMin":10,"corrige":"**1.**\n1. **Während der** Ferien fahre ich nach Hamburg. — *Ferien* est un pluriel → *der*.\n2. **Trotz des** Regens spielen wir Fußball. — masculin → *des Regens*.\n3. **Wegen des** Sturms bleibt das Museum geschlossen.\n4. **Statt eines** Kaffees trinke ich einen Tee. — masculin → *eines*, nom en *-s*.\n5. Das Haus **meiner** Großmutter liegt außerhalb **der** Stadt. — féminin → *meiner*, *der*.\n\n**2.**\n- a. *Lisas Fahrrad* (génitif saxon, courant pour un nom propre) / *das Fahrrad von Lisa* (oral, plus relâché). La forme la plus soignée : **Lisas Fahrrad**.\n- b. *das Auto meines Vaters* (génitif ordinaire) / *das Auto von meinem Vater* (von + datif). La forme la plus soignée : **das Auto meines Vaters**.\n\nLe génitif recule à l'oral mais reste la marque d'un écrit soigné ; *von* + datif est la tournure parlée."}$exo$::jsonb),
  ('5790341b-1018-523f-896d-1d96708b2992'::uuid, 3, 'traduction', $exo${"titre":"Réécrire en allemand soigné","consigne":"Réécris le texte de Lena dans un allemand écrit soigné, explique tes choix, puis écris trois phrases à ton sujet.","enonce":"**Document — Le message de Lena, écrit comme on parle**\n\n> Wegen dem Regen feiern wir im Haus von meiner Tante. Das Geschenk von meinem Bruder ist toll. Trotz dem Wetter kommen alle Freunde von Lena. Das Auto von Paul steht vor der Tür.\n\n1. Réécris les quatre phrases en remplaçant chaque tournure orale par le **génitif** (génitif ordinaire ou génitif saxon selon le cas).\n2. Explique pourquoi un correcteur remarque ces transformations.\n3. Écris **trois phrases** sur ta vie (école, loisirs, famille) : une avec *während*, une avec *wegen*, une avec un génitif saxon.\n\n*Aide : das Wetter = le temps ; das Geschenk = le cadeau.*","bareme":[{"critere":"Prépositions wegen et trotz suivies du génitif : des Regens, des Wetters","points":6},{"critere":"Compléments du nom au génitif : meiner Tante, meines Bruders, Lenas Freunde, Pauls Auto","points":6},{"critere":"Explication : le génitif marque un niveau de langue écrit et soigné","points":3},{"critere":"Trois phrases correctes avec während, wegen et un génitif saxon","points":5}],"dureeMin":15,"corrige":"**1. Texte réécrit**\n\n> *Wegen **des Regens** feiern wir im Haus **meiner Tante**. Das Geschenk **meines Bruders** ist toll. Trotz **des Wetters** kommen alle **Freunde Lenas** (ou : **Lenas Freunde**). **Pauls Auto** steht vor der Tür.*\n\n- *wegen* et *trotz* régissent le génitif à l'écrit : *des Regens*, *des Wetters* (masculin / neutre → *des* + *-s*).\n- *meiner Tante* : féminin → *meiner*, sans marque sur le nom.\n- *meines Bruders* : masculin → *meines*, nom en *-s*.\n- Noms propres : génitif saxon devant le nom, sans article ni apostrophe (*Pauls Auto*, *Lenas Freunde*).\n\n**2.** Le génitif recule dans l'allemand parlé (on dit *wegen dem*, *von meinem*), mais il reste un **marqueur de niveau de langue** : à l'écrit, il montre qu'on maîtrise la langue soignée.\n\n**3. Exemple de réponse**\n- *Während der Woche habe ich viel Arbeit.*\n- *Wegen des Tests lerne ich heute Abend.*\n- *Am Samstag spiele ich mit Maxims Ball.*\n\nToute phrase correcte avec *während* + génitif, *wegen* + génitif et un nom propre + *-s* devant le nom est acceptée."}$exo$::jsonb),
  ('4b94516b-8145-55a5-9de3-8b90b91ef412'::uuid, 1, 'traduction', $exo${"titre":"Plus grand, plus vieux, meilleur","consigne":"Complète chaque phrase avec le comparatif de l'adjectif entre parenthèses, puis corrige la phrase de la question 2.","enonce":"**1. Complète.**\n\n1. Berlin ist ___ als München. *(groß)*\n2. Mein Bruder ist ___ als ich. *(alt)*\n3. Das Buch ist ___ als der Film. *(interessant)*\n4. Heute ist es ___ als gestern. *(warm)*\n5. Mein Deutsch ist ___ als mein Englisch. *(gut)*\n6. Ich trinke ___ Tee als Kaffee. *(gern)*\n7. Anna ist so ___ wie Lisa. *(groß)*\n\n**2.** Corrige la phrase suivante et explique ta correction : *Tom ist größer wie Paul.*","bareme":[{"critere":"Comparatifs réguliers en -er avec Umlaut : größer, älter, interessanter, wärmer","points":8},{"critere":"Irréguliers justes : besser, lieber","points":4},{"critere":"als après un comparatif, so… wie pour l'égalité, faute de la question 2 corrigée et expliquée","points":8}],"dureeMin":6,"corrige":"**1.**\n1. Berlin ist **größer** als München.\n2. Mein Bruder ist **älter** als ich.\n3. Das Buch ist **interessanter** als der Film. — adjectif long, mais toujours *-er*, jamais « mehr interessant ».\n4. Heute ist es **wärmer** als gestern.\n5. Mein Deutsch ist **besser** als mein Englisch. — *gut → besser*.\n6. Ich trinke **lieber** Tee als Kaffee. — *gern → lieber* : je préfère le thé au café.\n7. Anna ist so **groß** wie Lisa. — égalité : l'adjectif ne change pas.\n\n**2.** *Tom ist größer **als** Paul.* Après un comparatif, le second terme est introduit par **als** ; *wie* ne s'emploie qu'après *so* (égalité)."}$exo$::jsonb),
  ('4b94516b-8145-55a5-9de3-8b90b91ef412'::uuid, 2, 'traduction', $exo${"titre":"Deux vélos à comparer","consigne":"Noah hésite entre deux vélos. À partir du tableau, écris les phrases demandées en allemand.","enonce":"**Document — Les deux vélos**\n\n| | Rad X | Rad Y |\n| Prix | 400 € | 400 € |\n| Poids | 14 kg | 10 kg |\n| Âge | 3 ans | 1 an |\n| Vitesse | 25 km/h | 30 km/h |\n\n1. Écris **quatre phrases** de comparaison : une sur le prix, une sur le poids, une sur l'âge, une sur la vitesse.\n2. Noah préfère le Rad Y : écris-le avec *lieber*.\n3. Les vélos coûtent de plus en plus cher : dis-le en allemand.\n\n*Aide : teuer → teurer (cher) ; schwer (lourd) ; leicht (léger) ; alt (vieux) ; schnell (rapide) ; fahren = rouler ; kosten = coûter.*","bareme":[{"critere":"Comparatifs de supériorité justes avec als (poids, âge, vitesse)","points":6},{"critere":"Égalité exprimée par so… wie pour le prix","points":4},{"critere":"Préférence exprimée avec lieber","points":4},{"critere":"immer + comparatif : immer teurer","points":3},{"critere":"Formes justes : Umlaut d'älter, orthographe de teurer","points":3}],"dureeMin":10,"corrige":"**1. Exemples de réponses**\n- Prix : *Rad X ist **so teuer wie** Rad Y.* — même prix → égalité.\n- Poids : *Rad X ist **schwerer als** Rad Y.* (ou *Rad Y ist leichter als Rad X.*)\n- Âge : *Rad X ist **älter als** Rad Y.* — Umlaut : *alt → älter*.\n- Vitesse : *Rad Y ist **schneller als** Rad X.*\n\n**2.** *Noah fährt **lieber** mit Rad Y.* (ou *Noah mag Rad Y lieber.*) — *gern → lieber* = préférer.\n\n**3.** *Die Fahrräder werden **immer teurer**.* — *immer* + comparatif = de plus en plus.\n\nToute formulation correcte est acceptée ; *als* après le comparatif et *wie* après *so* sont exigés."}$exo$::jsonb),
  ('4b94516b-8145-55a5-9de3-8b90b91ef412'::uuid, 3, 'traduction', $exo${"titre":"Comparer sans se tromper","consigne":"Corrige le texte de Hugo en justifiant, traduis les trois phrases, puis compare deux saisons en trois phrases.","enonce":"**Document — Le texte de Hugo**\n\n> Mein Bruder ist mehr groß als ich. Er hat ein größer Zimmer. Er ist so alt als mein Cousin. Je mehr er trainiert, desto er wird stärker.\n\n1. Le texte contient **quatre fautes**. Corrige chaque phrase et justifie.\n2. Traduis en allemand :\n   - a. Plus je lis, mieux je comprends.\n   - b. Mon frère aîné a un plus grand vélo.\n   - c. Il fait de plus en plus froid.\n3. Compare l'été et l'hiver en **trois phrases** : une avec *als*, une avec *so… wie* ou *nicht so… wie*, une avec *lieber*.\n\n*Aide : lesen, verstehen ; das Fahrrad ; kalt ; der Sommer, der Winter ; lang (long) ; die Tage.*","bareme":[{"critere":"Les quatre fautes corrigées : größer, größeres, so alt wie, desto stärker wird er","points":8},{"critere":"Traductions justes : je… desto, älterer / größeres déclinés, immer kälter","points":6},{"critere":"Trois phrases de comparaison correctes (als, so… wie, lieber)","points":6}],"dureeMin":16,"corrige":"**1. Corrections**\n- *mehr groß* → **größer** : *mehr* traduit une quantité, jamais le comparatif d'un adjectif.\n- *ein größer Zimmer* → **ein größeres Zimmer** : le comparatif épithète se décline ; neutre après *ein* → *-es*.\n- *so alt als* → **so alt wie** : égalité = *so… wie*.\n- *desto er wird stärker* → **desto stärker wird er** : après *desto*, le comparatif vient d'abord, puis le verbe, puis le sujet (*Je mehr er trainiert, desto stärker wird er.*).\n\n**2.**\n- a. *Je mehr ich lese, desto (umso) besser verstehe ich.*\n- b. *Mein **älterer** Bruder hat ein **größeres** Fahrrad.* — deux terminaisons : celle du comparatif, puis celle de la déclinaison.\n- c. *Es wird **immer kälter**.*\n\n**3. Exemple de réponse**\n- *Im Sommer sind die Tage länger als im Winter.*\n- *Der Winter ist nicht so warm wie der Sommer.*\n- *Ich mag den Sommer lieber als den Winter.*"}$exo$::jsonb),
  ('149b010e-7cf9-5452-9f66-28b46bb2ee67'::uuid, 1, 'traduction', $exo${"titre":"Les superlatifs à connaître","consigne":"Donne le superlatif en am … -sten de chaque adjectif, puis choisis la bonne forme dans les deux phrases de la question 2.","enonce":"**1. Donne la forme en *am … -sten*.**\n\nschnell · alt · kurz · groß · gut · viel · gern · hoch\n\n**2. Choisis la bonne forme et justifie en une phrase.**\n\n1. Der ICE ist *am schnellsten / der schnellste*.\n2. Das ist *am schnellsten / der schnellste* Zug.","bareme":[{"critere":"Superlatifs réguliers justes, avec le e de liaison et l'exception groß : schnellsten, ältesten, kürzesten, größten","points":8},{"critere":"Irréguliers justes : besten, meisten, liebsten, höchsten","points":8},{"critere":"Choix justifié : am -sten en attribut, der -ste devant un nom","points":4}],"dureeMin":6,"corrige":"**1.**\n- schnell → **am schnellsten**\n- alt → **am ältesten** (e de liaison après *t*, et Umlaut)\n- kurz → **am kürzesten** (e de liaison après *z*)\n- groß → **am größten** (exception : pas de e)\n- gut → **am besten**\n- viel → **am meisten**\n- gern → **am liebsten**\n- hoch → **am höchsten**\n\n**2.**\n1. *Der ICE ist **am schnellsten**.* — l'adjectif est attribut (après *sein*) : forme figée *am … -sten*.\n2. *Das ist **der schnellste** Zug.* — l'adjectif est épithète, devant le nom : *der … -ste*, qui se décline."}$exo$::jsonb),
  ('149b010e-7cf9-5452-9f66-28b46bb2ee67'::uuid, 2, 'traduction', $exo${"titre":"Le sondage de la classe","consigne":"Lis le tableau du cours de sport, puis réponds en allemand par des phrases complètes.","enonce":"**Document — 100 mètres, classe 3eB**\n\n| Élève | Temps | Âge |\n| Tim | 12,4 s | 15 ans |\n| Mia | 13,1 s | 14 ans |\n| Jonas | 14,0 s | 16 ans |\n\n1. *Wer läuft am schnellsten?*\n2. *Wer ist am ältesten? Wer ist am jüngsten?*\n3. Écris une phrase qui dit que Tim est **le coureur le plus rapide de tous**, avec l'adjectif devant le nom. *(der Läufer = le coureur)*\n4. Écris deux phrases qui disent ce que tu préfères faire par-dessus tout, en sport et le week-end.\n\n*Aide : jung = jeune.*","bareme":[{"critere":"Forme am … -sten juste en attribut et en adverbe (schnellsten, ältesten, jüngsten)","points":6},{"critere":"Superlatif épithète décliné : der schnellste Läufer","points":6},{"critere":"Complément du superlatif juste : von allen + datif","points":4},{"critere":"Deux phrases correctes avec am liebsten et l'inversion","points":4}],"dureeMin":10,"corrige":"**1.** *Tim läuft **am schnellsten**.* — adverbe : forme figée.\n\n**2.** *Jonas ist **am ältesten**.* (e de liaison après *t*, Umlaut) — *Mia ist **am jüngsten**.*\n\n**3.** *Tim ist **der schnellste Läufer von allen**.* — épithète devant le nom → *der schnellste* ; complément introduit par *von* + datif. (*Tim ist der Schnellste von allen* est aussi accepté.)\n\n**4. Exemple de réponse**\n- *Am liebsten spiele ich Basketball.*\n- *Am Wochenende schlafe ich am liebsten lange.*\n\n*am liebsten* = ce que je préfère par-dessus tout ; placé en tête, il entraîne l'inversion verbe-sujet."}$exo$::jsonb),
  ('149b010e-7cf9-5452-9f66-28b46bb2ee67'::uuid, 3, 'traduction', $exo${"titre":"Le meilleur et le plus haut","consigne":"Traduis les phrases, corrige les deux erreurs du document, puis explique la règle des deux formes du superlatif.","enonce":"**1. Traduis en allemand.**\n\n1. Berlin est la plus grande ville d'Allemagne. *(deux façons)*\n2. Ce que je préfère par-dessus tout, c'est lire des romans policiers.\n3. Je joue avec mon meilleur ami.\n4. La Zugspitze est la montagne la plus haute d'Allemagne.\n5. C'est lui qui a le plus d'argent.\n\n**Document — deux phrases d'un élève**\n\n> a. Das ist der Zug am schnellsten.\n> b. Paula ist am altsten.\n\n**2.** Corrige les deux phrases du document.\n**3.** Explique en quelques lignes, en français, comment on choisit entre les deux formes du superlatif.\n\n*Aide : die Stadt ; der Krimi, die Krimis ; der Freund ; der Berg ; das Geld.*","bareme":[{"critere":"Phrases 1 et 4 : superlatif épithète décliné et complément de lieu (in + datif ou génitif)","points":5},{"critere":"Phrases 2, 3 et 5 : am liebsten avec inversion, meinem besten Freund, am meisten","points":5},{"critere":"Les deux phrases du document corrigées : der schnellste Zug, am ältesten","points":5},{"critere":"Explication : attribut ou adverbe → am -sten figé ; épithète → der -ste décliné","points":5}],"dureeMin":16,"corrige":"**1.**\n1. *Berlin ist **die größte Stadt in Deutschland**.* / *Berlin ist **Deutschlands größte Stadt**.* — épithète féminine ; complément avec *in* + datif ou génitif.\n2. ***Am liebsten** lese ich Krimis.* — *am liebsten* n'est pas « le plus aimé » mais « ce que je préfère » ; inversion après l'adverbe.\n3. *Ich spiele mit **meinem besten** Freund.* — *mit* + datif, superlatif épithète décliné.\n4. *Die Zugspitze ist **der höchste Berg** Deutschlands* (ou *in Deutschland*). — *hoch → höchste*, *Berg* masculin.\n5. *Er hat **am meisten** Geld.* — *viel → am meisten*.\n\n**2.**\n- a. *Das ist **der schnellste Zug**.* — devant un nom, on emploie la forme déclinée.\n- b. *Paula ist **am ältesten**.* — après *t*, on intercale un *e* ; *alt* prend aussi l'Umlaut.\n\n**3.** Le superlatif a deux formes selon la **place** de l'adjectif. Quand il est **attribut** (après *sein*) ou **adverbe** (*er läuft…*), on emploie *am* + *-sten*, forme figée qui ne se décline pas. Quand il est **épithète**, devant un nom, on emploie *der / die / das* + *-ste*, qui se décline comme un adjectif (*mit dem besten Freund*). Dans les deux cas, on ajoute un *e* de liaison après *d, t, s, ß, z, sch* (sauf *groß → größten*)."}$exo$::jsonb),
  ('677f76f9-8081-5751-bab2-7865d4ccfa59'::uuid, 1, 'traduction', $exo${"titre":"Durch, für, gegen, ohne, um","consigne":"Complète chaque phrase avec la préposition qui convient et, s'il le faut, la terminaison de l'article ou du possessif.","enonce":"**1. Complète avec *durch, für, gegen, ohne* ou *um*.**\n\n1. Wir gehen ___ d__ Park. *(à travers — der Park)*\n2. Das Geschenk ist ___ mein__ Schwester. *(pour)*\n3. Ich trinke den Kaffee ___ Zucker. *(sans)*\n4. Wir sitzen ___ d__ Tisch. *(autour de — der Tisch)*\n5. Ich bin ___ dies__ Idee. *(contre — die Idee)*\n6. Der Film beginnt ___ acht Uhr. *(à huit heures pile)*\n\n**2.** Quel cas suit ces cinq prépositions ? Explique pourquoi on écrit *den Park* et non *der Park* dans la phrase 1.","bareme":[{"critere":"Prépositions justes : durch, für, ohne, um, gegen, um","points":8},{"critere":"Terminaisons de l'accusatif justes : den Park, meine Schwester, den Tisch, diese Idee","points":8},{"critere":"Explication : ces prépositions imposent toujours l'accusatif, masculin der → den","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Wir gehen **durch den** Park.\n2. Das Geschenk ist **für meine** Schwester.\n3. Ich trinke den Kaffee **ohne** Zucker. — *ohne* se passe souvent d'article.\n4. Wir sitzen **um den** Tisch.\n5. Ich bin **gegen diese** Idee.\n6. Der Film beginnt **um** acht Uhr. — heure précise → *um* (*gegen acht Uhr* = vers huit heures).\n\n**2.** *durch, für, gegen, ohne, um* imposent **toujours l'accusatif**, quel que soit le sens. Au masculin, l'article *der* devient *den* à l'accusatif : *durch den Park*. Au féminin et au neutre, la forme ne change pas (*meine Schwester*, *diese Idee*)."}$exo$::jsonb),
  ('677f76f9-8081-5751-bab2-7865d4ccfa59'::uuid, 2, 'traduction', $exo${"titre":"Le message d'Emma","consigne":"Emma répond à une invitation. Traduis son message en allemand, puis réponds à la question 2.","enonce":"**Le message d'Emma, en français**\n\n1. J'arrive vers huit heures.\n2. Le cadeau est pour ton frère.\n3. Nous marchons le long de la rivière.\n4. Je vais jusqu'à la gare en bus.\n5. Je viens sans mon vélo.\n\n*Aide : kommen ; das Geschenk ; der Bruder ; laufen ; der Fluss ; fahren ; der Bahnhof ; mit dem Bus ; das Fahrrad.*\n\n**2.** Emma hésite entre *gegen acht Uhr* et *um acht Uhr*. Explique la différence.","bareme":[{"critere":"Prépositions justes : gegen, für, entlang, bis zum, ohne","points":7},{"critere":"Accusatif juste après les prépositions : deinen Bruder, den Fluss, mein Fahrrad","points":6},{"critere":"Place d'entlang après le nom et bis suivi de zum","points":3},{"critere":"Différence gegen (vers) / um (heure précise) expliquée","points":4}],"dureeMin":10,"corrige":"**Traduction modèle**\n1. *Ich komme **gegen** acht Uhr.* — heure approximative.\n2. *Das Geschenk ist **für deinen** Bruder.* — *für* + accusatif ; masculin → *deinen*.\n3. *Wir laufen **den Fluss entlang**.* — *entlang* se place **après** le nom, qui est à l'accusatif.\n4. *Ich fahre mit dem Bus **bis zum** Bahnhof.* — *bis* est souvent suivi d'une seconde préposition (*zum* = *zu dem*).\n5. *Ich komme **ohne mein** Fahrrad.* — *Fahrrad* neutre : *mein* à l'accusatif.\n\n**2.** *gegen acht Uhr* = **vers** huit heures (approximatif) ; *um acht Uhr* = **à** huit heures pile. Une seule préposition d'écart change l'heure du rendez-vous."}$exo$::jsonb),
  ('677f76f9-8081-5751-bab2-7865d4ccfa59'::uuid, 3, 'traduction', $exo${"titre":"Pour apprendre, pas für lernen","consigne":"Corrige le texte de Jules en justifiant chaque correction, puis rédige une invitation de quatre phrases.","enonce":"**Document — Le texte de Jules**\n\n> Ich lerne Deutsch für in Berlin studieren. Jeden Morgen gehe ich durch dem Wald. Das Buch ist für mein Vater. Am Sonntag laufen wir entlang die Straße.\n\n1. Chaque phrase contient **une faute**. Recopie les phrases corrigées.\n2. Justifie chaque correction en une phrase.\n3. Rédige en allemand une **invitation de quatre phrases** à une fête d'anniversaire, avec **quatre prépositions différentes** parmi *durch, für, gegen, ohne, um, bis, entlang*.\n\n*Aide : die Party ; der Geburtstag ; der Garten ; der Kuchen.*","bareme":[{"critere":"Quatre corrections justes : um… zu studieren, durch den Wald, für meinen Vater, die Straße entlang","points":8},{"critere":"Justifications : für devant un nom seulement, accusatif obligatoire, place d'entlang","points":4},{"critere":"Invitation : quatre prépositions différentes suivies de l'accusatif correct","points":6},{"critere":"Invitation compréhensible, verbes conjugués et ordre des mots corrects","points":2}],"dureeMin":16,"corrige":"**1. Texte corrigé**\n\n> *Ich lerne Deutsch, **um in Berlin zu studieren**. Jeden Morgen gehe ich **durch den** Wald. Das Buch ist **für meinen** Vater. Am Sonntag laufen wir **die Straße entlang**.*\n\n**2. Justifications**\n- « Pour + verbe » ne se dit pas *für* : *für* introduit un groupe nominal, jamais un verbe. Le but se dit **um… zu** + infinitif.\n- *durch* impose l'**accusatif** : *der Wald* → *den Wald* (et non le datif *dem*).\n- *für* impose l'accusatif : *Vater* masculin → *meinen Vater*.\n- *entlang* se place **après** le nom : *die Straße entlang*.\n\n**3. Exemple de réponse**\n\n> *Hallo Tim! Ich mache am Samstag eine Party für meinen Geburtstag. Die Party beginnt um drei Uhr. Wir essen Kuchen und spielen im Garten bis zum Abend. Komm nicht ohne deinen Bruder!*\n\nToute invitation correcte employant quatre prépositions différentes avec l'accusatif juste est acceptée."}$exo$::jsonb),
  ('f56b2d76-3490-59a9-9c3f-f9f6d5d954f7'::uuid, 1, 'traduction', $exo${"titre":"Aus, bei, mit, nach, seit, von, zu","consigne":"Complète chaque phrase avec la préposition entre parenthèses et la terminaison du datif, en contractant quand c'est l'usage.","enonce":"**1. Complète.**\n\n1. Ich fahre ___ d__ Bus in die Stadt. *(avec)*\n2. Er kommt ___ d__ Schweiz. *(de — die Schweiz)*\n3. Ich wohne ___ mein__ Eltern. *(chez)*\n4. Ich gehe heute ___ Arzt. *(chez — contracté)*\n5. ___ d__ Film essen wir Pizza. *(après — der Film)*\n6. Ich lerne ___ ein__ Jahr Deutsch. *(depuis — das Jahr)*\n\n**2.** Dans la phrase 6, pourquoi le verbe est-il au présent alors que le français pourrait hésiter ? Explique en une phrase.","bareme":[{"critere":"Prépositions justes : mit, aus, bei, zum, nach, seit","points":6},{"critere":"Terminaisons du datif justes : dem Bus, der Schweiz, meinen Eltern, dem Film, einem Jahr","points":8},{"critere":"Contraction zum employée","points":2},{"critere":"Explication : seit + présent","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Ich fahre **mit dem** Bus in die Stadt.\n2. Er kommt **aus der** Schweiz. — féminin au datif → *der*.\n3. Ich wohne **bei meinen** Eltern. — datif pluriel → *-en*.\n4. Ich gehe heute **zum** Arzt. — *zu dem* → *zum*, contraction obligatoire dans l'usage.\n5. **Nach dem** Film essen wir Pizza. — masculin datif → *dem* ; inversion après le complément.\n6. Ich lerne **seit einem** Jahr Deutsch. — neutre datif → *einem*.\n\n**2.** Avec *seit*, l'action a commencé dans le passé et **dure encore** : l'allemand emploie le **présent**, comme le français (« j'apprends l'allemand depuis un an »)."}$exo$::jsonb),
  ('f56b2d76-3490-59a9-9c3f-f9f6d5d954f7'::uuid, 2, 'traduction', $exo${"titre":"Le voyage de Noah","consigne":"Noah raconte ses projets de voyage. Traduis ses phrases en allemand, puis explique tes choix de préposition.","enonce":"**1. Traduis en allemand.**\n\n1. Cet été, je vais en Autriche.\n2. Ensuite, je vais en Suisse.\n3. Je vais chez ma tante.\n4. Le soir, je rentre à la maison.\n5. Le dimanche, je suis à la maison.\n6. J'habite à Munich depuis deux ans.\n\n*Aide : Österreich (sans article) ; die Schweiz ; die Tante ; fahren, gehen ; wohnen ; München ; das Jahr, die Jahre ; im Sommer ; dann ; abends ; sonntags.*\n\n**2.** Explique quand on emploie *nach*, *in* + accusatif et *zu* pour dire où l'on va.","bareme":[{"critere":"Choix juste de nach, in die et zu selon le lieu (phrases 1 à 3)","points":7},{"critere":"Datif et contractions justes : zu meiner Tante, seit zwei Jahren","points":5},{"critere":"Expressions figées nach Hause / zu Hause bien employées","points":4},{"critere":"seit + présent, et règle nach / in / zu expliquée","points":4}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n1. *Im Sommer fahre ich **nach Österreich**.* — pays sans article → *nach*.\n2. *Dann fahre ich **in die Schweiz**.* — pays avec article → *in* + accusatif.\n3. *Ich fahre **zu meiner** Tante.* — personne → *zu* + datif.\n4. *Abends gehe ich **nach Hause**.* — avec mouvement.\n5. *Sonntags bin ich **zu Hause**.* — sans mouvement.\n6. *Ich wohne **seit zwei Jahren** in München.* — *seit* + datif pluriel (*Jahren*) et verbe au **présent**.\n\n**2.** Pour dire où l'on va : **nach** devant un pays ou une ville **sans article** (*nach Wien*) ; **in** + accusatif devant un pays **avec article** (*in die Schweiz, in die Türkei*) ; **zu** + datif devant une **personne** ou un bâtiment vu comme un but (*zum Arzt, zur Post*). *nach Hause* / *zu Hause* sont des expressions figées."}$exo$::jsonb),
  ('f56b2d76-3490-59a9-9c3f-f9f6d5d954f7'::uuid, 3, 'traduction', $exo${"titre":"Une journée à Hambourg","consigne":"Corrige le texte d'Hugo en justifiant, puis décris ta propre journée en quatre phrases.","enonce":"**Document — Le texte d'Hugo**\n\n> Seit drei Jahren habe ich in Hamburg gewohnt. Jeden Tag fahre ich mit meinem Fahrrad zu die Schule. Nach der Schule gehe ich bei meinem Freund Max. Im Juli fahren wir nach die Türkei. Meine Mutter kommt aus Frankreich.\n\n1. Le texte contient **quatre fautes**. Recopie les phrases fautives corrigées.\n2. Justifie chaque correction.\n3. Une phrase du texte est entièrement correcte : laquelle ? Explique pourquoi.\n4. Décris ta journée en **quatre phrases** en employant au moins quatre prépositions différentes parmi *aus, bei, mit, nach, seit, von, zu*.","bareme":[{"critere":"Quatre corrections : Seit… wohne ich, zur Schule, zu meinem Freund, in die Türkei","points":8},{"critere":"Justifications : seit + présent, contraction, zu pour une destination, pays avec article","points":4},{"critere":"Phrase correcte identifiée : aus Frankreich, pays sans article, aus + origine","points":2},{"critere":"Quatre phrases personnelles avec quatre prépositions à datif bien construites","points":6}],"dureeMin":16,"corrige":"**1. Corrections**\n- *Seit drei Jahren **wohne ich** in Hamburg.*\n- *Jeden Tag fahre ich mit meinem Fahrrad **zur** Schule.*\n- *Nach der Schule gehe ich **zu meinem** Freund Max.*\n- *Im Juli fahren wir **in die** Türkei.*\n\n**2. Justifications**\n- Avec *seit*, l'action dure encore : **présent**, pas parfait.\n- *zu* impose le datif : *zu der* → contraction **zur** (obligatoire dans l'usage).\n- On **va** chez quelqu'un : *zu* + datif ; *bei* indique qu'on **est** chez lui (sans mouvement).\n- *die Türkei* a un article : on emploie **in** + accusatif, pas *nach*.\n\n**3.** *Meine Mutter kommt aus Frankreich* est correct : *aus* + datif marque l'origine, et *Frankreich* s'emploie sans article.\n\n**4. Exemple de réponse**\n- *Ich fahre mit dem Bus zur Schule.*\n- *Nach dem Unterricht esse ich bei meiner Oma.*\n- *Ich lerne seit vier Jahren Deutsch.*\n- *Am Abend bekomme ich eine Nachricht von meinem Freund.*"}$exo$::jsonb),
  ('51441b16-101a-5024-9d3a-0563517f9440'::uuid, 1, 'traduction', $exo${"titre":"Wo ou wohin ?","consigne":"Complète chaque phrase avec l'article au bon cas, puis explique ton choix pour les phrases 1 et 2.","enonce":"**1. Complète avec l'article.**\n\n1. Ich gehe in ___ Schule. *(die Schule)*\n2. Ich bin in ___ Schule.\n3. Das Bild hängt an ___ Wand. *(die Wand)*\n4. Die Katze liegt unter ___ Tisch. *(der Tisch)*\n5. Die Katze läuft unter ___ Tisch. *(elle s'y glisse)*\n6. Das Heft liegt neben ___ Buch. *(das Buch)*\n\n**2.** Explique pourquoi l'article n'est pas le même dans les phrases 1 et 2.","bareme":[{"critere":"Accusatif juste en cas de déplacement (wohin) : die Schule, den Tisch","points":8},{"critere":"Datif juste en cas de localisation (wo) : der Schule, der Wand, dem Tisch, dem Buch","points":8},{"critere":"Explication avec les questions wo ? / wohin ?","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Ich gehe in **die** Schule. — *wohin?* déplacement → accusatif.\n2. Ich bin in **der** Schule. — *wo?* localisation → datif.\n3. Das Bild hängt an **der** Wand. — état → datif.\n4. Die Katze liegt unter **dem** Tisch. — *wo?* → datif.\n5. Die Katze läuft unter **den** Tisch. — elle change de lieu (*wohin?*) → accusatif.\n6. Das Heft liegt neben **dem** Buch. — *wo?* → datif.\n\n**2.** Les neuf prépositions mixtes changent de cas selon le sens. Dans la phrase 1, il y a un **changement de lieu** (question *wohin?*) → **accusatif** ; dans la phrase 2, une **localisation** (question *wo?*) → **datif**."}$exo$::jsonb),
  ('51441b16-101a-5024-9d3a-0563517f9440'::uuid, 2, 'traduction', $exo${"titre":"Clara range sa chambre","consigne":"Complète chaque paire de phrases avec le verbe conjugué et l'article au bon cas, puis réponds à la question 2.","enonce":"**1. Complète.** Dans chaque paire, la phrase **a** décrit l'action, la phrase **b** le résultat.\n\n1. a. Clara ___ die Lampe auf ___ Schreibtisch. *(stellen / stehen)* — b. Die Lampe ___ auf ___ Schreibtisch.\n2. a. Sie ___ das Buch auf ___ Bett. *(legen / liegen)* — b. Das Buch ___ auf ___ Bett.\n3. a. Sie ___ das Poster an ___ Wand. *(hängen)* — b. Das Poster ___ an ___ Wand.\n\n*der Schreibtisch, das Bett, die Wand*\n\n**2.** Contracte : *in das Zimmer* ; *an dem Fenster* ; *auf das Bett*.","bareme":[{"critere":"Couples de verbes justes et conjugués : stellt / steht, legt / liegt, hängt / hängt","points":8},{"critere":"Accusatif pour l'action, datif pour l'état : den / dem Schreibtisch, das / dem Bett, die / der Wand","points":8},{"critere":"Contractions justes : ins, am, aufs","points":4}],"dureeMin":10,"corrige":"**1.**\n1. a. Clara **stellt** die Lampe auf **den** Schreibtisch. — action → accusatif. b. Die Lampe **steht** auf **dem** Schreibtisch. — état → datif.\n2. a. Sie **legt** das Buch auf **das** (*aufs*) Bett. b. Das Buch **liegt** auf **dem** Bett.\n3. a. Sie **hängt** das Poster an **die** Wand. — *hängen* faible = accrocher. b. Das Poster **hängt** an **der** Wand. — *hängen* fort = être accroché.\n\nLes verbes d'action (*stellen, legen, setzen, hängen* faible) appellent l'accusatif ; les verbes d'état (*stehen, liegen, sitzen, hängen* fort) le datif.\n\n**2.** *in das Zimmer* → **ins Zimmer** ; *an dem Fenster* → **am Fenster** ; *auf das Bett* → **aufs Bett**."}$exo$::jsonb),
  ('51441b16-101a-5024-9d3a-0563517f9440'::uuid, 3, 'traduction', $exo${"titre":"Même verbe, deux cas","consigne":"Traduis les phrases en allemand, puis explique en français la méthode qui permet de choisir le cas.","enonce":"**1. Traduis en allemand.**\n\n1. Je cours dans le parc (à l'intérieur du parc).\n2. J'entre en courant dans le parc.\n3. Je pose la bouteille sur la table.\n4. La bouteille est sur la table.\n5. Je me réjouis des vacances.\n6. En janvier, nous allons au cinéma.\n\n*Aide : laufen ; der Park ; die Flasche ; der Tisch ; sich freuen auf ; die Ferien (pluriel) ; der Januar ; das Kino.*\n\n**2.** En quelques lignes, explique pourquoi les phrases 1 et 2 n'ont pas le même cas alors que le verbe est le même, et donne la méthode à suivre pour choisir l'article.","bareme":[{"critere":"Phrases 1 et 2 : im Park (datif) / in den Park (accusatif)","points":5},{"critere":"Phrases 3 et 4 : stellen + accusatif, stehen + datif","points":4},{"critere":"Emplois figés justes : auf die Ferien (accusatif), im Januar, ins Kino avec inversion","points":5},{"critere":"Explication : c'est le changement de lieu, pas le verbe, qui décide ; méthode wo ? / wohin ?","points":6}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n1. *Ich laufe **im Park**.* — je cours à l'intérieur : pas de changement de lieu → datif (*in dem* → *im*).\n2. *Ich laufe **in den Park**.* — j'y entre : changement de lieu → accusatif.\n3. *Ich **stelle** die Flasche auf **den** Tisch.* — action → accusatif.\n4. *Die Flasche **steht** auf **dem** Tisch.* — état → datif.\n5. *Ich freue mich **auf die** Ferien.* — emploi figé : *sich freuen auf* + accusatif.\n6. ***Im** Januar gehen wir **ins** Kino.* — *im Januar* figé ; *ins Kino* = déplacement ; inversion après le complément de temps.\n\n**2.** Ce n'est pas le verbe de mouvement qui décide, mais le **changement de lieu** : dans la phrase 1, on court en restant dans le parc (*wo?* → datif) ; dans la phrase 2, on passe de l'extérieur à l'intérieur (*wohin?* → accusatif). Méthode : trouver le **verbe**, se demander **wo?** ou **wohin?**, et n'écrire l'article qu'**ensuite**. Certaines expressions ne relèvent plus du lieu et s'apprennent telles quelles (*im Januar, sich freuen auf* + accusatif)."}$exo$::jsonb),
  ('3d9ceb19-367e-5aab-bfc5-2001708618a1'::uuid, 1, 'traduction', $exo${"titre":"Relier deux phrases","consigne":"Relie chaque paire de phrases avec la conjonction indiquée, en respectant la virgule et l'ordre des mots.","enonce":"**1. Relie les deux phrases.**\n\n1. Ich bleibe zu Hause. Ich bin krank. *(denn)*\n2. Er ist arm. Er ist glücklich. *(aber)*\n3. Das ist nicht mein Buch. Es ist deins. *(sondern)*\n4. Trinkst du Tee? Trinkst du Kaffee? *(oder)*\n5. Ich spiele Fußball. Mein Bruder spielt Tennis. *(und)*\n\n**2.** Dans la phrase 3, pourquoi faut-il *sondern* et non *aber* ?","bareme":[{"critere":"Phrases reliées sans changer l'ordre des mots après la conjonction (verbe en 2e position)","points":10},{"critere":"Virgule devant denn, aber et sondern, pas devant und ni oder","points":5},{"critere":"Explication : sondern après une négation","points":5}],"dureeMin":6,"corrige":"**1.**\n1. *Ich bleibe zu Hause, **denn** ich bin krank.* — après *denn*, rien ne bouge : sujet puis verbe.\n2. *Er ist arm, **aber** glücklich.* (ou *…, aber er ist glücklich.*)\n3. *Das ist nicht mein Buch, **sondern** deins.*\n4. *Trinkst du Tee **oder** Kaffee?*\n5. *Ich spiele Fußball **und** mein Bruder spielt Tennis.*\n\nLes conjonctions de coordination occupent la **position zéro** : elles ne comptent pas dans l'ordre des mots.\n\n**2.** *sondern* (« mais au contraire ») s'emploie après une **négation** pour rectifier : *nicht mein Buch, sondern deins*. *aber* s'emploie sans négation, pour une opposition simple."}$exo$::jsonb),
  ('3d9ceb19-367e-5aab-bfc5-2001708618a1'::uuid, 2, 'traduction', $exo${"titre":"Trois syntaxes pour une même idée","consigne":"Réécris chaque idée avec les mots de liaison demandés, puis explique où se place le verbe dans chaque cas.","enonce":"**1. Idée : nous restons à la maison parce qu'il pleut.**\n\nÉcris la phrase de trois façons :\na. avec *denn* ;\nb. avec *weil* ;\nc. avec *deshalb*.\n\n*(Wir bleiben zu Hause. — Es regnet.)*\n\n**2. Idée : je suis fatigué, pourtant je continue à travailler.**\n\nÉcris la phrase de deux façons :\na. avec *aber* ;\nb. avec *trotzdem*.\n\n*(Ich bin müde. — Ich lerne weiter.)*\n\n**3.** Explique en français, pour *denn*, *weil* et *deshalb*, où se place le verbe conjugué.","bareme":[{"critere":"Phrase avec denn : ordre normal, virgule","points":4},{"critere":"Phrase avec weil : verbe conjugué à la fin","points":4},{"critere":"Phrases avec deshalb et trotzdem : inversion verbe-sujet","points":6},{"critere":"Explication des trois places du verbe (coordination, subordination, adverbe)","points":6}],"dureeMin":10,"corrige":"**1.**\na. *Wir bleiben zu Hause, **denn** es regnet.*\nb. *Wir bleiben zu Hause, **weil** es **regnet**.*\nc. *Es regnet, **deshalb bleiben wir** zu Hause.*\n\n**2.**\na. *Ich bin müde, **aber** ich lerne weiter.*\nb. *Ich bin müde, **trotzdem lerne ich** weiter.*\n\n**3.**\n- Après **denn** (coordination) : la conjonction est en position zéro, rien ne bouge — sujet puis verbe en **2e position**.\n- Après **weil** (subordination) : le verbe conjugué part **à la fin** de la subordonnée.\n- Après **deshalb** (adverbe de liaison, comme *trotzdem*) : l'adverbe occupe la **1re position**, le verbe reste en 2e position, donc le sujet passe derrière : **inversion**.\n\nTrois syntaxes pour un même lien logique : les confondre est l'erreur la plus fréquente en expression écrite."}$exo$::jsonb),
  ('3d9ceb19-367e-5aab-bfc5-2001708618a1'::uuid, 3, 'traduction', $exo${"titre":"Donner son avis en nuances","consigne":"Traduis les phrases, corrige les deux erreurs du document, puis donne ton avis en quatre phrases.","enonce":"**1. Traduis en allemand.**\n\n1. Ni mon frère ni ma sœur ne parlent allemand.\n2. Il joue non seulement au football, mais aussi au tennis.\n3. Ou bien nous allons au cinéma, ou bien nous restons à la maison.\n4. Certes, le voyage est cher, mais il est intéressant.\n\n**Document — deux phrases d'élève**\n\n> a. Ich spiele nicht Tennis, aber Fußball.\n> b. Weder Tom noch Lisa kommt nicht.\n\n**2.** Corrige les deux phrases et justifie.\n\n**3.** Donne ton avis sur le téléphone portable au collège en **quatre phrases**, en utilisant *zwar… aber*, *denn* et *deshalb*.\n\n*Aide : die Reise ; teuer ; das Handy ; nützlich (utile) ; stören (déranger) ; im Unterricht.*","bareme":[{"critere":"Traductions justes des corrélatifs : weder… noch, nicht nur… sondern auch, entweder… oder, zwar… aber","points":8},{"critere":"Corrections justifiées : sondern après négation, pas de nicht après weder… noch","points":4},{"critere":"Avis : zwar… aber, denn (sans inversion) et deshalb (avec inversion) bien construits","points":6},{"critere":"Avis cohérent et compréhensible","points":2}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n1. *Weder mein Bruder noch meine Schwester spricht Deutsch.* (*sprechen* au pluriel est aussi accepté) — la phrase est déjà négative : pas de *nicht*.\n2. *Er spielt nicht nur Fußball, sondern auch Tennis.*\n3. *Entweder gehen wir ins Kino, oder wir bleiben zu Hause.* (*Entweder wir gehen…* est aussi accepté.)\n4. *Die Reise ist zwar teuer, aber (sie ist) interessant.*\n\n**2.**\n- a. *Ich spiele nicht Tennis, **sondern** Fußball.* — après une négation, on rectifie avec *sondern*.\n- b. *Weder Tom noch Lisa **kommt**.* — *weder… noch* porte déjà la négation : ajouter *nicht* est une faute.\n\n**3. Exemple de réponse**\n\n> *Das Handy ist zwar nützlich, aber es stört im Unterricht. Viele Schüler spielen im Unterricht, denn sie sind nicht konzentriert. Deshalb bin ich für ein Handyverbot in der Klasse. Nach der Schule ist das Handy aber okay.*\n\nSont vérifiés : *zwar* après le verbe et *aber* en tête de la seconde partie, *denn* sans changement d'ordre, *deshalb* suivi de l'inversion."}$exo$::jsonb),
  ('0b5ef7f9-8b66-5ebe-bf9d-a8994486e5fe'::uuid, 1, 'traduction', $exo${"titre":"Wo, wohin, woher ?","consigne":"Complète chaque phrase avec la préposition (et l'article contracté si besoin), puis indique la question à laquelle elle répond.","enonce":"**1. Complète, puis écris à côté *wo?*, *wohin?* ou *woher?*.**\n\n1. Ich fahre ___ Deutschland.\n2. Ich komme ___ Frankreich.\n3. Im Sommer fahren wir ___ Meer. *(das Meer)*\n4. Heute Abend gehe ich ___ Kino. *(das Kino)*\n5. Ich bin gerade ___ Arzt. *(der Arzt)*\n6. Mama kommt um sechs Uhr ___ der Arbeit.","bareme":[{"critere":"Prépositions justes : nach, aus, ans, ins, beim, von","points":12},{"critere":"Contractions correctes : ans, ins, beim","points":4},{"critere":"Question juste pour chaque phrase","points":4}],"dureeMin":6,"corrige":"1. Ich fahre **nach** Deutschland. — *wohin?* pays sans article.\n2. Ich komme **aus** Frankreich. — *woher?* venir d'un pays.\n3. Im Sommer fahren wir **ans** Meer. — *wohin?* un bord : *an* + accusatif (*an das* → *ans*).\n4. Heute Abend gehe ich **ins** Kino. — *wohin?* nom avec article : *in* + accusatif (*in das* → *ins*).\n5. Ich bin gerade **beim** Arzt. — *wo?* chez une personne sans mouvement : *bei dem* → *beim*.\n6. Mama kommt um sechs Uhr **von** der Arbeit. — *woher?* point de départ : *von* + datif."}$exo$::jsonb),
  ('0b5ef7f9-8b66-5ebe-bf9d-a8994486e5fe'::uuid, 2, 'traduction', $exo${"titre":"Dialogue avant les vacances","consigne":"Complète le dialogue entre Ben et Aylin, puis traduis les deux paires de phrases de la question 2.","enonce":"**1. Complète le dialogue.**\n\n> Ben: Wohin fährst du in den Ferien?\n> Aylin: Ich fahre ___ Land zu meiner Oma. *(à la campagne)*\n> Ben: Wo wohnt sie genau?\n> Aylin: Sie wohnt ___ Land, in einem kleinen Dorf.\n> Ben: Und dein Vater? Woher kommt er?\n> Aylin: Er kommt ___ Türkei. Im August fahren wir alle ___ Türkei.\n\n**2. Traduis en allemand.**\na. Je vais chez le médecin. / Je suis chez le médecin.\nb. Il part à l'étranger. / Il vit à l'étranger.\n\n*Aide : das Ausland = l'étranger ; der Arzt.*","bareme":[{"critere":"Paire aufs Land / auf dem Land juste","points":4},{"critere":"aus der Türkei (origine) et in die Türkei (destination) justes","points":4},{"critere":"zum Arzt / beim Arzt justes","points":6},{"critere":"ins Ausland / im Ausland justes","points":6}],"dureeMin":10,"corrige":"**1.**\n- Ich fahre **aufs** Land zu meiner Oma. — mouvement : *auf* + accusatif (*auf das* → *aufs*).\n- Sie wohnt **auf dem** Land. — sans mouvement : datif.\n- Er kommt **aus der** Türkei. — origine : *aus* + datif ; pays avec article féminin → *der*.\n- Im August fahren wir alle **in die** Türkei. — destination, pays avec article → *in* + accusatif (jamais *nach*).\n\n**2.**\na. *Ich gehe **zum** Arzt.* (mouvement vers une personne) / *Ich bin **beim** Arzt.* (sans mouvement). Le français dit « chez » dans les deux cas ; l'allemand oblige à choisir.\nb. *Er geht (fährt) **ins** Ausland.* / *Er lebt **im** Ausland.* — expressions figées par paires : une avec mouvement (accusatif), une sans (datif)."}$exo$::jsonb),
  ('0b5ef7f9-8b66-5ebe-bf9d-a8994486e5fe'::uuid, 3, 'traduction', $exo${"titre":"Hin, her et le récit d'un voyage","consigne":"Traduis les phrases de la question 1, rédige le récit demandé, puis réponds à la question 3 en français.","enonce":"**1. Traduis en allemand.**\na. Viens ici !\nb. Vas-y !\nc. Où vas-tu ? *(deux façons)*\nd. D'où viens-tu ? *(deux façons)*\n\n**2.** Raconte en **six phrases** un voyage imaginaire : d'où tu pars, où tu vas, chez qui, où tu dors, ce que tu visites. Emploie au moins **cinq** constructions différentes parmi : *nach, in* + accusatif, *zu, an* + accusatif, *aus, von, bei*.\n\n**3.** Explique la différence entre *hineingehen* et *herauskommen* en t'appuyant sur le sens de *hin* et *her*.","bareme":[{"critere":"Impératifs justes : Komm her!, Geh hin!","points":3},{"critere":"Questions justes : Wohin / Wo… hin, Woher / Wo… her","points":4},{"critere":"Récit : cinq constructions de lieu différentes avec le bon cas","points":7},{"critere":"Récit compréhensible, verbes conjugués correctement","points":2},{"critere":"Explication : hin = éloignement du locuteur, her = rapprochement","points":4}],"dureeMin":18,"corrige":"**1.**\na. *Komm **her**!* — rapprochement vers celui qui parle.\nb. *Geh **hin**!* — éloignement.\nc. *Wohin gehst du?* / *Wo gehst du **hin**?*\nd. *Woher kommst du?* / *Wo kommst du **her**?* — la particule peut se détacher et partir en fin de phrase.\n\n**2. Exemple de réponse**\n\n> *Ich komme aus Lyon. Im Juli fahre ich mit dem Zug nach Berlin. Dort gehe ich zu meinem Brieffreund Jonas. Ich schlafe bei seiner Familie. Am Montag gehen wir ins Museum. Am Wochenende fahren wir ans Meer.*\n\nConstructions attendues : *aus* (origine), *nach* (ville sans article), *zu* + datif (personne), *bei* + datif (sans mouvement), *in* + accusatif (*ins Museum*), *an* + accusatif (*ans Meer*).\n\n**3.** *hin* marque l'**éloignement** du locuteur, *her* le **rapprochement**. *hineingehen* = entrer, vu de **dehors** (on s'éloigne de celui qui parle) ; *herauskommen* = sortir, vu de **dedans** (on vient vers celui qui parle). Ces particules se soudent aux prépositions pour former des préverbes."}$exo$::jsonb),
  ('9f96b788-30df-5913-b04f-77ea6b655d8e'::uuid, 1, 'traduction', $exo${"titre":"Am, im ou um ?","consigne":"Complète chaque complément de temps, puis traduis les trois expressions de la question 2.","enonce":"**1. Complète avec *am*, *im*, *um* ou *in der*.**\n\n1. ___ Montag\n2. ___ Sommer\n3. ___ acht Uhr\n4. ___ Januar\n5. ___ Abend\n6. ___ Jahr 2026\n7. ___ Nacht\n8. ___ Mitternacht\n\n**2.** Traduis et explique la différence : *morgen* ; *morgens* ; *am Morgen*.","bareme":[{"critere":"am devant les jours et parties de la journée : am Montag, am Abend","points":4},{"critere":"im devant mois, saisons, années : im Sommer, im Januar, im Jahr 2026","points":4},{"critere":"um devant l'heure précise et exception in der Nacht","points":4},{"critere":"Sens juste de morgen, morgens, am Morgen","points":8}],"dureeMin":6,"corrige":"**1.**\n1. **am** Montag — jour\n2. **im** Sommer — saison\n3. **um** acht Uhr — heure précise\n4. **im** Januar — mois\n5. **am** Abend — partie de la journée\n6. **im** Jahr 2026 — année\n7. **in der** Nacht — exception (et non *am*)\n8. **um** Mitternacht — heure précise\n\n**2.**\n- *morgen* = **demain**.\n- *morgens* = **le matin, en général**, habituellement (adverbe).\n- *am Morgen* = **ce matin-là**, un matin précis.\n\nUn seul *s* d'écart suffit à changer le sens."}$exo$::jsonb),
  ('9f96b788-30df-5913-b04f-77ea6b655d8e'::uuid, 2, 'traduction', $exo${"titre":"L'agenda de Lina","consigne":"Traduis les phrases de l'agenda de Lina en commençant chaque phrase par le complément de temps.","enonce":"**L'agenda de Lina, en français**\n\n1. Chaque jour, je vais au collège.\n2. Il y a deux semaines, j'étais à Vienne.\n3. Dans une heure, le film commence.\n4. J'apprends l'allemand depuis trois ans. *(commence par « Seit… »)*\n5. Pendant les vacances, je lis beaucoup.\n6. Du lundi au vendredi, je me lève tôt.\n\n*Aide : in die Schule gehen ; die Woche ; Wien ; die Stunde ; beginnen ; die Ferien (pluriel) ; lesen ; früh aufstehen (ich stehe … auf).*","bareme":[{"critere":"Prépositions et cas justes : vor zwei Wochen, in einer Stunde, seit drei Jahren, während der Ferien, von… bis","points":8},{"critere":"Accusatif sans préposition : jeden Tag","points":3},{"critere":"Inversion verbe-sujet après le complément de temps en tête","points":5},{"critere":"seit + présent","points":4}],"dureeMin":10,"corrige":"**Traduction modèle**\n1. ***Jeden Tag** gehe ich in die Schule.* — durée ou date entière : accusatif sans préposition.\n2. ***Vor zwei Wochen** war ich in Wien.* — *vor* + datif = il y a.\n3. ***In einer Stunde** beginnt der Film.* — *in* + datif = dans (futur).\n4. ***Seit drei Jahren** lerne ich Deutsch.* — *seit* + datif pluriel, verbe au **présent**.\n5. ***Während der Ferien** lese ich viel.* — *während* + génitif ; *Ferien* pluriel → *der*.\n6. ***Von Montag bis Freitag** stehe ich früh auf.*\n\nDans chaque phrase, le complément de temps ouvre la phrase : le verbe reste en 2e position et le sujet passe **derrière** (inversion)."}$exo$::jsonb),
  ('9f96b788-30df-5913-b04f-77ea6b655d8e'::uuid, 3, 'traduction', $exo${"titre":"Des vacances en Italie","consigne":"Corrige le texte d'Inès en justifiant, puis raconte ta journée type en cinq phrases.","enonce":"**Document — La carte postale d'Inès**\n\n> Am Sommer fahre ich nach Italien. Ich bin dort seit zwei Wochen gewesen. Um Abend esse ich Pizza. Morgens stehe ich um neun Uhr auf. Nächsten Woche ich fahre nach Hause.\n\n1. Le texte contient **quatre phrases fautives** (une phrase est correcte). Corrige-les.\n2. Justifie chaque correction.\n3. Raconte ta journée type en **cinq phrases**, avec **cinq compléments de temps différents** ; au moins deux phrases commencent par le complément de temps.","bareme":[{"critere":"Corrections : Im Sommer, Ich bin seit zwei Wochen dort, Am Abend, Nächste Woche fahre ich","points":8},{"critere":"Justifications : im / am, seit + présent, accusatif sans préposition, inversion","points":4},{"critere":"Journée type : cinq compléments de temps différents et justes","points":5},{"critere":"Inversion correcte quand le complément ouvre la phrase","points":3}],"dureeMin":16,"corrige":"**1. Texte corrigé**\n\n> ***Im** Sommer fahre ich nach Italien. Ich **bin** seit zwei Wochen dort. **Am** Abend esse ich Pizza. Morgens stehe ich um neun Uhr auf. **Nächste Woche fahre ich** nach Hause.*\n\n**2. Justifications**\n- Saisons → **im** (*im Sommer*), pas *am*.\n- Avec *seit*, l'action dure encore : **présent** (*ich bin*), pas parfait.\n- Parties de la journée → **am** (*am Abend*) ; *um* est réservé à l'heure précise.\n- *nächste Woche* : accusatif sans préposition, **féminin** → *nächste* ; en tête de phrase, le verbe reste en 2e position → **inversion** (*fahre ich*).\n- La phrase *Morgens stehe ich um neun Uhr auf* est correcte (*morgens* = le matin, habituellement).\n\n**3. Exemple de réponse**\n\n> *Morgens stehe ich um sieben Uhr auf. Um acht Uhr beginnt der Unterricht. Am Mittag esse ich in der Kantine. Nach der Schule spiele ich Fußball. Am Abend lese ich ein Buch.*"}$exo$::jsonb),
  ('5ba02fae-7d2b-52f8-ac05-f0408c97ae3d'::uuid, 1, 'traduction', $exo${"titre":"Sein, haben, werden","consigne":"Complète avec la bonne forme de sein, haben ou werden au temps indiqué, puis donne les trois participes.","enonce":"**1. Complète.**\n\n1. Ihr ___ müde. *(sein, présent)*\n2. Du ___ einen Hund. *(haben, présent)*\n3. Mein Bruder ___ Arzt. *(werden, présent : il devient)*\n4. Gestern ___ ich krank. *(sein, prétérit)*\n5. Wir ___ keine Zeit. *(haben, prétérit)*\n6. Es ___ kalt. *(werden, prétérit)*\n\n**2.** Donne le participe passé de *sein*, *haben* et *werden* (verbe plein).","bareme":[{"critere":"Présents justes : seid, hast, wird","points":8},{"critere":"Prétérits justes : war, hatten, wurde","points":6},{"critere":"Participes justes : gewesen, gehabt, geworden","points":6}],"dureeMin":6,"corrige":"**1.**\n1. Ihr **seid** müde. (attention : *seid* avec d, le verbe ; *seit* avec t est la préposition « depuis »)\n2. Du **hast** einen Hund.\n3. Mein Bruder **wird** Arzt. — *werden* verbe plein = devenir.\n4. Gestern **war** ich krank.\n5. Wir **hatten** keine Zeit.\n6. Es **wurde** kalt.\n\n**2.** *sein → **gewesen*** ; *haben → **gehabt*** ; *werden → **geworden*** (et *worden* seulement quand *werden* est auxiliaire du passif)."}$exo$::jsonb),
  ('5ba02fae-7d2b-52f8-ac05-f0408c97ae3d'::uuid, 2, 'traduction', $exo${"titre":"Haben ou sein au parfait ?","consigne":"Complète chaque phrase au parfait avec haben ou sein conjugué, puis explique la différence entre les phrases 1 et 2.","enonce":"**1. Complète avec *haben* ou *sein*.**\n\n1. Ich ___ nach Berlin gefahren.\n2. Ich ___ das Auto meines Vaters gefahren.\n3. Er ___ um sieben Uhr aufgestanden.\n4. Wir ___ den ganzen Tag zu Hause geblieben.\n5. Sie ___ ein Buch gelesen.\n6. Was ___ passiert?\n7. Das Kind ___ schnell eingeschlafen.\n8. Ich ___ eine Pizza gegessen.\n\n**2.** Les phrases 1 et 2 ont le même verbe, mais pas le même auxiliaire. Explique pourquoi.","bareme":[{"critere":"sein pour les verbes de mouvement et de changement d'état : bin, ist aufgestanden, ist eingeschlafen","points":6},{"critere":"sein pour bleiben et passieren : sind geblieben, ist passiert","points":4},{"critere":"haben pour les autres verbes : habe gefahren (avec COD), hat gelesen, habe gegessen","points":4},{"critere":"Explication : fahren avec un COD prend haben, c'est le sens qui tranche","points":6}],"dureeMin":10,"corrige":"**1.**\n1. Ich **bin** nach Berlin gefahren. — déplacement.\n2. Ich **habe** das Auto meines Vaters gefahren. — *fahren* avec un COD (*das Auto*).\n3. Er **ist** um sieben Uhr aufgestanden. — changement d'état.\n4. Wir **sind** den ganzen Tag zu Hause geblieben. — *bleiben* prend toujours *sein*.\n5. Sie **hat** ein Buch gelesen.\n6. Was **ist** passiert? — *passieren* prend *sein*.\n7. Das Kind **ist** schnell eingeschlafen. — changement d'état.\n8. Ich **habe** eine Pizza gegessen.\n\n**2.** Dans la phrase 1, *fahren* exprime un **déplacement** d'un point à un autre : auxiliaire **sein** (je me suis déplacé). Dans la phrase 2, *fahren* a un **COD** (*das Auto*) : il signifie « conduire » et prend **haben**. C'est le sens de la phrase qui tranche, pas le verbe lui-même."}$exo$::jsonb),
  ('5ba02fae-7d2b-52f8-ac05-f0408c97ae3d'::uuid, 3, 'traduction', $exo${"titre":"Les trois vies de werden","consigne":"Traduis les phrases, corrige la phrase du document, puis explique les emplois de werden.","enonce":"**1. Traduis en allemand.**\n\n1. Je deviens nerveux.\n2. Je reçois une lettre.\n3. Demain, il fera beau.\n4. La maison est en train d'être construite.\n5. Il est devenu médecin.\n6. La maison a été construite en 1990.\n\n*Aide : nervös ; der Brief ; das Wetter ; schön ; bauen (construire) ; der Arzt.*\n\n**Document — phrase d'un élève**\n\n> Ich habe gestern nach Paris gegangen.\n\n**2.** Corrige cette phrase et justifie.\n**3.** Explique en français les trois emplois de *werden* et pourquoi *bekommen* est un piège.","bareme":[{"critere":"werden verbe plein, futur et passif justes (phrases 1, 3, 4)","points":6},{"critere":"bekommen = recevoir (phrase 2)","points":2},{"critere":"Participes justes : ist… geworden, ist… gebaut worden","points":5},{"critere":"Phrase du document corrigée : bin gegangen, verbe de mouvement","points":3},{"critere":"Explication des trois emplois de werden et du faux ami bekommen","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n1. *Ich **werde** nervös.* — verbe plein : devenir.\n2. *Ich **bekomme** einen Brief.* — *bekommen* = recevoir.\n3. *Morgen **wird** das Wetter schön (**sein**).* — auxiliaire du futur.\n4. *Das Haus **wird gebaut**.* — passif d'action : *werden* + participe.\n5. *Er **ist** Arzt **geworden**.* — parfait de *werden* verbe plein : *sein* + *geworden*.\n6. *Das Haus **ist** 1990 **gebaut worden**.* — parfait du passif : participe *worden*.\n\n**2.** *Ich **bin** gestern nach Paris **gegangen**.* — *gehen* est un verbe de mouvement d'un point à un autre : il forme son parfait avec **sein**.\n\n**3.** *werden* a trois emplois : **verbe plein** « devenir » (*Er wird Arzt*) ; **auxiliaire du futur** (*Es wird regnen*) ; **auxiliaire du passif** d'action (*Das Haus wird gebaut*). Au participe, il fait *geworden* comme verbe plein, *worden* dans un passif. *bekommen* ressemble à « become » ou « devenir », mais il signifie **recevoir** : « je deviens » se dit *ich werde*. La confusion produit un contresens complet."}$exo$::jsonb),
  ('62a14f6a-2405-53a0-88a6-81c842ae171f'::uuid, 1, 'traduction', $exo${"titre":"Les temps primitifs","consigne":"Donne les trois temps primitifs (infinitif, prétérit, participe II) de chaque verbe et classe-le.","enonce":"**1. Recopie et complète le tableau.**\n\n| Infinitif | Prétérit (er) | Participe II | Famille |\n| machen | | | |\n| spielen | | | |\n| fahren | | | |\n| schreiben | | | |\n| nehmen | | | |\n| gehen | | | |\n| studieren | | | |\n| bringen | | | |\n\n*Familles : faible, fort, mixte, verbe en -ieren.*\n\n**2.** Quelle différence vois-tu entre le participe d'un verbe faible et celui d'un verbe fort ?","bareme":[{"critere":"Verbes faibles justes : machte / gemacht, spielte / gespielt","points":4},{"critere":"Verbes forts justes : fuhr / gefahren, schrieb / geschrieben, nahm / genommen, ging / gegangen","points":8},{"critere":"Cas particuliers : studierte / studiert sans ge-, brachte / gebracht (mixte)","points":4},{"critere":"Différence ge-…-t / ge-…-en expliquée","points":4}],"dureeMin":8,"corrige":"**1.**\n| Infinitif | Prétérit | Participe II | Famille |\n| machen | machte | gemacht | faible |\n| spielen | spielte | gespielt | faible |\n| fahren | fuhr | gefahren | fort |\n| schreiben | schrieb | geschrieben | fort |\n| nehmen | nahm | genommen | fort |\n| gehen | ging | gegangen | fort |\n| studieren | studierte | studiert | en -ieren (faible, sans ge-) |\n| bringen | brachte | gebracht | mixte |\n\n**2.** Le participe d'un verbe **faible** se forme en *ge-… **-t*** et garde son radical (*gemacht*). Celui d'un verbe **fort** se forme en *ge-… **-en*** et change souvent de voyelle (*gesprochen, genommen*). Le mixte a un radical modifié mais des terminaisons faibles (*gebracht*)."}$exo$::jsonb),
  ('62a14f6a-2405-53a0-88a6-81c842ae171f'::uuid, 2, 'traduction', $exo${"titre":"Le samedi de Max","consigne":"Complète les phrases au présent, puis mets le récit de Max au prétérit.","enonce":"**1. Conjugue au présent.**\n\n1. Du ___ gut Deutsch. *(sprechen)*\n2. Er ___ mir das Buch. *(geben)*\n3. ___ du den Film heute Abend? *(sehen)*\n4. Sie ___ einen Roman. *(lesen)*\n5. Du ___ zu schnell! *(fahren)*\n6. Wir ___ ihm ein Geschenk. *(geben)*\n\n**2. Réécris le récit au prétérit.**\n\n> Am Samstag fahre ich nach Köln. Ich nehme den Zug. Im Zug schreibe ich eine Karte. In Köln kaufe ich ein T-Shirt und spiele mit meinem Cousin Fußball.","bareme":[{"critere":"Changement de voyelle aux 2e et 3e personnes du singulier : sprichst, gibt, siehst, liest, fährst","points":8},{"critere":"Pas de changement au pluriel : wir geben","points":2},{"critere":"Prétérits forts justes : fuhr, nahm, schrieb","points":6},{"critere":"Prétérits faibles justes : kaufte, spielte","points":4}],"dureeMin":10,"corrige":"**1.**\n1. Du **sprichst** gut Deutsch. — *e → i*.\n2. Er **gibt** mir das Buch. — *e → i*.\n3. **Siehst** du den Film heute Abend? — *e → ie*.\n4. Sie **liest** einen Roman. — *e → ie*.\n5. Du **fährst** zu schnell! — *a → ä*.\n6. Wir **geben** ihm ein Geschenk. — au pluriel, pas de changement.\n\n**2. Récit au prétérit**\n\n> *Am Samstag **fuhr** ich nach Köln. Ich **nahm** den Zug. Im Zug **schrieb** ich eine Karte. In Köln **kaufte** ich ein T-Shirt und **spielte** mit meinem Cousin Fußball.*\n\n- Verbes forts : la voyelle change et il n'y a pas de terminaison à la 1re personne (*fuhr, nahm, schrieb*).\n- Verbes faibles : radical inchangé + *-te* (*kaufte, spielte*)."}$exo$::jsonb),
  ('62a14f6a-2405-53a0-88a6-81c842ae171f'::uuid, 3, 'traduction', $exo${"titre":"Lire un récit au prétérit","consigne":"Analyse les verbes du récit, réécris-en une partie au parfait, puis traduis la dernière phrase.","enonce":"**Document — Le voyage de Paul**\n\n> Letzten Sommer **fuhr** Paul nach Hamburg. Er **nahm** den Zug und **schrieb** seiner Mutter eine Karte. Er **kaufte** ein Souvenir und **telefonierte** mit seinem Freund. Am Abend **dachte** er an seine Familie.\n\n1. Pour chaque verbe en gras, donne l'**infinitif** et la **famille** (fort, faible, mixte, en -ieren).\n2. Réécris les deux premières phrases du récit au **parfait**. *(Aide : fahren se conjugue avec sein au parfait, les autres avec haben.)*\n3. Traduis en allemand : **Il parle allemand et elle lit un livre.**","bareme":[{"critere":"Infinitifs justes : fahren, nehmen, schreiben, kaufen, telefonieren, denken","points":5},{"critere":"Familles justes : trois forts, un faible, un en -ieren, un mixte","points":4},{"critere":"Parfait juste : ist gefahren, hat genommen, geschrieben, gekauft, telefoniert (sans ge-)","points":7},{"critere":"Traduction avec les changements de voyelle : spricht, liest","points":4}],"dureeMin":16,"corrige":"**1.**\n| Forme | Infinitif | Famille |\n| fuhr | fahren | fort |\n| nahm | nehmen | fort |\n| schrieb | schreiben | fort |\n| kaufte | kaufen | faible (-te) |\n| telefonierte | telefonieren | en -ieren (faible) |\n| dachte | denken | mixte (radical modifié, terminaison faible) |\n\n**2. Au parfait**\n\n> *Letzten Sommer **ist** Paul nach Hamburg **gefahren**. Er **hat** den Zug **genommen** und seiner Mutter eine Karte **geschrieben**.*\n\n(La suite, si l'élève la réécrit : *Er hat ein Souvenir **gekauft** und mit seinem Freund **telefoniert**.* — pas de *ge-* pour les verbes en *-ieren* ; *Am Abend hat er an seine Familie **gedacht**.*)\n\n**3.** *Er **spricht** Deutsch und sie **liest** ein Buch.* — verbes forts : *e → i* (*sprechen*) et *e → ie* (*lesen*) à la 3e personne du singulier."}$exo$::jsonb),
  ('14eaa575-d3b9-5b1e-8b6a-a34ce30dd2de'::uuid, 1, 'traduction', $exo${"titre":"Le bon modal","consigne":"Complète chaque phrase avec le verbe de modalité qui convient, conjugué au présent, puis réponds à la question 2.","enonce":"**1. Complète.**\n\n1. Ich ___ gut schwimmen. *(capacité)*\n2. ___ ich reinkommen? *(autorisation)*\n3. Du ___ heute lernen, morgen ist der Test. *(nécessité)*\n4. Wir ___ im Sommer nach Berlin fahren. *(volonté)*\n5. Ich ___ einen Kaffee, bitte. *(demande polie)*\n6. Der Arzt sagt, er ___ im Bett bleiben. *(consigne venue d'autrui)*\n\n**2.** Dans la phrase 3, où se place l'infinitif *lernen* ? Énonce la règle.","bareme":[{"critere":"Modal juste selon le sens : kann, darf, musst, wollen, möchte, soll","points":8},{"critere":"Conjugaison juste, sans terminaison aux 1re et 3e personnes du singulier","points":8},{"critere":"Règle : modal en 2e position, infinitif à la fin","points":4}],"dureeMin":6,"corrige":"**1.**\n1. Ich **kann** gut schwimmen. — *können* : capacité.\n2. **Darf** ich reinkommen? — *dürfen* : permission.\n3. Du **musst** heute lernen, morgen ist der Test. — *müssen* : nécessité.\n4. Wir **wollen** im Sommer nach Berlin fahren. — *wollen* : volonté.\n5. Ich **möchte** einen Kaffee, bitte. — forme polie de *mögen*.\n6. Der Arzt sagt, er **soll** im Bett bleiben. — *sollen* : consigne venue d'autrui.\n\n**2.** Dans une principale, le modal conjugué est en **2e position** et l'infinitif part **à la fin** de la phrase : *Du musst heute **lernen**.*"}$exo$::jsonb),
  ('14eaa575-d3b9-5b1e-8b6a-a34ce30dd2de'::uuid, 2, 'traduction', $exo${"titre":"Le règlement de l'auberge","consigne":"Lis le règlement de l'auberge de jeunesse, puis réponds aux questions en allemand.","enonce":"**Document — Jugendherberge Bremen**\n\n> Rauchen verboten! — Frühstück von 7 bis 9 Uhr. — Die Zimmer sind um 10 Uhr frei. — Fahrräder: 8 Euro pro Tag. — Die Küche ist für alle offen.\n\n1. Écris **quatre phrases** avec *man* + un modal pour résumer le règlement : une interdiction, une obligation, une possibilité, une autorisation.\n2. Traduis et explique la différence : *Du musst nicht kommen.* / *Du darfst nicht rauchen.*\n3. Relie les deux phrases avec *weil* : *Ich kann heute nicht kommen. Ich muss lernen.*\n\n*Aide : rauchen ; frühstücken ; das Zimmer verlassen (quitter la chambre) ; mieten (louer) ; kochen.*","bareme":[{"critere":"Quatre phrases avec man + modal adapté au sens (darf nicht, muss, kann, darf)","points":8},{"critere":"Négation : muss nicht = pas obligé, darf nicht = interdiction","points":6},{"critere":"Subordonnée avec weil : infinitif puis modal à la fin","points":6}],"dureeMin":10,"corrige":"**1. Exemples de réponses**\n- Interdiction : *Man **darf** hier nicht **rauchen**.*\n- Obligation : *Man **muss** das Zimmer um 10 Uhr **verlassen**.*\n- Possibilité : *Man **kann** Fahrräder **mieten**.* (ou *Man kann von 7 bis 9 Uhr frühstücken.*)\n- Autorisation : *Man **darf** in der Küche **kochen**.*\n\n**2.**\n- *Du musst nicht kommen* = **tu n'es pas obligé** de venir.\n- *Du darfst nicht rauchen* = **tu n'as pas le droit** de fumer (interdiction).\n*müssen* + négation supprime l'obligation ; l'interdiction se dit avec *nicht dürfen*.\n\n**3.** *Ich kann heute nicht kommen, **weil** ich **lernen muss**.* — en subordonnée, tout part à la fin : l'infinitif, puis le modal conjugué."}$exo$::jsonb),
  ('14eaa575-d3b9-5b1e-8b6a-a34ce30dd2de'::uuid, 3, 'traduction', $exo${"titre":"Ce qu'on a dû faire","consigne":"Transforme les phrases au passé, traduis la phrase rapportée, puis écris un court texte sur tes projets.","enonce":"**1. Mets au parfait.**\na. Ich muss arbeiten.\nb. Er kann nicht kommen.\nc. Ich will es. *(sans infinitif)*\n\n**2. Mets au prétérit.**\na. Wir können nicht schwimmen.\nb. Sie muss lernen.\n\n**3.** Traduis en allemand, avec *sollen* : « Le médecin m'a dit de rester au lit. » (Commence par *Ich…*)\n\n**4.** Écris **quatre phrases** sur tes projets pour l'été, avec **quatre modaux différents**.\n\n*Aide : im Bett bleiben ; im Sommer ; arbeiten, reisen, schlafen.*","bareme":[{"critere":"Parfait avec double infinitif : habe arbeiten müssen, hat nicht kommen können ; participe gewollt sans infinitif","points":6},{"critere":"Prétérits justes sans Umlaut : konnten, musste","points":4},{"critere":"sollen employé pour rapporter une consigne : Ich soll im Bett bleiben","points":3},{"critere":"Quatre phrases avec quatre modaux différents, bien conjugués, infinitif à la fin","points":7}],"dureeMin":16,"corrige":"**1.**\na. *Ich **habe arbeiten müssen**.* — avec un infinitif dépendant : **double infinitif**, pas de participe.\nb. *Er **hat nicht kommen können**.*\nc. *Ich **habe es gewollt**.* — sans infinitif, le participe existe.\n\n**2.**\na. *Wir **konnten** nicht schwimmen.*\nb. *Sie **musste** lernen.* — prétérit régulier, **sans inflexion**.\n\n**3.** *Ich **soll** im Bett bleiben.* — *sollen* rapporte une consigne extérieure (on m'a dit de…).\n\n**4. Exemple de réponse**\n\n> *Im Sommer will ich nach Österreich reisen. Dort kann ich wandern. Ich darf zum ersten Mal allein fahren. Aber ich muss vorher etwas Geld verdienen.*\n\nSont vérifiés : un modal différent par phrase, conjugué, et l'infinitif en fin de phrase."}$exo$::jsonb),
  ('05fe13dd-c7ff-56ce-9148-dfbe2b9e7ac9'::uuid, 1, 'traduction', $exo${"titre":"Le préverbe à sa place","consigne":"Construis chaque phrase au présent, puis donne le participe passé de chaque verbe.","enonce":"**1. Construis la phrase au présent.**\n\n1. aufstehen — ich — um sieben Uhr\n2. einkaufen — wir — am Samstag\n3. anrufen — er — seine Mutter\n4. besuchen — ich — meine Tante\n5. verstehen — du — den Text\n\n**2.** Donne le participe passé de : *aufstehen, einkaufen, anrufen, besuchen, verstehen*.","bareme":[{"critere":"Préverbe séparable en fin de phrase : stehe… auf, kaufen… ein, ruft… an","points":8},{"critere":"Verbes inséparables non coupés : besuche, verstehst","points":4},{"critere":"Participes justes : aufgestanden, eingekauft, angerufen (ge- intercalé), besucht, verstanden (sans ge-)","points":8}],"dureeMin":6,"corrige":"**1.**\n1. *Ich **stehe** um sieben Uhr **auf**.* — le préverbe ferme la phrase.\n2. *Wir **kaufen** am Samstag **ein**.*\n3. *Er **ruft** seine Mutter **an**.*\n4. *Ich **besuche** meine Tante.* — *be-* est inséparable : rien ne bouge.\n5. *Du **verstehst** den Text.* — *ver-* inséparable.\n\n**2.**\n- *aufstehen → **aufgestanden*** ; *einkaufen → **eingekauft*** ; *anrufen → **angerufen*** — le *ge-* s'intercale entre le préverbe et le radical.\n- *besuchen → **besucht*** ; *verstehen → **verstanden*** — inséparables : **pas de ge-**."}$exo$::jsonb),
  ('05fe13dd-c7ff-56ce-9148-dfbe2b9e7ac9'::uuid, 2, 'traduction', $exo${"titre":"La journée de Lukas","consigne":"À partir des notes de Lukas, rédige sa journée en allemand, puis transforme deux phrases comme demandé.","enonce":"**Document — Les notes de Lukas**\n\n| Heure | Action |\n| 7 h | aufstehen |\n| 8 h | mit dem Bus abfahren |\n| 17 h | im Supermarkt einkaufen |\n| 19 h | fernsehen |\n| 22 h | einschlafen |\n\n1. Écris **cinq phrases** au présent sur la journée de Lukas (3e personne). Commence au moins deux phrases par l'heure.\n2. Relie avec *weil* : *Lukas ist müde. Er steht um sieben Uhr auf.*\n3. Complète avec *zu* : *Lukas hat keine Lust, ___ (einkaufen).*","bareme":[{"critere":"Préverbe en fin de phrase dans les principales : steht… auf, fährt… ab, kauft… ein, sieht… fern, schläft… ein","points":8},{"critere":"Inversion quand l'heure ouvre la phrase et verbes forts bien conjugués (fährt, sieht, schläft)","points":4},{"critere":"Subordonnée : préverbe recollé en fin (aufsteht)","points":4},{"critere":"zu intercalé : einzukaufen","points":4}],"dureeMin":10,"corrige":"**1. Exemple de réponse**\n- *Um sieben Uhr **steht** Lukas **auf**.*\n- *Um acht Uhr **fährt** er mit dem Bus **ab**.*\n- *Um siebzehn Uhr **kauft** er im Supermarkt **ein**.*\n- *Um neunzehn Uhr **sieht** er **fern**.*\n- *Um zweiundzwanzig Uhr **schläft** er **ein**.*\n\nLe préverbe séparable ferme la phrase ; l'heure en tête entraîne l'inversion ; *fahren, sehen, schlafen* changent de voyelle à la 3e personne.\n\n**2.** *Lukas ist müde, **weil** er um sieben Uhr **aufsteht**.* — en subordonnée, le préverbe se **recolle** au verbe, à la fin.\n\n**3.** *Lukas hat keine Lust, **einzukaufen**.* — le *zu* s'intercale entre le préverbe et le radical."}$exo$::jsonb),
  ('05fe13dd-c7ff-56ce-9148-dfbe2b9e7ac9'::uuid, 3, 'traduction', $exo${"titre":"Kommen et sa famille","consigne":"Donne le sens des verbes, traduis les phrases, puis explique comment reconnaître un préverbe séparable.","enonce":"**1.** Donne le sens de : *kommen, ankommen, bekommen, mitkommen, umkommen*.\n\n**2. Traduis en allemand.**\na. Le train arrive à huit heures.\nb. Je reçois un cadeau.\nc. Tu viens avec nous ?\nd. Elle traduit le texte.\ne. Le train est arrivé. *(parfait avec sein)*\nf. J'ai reçu un cadeau. *(parfait avec haben)*\n\n*Aide : der Zug ; das Geschenk ; übersetzen ; der Text.*\n\n**3.** Explique en français le test qui permet de savoir si un préverbe est séparable, et pourquoi *übersetzen* peut être les deux.","bareme":[{"critere":"Sens justes des cinq verbes","points":4},{"critere":"Phrases au présent : kommt… an, bekomme, Kommst du mit?, übersetzt (non coupé)","points":6},{"critere":"Participes : ist angekommen (ge- intercalé), habe bekommen (sans ge-)","points":4},{"critere":"Explication : test de l'accent et double statut selon le sens concret ou figuré","points":6}],"dureeMin":16,"corrige":"**1.** *kommen* = venir ; *ankommen* = arriver ; *bekommen* = recevoir ; *mitkommen* = accompagner, venir avec ; *umkommen* = périr. Le sens dépend entièrement du préverbe.\n\n**2.**\na. *Der Zug **kommt** um acht Uhr **an**.*\nb. *Ich **bekomme** ein Geschenk.* — *be-* inséparable.\nc. ***Kommst** du **mit**?*\nd. *Sie **übersetzt** den Text.* — sens figuré (traduire) → inséparable.\ne. *Der Zug **ist angekommen**.* — *ge-* intercalé.\nf. *Ich **habe** ein Geschenk **bekommen**.* — inséparable : pas de *ge-*.\n\n**3.** Le seul critère fiable est l'**accent** : un préverbe **séparable** est accentué (*ÁN-kommen*), un préverbe **inséparable** ne l'est pas, l'accent tombe sur le radical (*be-KÓMMEN*). *über-* fait partie des préverbes à double statut : au sens **concret**, il est séparable (*Ich setze über* = je traverse en bateau) ; au sens **figuré**, il est inséparable (*Ich übersetze den Text* = je traduis)."}$exo$::jsonb),
  ('0d0877d7-b03e-592f-8ec5-29b4b4d2cfc1'::uuid, 1, 'traduction', $exo${"titre":"Mich ou mir ?","consigne":"Complète chaque phrase avec le pronom réfléchi qui convient, puis explique la différence entre les phrases 1 et 2.","enonce":"**1. Complète avec le pronom réfléchi.**\n\n1. Ich wasche ___.\n2. Ich wasche ___ die Hände.\n3. Du kaufst ___ ein Buch.\n4. Er freut ___ auf die Ferien.\n5. Wir interessieren ___ für Musik.\n6. Setzen Sie ___ bitte!\n\n**2.** Pourquoi écrit-on *mich* dans la phrase 1 et *mir* dans la phrase 2 ?","bareme":[{"critere":"Réfléchis à l'accusatif sans COD : mich, sich, uns","points":6},{"critere":"Réfléchis au datif en présence d'un COD : mir, dir","points":6},{"critere":"sich en minuscule dans le vouvoiement","points":3},{"critere":"Explication : un COD dans la phrase fait passer le réfléchi au datif","points":5}],"dureeMin":6,"corrige":"**1.**\n1. Ich wasche **mich**. — pas de COD → accusatif.\n2. Ich wasche **mir** die Hände. — *die Hände* est COD → datif.\n3. Du kaufst **dir** ein Buch. — COD *ein Buch* → datif.\n4. Er freut **sich** auf die Ferien.\n5. Wir interessieren **uns** für Musik.\n6. Setzen Sie **sich** bitte! — *sich* ne prend **jamais** de majuscule, même dans le vouvoiement.\n\n**2.** Dans la phrase 1, il n'y a pas d'autre complément : le réfléchi est le COD → **accusatif** (*mich*). Dans la phrase 2, il y a déjà un COD (*die Hände*) : le réfléchi passe au **datif** (*mir*). Les deux séries ne diffèrent qu'aux deux premières personnes du singulier."}$exo$::jsonb),
  ('0d0877d7-b03e-592f-8ec5-29b4b4d2cfc1'::uuid, 2, 'traduction', $exo${"titre":"Le message d'Ambre","consigne":"Ambre écrit à sa correspondante. Traduis ses phrases en allemand, puis réponds à la question 2.","enonce":"**1. Traduis en allemand.**\n\n1. Je me souviens de mes vacances.\n2. Je m'intéresse au sport.\n3. Je me réjouis de ton cadeau (je l'ai reçu).\n4. Je me réjouis du week-end (il n'est pas encore là).\n5. Je me lève à sept heures.\n6. Je suis souvent en retard.\n\n*Aide : sich erinnern ; der Sport ; das Geschenk ; das Wochenende ; aufstehen ; sich verspäten ; oft.*\n\n**2.** Explique pourquoi la phrase 5 n'a pas de pronom réfléchi en allemand et pourquoi la phrase 6 en a un.","bareme":[{"critere":"Prépositions justes suivies de l'accusatif : an meine Ferien, für Sport","points":6},{"critere":"auf (à venir) et über (déjà arrivé) bien distingués","points":6},{"critere":"Faux pronominaux : stehe… auf sans réfléchi, verspäte mich","points":4},{"critere":"Explication juste des faux pronominaux","points":4}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n1. *Ich erinnere mich **an** meine Ferien.* — *sich erinnern an* + accusatif.\n2. *Ich interessiere mich **für** Sport.* — *sich interessieren für* + accusatif.\n3. *Ich freue mich **über** dein Geschenk.* — ce qui est déjà arrivé → *über*.\n4. *Ich freue mich **auf** das Wochenende.* — ce qui vient → *auf*.\n5. *Ich **stehe** um sieben Uhr **auf**.* — pas de pronom.\n6. *Ich **verspäte mich** oft.*\n\n**2.** Certains verbes pronominaux en français ne le sont pas en allemand : *aufstehen* (se lever) n'a pas de réfléchi. À l'inverse, *sich verspäten* (être en retard) est pronominal en allemand mais pas en français. Il faut apprendre chaque verbe avec sa construction."}$exo$::jsonb),
  ('0d0877d7-b03e-592f-8ec5-29b4b4d2cfc1'::uuid, 3, 'traduction', $exo${"titre":"Le pronom au bon endroit","consigne":"Place les pronoms, corrige le texte de Malo en justifiant, puis écris quatre phrases sur toi.","enonce":"**1. Place le pronom réfléchi au bon endroit.**\na. Gestern hat mein Bruder verletzt. *(sich)*\nb. Ich bin glücklich, weil ich freue. *(mich)*\nc. Heute Abend sehe ich den Film an. *(mir)*\n\n**Document — Le texte de Malo**\n\n> Jeden Morgen wasche ich mich die Haare. Mein Freund interessiert sich an Fußball. Nächste Woche beginnen die Ferien: wir freuen uns schon über die Ferien. Am Sonntag spaziere ich mich im Park.\n\n**2.** Chaque phrase contient une faute. Corrige-les et justifie.\n\n**3.** Écris **quatre phrases** sur toi avec quatre verbes pronominaux différents du cours (dont un au datif avec COD).","bareme":[{"critere":"Place juste du pronom : hat sich mein Bruder, weil ich mich freue, sehe mir… an","points":5},{"critere":"Corrections : mir die Haare, für Fußball, auf die Ferien, gehe… spazieren","points":6},{"critere":"Justifications : datif avec COD, bonne préposition, auf / über, faux pronominal","points":3},{"critere":"Quatre phrases personnelles correctes, dont un réfléchi au datif avec COD","points":6}],"dureeMin":16,"corrige":"**1.**\na. *Gestern hat **sich** mein Bruder verletzt.* — inversion : le pronom vient après le verbe, **avant** un sujet nominal.\nb. *Ich bin glücklich, weil ich **mich** freue.* — subordonnée : après le sujet.\nc. *Heute Abend sehe ich **mir** den Film an.* — COD *den Film* → datif, juste après le verbe et le sujet inversé.\n\n**2. Texte corrigé**\n- *Jeden Morgen wasche ich **mir** die Haare.* — il y a un COD (*die Haare*) → réfléchi au datif.\n- *Mein Freund interessiert sich **für** Fußball.* — *sich interessieren für* + accusatif.\n- *Wir freuen uns schon **auf** die Ferien.* — les vacances sont à venir → *auf* ; *über* pour ce qui est déjà arrivé.\n- *Am Sonntag **gehe** ich im Park **spazieren**.* — « se promener » n'est pas pronominal en allemand.\n\n**3. Exemple de réponse**\n- *Ich interessiere mich für Geschichte.*\n- *Ich erinnere mich gern an meine Kindheit.*\n- *Ich freue mich auf die Sommerferien.*\n- *Am Wochenende kaufe ich mir ein neues Buch.* — réfléchi au datif avec le COD *ein neues Buch*."}$exo$::jsonb),
  ('5ae68ba3-3b82-57d0-a239-2e9bbaf7919d'::uuid, 1, 'traduction', $exo${"titre":"Vroni à l'Oktoberfest","consigne":"Lis le texte, puis réponds aux questions en français, sauf indication contraire.","enonce":"**Texte** (texte écrit pour l'exercice)\n\n> Ich heiße Vroni und wohne in München. Jedes Jahr im September gehe ich mit meinen Freunden auf das Oktoberfest. Dort trage ich ein Dirndl, und mein Bruder trägt eine Lederhose. Meine Oma sagt, früher haben nur die Bauern Tracht getragen. Heute ist die Tracht wieder modern. Manche Touristen kaufen ein billiges Dirndl nur für einen Tag. Das finde ich schade, denn für mich ist die Tracht ein Stück Heimat. Ich fühle mich zuerst als Bayerin, dann als Deutsche.\n\n*Aide : der Bauer = le paysan ; billig = bon marché ; schade = dommage ; ein Stück = un morceau.*\n\n1. Relève : a) la ville où vit Vroni ; b) quand elle va à l'Oktoberfest ; c) ce qu'elle porte ; d) ce que porte son frère.\n2. Traduis en français : *Heute ist die Tracht wieder modern. Manche Touristen kaufen ein billiges Dirndl nur für einen Tag.*\n3. Que pense Vroni des touristes ? Explique pourquoi, en citant le texte.\n4. Que signifie la dernière phrase ? Quelle identité Vroni met-elle en premier ?","bareme":[{"critere":"Les quatre informations relevées (Munich, en septembre, un Dirndl, une Lederhose)","points":6},{"critere":"Traduction juste des deux phrases (wieder, manche, billig, nur für einen Tag)","points":6},{"critere":"Avis de Vroni expliqué : dommage, car la Tracht est pour elle un morceau de Heimat","points":4},{"critere":"Dernière phrase comprise : identité régionale bavaroise avant l'identité allemande","points":4}],"dureeMin":7,"corrige":"1. a) Elle vit à **Munich** (*in München*). b) Elle y va **chaque année en septembre** (*jedes Jahr im September*). c) Elle porte un **Dirndl** (la robe traditionnelle). d) Son frère porte une **Lederhose** (la culotte de cuir).\n\n2. Traduction modèle : « Aujourd'hui, le costume traditionnel est de nouveau à la mode. Certains touristes achètent un Dirndl bon marché pour un seul jour. » (*wieder* = de nouveau ; *manche* = certains, quelques ; *nur für einen Tag* = pour un jour seulement.)\n\n3. Vroni trouve cela **dommage** (*Das finde ich schade*), car pour elle le costume n'est pas un déguisement : c'est **un morceau de sa Heimat**, de son pays natal (*denn für mich ist die Tracht ein Stück Heimat*). Les touristes en font un costume d'un jour.\n\n4. « Je me sens d'abord Bavaroise, ensuite Allemande. » Vroni met en premier son **identité régionale** (la Bavière, son Land), avant son identité nationale : c'est fréquent en Allemagne, pays fédéral où chaque Land a son drapeau, son accent et ses fêtes."}$exo$::jsonb),
  ('5ae68ba3-3b82-57d0-a239-2e9bbaf7919d'::uuid, 2, 'traduction', $exo${"titre":"Le drapeau revient en 2006","consigne":"Lis le texte. Réponds en français aux questions 1 et 2, en allemand aux questions 3 et 4.","enonce":"**Texte** (texte écrit pour l'exercice)\n\n> Lange hatten viele Deutsche ein Problem mit ihrer Fahne. Nach 1945 war Patriotismus verdächtig. Im Sommer 2006 hat sich das geändert: Deutschland hat die Fußball-Weltmeisterschaft organisiert. Plötzlich hingen schwarz-rot-goldene Fahnen an den Fenstern und an den Autos. Junge Leute haben sich die Farben ins Gesicht gemalt. Man sprach von „Party-Patriotismus“. Aber viele Menschen fühlen sich weiterhin zuerst als Hamburger, Sachsen oder Bayern, denn jedes Bundesland hat seine eigene Fahne und seine eigenen Feste.\n\n*Aide : die Fahne = le drapeau ; verdächtig = suspect ; hängen (hing) = être accroché ; das Gesicht = le visage ; weiterhin = toujours, encore.*\n\n1. Vrai ou faux ? Justifie chaque réponse par une citation du texte.\n a) Après 1945, le patriotisme était bien vu en Allemagne.\n b) En 2006, l'Allemagne organisait la Coupe du monde de football.\n c) Des jeunes se sont peint les couleurs du drapeau sur le visage.\n d) Tous les Allemands se sentent d'abord Allemands.\n2. Qu'appelle-t-on le « patriotisme de fête » ?\n3. Réponds en allemand par une phrase complète : *Welche Farben hat die deutsche Fahne?*\n4. Écris en allemand 40 à 60 mots : *Und in Frankreich? Wann siehst du die französische Fahne? Zeigst du sie auch?*","bareme":[{"critere":"Les quatre vrai/faux justes, chacun justifié par la bonne citation","points":8},{"critere":"Patriotisme de fête expliqué : fierté joyeuse et passagère, liée à la fête du football","points":3},{"critere":"Réponse juste et complète en allemand (schwarz, rot und gold)","points":2},{"critere":"Production de 40 à 60 mots qui répond aux trois questions, compréhensible et correcte","points":7}],"dureeMin":12,"corrige":"1. a) **Faux** : *Nach 1945 war Patriotismus verdächtig* (le patriotisme était suspect).\nb) **Vrai** : *Deutschland hat die Fußball-Weltmeisterschaft organisiert.*\nc) **Vrai** : *Junge Leute haben sich die Farben ins Gesicht gemalt.*\nd) **Faux** : *viele Menschen fühlen sich weiterhin zuerst als Hamburger, Sachsen oder Bayern.*\n\n2. C'est la **fierté nationale joyeuse** qui s'est affichée pendant la Coupe du monde 2006 : on sortait le drapeau pour faire la fête autour du football, sans le nationalisme agressif que l'Allemagne redoutait depuis 1945.\n\n3. *Die deutsche Fahne ist schwarz, rot und gold.* (ou *Sie hat die Farben Schwarz, Rot und Gold.*)\n\n4. Exemple de production :\n*In Frankreich sehe ich die Fahne vor allem am 14. Juli und bei Fußballspielen. Die Fahne ist blau, weiß und rot. Bei der Weltmeisterschaft male ich mir manchmal die Farben ins Gesicht. Aber sonst zeige ich die Fahne nicht oft. Ich fühle mich zuerst als Europäerin und dann als Französin.*\n\nOn attend : réponses aux trois questions (quand, où, est-ce que je la montre), verbe conjugué en deuxième position, vocabulaire du texte réemployé (*die Fahne, die Farben, sich fühlen als*), phrases simples et correctes."}$exo$::jsonb),
  ('5ae68ba3-3b82-57d0-a239-2e9bbaf7919d'::uuid, 3, 'traduction', $exo${"titre":"Deux autoportraits, deux images de soi","consigne":"Traduis les phrases demandées, puis rédige en allemand un texte personnel et structuré.","enonce":"**Document 1** – Albrecht Dürer, *Autoportrait* (1500). Le peintre se représente de face, les cheveux longs, la main sur la poitrine, dans une pose réservée jusque-là au Christ.\n\n**Document 2** – Egon Schiele, autoportraits (début du XXe siècle). Le peintre autrichien se représente maigre, le corps tordu, presque nu.\n\n*Aide : malen = peindre ; von vorn = de face ; die Würde = la dignité ; dünn = maigre ; sich darstellen = se représenter ; zeigen = montrer ; verstecken = cacher ; das Selfie = le selfie.*\n\n1. Traduis en allemand :\n a) Dürer se peint de face.\n b) Il veut montrer sa dignité d'artiste.\n c) Schiele se représente maigre et malade.\n2. En français, en trois ou quatre phrases : qu'est-ce que chacun des deux peintres veut dire de lui-même ?\n3. Rédige en allemand un texte de 80 à 100 mots : *Wie würdest du dich in einem Selbstporträt oder auf einem Selfie darstellen? Was zeigst du, was versteckst du? Warum?*","bareme":[{"critere":"Trois traductions justes (verbe réfléchi, dar- séparé, place du verbe)","points":6},{"critere":"Analyse : Dürer affirme sa dignité de créateur ; Schiele avoue un malaise intérieur","points":4},{"critere":"Production de 80 à 100 mots qui répond aux trois questions, idées développées","points":6},{"critere":"Correction de la langue : verbe en 2e position, verbes réfléchis, vocabulaire du chapitre","points":4}],"dureeMin":18,"corrige":"1. a) *Dürer malt sich von vorn.* (accepté : *Dürer malt sich selbst von vorn.*)\nb) *Er will seine Würde als Künstler zeigen.*\nc) *Schiele stellt sich dünn und krank dar.* (*sich darstellen* est séparable : *dar* en fin de proposition.)\n\n2. **Dürer** prend une pose réservée au Christ : il affirme la **dignité du créateur**, l'artiste n'est plus un simple artisan. **Schiele**, quatre siècles plus tard, se montre maigre, tordu, presque nu : l'autoportrait devient l'**aveu d'un malaise intérieur**. Tous deux choisissent ce qu'ils montrent : l'image voulue en dit autant que la réalité.\n\n3. Exemple de production :\n*Auf einem Selfie zeige ich mich meistens lustig und glücklich, mit meinen Freunden oder beim Sport. Ich zeige nicht, wenn ich müde oder traurig bin, denn ich möchte ein gutes Bild von mir geben. Aber das ist nur ein Teil von mir. In einem Selbstporträt würde ich mich anders darstellen: ruhig, mit einem Buch, weil ich gern lese. Ich würde meine Brille nicht verstecken. Wie Schiele würde ich vielleicht auch zeigen, dass ich manchmal Zweifel habe. Ein Bild sagt nie die ganze Wahrheit.*\n\nOn attend : réponse aux trois questions (comment je me représente, ce que je montre et ce que je cache, pourquoi) ; au moins une justification (*weil*, *denn*) ; vocabulaire du chapitre (*sich darstellen, das Selbstporträt, zeigen, verstecken, das Selbstbild*) ; verbe en 2e position dans les principales, verbe à la fin après *weil*, *wenn*, *dass*. La forme *würde* + infinitif est bienvenue mais non exigée."}$exo$::jsonb),
  ('5d8e5f36-5636-5ef7-a2cc-48026a7f9cc4'::uuid, 1, 'traduction', $exo${"titre":"Lukas habite chez Frau Becker","consigne":"Lis le texte, puis réponds aux questions en français.","enonce":"**Texte** (texte écrit pour l'exercice)\n\n> Lukas studiert in Köln. Ein Zimmer ist dort sehr teuer. Seit Oktober wohnt er bei Frau Becker, 78 Jahre alt. Er zahlt keine Miete, aber er hilft ihr: Er kauft ein, trägt die Wasserkisten und repariert ihren Computer. Am Abend spielen sie manchmal Karten. „Frau Becker erzählt mir viel von früher“, sagt Lukas. „Und ich zeige ihr, wie man mit den Enkeln per Video telefoniert.“ Das Projekt heißt „Wohnen für Hilfe“.\n\n*Aide : die Miete = le loyer ; die Wasserkiste = le pack d'eau ; von früher = d'autrefois.*\n\n1. Relève : a) la ville où étudie Lukas ; b) l'âge de Frau Becker ; c) trois choses que Lukas fait pour elle.\n2. Pourquoi Lukas a-t-il choisi ce logement ?\n3. Traduis les deux phrases entre guillemets.\n4. Explique en deux phrases ce que chacun apporte à l'autre.","bareme":[{"critere":"Cologne, 78 ans et trois services relevés","points":6},{"critere":"Raison : les chambres sont chères, il ne paie pas de loyer","points":3},{"critere":"Traduction juste des deux phrases (erzählen, von früher, zeigen, die Enkel)","points":7},{"critere":"Échange dans les deux sens expliqué (aide et souvenirs / nouvelles technologies)","points":4}],"dureeMin":7,"corrige":"1. a) **Cologne** (*Köln*). b) **78 ans**. c) Il **fait les courses** (*kauft ein*), **porte les packs d'eau** (*trägt die Wasserkisten*), **répare son ordinateur** (*repariert ihren Computer*).\n\n2. Une chambre est **très chère** à Cologne (*Ein Zimmer ist dort sehr teuer*) ; chez Frau Becker, il **ne paie pas de loyer** : il paie en rendant service.\n\n3. « Frau Becker me raconte beaucoup de choses sur autrefois », dit Lukas. « Et moi, je lui montre comment on téléphone en vidéo avec ses petits-enfants. »\n\n4. Lukas apporte à Frau Becker de l'**aide au quotidien** et lui transmet un savoir nouveau (la vidéo avec ses petits-enfants). Frau Becker lui offre un **logement** et lui transmet ses **souvenirs** : la transmission se fait dans les deux sens, c'est le principe de *Wohnen für Hilfe*."}$exo$::jsonb),
  ('5d8e5f36-5636-5ef7-a2cc-48026a7f9cc4'::uuid, 2, 'traduction', $exo${"titre":"Une maison pour toutes les générations","consigne":"Lis le texte. Réponds en français à la question 1, en allemand aux questions 2 et 3.","enonce":"**Texte** (texte écrit pour l'exercice)\n\n> In unserer Stadt gibt es seit 2008 ein Mehrgenerationenhaus. Es ist für alle offen: für Kinder, Familien und Senioren. Am Montag helfen Schüler alten Menschen mit dem Smartphone. Am Mittwoch kochen Großeltern mit jungen Familien. Am Freitag machen Kinder ihre Hausaufgaben, und pensionierte Lehrer helfen ihnen. Im Café kann man sich einfach treffen und reden. „Wir können voneinander lernen“, sagt die Leiterin, Frau Yilmaz.\n\n*Aide : pensioniert = retraité ; die Leiterin = la directrice ; sich treffen = se rencontrer.*\n\n1. Présente en français le Mehrgenerationenhaus : pour qui, et trois activités (jour et contenu).\n2. Réponds en allemand par des phrases complètes :\n a) *Für wen ist das Haus offen?*\n b) *Was machen die Schüler am Montag?*\n c) *Was sagt Frau Yilmaz?*\n3. Écris en allemand un courriel de 50 à 70 mots à Frau Yilmaz : tu te présentes, tu proposes ton aide (quel jour, pour quoi faire) et tu expliques pourquoi.","bareme":[{"critere":"Présentation juste : ouvert à tous, trois activités avec leur jour","points":5},{"critere":"Trois réponses justes en phrases allemandes complètes","points":6},{"critere":"Courriel de 50 à 70 mots : formule d'appel, présentation, proposition, justification, formule finale","points":5},{"critere":"Langue correcte : verbe en 2e position, datif après helfen, vocabulaire du chapitre","points":4}],"dureeMin":12,"corrige":"1. Le Mehrgenerationenhaus (maison multigénérations) existe dans la ville depuis 2008 ; il est **ouvert à tous** : enfants, familles, seniors. **Le lundi**, des élèves aident des personnes âgées à se servir de leur smartphone ; **le mercredi**, des grands-parents cuisinent avec de jeunes familles ; **le vendredi**, des enseignants retraités aident des enfants à faire leurs devoirs. Au café, on peut simplement se retrouver et discuter.\n\n2. a) *Das Haus ist für alle offen: für Kinder, Familien und Senioren.*\nb) *Am Montag helfen die Schüler alten Menschen mit dem Smartphone.*\nc) *Sie sagt: „Wir können voneinander lernen.“* (ou *Sie sagt, dass wir voneinander lernen können.*)\n\n3. Exemple :\n*Liebe Frau Yilmaz,\nich heiße Inès, ich bin 15 Jahre alt und gehe in die zehnte Klasse. Ich möchte gern im Mehrgenerationenhaus helfen. Am Montag habe ich Zeit: Ich kann alten Menschen mit dem Smartphone helfen. Meine Großeltern wohnen weit weg, deshalb spreche ich gern mit Senioren. Wir können voneinander lernen!\nViele Grüße\nInès*\n\nOn attend : *Liebe Frau…* / *Viele Grüße* ; présentation ; un jour et une activité ; une raison ; *helfen* + datif (*alten Menschen, ihnen*)."}$exo$::jsonb),
  ('5d8e5f36-5636-5ef7-a2cc-48026a7f9cc4'::uuid, 3, 'traduction', $exo${"titre":"Un combat des générations ?","consigne":"Exploite les documents, puis rédige en allemand un texte argumenté.","enonce":"**Document 1** – Slogan des étudiants ouest-allemands, fin des années 1960 :\n\n> „Trau keinem über 30!“\n\n**Document 2** (texte écrit pour l'exercice)\n\n> Viele Jugendliche gehen freitags mit „Fridays for Future“ auf die Straße. Sie sagen den Erwachsenen: „Ihr habt uns einen kaputten Planeten gegeben!“ Aber auch viele Großeltern demonstrieren – mit „Omas for Future“. Eine Oma erklärt: „Ich kämpfe für meine Enkel.“\n\n*Aide : trauen + datif = faire confiance à ; die Erwachsenen = les adultes ; kämpfen = se battre.*\n\n1. En français : traduis le slogan du document 1. Quelle question les jeunes de 1968 posaient-ils à leurs parents ?\n2. En français : quel reproche les jeunes font-ils aux anciens dans le document 2 ? Quel élément du texte montre que le conflit n'est pas total ?\n3. Rédige en allemand un texte de 100 à 120 mots : *Gibt es heute einen Kampf der Generationen?* Donne au moins un argument pour et un argument contre, avec un exemple, puis ton avis.","bareme":[{"critere":"Slogan traduit ; question sur le rôle des parents sous le nazisme","points":4},{"critere":"Reproche : planète abîmée ; nuance : les Omas for Future manifestent aussi","points":4},{"critere":"Texte de 100 à 120 mots : un argument pour, un contre, des exemples, un avis","points":7},{"critere":"Langue : connecteurs (aber, denn, weil, deshalb), ordre des mots, vocabulaire du chapitre","points":5}],"dureeMin":20,"corrige":"1. « **Ne fais confiance à personne de plus de 30 ans !** » Les jeunes de 1968 demandaient à leurs parents : **qu'avez-vous fait sous le nazisme ?** Beaucoup d'anciens nazis occupaient encore des postes importants.\n\n2. Les jeunes reprochent aux adultes de leur **laisser une planète abîmée** (*einen kaputten Planeten*). Mais des **grands-parents manifestent aussi**, avec *Omas for Future* : une grand-mère se bat pour ses petits-enfants. Le conflit n'oppose donc pas toutes les générations.\n\n3. Exemple :\n*Gibt es heute einen Kampf der Generationen? Einerseits sind viele Jugendliche wütend. Mit „Fridays for Future“ sagen sie, dass die Erwachsenen die Umwelt kaputt gemacht haben. Auch die Rente ist ein Problem: Die Gesellschaft wird älter, deshalb müssen die Jungen mehr bezahlen. Andererseits kämpfen viele Großeltern mit „Omas for Future“ für ihre Enkel. Und in Mehrgenerationenhäusern helfen Junge und Alte einander. 1968 war der Konflikt viel stärker, denn die Studenten fragten ihre Eltern nach dem Nazismus. Ich denke, es gibt heute keinen echten Kampf, sondern eine Diskussion. Wir können voneinander lernen, und jede Generation braucht die andere.*\n\nOn attend : une introduction qui reprend la question ; au moins un argument **pour** (colère climatique, retraites, *Generationenvertrag*) et un **contre** (*Omas for Future*, entraide, *Wohnen für Hilfe*, maisons multigénérations) ; un exemple ; un avis final (*Ich denke / Ich finde, dass…*). Connecteurs variés avec le bon ordre des mots (*deshalb* + inversion, *weil/dass* + verbe final, *denn* + ordre normal)."}$exo$::jsonb),
  ('38809e26-c505-5e51-a8cf-9e7d05be194a'::uuid, 1, 'traduction', $exo${"titre":"Deux pavés devant le numéro 12","consigne":"Lis le texte, puis réponds aux questions en français.","enonce":"**Texte** (texte écrit pour l'exercice)\n\n> Vor dem Haus Nummer 12 in unserer Straße liegen zwei kleine Steine aus Messing. Auf jedem Stein stehen ein Name, ein Geburtsjahr und ein Datum. Hier wohnte eine jüdische Familie, bevor die Nazis sie deportiert haben. Der Künstler Gunter Demnig hat diese „Stolpersteine“ erfunden. Man stolpert nicht mit den Füßen, sondern mit dem Kopf und mit dem Herzen. Jedes Jahr putzen wir mit der Schule die Steine. So vergessen wir die Namen nicht.\n\n*Aide : das Messing = le laiton ; stolpern = trébucher ; erfinden (erfunden) = inventer ; putzen = nettoyer.*\n\n1. Relève : a) où se trouvent les pierres ; b) en quelle matière elles sont ; c) ce qui est écrit dessus ; d) qui les a inventées.\n2. Traduis : *Man stolpert nicht mit den Füßen, sondern mit dem Kopf und mit dem Herzen.*\n3. Pourquoi les élèves nettoient-ils les pierres chaque année ? Relie ta réponse à l'idée des Stolpersteine.","bareme":[{"critere":"Quatre informations relevées (devant le n° 12, laiton, nom-année de naissance-date, Gunter Demnig)","points":8},{"critere":"Traduction juste (nicht… sondern, les deux compléments)","points":6},{"critere":"Explication : ne pas oublier les noms des victimes, travail de mémoire","points":6}],"dureeMin":7,"corrige":"1. a) **Devant la maison numéro 12** de la rue (*vor dem Haus Nummer 12*), là où vivait la famille. b) En **laiton** (*aus Messing*). c) **Un nom, une année de naissance et une date** (celle de la déportation). d) L'artiste **Gunter Demnig**.\n\n2. « On ne trébuche pas avec les pieds, mais avec la tête et avec le cœur. » (*nicht… sondern* = non pas… mais.)\n\n3. Les élèves nettoient les pierres pour que **les noms restent lisibles et ne soient pas oubliés** (*So vergessen wir die Namen nicht*). C'est l'idée des *Stolpersteine* : « un homme n'est oublié que lorsque son nom est oublié ». On « trébuche » du regard sur le nom d'une victime du nazisme, devant son dernier domicile. Ce geste fait partie de l'***Aufarbeitung der Vergangenheit***, le travail de l'Allemagne pour assumer les crimes nazis et la Shoah."}$exo$::jsonb),
  ('38809e26-c505-5e51-a8cf-9e7d05be194a'::uuid, 2, 'traduction', $exo${"titre":"Le grand-père de Paul et la RDA","consigne":"Lis le dialogue. Réponds en français aux questions 1, 2 et 4, en allemand à la question 3.","enonce":"**Dialogue** (texte écrit pour l'exercice)\n\n> **Paul:** Opa, du hast bis 1990 in der DDR gelebt. Vermisst du die DDR?\n> **Opa:** Die Mauer und die Stasi vermisse ich überhaupt nicht! Aber ich erinnere mich gern an unsere Nachbarn. Wir haben uns immer geholfen. Und jeder hatte eine Arbeit.\n> **Paul:** Und nach der Wiedervereinigung?\n> **Opa:** Meine Fabrik hat 1991 zugemacht. Das war schwer. Aber jetzt kann ich reisen, wohin ich will.\n> **Paul:** Deshalb hast du noch das Ampelmännchen an deinem Schlüssel!\n> **Opa:** Genau. Das ist ein Stück Erinnerung, keine Politik.\n\n*Aide : vermissen = regretter l'absence de ; zumachen = fermer ; der Schlüssel = la clé.*\n\n1. Qu'est-ce que le grand-père ne regrette pas du tout ? Qu'est-ce qu'il regrette ? Cite le texte.\n2. Traduis : *Meine Fabrik hat 1991 zugemacht. Das war schwer. Aber jetzt kann ich reisen, wohin ich will.*\n3. Réponds en allemand par une phrase complète, avec *sich erinnern an* : *Woran erinnert sich der Opa gern?*\n4. Explique ce qu'est l'Ostalgie et pourquoi la dernière réplique du grand-père est importante.","bareme":[{"critere":"Ne regrette pas le Mur et la Stasi ; regrette l'entraide et la sécurité de l'emploi, avec citations","points":5},{"critere":"Traduction juste (zugemacht, schwer, wohin ich will)","points":5},{"critere":"Phrase juste : Er erinnert sich gern an seine Nachbarn (an + accusatif)","points":4},{"critere":"Ostalgie définie ; souvenir affectif sans regret de la dictature","points":6}],"dureeMin":11,"corrige":"1. Il ne regrette **pas du tout le Mur ni la Stasi** (*Die Mauer und die Stasi vermisse ich überhaupt nicht!*). Il se souvient avec plaisir de la **solidarité entre voisins** (*Wir haben uns immer geholfen*) et de la **sécurité de l'emploi** (*jeder hatte eine Arbeit*).\n\n2. « Mon usine a fermé en 1991. C'était difficile. Mais maintenant, je peux voyager où je veux. »\n\n3. *Er erinnert sich gern an seine Nachbarn.* (accepté : *an die Nachbarn* ; *sich erinnern an* + accusatif.)\n\n4. L'**Ostalgie** (*Ost* + *Nostalgie*) est la nostalgie de certains aspects de la vie en RDA après la réunification : produits, solidarité, sécurité de l'emploi. La dernière réplique montre que ce regret est **affectif** : l'Ampelmännchen est un souvenir, « pas de la politique ». Regretter certains aspects de la vie en RDA ne signifie **pas regretter la dictature** : le grand-père apprécie sa liberté de voyager."}$exo$::jsonb),
  ('38809e26-c505-5e51-a8cf-9e7d05be194a'::uuid, 3, 'traduction', $exo${"titre":"Pourquoi se souvenir ?","consigne":"Traduis les deux phrases, puis rédige en allemand un texte argumenté en t'appuyant sur des exemples du cours.","enonce":"**Sujet.** Pour le journal franco-allemand de ton lycée, tu écris un article sur la mémoire en Allemagne.\n\n*Aide : ermorden = assassiner ; das Denkmal = le monument ; sich erinnern an + acc. = se souvenir de ; die Vergangenheit = le passé ; niederknien (kniete nieder) = s'agenouiller ; das Ghetto = le ghetto.*\n\n1. Traduis en allemand :\n a) On ne doit pas oublier que les nazis ont assassiné des millions de personnes.\n b) En 1970, le chancelier Willy Brandt s'est agenouillé à Varsovie.\n2. Rédige en allemand un article de 100 à 120 mots : *Warum ist es wichtig, sich an die Vergangenheit zu erinnern?* Appuie-toi sur au moins **deux** exemples de lieux ou de gestes de mémoire, et termine par ton avis.","bareme":[{"critere":"Traduction a) juste (Man darf nicht vergessen, dass… verbe final)","points":4},{"critere":"Traduction b) juste (prétérit ou parfait, place du verbe après 1970)","points":3},{"critere":"Article de 100 à 120 mots, deux exemples exacts du cours, avis final","points":8},{"critere":"Langue : subordonnées, sich erinnern an, vocabulaire de la mémoire","points":5}],"dureeMin":20,"corrige":"1. a) *Man darf nicht vergessen, dass die Nazis Millionen (von) Menschen ermordet haben.*\nb) *1970 kniete der Bundeskanzler Willy Brandt in Warschau nieder.* (accepté : *1970 ist Willy Brandt in Warschau niedergekniet.* / *… hat sich … hingekniet* ; verbe conjugué en 2e position après *1970*.)\n\n2. Exemple :\n*Warum ist es wichtig, sich an die Vergangenheit zu erinnern? In Deutschland gibt es viele Orte der Erinnerung. In Berlin steht seit 2005 das Denkmal für die ermordeten Juden Europas mit 2711 Stelen. In vielen Straßen liegen Stolpersteine: Auf jedem Stein stehen der Name und die Geschichte eines Opfers. So vergisst man die Namen nicht. 1970 kniete Willy Brandt in Warschau nieder: Das war ein starkes Zeichen. Diese Aufarbeitung war nicht einfach, aber sie war nötig. Ich finde, dass man sich erinnern muss, weil man aus der Vergangenheit lernt. Wer die Vergangenheit vergisst, kann dieselben Fehler wiederholen.*\n\nOn attend : deux exemples exacts parmi le mémorial de Berlin (2005, 2 711 stèles), les *Stolpersteine* (Gunter Demnig), l'agenouillement de Brandt (1970), les procès d'Auschwitz à Francfort (1963-1965), les camps devenus mémoriaux, éventuellement la mine Zollverein pour la mémoire industrielle ; une justification (*weil*, *denn*) ; un avis final ; vocabulaire *die Erinnerung, das Denkmal, die Vergangenheit, sich erinnern an*."}$exo$::jsonb),
  ('7218dfa3-6b7f-5130-8e2c-e7a581f93e89'::uuid, 1, 'traduction', $exo${"titre":"L'Allemagne sort du nucléaire","consigne":"Lis le texte, puis réponds aux questions en français.","enonce":"**Texte** (texte écrit pour l'exercice)\n\n> Im Jahr 2011 gab es in Japan die Atomkatastrophe von Fukushima. Danach hat Deutschland entschieden: Wir steigen aus der Atomkraft aus. Im April 2023 sind die letzten drei Kernkraftwerke vom Netz gegangen. Heute kommt mehr als die Hälfte des Stroms aus erneuerbaren Energien: Wind, Sonne und Biomasse. Aber es gibt Probleme: Der Wind weht vor allem im Norden, die Industrie ist oft im Süden. Man muss neue Stromleitungen bauen, und der Strom ist teuer.\n\n*Aide : aussteigen = sortir ; vom Netz gehen = être déconnecté du réseau ; der Strom = l'électricité ; wehen = souffler ; die Leitung = la ligne.*\n\n1. Relève deux dates et dis ce qui s'est passé à chacune.\n2. D'où vient aujourd'hui plus de la moitié de l'électricité allemande ? Cite les trois sources.\n3. Traduis les deux dernières phrases du texte (*Aber es gibt Probleme… teuer.*).\n4. Comment appelle-t-on en allemand ce tournant énergétique ?","bareme":[{"critere":"2011 : Fukushima puis décision de sortir du nucléaire ; avril 2023 : arrêt des trois derniers réacteurs","points":6},{"critere":"Énergies renouvelables : vent, soleil, biomasse","points":4},{"critere":"Traduction juste des deux phrases (vor allem, oft, bauen, teuer)","points":7},{"critere":"die Energiewende","points":3}],"dureeMin":7,"corrige":"1. **2011** : catastrophe nucléaire de **Fukushima** au Japon ; ensuite l'Allemagne **décide de sortir du nucléaire**. **Avril 2023** : les **trois derniers réacteurs** sont déconnectés du réseau.\n\n2. Des **énergies renouvelables** : le **vent** (éolien), le **soleil** (solaire) et la **biomasse**.\n\n3. « Mais il y a des problèmes : le vent souffle surtout dans le nord, l'industrie est souvent dans le sud. Il faut construire de nouvelles lignes électriques, et l'électricité est chère. »\n\n4. ***die Energiewende*** (le tournant, la transition énergétique)."}$exo$::jsonb),
  ('7218dfa3-6b7f-5130-8e2c-e7a581f93e89'::uuid, 2, 'traduction', $exo${"titre":"Un pays qui manque de bras","consigne":"Lis le texte. Réponds en français à la question 1, en allemand aux questions 2 et 3.","enonce":"**Texte** (texte écrit pour l'exercice)\n\n> In Deutschland bekommen Frauen im Durchschnitt nur etwa 1,4 Kinder. Gleichzeitig leben die Menschen immer länger. Das hat Folgen: Viele Firmen finden keine Fachkräfte, zum Beispiel in Krankenhäusern und im Handwerk. Und wer bezahlt später die Renten? Eine Lösung ist die Einwanderung: Deutschland sucht Pflegekräfte und Ingenieure aus dem Ausland.\n\n*Aide : im Durchschnitt = en moyenne ; die Folge = la conséquence ; das Handwerk = l'artisanat ; die Einwanderung = l'immigration ; die Pflegekraft = l'aide-soignant(e) ; das Ausland = l'étranger.*\n\n1. Explique en français les deux causes de la crise démographique et deux de ses conséquences. Quelle solution le texte propose-t-il ?\n2. Réponds en allemand par des phrases complètes :\n a) *Wie viele Kinder bekommen Frauen in Deutschland im Durchschnitt?*\n b) *Wo fehlen Fachkräfte?*\n3. Écris en allemand 50 à 70 mots : *Möchtest du später im Ausland arbeiten, zum Beispiel in Deutschland? Warum (nicht)?*","bareme":[{"critere":"Causes (peu d'enfants, espérance de vie), conséquences (pénurie de main-d'œuvre, retraites), solution (immigration)","points":6},{"critere":"Deux réponses justes en phrases allemandes complètes","points":5},{"critere":"Production de 50 à 70 mots qui répond et justifie","points":5},{"critere":"Langue : verbe en 2e position, weil ou denn bien construits, vocabulaire du chapitre","points":4}],"dureeMin":12,"corrige":"1. Causes : les femmes ont **peu d'enfants** (environ **1,4** par femme en moyenne) et les gens **vivent de plus en plus longtemps**. Conséquences : beaucoup d'entreprises ne trouvent **pas de main-d'œuvre qualifiée** (*der Fachkräftemangel*), par exemple dans les hôpitaux et l'artisanat ; le **financement des retraites** devient difficile. Solution proposée : l'**immigration** de travailleurs qualifiés (aides-soignants, ingénieurs).\n\n2. a) *Sie bekommen im Durchschnitt nur etwa 1,4 Kinder.*\nb) *Fachkräfte fehlen zum Beispiel in Krankenhäusern und im Handwerk.*\n\n3. Exemple :\n*Ja, ich möchte später gern in Deutschland arbeiten. Ich lerne Deutsch, und ich interessiere mich für Technik. Deutschland sucht Ingenieure, deshalb habe ich dort gute Chancen. Außerdem möchte ich eine andere Kultur kennenlernen. Aber ich würde meine Familie vermissen. Vielleicht arbeite ich zwei oder drei Jahre in Deutschland und komme dann zurück nach Frankreich.*\n\nOn attend : une réponse claire (oui / non / peut-être), au moins deux raisons, un connecteur de cause ou de conséquence correctement construit, réemploi du texte (*Fachkräfte, das Ausland, suchen*)."}$exo$::jsonb),
  ('7218dfa3-6b7f-5130-8e2c-e7a581f93e89'::uuid, 3, 'traduction', $exo${"titre":"Quel défi pour l'Allemagne ?","consigne":"Exploite les documents, puis rédige en allemand un texte argumenté.","enonce":"**Document 1** – Première phrase de la Loi fondamentale allemande (1949) :\n\n> „Die Würde des Menschen ist unantastbar.“\n\n**Document 2** (texte écrit pour l'exercice)\n\n> In den bayerischen Alpen fällt immer weniger Schnee. Viele Skigebiete benutzen Schneekanonen, aber sie brauchen viel Wasser und Energie. Andere Orte bieten im Winter jetzt Wandern und Mountainbiken an.\n\n*Aide : die Würde = la dignité ; unantastbar = intangible ; das Skigebiet = la station de ski ; anbieten = proposer ; die Herausforderung = le défi.*\n\n1. Traduis le document 1. Pourquoi la RFA a-t-elle voulu, après le nazisme, une « démocratie capable de se défendre » (*wehrhafte Demokratie*) ?\n2. Résume en français le problème des stations de ski et les deux réponses possibles.\n3. Rédige en allemand un texte de 100 à 120 mots : *Welche Herausforderung ist für Deutschland die wichtigste: die Energiewende, die Demografie oder die Demokratie?* Présente au moins deux défis avec un exemple chacun, puis donne ton avis argumenté.","bareme":[{"critere":"Traduction juste ; lien avec la dictature nazie et la défense de la démocratie contre ses ennemis","points":4},{"critere":"Manque de neige dû au réchauffement ; canons à neige ou reconversion (randonnée, VTT)","points":4},{"critere":"Texte de 100 à 120 mots : deux défis exacts avec exemples, avis argumenté","points":7},{"critere":"Langue : connecteurs, ordre des mots, vocabulaire (Herausforderung, Energiewende, Fachkräftemangel…)","points":5}],"dureeMin":20,"corrige":"1. « **La dignité humaine est intangible.** » Après la dictature nazie, arrivée au pouvoir dans une république, la RFA a voulu une démocratie **capable de se défendre contre ses ennemis** ; elle place la dignité humaine en tête de sa Loi fondamentale et éduque à la démocratie (*politische Bildung*, *Bundeszentrale für politische Bildung*).\n\n2. Avec le **réchauffement**, il tombe de moins en moins de **neige** dans les Alpes bavaroises. Certaines stations utilisent des **canons à neige**, qui consomment beaucoup d'eau et d'énergie ; d'autres se **reconvertissent** en proposant l'hiver de la **randonnée** et du **VTT**.\n\n3. Exemple :\n*Deutschland steht vor großen Herausforderungen. Die erste ist die Energiewende: Seit April 2023 gibt es keine Kernkraftwerke mehr, und mehr als die Hälfte des Stroms kommt aus erneuerbaren Energien. Aber der Strom ist teuer, und man muss neue Leitungen bauen. Die zweite ist die Demografie: Die Frauen bekommen nur etwa 1,4 Kinder, deshalb fehlen Fachkräfte. Wer bezahlt später die Renten? Ich denke, dass die Energiewende am wichtigsten ist, weil der Klimawandel alle betrifft. In den Alpen fällt schon weniger Schnee. Aber ohne Fachkräfte kann man auch keine Windräder bauen. Die beiden Herausforderungen hängen also zusammen.*\n\nOn attend : deux défis présentés avec des faits exacts du cours (Energiewende et dates, 1,4 enfant par femme et *Fachkräftemangel*, retraites, *wehrhafte Demokratie*, manque de neige) ; un avis justifié ; des connecteurs bien construits."}$exo$::jsonb),
  ('fee03f30-f26b-575e-9a22-e29e7393ddb2'::uuid, 1, 'traduction', $exo${"titre":"Le rocher de la Loreley","consigne":"Lis le texte, puis réponds aux questions en français.","enonce":"**Texte** (texte écrit pour l'exercice)\n\n> Die Loreley ist ein hoher Felsen am Rhein. Hier ist der Fluss eng und gefährlich. Früher sind hier viele Schiffe gesunken. Der Dichter Clemens Brentano hat 1801 die Figur einer jungen Frau erfunden. 1824 hat Heinrich Heine ein berühmtes Gedicht geschrieben: Eine schöne Frau sitzt auf dem Felsen und kämmt ihr goldenes Haar. Die Schiffer schauen nur nach oben und sinken. Heute kommen jedes Jahr viele Touristen zum Felsen.\n\n*Aide : der Felsen = le rocher ; eng = étroit ; sinken (gesunken) = couler, sombrer ; erfinden (erfunden) = inventer ; kämmen = peigner ; der Schiffer = le batelier.*\n\n1. Relève : a) sur quel fleuve se trouve la Loreley ; b) pourquoi ce passage est dangereux ; c) qui invente la figure de la jeune femme, et en quelle année.\n2. Traduis : *Eine schöne Frau sitzt auf dem Felsen und kämmt ihr goldenes Haar. Die Schiffer schauen nur nach oben und sinken.*\n3. Heine commence son poème ainsi : *„Ich weiß nicht, was soll es bedeuten, / Dass ich so traurig bin“*. Traduis ces deux vers.\n4. Qu'est-ce qui est réel et qu'est-ce qui est légende dans l'histoire de la Loreley ?","bareme":[{"critere":"Le Rhin ; fleuve étroit et dangereux ; Clemens Brentano en 1801","points":6},{"critere":"Traduction juste des deux phrases","points":6},{"critere":"Traduction juste des deux vers de Heine","points":4},{"critere":"Réel : le rocher, le passage dangereux ; légende : la sirène inventée par les poètes","points":4}],"dureeMin":8,"corrige":"1. a) Le **Rhin** (*am Rhein*). b) Le fleuve y est **étroit et dangereux** (*eng und gefährlich*) : beaucoup de bateaux y ont coulé. c) Le poète **Clemens Brentano**, en **1801**.\n\n2. « Une belle femme est assise sur le rocher et peigne sa chevelure d'or. Les bateliers ne regardent que vers le haut et sombrent. »\n\n3. « Je ne sais pas ce que cela veut dire, que je sois si triste. » (accepté : « Je ne sais pas ce que cela signifie, d'être si triste. »)\n\n4. **Réel** : un rocher du Rhin, un passage étroit, dangereux pour les bateliers, où des bateaux ont coulé. **Légende** : la jeune femme, inventée par Brentano en 1801, que Heine transforme en 1824 en sirène qui fait sombrer les bateliers. Mis en musique par Friedrich Silcher, le poème est devenu une chanson connue de tous les Allemands, et le rocher attire aujourd'hui les touristes."}$exo$::jsonb),
  ('fee03f30-f26b-575e-9a22-e29e7393ddb2'::uuid, 2, 'traduction', $exo${"titre":"Faust, le savant insatisfait","consigne":"Lis le texte. Réponds en français aux questions 1 et 2, en allemand à la question 3.","enonce":"**Texte** (texte écrit pour l'exercice, qui résume l'histoire)\n\n> Faust ist ein Gelehrter. Er hat alles studiert, aber er ist nicht zufrieden: Er will alles wissen und alles erleben. Da kommt Mephisto, der Teufel. Die beiden schließen eine Wette: Wenn Faust einmal ganz zufrieden ist, gehört seine Seele dem Teufel. Goethe hat diese Geschichte 1808 veröffentlicht. Schon 1587 erzählte ein Volksbuch von einem Doktor Faust, der einen Pakt mit dem Teufel schließt und verdammt wird.\n\n*Aide : der Gelehrte = le savant ; zufrieden = satisfait ; erleben = vivre, faire l'expérience de ; die Wette = le pari ; die Seele = l'âme ; veröffentlichen = publier ; verdammt = damné.*\n\n1. Présente Faust en français : qui est-il, que veut-il, quel accord fait-il avec Méphisto ?\n2. Quelle différence le texte fait-il entre le *Volksbuch* de 1587 et la version de Goethe ? Que signifie aujourd'hui l'adjectif *faustisch* ?\n3. Faust dit chez Goethe : *„Zwei Seelen wohnen, ach! in meiner Brust.“* Traduis cette phrase, puis écris en allemand 40 à 60 mots : *Gibt es heute noch „faustische“ Menschen? Nenne ein Beispiel.*","bareme":[{"critere":"Faust savant insatisfait, qui veut tout savoir et tout vivre ; pari avec Méphisto sur son âme","points":5},{"critere":"Volksbuch : pacte et damnation ; Goethe : pari ; faustisch = ambition sans limite","points":5},{"critere":"Traduction juste de la citation","points":3},{"critere":"Production de 40 à 60 mots avec un exemple pertinent, langue correcte","points":7}],"dureeMin":12,"corrige":"1. Faust est un **savant** qui a tout étudié mais qui n'est **pas satisfait** : il veut **tout savoir et tout vivre**. Méphisto, le **diable**, lui propose un **pari** : si Faust est un jour pleinement satisfait, son **âme** appartiendra au diable.\n\n2. Dans le *Volksbuch* de **1587**, Faust signe un **pacte** avec le diable et il est **damné**. Chez **Goethe** (*Faust I*, **1808**), l'accord devient un **pari**, et Faust est surtout avide de connaissance. L'adjectif ***faustisch*** qualifie une **ambition sans limite**.\n\n3. « **Deux âmes habitent, hélas, ma poitrine.** »\nExemple de production :\n*Ja, ich denke, es gibt heute noch faustische Menschen. Manche Forscher wollen alles wissen und alles machen, zum Beispiel mit der künstlichen Intelligenz. Sie arbeiten Tag und Nacht und denken nicht an die Gefahren. Auch Sportler nehmen manchmal Doping, weil sie immer gewinnen wollen. Das ist wie ein Pakt mit dem Teufel.*\n\nOn attend : une réponse claire, un exemple concret relié à l'idée d'ambition sans limite, phrases correctes (verbe en 2e position, *weil* + verbe final)."}$exo$::jsonb),
  ('fee03f30-f26b-575e-9a22-e29e7393ddb2'::uuid, 3, 'traduction', $exo${"titre":"Réécrire un conte","consigne":"Réponds en français à la question 1, puis rédige en allemand la réécriture demandée et termine par un court commentaire en français.","enonce":"**Rappel.** Dans les *Contes de l'enfance et du foyer* des frères Grimm (1812), la forêt est le lieu de l'épreuve : Hänsel et Gretel s'y perdent, le Petit Chaperon rouge y rencontre le loup. En 2017, la série allemande *Dark* place ses grottes et ses disparitions d'enfants dans une forêt, autour de la ville fictive de Winden. Le héros Siegfried, vainqueur du dragon, sert aujourd'hui à vendre des bières et des jeux vidéo.\n\n*Aide : der Wald = la forêt ; sich verlaufen (verlief sich) = se perdre ; die Hexe = la sorcière ; das Handy = le portable ; der Akku ist leer = la batterie est vide ; das Märchen = le conte.*\n\n1. En français : montre, à l'aide de deux exemples du rappel, que la forêt et les héros des mythes allemands sont sans cesse repris et transformés.\n2. Écris en allemand une version moderne de *Hänsel und Gretel* en 80 à 100 mots, au présent ou au passé : deux adolescents d'aujourd'hui se perdent dans une forêt. Garde au moins deux éléments du conte (la forêt, la maison, la sorcière…) et ajoute des éléments d'aujourd'hui.\n3. En français, en deux ou trois phrases : qu'est-ce que ta réécriture dit de notre époque ?","bareme":[{"critere":"Deux exemples exacts de reprise (Grimm → Dark ; Siegfried → marketing) et idée de transformation","points":4},{"critere":"Récit de 80 à 100 mots, cohérent, qui garde deux éléments du conte et en modernise d'autres","points":7},{"critere":"Langue du récit : conjugaison, verbe en 2e position, vocabulaire du chapitre","points":5},{"critere":"Commentaire : la reprise d'un mythe révèle les préoccupations de l'époque","points":4}],"dureeMin":20,"corrige":"1. La **forêt** des contes de Grimm (1812), lieu de l'épreuve où Hänsel et Gretel se perdent, est reprise en 2017 par la série ***Dark***, qui y place des disparitions d'enfants : même lieu inquiétant, nouvel habillage (science-fiction, voyages dans le temps). **Siegfried**, héros de la *Chanson des Nibelungen* (vers 1200), inspire Wagner puis devient un argument de **marketing** (bières, jeux vidéo) : le mythe devient produit. Recréer n'est pas copier.\n\n2. Exemple :\n*Hanna und Tim sind fünfzehn. Am Samstag machen sie eine Wanderung im Wald. Sie schauen nur auf ihr Handy und verlaufen sich. Plötzlich ist der Akku leer: kein GPS, kein Netz! Es wird dunkel, und sie haben Angst. Da sehen sie ein kleines Haus aus Holz mit Licht. Eine alte Frau öffnet die Tür und lächelt: „Kommt herein, ich habe Kuchen!“ Ist sie eine Hexe? Nein, sie ist eine Försterin. Sie gibt ihnen Tee und ein Ladekabel. Am nächsten Morgen zeigt sie ihnen den Weg nach Hause. Jetzt lassen Hanna und Tim das Handy manchmal zu Hause.*\n\nOn attend : un récit cohérent, deux éléments du conte (forêt, maison, sorcière, les deux enfants, la peur), des éléments d'aujourd'hui, des verbes correctement conjugués (présent ou prétérit/parfait), le verbe en deuxième position.\n\n3. Exemple : ma réécriture montre notre dépendance au téléphone et notre peur d'être coupés du réseau ; la « sorcière » n'est plus menaçante, la vraie épreuve est de se passer de l'écran. Comme toute reprise d'un mythe, elle parle autant de **notre époque** que du conte d'origine."}$exo$::jsonb),
  ('bc69cf7f-eda0-5ad0-a94f-43541f150383'::uuid, 1, 'traduction', $exo${"titre":"Lübeck, reine de la Hanse","consigne":"Lis le texte, puis réponds aux questions en français.","enonce":"**Texte** (texte écrit pour l'exercice)\n\n> Deutschland liegt in der Mitte Europas und hat neun Nachbarländer, mehr als jedes andere Land in Europa. Im Mittelalter haben Kaufleute die Hanse gegründet. Lübeck war die „Königin der Hanse“. Die Städte handelten mit Salz, Hering, Holz und Pelzen. Noch heute steht auf den Autokennzeichen von Hamburg „HH“: Das bedeutet „Hansestadt Hamburg“.\n\n*Aide : der Kaufmann (pl. die Kaufleute) = le marchand ; gründen = fonder ; handeln mit = faire le commerce de ; der Pelz = la fourrure ; das Kennzeichen = la plaque d'immatriculation.*\n\n1. Relève : a) le nombre de pays voisins de l'Allemagne ; b) la ville surnommée « reine de la Hanse » ; c) quatre marchandises échangées.\n2. Traduis : *Noch heute steht auf den Autokennzeichen von Hamburg „HH“: Das bedeutet „Hansestadt Hamburg“.*\n3. Qu'était la Hanse ? Pourquoi peut-on parler d'une « mondialisation avant l'heure » ?\n4. Que désigne le mot *Mitteleuropa* ?","bareme":[{"critere":"Neuf voisins ; Lübeck ; sel, hareng, bois, fourrures","points":6},{"critere":"Traduction juste (noch heute, das Kennzeichen, bedeuten)","points":5},{"critere":"Hanse : association de villes marchandes ; réseau de commerce entre plusieurs pays","points":6},{"critere":"Mitteleuropa = l'Europe du milieu","points":3}],"dureeMin":7,"corrige":"1. a) **Neuf** pays voisins (*neun Nachbarländer*), plus que tout autre pays d'Europe. b) **Lübeck**. c) Le **sel**, le **hareng**, le **bois** et les **fourrures**.\n\n2. « Aujourd'hui encore, il y a “HH” sur les plaques d'immatriculation de Hambourg : cela signifie “ville hanséatique de Hambourg”. »\n\n3. La **Hanse** était une **association de villes marchandes** (du XIIe au XVIIe siècle) autour de la mer du Nord et de la Baltique : Lübeck, Hambourg, Brême, avec des comptoirs à Londres, Bruges, Bergen ou Novgorod. On parle de **mondialisation avant l'heure** parce que ce **réseau commercial** reliait de nombreux pays et échangeait des marchandises sur de longues distances.\n\n4. *Mitteleuropa* désigne l'**Europe du milieu**, l'espace au centre de l'Europe où se trouve l'aire germanophone."}$exo$::jsonb),
  ('bc69cf7f-eda0-5ad0-a94f-43541f150383'::uuid, 2, 'traduction', $exo${"titre":"D'ennemis à partenaires","consigne":"Lis le texte. Réponds en allemand aux questions 1 et 3, en français à la question 2.","enonce":"**Texte** (texte écrit pour l'exercice)\n\n> Frankreich und Deutschland haben dreimal gegeneinander Krieg geführt: 1870, 1914 und 1939. Nach 1945 wollten beide Länder Frieden. 1951 gründeten sie mit vier anderen Ländern die Europäische Gemeinschaft für Kohle und Stahl. 1957 kamen die Römischen Verträge. 1963 unterschrieben Charles de Gaulle und Konrad Adenauer den Élysée-Vertrag. Seitdem gibt es viele Schüleraustausche. Seit 2002 bezahlen beide Länder mit dem Euro.\n\n*Aide : Krieg führen = faire la guerre ; die Kohle = le charbon ; der Stahl = l'acier ; der Vertrag (pl. Verträge) = le traité ; unterschreiben = signer ; der Austausch = l'échange.*\n\n1. Réponds en allemand par des phrases complètes :\n a) *Wie oft haben Frankreich und Deutschland gegeneinander Krieg geführt?*\n b) *Was ist 1963 passiert?*\n c) *Seit wann bezahlt man in beiden Ländern mit dem Euro?*\n2. En français : explique le passage « d'ennemis à partenaires ». Que signifie *die Versöhnung* ?\n3. Écris en allemand 50 à 70 mots : *Warum ist die deutsch-französische Freundschaft heute noch wichtig?* Donne au moins deux raisons.","bareme":[{"critere":"Trois réponses justes en phrases allemandes complètes","points":6},{"critere":"Passage expliqué avec les étapes (CECA, traités de Rome, Élysée) ; Versöhnung = réconciliation","points":5},{"critere":"Production de 50 à 70 mots avec deux raisons","points":5},{"critere":"Langue : ordre des mots, connecteurs, vocabulaire (Zusammenarbeit, Nachbar, Frieden)","points":4}],"dureeMin":12,"corrige":"1. a) *Sie haben dreimal gegeneinander Krieg geführt: 1870, 1914 und 1939.*\nb) *1963 haben Charles de Gaulle und Konrad Adenauer den Élysée-Vertrag unterschrieben.*\nc) *Seit 2002 bezahlt man in beiden Ländern mit dem Euro.*\n\n2. Après trois guerres (1870, 1914, 1939), la France et l'Allemagne choisissent la **paix** et fondent ensemble la construction européenne : la **CECA** en 1951, la **CEE** par les traités de Rome en 1957, puis le **traité de l'Élysée** en 1963 ; en 2002, l'euro remplace le mark. On parle de **couple franco-allemand**. *Die Versöhnung* signifie **la réconciliation**.\n\n3. Exemple :\n*Die deutsch-französische Freundschaft ist heute noch wichtig, weil die beiden Länder Nachbarn sind. Zusammen sind sie ein Motor für Europa. Ohne Zusammenarbeit kann die EU keine großen Entscheidungen treffen. Außerdem gibt es viele Schüleraustausche: Junge Menschen lernen die andere Sprache und Kultur kennen. So bleibt der Frieden stabil. Ich habe selbst eine Brieffreundin in Freiburg.*\n\nOn attend : deux raisons (paix, moteur de l'Europe, échanges, économie), un connecteur bien construit, vocabulaire du chapitre."}$exo$::jsonb),
  ('bc69cf7f-eda0-5ad0-a94f-43541f150383'::uuid, 3, 'traduction', $exo${"titre":"Locomotive ou chef de l'Europe ?","consigne":"Exploite les données, puis rédige en allemand un texte argumenté et nuancé.","enonce":"**Données**\n\n- L'Allemagne est la **première économie** de l'Union européenne et son **pays le plus peuplé** (environ 84 millions d'habitants).\n- Elle a **neuf voisins**, plus que tout autre pays d'Europe.\n- Depuis la chute du rideau de fer (1989) et l'élargissement de l'UE (2004), la **Pologne**, la Tchéquie ou la Hongrie sont devenues des partenaires économiques majeurs : des usines s'y sont installées, les échanges d'étudiants se multiplient.\n- Ses voisins attendent qu'elle entraîne l'Europe, mais craignent qu'elle domine.\n\n*Aide : die Lokomotive = la locomotive ; der Chef = le chef ; die Wirtschaft = l'économie ; stark = fort ; die Angst vor + dat. = la peur de ; die Einwohner = les habitants.*\n\n1. Traduis en allemand : a) L'Allemagne a neuf pays voisins. b) C'est le pays le plus peuplé de l'Union européenne.\n2. Rédige en allemand un texte de 100 à 120 mots : *Ist Deutschland die Lokomotive oder der Chef Europas?* Présente au moins un argument pour chaque point de vue, avec un exemple, et termine par ton avis.","bareme":[{"critere":"Deux traductions justes (neun Nachbarländer ; das bevölkerungsreichste Land / hat die meisten Einwohner)","points":5},{"critere":"Argument « locomotive » avec exemple exact (économie, Pologne, construction européenne)","points":4},{"critere":"Argument « chef » (poids dans les décisions, crainte des voisins) et avis final nuancé","points":5},{"critere":"Langue : connecteurs variés, ordre des mots, vocabulaire du chapitre, 100 à 120 mots","points":6}],"dureeMin":20,"corrige":"1. a) *Deutschland hat neun Nachbarländer.*\nb) *Es ist das bevölkerungsreichste Land der Europäischen Union.* (accepté : *Deutschland hat die meisten Einwohner in der EU.*)\n\n2. Exemple :\n*Ist Deutschland die Lokomotive oder der Chef Europas? Einerseits ist Deutschland die erste Wirtschaft der EU und hat etwa 84 Millionen Einwohner. Es liegt in der Mitte Europas und hat neun Nachbarn. Seit 2004 sind Polen und Tschechien wichtige Partner: Deutsche Firmen bauen dort Fabriken, und viele Studenten machen einen Austausch. So zieht Deutschland die anderen Länder mit wie eine Lokomotive. Andererseits haben manche Nachbarn Angst vor einem zu starken Deutschland, denn es spielt eine große Rolle bei den Entscheidungen. Ich denke, dass Deutschland eine Lokomotive sein soll, aber kein Chef. Europa funktioniert nur mit Zusammenarbeit, wie beim deutsch-französischen Paar.*\n\nOn attend : un argument « locomotive » (poids économique, partenariats à l'Est, moteur franco-allemand) et un argument « chef » (poids dans les décisions, crainte de domination), avec des faits exacts ; un avis nuancé ; des connecteurs (*einerseits… andererseits, denn, deshalb, aber*) et le vocabulaire du chapitre (*der Nachbar, die Zusammenarbeit, die EU, der Handel*)."}$exo$::jsonb),
  ('fcbde816-6447-525b-8c07-7cf09823fbd5'::uuid, 1, 'traduction', $exo${"titre":"De « j'ai su » à « j'aurais su »","consigne":"Mets chaque forme au subjonctif II passé et traduis-la. Réponds ensuite aux questions.","enonce":"1. Mets ces verbes au **subjonctif II passé**, puis traduis la forme obtenue en français.\n a) ich habe gewusst\n b) du bist gekommen\n c) wir haben gespielt\n d) sie ist geblieben\n e) er hat gearbeitet\n f) ihr seid gefahren\n g) ich bin gefallen\n h) sie haben gegessen (*ils*)\n2. Comment choisit-on entre *hätte* et *wäre* ?\n3. Traduis et explique la différence : *Ich hatte Zeit.* / *Ich hätte Zeit gehabt.*\n4. Complète avec l'auxiliaire qui convient et place-le correctement : *Wenn ich das gewusst ___, ___ ich gekommen.*","bareme":[{"critere":"Huit formes justes (hätte ou wäre selon l'auxiliaire du parfait, terminaisons correctes)","points":8},{"critere":"Huit traductions au conditionnel passé","points":4},{"critere":"Règle : même auxiliaire qu'au parfait ; hatte (prétérit) / hätte (subjonctif) distingués et traduits","points":4},{"critere":"Phrase complétée : gewusst hätte (auxiliaire en fin), wäre ich gekommen","points":4}],"dureeMin":8,"corrige":"1. a) *ich hätte gewusst* : j'aurais su.\nb) *du wär(e)st gekommen* : tu serais venu(e).\nc) *wir hätten gespielt* : nous aurions joué.\nd) *sie wäre geblieben* : elle serait restée.\ne) *er hätte gearbeitet* : il aurait travaillé.\nf) *ihr wär(e)t gefahren* : vous seriez partis (allés en voiture, en train…).\ng) *ich wäre gefallen* : je serais tombé(e).\nh) *sie hätten gegessen* : ils auraient mangé.\n\n2. On garde **le même auxiliaire qu'au parfait** : *haben* devient *hätte*, *sein* devient *wäre*, suivi du participe II.\n\n3. *Ich hatte Zeit* : « **j'avais** le temps » (prétérit, fait réel). *Ich hätte Zeit gehabt* : « **j'aurais eu** le temps » (subjonctif II passé, irréel). Un seul tréma change le sens.\n\n4. *Wenn ich das gewusst **hätte**, **wäre** ich gekommen.* Dans la subordonnée en *wenn*, l'auxiliaire conjugué vient **en dernier** ; la principale commence par son verbe (*wäre*), car la subordonnée occupe la première place. (« Si j'avais su, je serais venu. »)"}$exo$::jsonb),
  ('fcbde816-6447-525b-8c07-7cf09823fbd5'::uuid, 2, 'traduction', $exo${"titre":"Regrets et reproches","consigne":"Transforme les phrases comme indiqué, puis traduis les phrases françaises en allemand.","enonce":"1. Transforme en **condition irréelle du passé** (une phrase avec *wenn*) :\n a) *Ich hatte keine Zeit. Ich habe dir nicht geholfen.*\n b) *Es hat geregnet. Wir sind nicht an den Strand gegangen.*\n2. Exprime un **regret** à partir de la phrase : *Ich habe nicht mehr gelernt.* (deux tournures possibles)\n3. Exprime un **reproche** à partir de la phrase : *Du hast mich nicht angerufen.*\n4. Traduis en allemand :\n a) J'ai failli rater le bus. (*verpassen*)\n b) Si nous étions partis plus tôt, nous n'aurions pas raté le train. (*abfahren*, parfait avec *sein*)","bareme":[{"critere":"Deux conditions irréelles justes (hätte/wäre, auxiliaire final dans la subordonnée, principale commençant par le verbe)","points":6},{"critere":"Regret juste (Hätte ich doch… / Wenn ich nur… hätte!)","points":4},{"critere":"Reproche juste : Du hättest mich anrufen sollen","points":4},{"critere":"Deux traductions justes","points":6}],"dureeMin":11,"corrige":"1. a) *Wenn ich Zeit gehabt hätte, hätte ich dir geholfen.* (Si j'avais eu le temps, je t'aurais aidé.)\nb) *Wenn es nicht geregnet hätte, wären wir an den Strand gegangen.* (*gehen* se conjugue avec *sein* au parfait → *wären … gegangen*.)\n\n2. *Hätte ich doch mehr gelernt!* ou *Wenn ich nur mehr gelernt hätte!* (Si seulement j'avais plus travaillé !)\n\n3. *Du hättest mich anrufen sollen.* (Tu aurais dû m'appeler.)\n\n4. a) *Fast hätte ich den Bus verpasst.* (ce qui a failli arriver : *fast* + subjonctif II passé ; *verpassen* prend *haben*.)\nb) *Wenn wir früher abgefahren wären, hätten wir den Zug nicht verpasst.* (*abfahren* → *wären … abgefahren* ; *verpassen* → *hätten … verpasst*.)"}$exo$::jsonb),
  ('fcbde816-6447-525b-8c07-7cf09823fbd5'::uuid, 3, 'traduction', $exo${"titre":"Le concert raté","consigne":"Traduis le texte en allemand, puis rédige un court texte personnel au subjonctif II passé.","enonce":"1. Traduis en allemand :\n\n> Si j'avais su que le concert était complet, je serais resté à la maison. Mon ami aurait dû acheter les billets plus tôt. Au retour, nous avons failli rater le dernier train. Si seulement nous étions partis plus tôt !\n\n*Aide : complet = ausverkauft ; le billet = die Karte ; rester = bleiben (sein) ; rater = verpassen (haben) ; partir = abfahren (sein) ; le dernier train = der letzte Zug ; au retour = auf dem Rückweg.*\n\n2. Rédige en allemand 50 à 70 mots : *Was hättest du im letzten Schuljahr anders gemacht?* Utilise au moins une condition irréelle avec *wenn*, un regret et un reproche (à toi-même ou à quelqu'un d'autre).","bareme":[{"critere":"Première phrase juste (Wenn ich gewusst hätte, dass… war, wäre ich… geblieben)","points":4},{"critere":"Reproche et « failli » justes (hätte… kaufen sollen ; fast hätten wir… verpasst)","points":4},{"critere":"Regret final juste (Wären wir doch… abgefahren ! / Wenn wir nur… abgefahren wären !)","points":2},{"critere":"Texte de 50 à 70 mots avec condition irréelle, regret et reproche","points":6},{"critere":"Formes et ordre des mots corrects dans la production","points":4}],"dureeMin":18,"corrige":"1. Traduction modèle :\n*Wenn ich gewusst hätte, dass das Konzert ausverkauft war, wäre ich zu Hause geblieben. Mein Freund hätte die Karten früher kaufen sollen. Auf dem Rückweg hätten wir fast den letzten Zug verpasst. Wären wir doch früher abgefahren!* (ou *Wenn wir nur früher abgefahren wären!*)\nPoints de vigilance : *hätte* en fin de subordonnée ; *wäre ich … geblieben* (principale qui commence par le verbe) ; reproche en *hätte … kaufen sollen* ; *fast* + subjonctif II passé ; *abfahren* avec *sein*. (*… dass das Konzert ausverkauft ist* est aussi accepté.)\n\n2. Exemple :\n*Im letzten Schuljahr habe ich zu wenig gelesen. Hätte ich doch mehr Bücher gelesen! Wenn ich jeden Tag Vokabeln gelernt hätte, wäre meine Note in Deutsch besser gewesen. Ich hätte auch früher ins Bett gehen sollen, denn ich war oft müde. Fast hätte ich den Schüleraustausch verpasst, aber meine Mutter hat mich daran erinnert. Dieses Jahr mache ich es besser!*\n\nOn attend : une condition irréelle avec *wenn* (auxiliaire en fin de subordonnée, principale commençant par le verbe), un regret (*Hätte ich doch… !* / *Wenn ich nur… !*), un reproche (*Ich hätte … sollen* / *Du hättest … sollen*), le bon choix entre *hätte* et *wäre*."}$exo$::jsonb),
  ('5468a974-5a8d-5ed8-8285-f239695567ce'::uuid, 1, 'traduction', $exo${"titre":"La bonne préposition, le bon cas","consigne":"Complète chaque phrase avec la préposition et l'article qui conviennent, puis réponds aux questions.","enonce":"1. Complète avec la préposition et l'article défini au bon cas (le genre du nom est indiqué).\n a) Ich warte ___ ___ Bus. (*der*)\n b) Wir interessieren uns ___ ___ Geschichte. (*die*)\n c) Sie hat Angst ___ ___ Hund. (*der*)\n d) Ich nehme ___ ___ Wettbewerb teil. (*der*)\n e) Das hängt ___ ___ Wetter ab. (*das*)\n f) Die Eltern sind stolz ___ ___ Sohn. (*der*)\n g) Ich kümmere mich ___ ___ Katze. (*die*)\n h) Wir sprechen ___ ___ Film. (*der*)\n2. Pourquoi dit-on *Angst vor* **dem** *Hund* (datif), alors que *vor* peut aussi être suivi de l'accusatif ?\n3. Traduis : *Ich freue mich auf die Ferien.* / *Ich freue mich über dein Geschenk.* Explique la différence.","bareme":[{"critere":"Huit compléments justes (préposition et cas de l'article)","points":12},{"critere":"La rection fixe le cas une fois pour toutes, sans idée de lieu ni de mouvement","points":3},{"critere":"Traductions justes ; auf = chose à venir, über = chose présente ou passée","points":5}],"dureeMin":8,"corrige":"1. a) *auf den Bus* (*warten auf* + acc.)\nb) *für die Geschichte* (*sich interessieren für* + acc.)\nc) *vor dem Hund* (*Angst haben vor* + dat.)\nd) *an dem (am) Wettbewerb* (*teilnehmen an* + dat.)\ne) *von dem (vom) Wetter* (*abhängen von* + dat.)\nf) *auf den Sohn* (*stolz auf* + acc.)\ng) *um die Katze* (*sich kümmern um* + acc.)\nh) *über den Film* (*sprechen über* + acc.)\n\n2. Avec un verbe (ou un adjectif) à rection prépositionnelle, le cas est **fixé une fois pour toutes** : il ne dépend ni du lieu ni du mouvement. *Angst haben vor* demande toujours le **datif**. C'est pourquoi on apprend le verbe avec sa préposition et son cas, comme un seul mot.\n\n3. « Je me réjouis des vacances (à venir). » / « Je suis content(e) de ton cadeau. » *sich freuen auf* + acc. : se réjouir d'une chose **à venir** ; *sich freuen über* + acc. : se réjouir d'une chose **présente ou passée**."}$exo$::jsonb),
  ('5468a974-5a8d-5ed8-8285-f239695567ce'::uuid, 2, 'traduction', $exo${"titre":"Traduire sans calquer le français","consigne":"Traduis chaque phrase en allemand, puis pose les questions demandées.","enonce":"1. Traduis en allemand :\n a) Je m'intéresse à la musique.\n b) Nous participons à un concours. (*der Wettbewerb*)\n c) Elle rêve d'un voyage au Canada. (*die Reise nach Kanada*)\n d) As-tu peur de l'examen ? (*die Prüfung*)\n e) Je pense souvent à mon grand-père.\n f) Mon frère s'occupe de notre chien.\n2. Pose la question qui porte sur le groupe souligné, en tenant compte de la différence entre une personne et une chose :\n a) *Ich warte auf **meine Schwester**.*\n b) *Er spricht über **seine Reise**.*\n3. Explique en français pourquoi « attendre quelqu'un » et « avoir peur de » sont des pièges pour un francophone.","bareme":[{"critere":"Six traductions justes (préposition, cas, verbe séparable teilnehmen, verbes réfléchis)","points":12},{"critere":"Deux questions justes : Auf wen wartest du ? / Worüber spricht er ?","points":4},{"critere":"Pièges expliqués : warten auf sans équivalent français ; « de » devient vor","points":4}],"dureeMin":11,"corrige":"1. a) *Ich interessiere mich für Musik.*\nb) *Wir nehmen an einem Wettbewerb teil.* (*teilnehmen an* + dat., préverbe séparable en fin de phrase)\nc) *Sie träumt von einer Reise nach Kanada.*\nd) *Hast du Angst vor der Prüfung?*\ne) *Ich denke oft an meinen Großvater.* (*denken an* + acc.)\nf) *Mein Bruder kümmert sich um unseren Hund.* (*sich kümmern um* + acc.)\n\n2. a) Une personne : préposition + pronom interrogatif → ***Auf wen*** *wartest du?*\nb) Une chose : *wo(r)-* + préposition → ***Worüber*** *spricht er?*\n\n3. En français, on « attend quelqu'un » **sans préposition**, alors que l'allemand dit ***warten auf*** + accusatif. Et « avoir peur **de** » ne se traduit pas par *von* : on dit ***Angst haben vor*** + datif. Le français ne guide pas : il faut apprendre chaque verbe avec sa préposition et son cas."}$exo$::jsonb),
  ('5468a974-5a8d-5ed8-8285-f239695567ce'::uuid, 3, 'traduction', $exo${"titre":"Le courriel de Tom","consigne":"Corrige les fautes du courriel en justifiant, puis rédige ta réponse en allemand.","enonce":"**Courriel de Tom** (il contient **six fautes** de préposition ou de cas)\n\n> Liebe Anna,\n> ich freue mich über die Ferien nächste Woche! Ich denke oft an dir. Mein Bruder interessiert sich an Fußball. Am Samstag nimmt er an ein Turnier teil. Meine Mutter hat Angst von dem Wetter. Wir warten für deine Antwort!\n> Bis bald, Tom\n\n1. Relève les six fautes, corrige-les et justifie chaque correction (préposition et cas).\n2. Rédige en allemand la réponse d'Anna (60 à 80 mots). Elle parle de ce qui l'intéresse, de ce qu'elle attend avec impatience et de ce dont elle a peur. Utilise au moins **cinq** verbes ou adjectifs à rection prépositionnelle différents, avec le bon cas.","bareme":[{"critere":"Six fautes relevées et corrigées","points":6},{"critere":"Chaque correction justifiée par la rection (préposition + cas)","points":4},{"critere":"Réponse de 60 à 80 mots, cohérente, qui traite les trois thèmes","points":5},{"critere":"Cinq rections différentes employées correctement","points":5}],"dureeMin":18,"corrige":"1. Corrections :\n- *über die Ferien* → ***auf die Ferien*** : les vacances sont **à venir** (*sich freuen auf* + acc.).\n- *an dir* → ***an dich*** : *denken an* + **accusatif**.\n- *interessiert sich an* → ***für Fußball*** : *sich interessieren für* + acc.\n- *an ein Turnier* → ***an einem Turnier*** : *teilnehmen an* + **datif**.\n- *Angst von dem Wetter* → ***Angst vor dem Wetter*** : *Angst haben vor* + dat.\n- *warten für* → ***warten auf deine Antwort*** : *warten auf* + acc.\n\n2. Exemple :\n*Lieber Tom,\nvielen Dank für deine Mail! Ich freue mich auch auf die Ferien. Ich interessiere mich sehr für Musik und nehme im Juli an einem Chorwettbewerb teil. Meine Eltern sind stolz auf mich. Aber ich habe ein bisschen Angst vor dem Konzert, denn das Publikum ist groß. Meine Oma kümmert sich um meinen kleinen Bruder, wenn ich probe. Ich denke oft an unsere Reise nach Wien!\nBis bald, Anna*\n\nRections attendues (cinq parmi) : *sich freuen auf* + acc., *sich interessieren für* + acc., *teilnehmen an* + dat., *stolz auf* + acc., *Angst haben vor* + dat., *sich kümmern um* + acc., *denken an* + acc., *träumen von* + dat., *warten auf* + acc., *sprechen über* + acc."}$exo$::jsonb),
  ('3a430ec2-1f93-50b9-ba19-dd4cdf573202'::uuid, 1, 'traduction', $exo${"titre":"Former les mots en da- et en wo-","consigne":"Forme les mots demandés, puis réponds aux questions.","enonce":"1. Forme le pronom en *da-* et le mot interrogatif en *wo-* pour chaque préposition : *mit, für, auf, an, über, von, um*.\n2. Pourquoi écrit-on *darauf* avec un **r**, mais *damit* sans **r** ?\n3. Remplace le groupe souligné par un pronom en *da-* ou par préposition + pronom personnel :\n a) *Ich warte auf **den Zug**.*\n b) *Ich warte auf **meine Schwester**.*\n c) *Er spricht über **das Konzert**.*\n d) *Wir denken an **unseren Lehrer**.*\n4. Existe-t-il une forme en *da-* avec *ohne* ?","bareme":[{"critere":"Quatorze formes justes (sept en da-, sept en wo-)","points":7},{"critere":"Règle du r : préposition commençant par une voyelle","points":3},{"critere":"Quatre remplacements justes selon chose ou personne","points":8},{"critere":"Pas de forme en da- avec ohne","points":2}],"dureeMin":7,"corrige":"1. *mit* → *damit / womit* ; *für* → *dafür / wofür* ; *auf* → *darauf / worauf* ; *an* → *daran / woran* ; *über* → *darüber / worüber* ; *von* → *davon / wovon* ; *um* → *darum / worum*.\n\n2. Quand la préposition commence par une **voyelle** (*auf, an, über, um*), on intercale un **r** : *da-r-auf*. *mit* commence par une consonne : *damit*.\n\n3. a) *Ich warte **darauf**.* (le train est une chose)\nb) *Ich warte **auf sie**.* (une personne : préposition + pronom)\nc) *Er spricht **darüber**.* (une chose)\nd) *Wir denken **an ihn**.* (une personne)\n\n4. **Non** : il n'y a pas de forme en *da-* avec *ohne* (ni avec *seit*, *außer*, *gegenüber*)."}$exo$::jsonb),
  ('3a430ec2-1f93-50b9-ba19-dd4cdf573202'::uuid, 2, 'traduction', $exo${"titre":"Questions et réponses","consigne":"Pose la question sur le groupe souligné, puis réponds par « Ja, … » en reprenant ce groupe par un pronom.","enonce":"Pour chaque phrase : a) pose la question qui porte sur le groupe souligné ; b) réponds à la question *Stimmt das?* par une phrase commençant par *Ja,* qui reprend ce groupe par un pronom.\n\nExemple : *Ich warte auf **das Paket**.* → *Worauf wartest du?* → *Ja, ich warte darauf.*\n\n1. *Ich interessiere mich für **Fotografie**.*\n2. *Ich denke an **meinen Bruder**.*\n3. *Sie träumt von **einem Hund**.*\n4. *Wir sprechen über **die Klassenfahrt**.*\n5. *Er hat Angst vor **der Lehrerin**.*\n6. *Ihr erinnert euch an **den Urlaub**.*","bareme":[{"critere":"Six questions justes : wo- pour les choses, préposition + wen/wem pour les personnes","points":10},{"critere":"Six reprises justes : da- pour les choses, préposition + pronom personnel pour les personnes","points":10}],"dureeMin":10,"corrige":"1. *Wofür interessierst du dich?* → *Ja, ich interessiere mich dafür.* (une chose)\n2. *An wen denkst du?* → *Ja, ich denke an ihn.* (une personne : *an* + acc. → *wen*, *ihn*)\n3. *Wovon träumt sie?* → *Ja, sie träumt davon.* (une chose)\n4. *Worüber sprecht ihr?* → *Ja, wir sprechen darüber.* (une chose)\n5. *Vor wem hat er Angst?* → *Ja, er hat Angst vor ihr.* (une personne : *vor* + dat. → *wem*, *ihr*)\n6. *Woran erinnert ihr euch?* → *Ja, wir erinnern uns daran.* (une chose)\n\nRègle d'or : *da-* et *wo-* ne remplacent **que des choses** (ou des idées) ; pour une **personne**, on garde **préposition + pronom** (*an ihn*, *vor ihr*) et, pour la question, **préposition + wen/wem**."}$exo$::jsonb),
  ('3a430ec2-1f93-50b9-ba19-dd4cdf573202'::uuid, 3, 'traduction', $exo${"titre":"Annoncer ce qui suit","consigne":"Traduis les phrases en utilisant un pronom en da- qui annonce la suite, puis rédige un dialogue.","enonce":"1. Traduis en allemand, en utilisant un pronom en *da-* qui annonce la subordonnée ou le groupe infinitif :\n a) Je me réjouis que tu viennes samedi. (*sich freuen auf*)\n b) Il pense à prendre son passeport. (*denken an* ; *mitnehmen* ; *der Pass*)\n c) Nous parlons de ce que nous faisons le week-end. (*sprechen über*)\n d) Je m'intéresse à la façon dont on fait un film. (*sich interessieren für* ; *wie man…*)\n2. Pourquoi le français n'a-t-il pas besoin de ces pronoms ?\n3. Rédige en allemand un dialogue de 8 à 10 répliques entre deux amis qui préparent une fête. Emploie au moins **deux** mots interrogatifs en *wo-*, **deux** pronoms en *da-* (dont un qui annonce une subordonnée ou un infinitif) et **une** reprise d'une personne par préposition + pronom.","bareme":[{"critere":"Quatre traductions justes (pronom en da-, virgule, verbe final ou zu + infinitif)","points":8},{"critere":"Explication : le français dit « que… » sans trace de la préposition","points":2},{"critere":"Dialogue cohérent de 8 à 10 répliques","points":4},{"critere":"Formes demandées présentes et justes (deux wo-, deux da- dont un annonçant, une personne)","points":6}],"dureeMin":18,"corrige":"1. a) *Ich freue mich darauf, dass du am Samstag kommst.*\nb) *Er denkt daran, seinen Pass mitzunehmen.*\nc) *Wir sprechen darüber, was wir am Wochenende machen.*\nd) *Ich interessiere mich dafür, wie man einen Film macht.*\n\n2. Le français dit simplement « je me réjouis **que**… », « il pense **à** prendre… » : la subordonnée suit directement. L'allemand **garde la trace de la préposition** du verbe par le pronom en *da-*, qui annonce ce qui suit.\n\n3. Exemple :\n*Lea: Worüber sollen wir zuerst sprechen?\nMax: Über die Musik. Ich kümmere mich darum.\nLea: Super! Und woran denkst du noch?\nMax: An das Essen. Ich denke daran, Pizza zu bestellen.\nLea: Wartest du noch auf Jonas?\nMax: Ja, ich warte auf ihn. Er bringt die Getränke.\nLea: Wovon träumst du für die Party?\nMax: Davon, dass alle tanzen!\nLea: Ich freue mich schon darauf!*\n\nFormes attendues : *worüber, woran, wovon* (questions sur des choses), *darum, daran… zu* (annonce d'un infinitif), *davon, dass…*, *darauf* ; *auf ihn* (reprise d'une personne)."}$exo$::jsonb),
  ('bd269c7c-0d90-57de-ae34-c341e21718e0'::uuid, 1, 'traduction', $exo${"titre":"Le suffixe donne le genre","consigne":"Donne l'article défini de chaque nom et le repère qui te permet de le trouver.","enonce":"1. Donne l'article (*der, die, das*) de chaque nom et indique le suffixe qui le justifie :\n\n*Hoffnung – Brötchen – Gesundheit – Pessimismus – Einsamkeit – Tourist – Gesellschaft – Dokument – Religion – Qualität – Drama – Politik – Motor – Präsident – Datum – Bäckerei*\n\n2. *Mädchen* désigne une fille. Pourquoi dit-on pourtant **das** *Mädchen* ?\n3. Que faut-il faire pour un nom court sans suffixe, comme *Tisch*, *Tür* ou *Buch* ?","bareme":[{"critere":"Seize articles justes","points":12},{"critere":"Suffixes cités comme justification","points":4},{"critere":"-chen rend neutre : le genre suit le suffixe, pas le sexe","points":2},{"critere":"Apprendre chaque nom court avec son article","points":2}],"dureeMin":8,"corrige":"1. *die Hoffnung* (-ung) ; *das Brötchen* (-chen) ; *die Gesundheit* (-heit) ; *der Pessimismus* (-ismus) ; *die Einsamkeit* (-keit) ; *der Tourist* (-ist) ; *die Gesellschaft* (-schaft) ; *das Dokument* (-ment) ; *die Religion* (-ion) ; *die Qualität* (-tät) ; *das Drama* (-ma) ; *die Politik* (-ik) ; *der Motor* (-or) ; *der Präsident* (-ent) ; *das Datum* (-um) ; *die Bäckerei* (-ei).\n\n2. Le suffixe ***-chen*** (comme *-lein*) rend le nom **neutre**, même quand il désigne une personne : **le genre suit le suffixe, pas le sexe**.\n\n3. Pour les mots courts sans suffixe (*der Tisch, die Tür, das Buch*), il n'y a pas de règle sûre : il faut **apprendre chaque nom avec son article** (et sa couleur dans le cahier)."}$exo$::jsonb),
  ('bd269c7c-0d90-57de-ae34-c341e21718e0'::uuid, 2, 'traduction', $exo${"titre":"Familles de sens et mots fabriqués","consigne":"Donne le genre de chaque nom en justifiant par une famille de sens ou par une formation.","enonce":"1. Donne l'article et la famille de sens qui le justifie :\n*Sonntag – Herbst – Nebel – Osten – Grün – Gebirge – Sonne*\n2. Forme un nom à partir de chaque verbe ou adjectif, donne son article et nomme la formation (conversion ou dérivation implicite) :\n a) *schwimmen* → *das …* b) *besuchen* → *der …* c) *springen* → *der …* d) *essen* → *das …* e) *bauen* → *der …*\n3. Les noms en *-e* sont en général féminins. Cite deux exceptions du cours et explique-les.\n4. Donne l'article de ces mots d'origine étrangère : *Kultur, Kooperation, Klima, Argument*.","bareme":[{"critere":"Sept articles justes avec la famille de sens (jours, saisons, météo, points cardinaux, couleurs, Ge-, -e)","points":7},{"critere":"Cinq noms formés, articles justes, conversion (neutre) et dérivation implicite (masculin) nommées","points":6},{"critere":"Deux exceptions en -e : der Junge, der Name","points":3},{"critere":"die Kultur, die Kooperation, das Klima, das Argument","points":4}],"dureeMin":11,"corrige":"1. *der Sonntag* (jours : masculin) ; *der Herbst* (saisons : masculin) ; *der Nebel* (phénomènes météo : masculin) ; *der Osten* (points cardinaux : masculin) ; *das Grün* (couleur substantivée : neutre) ; *das Gebirge* (la plupart des noms en *Ge-* : neutre) ; *die Sonne* (la plupart des noms en *-e* : féminin).\n\n2. a) *das Schwimmen* : **conversion** (infinitif substantivé → neutre).\nb) *der Besuch* : **dérivation implicite** (radical verbal devenu nom → masculin).\nc) *der Sprung* : dérivation implicite → masculin.\nd) *das Essen* : conversion → neutre.\ne) *der Bau* : dérivation implicite → masculin.\n\n3. *der Junge* et *der Name* sont masculins bien qu'ils finissent par *-e* (*der Junge* désigne un garçon). La règle du *-e* féminin vaut pour **la plupart** des noms, pas pour tous.\n\n4. *die Kultur* ; *die Kooperation* (-ion) ; *das Klima* (-ma) ; *das Argument* (-ment). Les mots étrangers suivent leurs suffixes."}$exo$::jsonb),
  ('bd269c7c-0d90-57de-ae34-c341e21718e0'::uuid, 3, 'traduction', $exo${"titre":"Lena et Aylin","consigne":"Complète le texte avec l'article défini au nominatif ou à l'accusatif, justifie chaque choix, puis fabrique des noms.","enonce":"1. Complète chaque blanc par l'article défini qui convient (*der, die, das* ; aucun nom n'est au datif, et à l'accusatif neutre ou féminin, l'article ne change pas). Justifie chaque choix par un repère du cours.\n\n> (1) ___ Freundschaft zwischen Lena und Aylin ist stark. (2) ___ Mädchen aus Hamburg heißt Lena. Ihr Hobby ist (3) ___ Schwimmen. (4) ___ Winter ist kalt, aber (5) ___ Museum der Stadt ist warm. (6) ___ Optimismus von Aylin gefällt Lena. (7) ___ Zeitung von heute spricht über (8) ___ Gebäude am Fluss. (9) ___ Journalist findet (10) ___ Klima dort angenehm.\n\n2. Forme un nom à partir de chaque mot, avec son article : *gesund – möglich – frei – freund(lich) → Freund… – lesen – springen*. Nomme le repère utilisé.\n3. En français : quelle méthode proposerais-tu à un camarade qui trouve le genre allemand « aléatoire » ? Donne trois conseils tirés du cours.","bareme":[{"critere":"Dix articles justes","points":8},{"critere":"Dix justifications par le bon repère","points":4},{"critere":"Six noms formés avec leur article et leur repère","points":5},{"critere":"Trois conseils pertinents (suffixes, familles de sens, apprendre avec l'article)","points":3}],"dureeMin":18,"corrige":"1. (1) ***Die*** *Freundschaft* (-schaft) ; (2) ***Das*** *Mädchen* (-chen) ; (3) ***das*** *Schwimmen* (infinitif substantivé) ; (4) ***Der*** *Winter* (saison) ; (5) ***das*** *Museum* (-um) ; (6) ***Der*** *Optimismus* (-ismus) ; (7) ***Die*** *Zeitung* (-ung) ; (8) ***das*** *Gebäude* (Ge-, accusatif neutre identique au nominatif) ; (9) ***Der*** *Journalist* (-ist) ; (10) ***das*** *Klima* (-ma, accusatif neutre).\n\n2. *gesund* → ***die Gesundheit*** (-heit) ; *möglich* → ***die Möglichkeit*** (-keit) ; *frei* → ***die Freiheit*** (-heit) ; *Freund* → ***die Freundschaft*** (-schaft) ; *lesen* → ***das Lesen*** (conversion, neutre) ; *springen* → ***der Sprung*** (dérivation implicite, masculin).\n\n3. Conseils attendus : 1) repérer d'abord le **suffixe**, le repère le plus sûr (*-ung, -heit, -keit, -schaft, -ion, -tät* féminins ; *-ismus, -ist, -ling, -or* masculins ; *-chen, -lein, -um, -ment, -ma* neutres) ; 2) penser aux **familles de sens** (jours, mois, saisons, météo : masculins ; infinitifs et couleurs substantivés : neutres) ; 3) pour les mots courts sans repère, **apprendre chaque nom avec son article**. On peut ajouter : se méfier des exceptions (*der Junge*, *der Name*)."}$exo$::jsonb),
  ('d9ad30a6-3cab-5bfc-9fa9-314a9c56ff99'::uuid, 1, 'traduction', $exo${"titre":"Der Mensch, den Menschen","consigne":"Décline les noms demandés, puis trie la liste en justifiant.","enonce":"1. Décline au singulier et au pluriel, avec l'article défini, aux quatre cas : *der Student* et *der Junge*.\n2. À quel seul endroit un masculin faible ne prend-il pas *-(e)n* ?\n3. Parmi ces noms, lesquels sont des masculins faibles ? Justifie chaque réponse.\n*der Tisch – der Kollege – der Käse – der Journalist – der Lehrer – der Held – der Franzose – der Deutsche*","bareme":[{"critere":"Deux tableaux de déclinaison justes (huit formes chacun)","points":8},{"critere":"Seule forme sans -(e)n : nominatif singulier","points":2},{"critere":"Quatre masculins faibles identifiés et justifiés (Kollege, Journalist, Held, Franzose)","points":6},{"critere":"Quatre non-faibles justifiés (Tisch, Käse, Lehrer, Deutsche décliné comme un adjectif)","points":4}],"dureeMin":8,"corrige":"1. **der Student** : singulier *der Student, den Studenten, dem Studenten, des Studenten* ; pluriel *die Studenten, die Studenten, den Studenten, der Studenten*.\n**der Junge** : singulier *der Junge, den Jungen, dem Jungen, des Jungen* ; pluriel *die Jungen, die Jungen, den Jungen, der Jungen*.\n\n2. Au **nominatif singulier** seulement : partout ailleurs, singulier comme pluriel, le nom finit en *-(e)n*.\n\n3. Masculins faibles : ***der Kollege*** (masculin en *-e* désignant un être vivant) ; ***der Journalist*** (mot d'origine étrangère en *-ist*) ; ***der Held*** (mot court à retenir) ; ***der Franzose*** (nationalité en *-e*).\nNon faibles : *der Tisch* et *der Lehrer* (masculins ordinaires : *den Tisch, den Lehrer*) ; *der Käse* (finit par *-e* mais ne désigne pas un être vivant : *den Käse*) ; *der Deutsche* se décline **comme un adjectif** (*ein Deutscher*), ce n'est pas un masculin faible."}$exo$::jsonb),
  ('d9ad30a6-3cab-5bfc-9fa9-314a9c56ff99'::uuid, 2, 'traduction', $exo${"titre":"Des -en à ne pas oublier","consigne":"Complète chaque phrase avec la bonne forme du nom entre parenthèses et indique le cas.","enonce":"1. Complète avec la forme qui convient et indique le cas :\n a) Ich sehe den ___. (*der Nachbar*)\n b) Wir sprechen mit dem ___. (*der Präsident*)\n c) Das ist das Auto des ___. (*der Kollege*)\n d) Der ___ stellt eine Frage. (*der Journalist*)\n e) Kennst du den ___? (*der Franzose*)\n f) Sie hilft dem ___. (*der Junge*)\n g) Ich esse gern ___. (*der Käse*, sans article)\n h) Sehr geehrte Damen und ___! (*der Herr*, pluriel)\n i) Die Rechte des ___. (*der Mensch*)\n j) Ich frage den ___. (*der Herr*, singulier)\n2. Traduis : a) J'interroge le policier. b) Le nom du héros.","bareme":[{"critere":"Dix formes justes","points":10},{"critere":"Cas correctement indiqués","points":4},{"critere":"Deux traductions justes (den Polizisten ; der Name des Helden)","points":6}],"dureeMin":11,"corrige":"1. a) *den **Nachbarn*** (accusatif)\nb) *mit dem **Präsidenten*** (datif)\nc) *des **Kollegen*** (génitif)\nd) *Der **Journalist*** (nominatif singulier : pas de *-en*)\ne) *den **Franzosen*** (accusatif)\nf) *dem **Jungen*** (datif, *helfen* + dat.)\ng) ***Käse*** (accusatif ; *der Käse* n'est pas un masculin faible)\nh) *Damen und **Herren*** (pluriel)\ni) *des **Menschen*** (génitif)\nj) *den **Herrn*** (accusatif singulier : *der Herr* fait *-n* au singulier, *-en* au pluriel)\n\n2. a) *Ich frage den Polizisten.* (*fragen* + accusatif ; *-ist* : masculin faible)\nb) *der Name des Helden* (*der Held* est faible : génitif *des Helden* ; *der Name* est un masculin mixte, mais ici au nominatif)."}$exo$::jsonb),
  ('d9ad30a6-3cab-5bfc-9fa9-314a9c56ff99'::uuid, 3, 'traduction', $exo${"titre":"Le héros du film","consigne":"Corrige le texte en justifiant, puis traduis le texte français en allemand.","enonce":"1. Ce résumé de film contient **six fautes** sur les masculins faibles. Relève-les, corrige-les et justifie (cas et famille du nom).\n\n> Der Held des Films ist ein Soldat. Am Anfang sieht er einen Bär im Wald. Dann hilft er dem Bauer. Später trifft er den Präsident. Der Präsidenten gibt dem Soldat eine Medaille. Alle bewundern den Held.\n\n2. Traduis en allemand :\n\n> Hier, j'ai rencontré un journaliste. Il écrit un article sur le président. Je lui ai parlé de mon voisin, un étudiant français. Le journaliste veut interviewer l'étudiant.\n\n*Aide : treffen (getroffen) = rencontrer ; der Artikel = l'article ; mit jm über etwas sprechen = parler de qqch avec qqn ; interviewen = interviewer.*","bareme":[{"critere":"Six fautes relevées et corrigées","points":6},{"critere":"Corrections justifiées (cas, famille du masculin faible, nominatif sans -en)","points":4},{"critere":"Traduction : les quatre masculins faibles au bon cas (Journalisten, Präsidenten, Nachbarn, Studenten)","points":6},{"critere":"Traduction : temps, ordre des mots et prépositions justes","points":4}],"dureeMin":18,"corrige":"1. Corrections :\n- *einen Bär* → *einen **Bären*** (accusatif ; *der Bär* est un mot court à retenir).\n- *dem Bauer* → *dem **Bauern*** (datif ; *der Bauer* fait partie des mots courts faibles).\n- *den Präsident* → *den **Präsidenten*** (accusatif ; *-ent*).\n- *Der Präsidenten* → *Der **Präsident*** (**nominatif** singulier : c'est la seule forme sans *-en*).\n- *dem Soldat* → *dem **Soldaten*** (datif ; *-at*).\n- *den Held* → *den **Helden*** (accusatif).\n*Der Held* et *ein Soldat* (1re phrase) sont au nominatif : ils sont justes.\n\n2. Traduction modèle :\n*Gestern habe ich einen Journalisten getroffen. Er schreibt einen Artikel über den Präsidenten. Ich habe mit ihm über meinen Nachbarn gesprochen, einen französischen Studenten. Der Journalist will den Studenten interviewen.*\nPoints de vigilance : *einen Journalisten* (accusatif), *über den Präsidenten* (accusatif), *über meinen Nachbarn, einen französischen Studenten* (accusatif, apposition au même cas), *Der Journalist* (nominatif, sans *-en*), *den Studenten* (accusatif) ; verbe en 2e position après *Gestern*."}$exo$::jsonb),
  ('6a8f8b40-3154-5869-b6dd-c30cc135f510'::uuid, 1, 'traduction', $exo${"titre":"Weil, denn, deshalb","consigne":"Relie les phrases avec le mot indiqué en respectant la place du verbe.","enonce":"1. Relie les deux phrases avec le mot indiqué :\n a) *Ich bleibe zu Hause. Ich bin krank.* (*weil*)\n b) *Ich bleibe zu Hause. Ich bin krank.* (*denn*)\n c) *Es regnet. Ich nehme den Bus.* (*deshalb*)\n d) *Er hat viel gelernt. Er hat die Prüfung bestanden.* (*deswegen*)\n e) *Sie war müde. Sie ist früh ins Bett gegangen.* (*so … dass*)\n2. Indique pour chaque mot (*weil, denn, deshalb*) sa nature et la place du verbe qui le suit.\n3. Que signifie *also* ? Comment dit-on « aussi » ?","bareme":[{"critere":"Cinq phrases justes (verbe final, ordre normal, inversion)","points":12},{"critere":"Nature et place du verbe pour weil, denn, deshalb","points":5},{"critere":"also = donc ; aussi = auch","points":3}],"dureeMin":8,"corrige":"1. a) *Ich bleibe zu Hause, weil ich krank **bin**.*\nb) *Ich bleibe zu Hause, denn ich **bin** krank.*\nc) *Es regnet, deshalb **nehme ich** den Bus.*\nd) *Er hat viel gelernt, deswegen **hat er** die Prüfung bestanden.*\ne) *Sie war so müde, dass sie früh ins Bett gegangen **ist**.*\n\n2. ***weil*** : subordonnant, le verbe conjugué va **à la fin**. ***denn*** : coordonnant (position 0), **ordre normal** (sujet puis verbe). ***deshalb*** : adverbe, **inversion** (verbe en 2e position, sujet derrière).\n\n3. ***also*** signifie « **donc** ». « Aussi » se dit ***auch***."}$exo$::jsonb),
  ('6a8f8b40-3154-5869-b6dd-c30cc135f510'::uuid, 2, 'traduction', $exo${"titre":"Un même lien, plusieurs outils","consigne":"Construis les phrases demandées en respectant la place du verbe, puis choisis l'outil qui convient.","enonce":"1. Exprime le lien « Le bus était en retard, donc je suis arrivé trop tard » de **trois** façons : avec *deshalb*, avec *weil*, avec *denn*.\n*Aide : der Bus hatte Verspätung ; ich bin zu spät gekommen.*\n2. Réécris chaque phrase avec l'outil indiqué :\n a) *Es ist heiß. Wir gehen schwimmen.* (*da*, en tête de phrase)\n b) *Ich kann nicht kommen. Ich habe Training.* (*nämlich*)\n c) *Es hat stark geschneit. Die Schule war geschlossen.* (*sodass*)\n d) *Das Spiel fällt aus. Es regnet.* (*wegen* + génitif : *der Regen*)\n3. Pourquoi ne peut-on pas répondre à *Warum?* par *Denn ich bin müde* ?","bareme":[{"critere":"Trois constructions justes du même lien","points":6},{"critere":"Quatre réécritures justes (da, nämlich, sodass, wegen des Regens)","points":10},{"critere":"denn ne peut pas commencer une réponse ; on emploie weil","points":4}],"dureeMin":12,"corrige":"1. *Der Bus hatte Verspätung, deshalb **bin ich** zu spät gekommen.* (adverbe : inversion)\n*Ich bin zu spät gekommen, weil der Bus Verspätung **hatte**.* (subordonnée : verbe à la fin)\n*Ich bin zu spät gekommen, denn der Bus **hatte** Verspätung.* (coordination : ordre normal)\n\n2. a) *Da es heiß **ist**, **gehen** wir schwimmen.* (cause connue en tête ; la principale commence par son verbe.)\nb) *Ich kann nicht kommen, ich **habe** nämlich Training.* (*nämlich* jamais en tête, après le verbe.)\nc) *Es hat stark geschneit, sodass die Schule geschlossen **war**.* (verbe à la fin.)\nd) *Das Spiel fällt **wegen des Regens** aus.* (préposition + génitif, pas de verbe.)\n\n3. *denn* est un coordonnant : il relie deux propositions et **ne peut jamais commencer une réponse** ni une phrase isolée. Pour répondre à *Warum?*, on dit ***Weil ich müde bin.***"}$exo$::jsonb),
  ('6a8f8b40-3154-5869-b6dd-c30cc135f510'::uuid, 3, 'traduction', $exo${"titre":"Faut-il interdire le portable au lycée ?","consigne":"Corrige les phrases fautives, puis rédige un texte argumenté en allemand.","enonce":"1. Ces phrases d'élèves contiennent chacune une faute. Corrige-les et justifie.\n a) *Ich brauche mein Handy, weil ich höre Musik.*\n b) *Das Handy stört, deshalb die Schüler lernen weniger.*\n c) *Warum? Denn es ist gefährlich.*\n d) *Nämlich ist das Handy nützlich.*\n e) *Es ist praktisch, also ich nehme es mit.*\n2. Rédige en allemand un texte de 100 à 120 mots : *Sollte man das Handy in der Schule verbieten?* Donne au moins deux arguments pour et un argument contre, puis ton avis. Utilise au moins **cinq** outils différents de cause ou de conséquence (*weil, da, denn, nämlich, wegen, deshalb, deswegen, darum, also, so … dass, sodass*).\n*Aide : verbieten = interdire ; stören = déranger ; nützlich = utile ; sich konzentrieren = se concentrer.*","bareme":[{"critere":"Cinq phrases corrigées","points":5},{"critere":"Corrections justifiées par la nature de l'outil et la place du verbe","points":3},{"critere":"Texte de 100 à 120 mots : deux arguments pour, un contre, un avis","points":6},{"critere":"Cinq outils différents employés avec la bonne place du verbe","points":6}],"dureeMin":20,"corrige":"1. a) *… weil ich Musik **höre**.* (*weil* : verbe à la fin.)\nb) *… deshalb **lernen die Schüler** weniger.* (*deshalb* : inversion.)\nc) *Warum? **Weil** es gefährlich ist.* (*denn* ne commence jamais une réponse.)\nd) *Das Handy **ist nämlich** nützlich.* (*nämlich* jamais en tête.)\ne) *Es ist praktisch, also **nehme ich** es mit.* (*also* : inversion.)\n\n2. Exemple :\n*Sollte man das Handy in der Schule verbieten? Ich finde, ja. Erstens stört das Handy im Unterricht, weil es oft klingelt. Die Schüler können sich nicht konzentrieren, deshalb lernen sie weniger. Zweitens spielen viele in der Pause nur noch am Handy. Da sie nicht mehr miteinander sprechen, wird die Pause langweilig. Aber das Handy ist auch nützlich: Man kann nämlich schnell Wörter nachschlagen oder die Eltern anrufen. Wegen dieser Vorteile möchten manche Schüler es behalten. Trotzdem denke ich, dass ein Verbot im Unterricht richtig ist. Das Handy ist so attraktiv, dass man ohne Regel nicht aufhört. Man sollte es also nur in Notfällen benutzen.*\n\nOn attend : deux arguments pour et un contre, un avis ; au moins cinq outils différents (ici *weil, deshalb, da, nämlich, wegen, so … dass, also*) avec la bonne construction (verbe final, inversion, ordre normal, génitif après *wegen*)."}$exo$::jsonb),
  ('16e9c918-98a3-5e99-a22f-d8e693511c64'::uuid, 1, 'traduction', $exo${"titre":"A, an, the ou rien ?","consigne":"Complète chaque phrase avec a, an, the ou Ø (article zéro), puis traduis les deux dernières phrases en anglais.","enonce":"**1. Complète avec a, an, the ou Ø.**\n\n1. She is ___ engineer.\n2. I bought ___ umbrella yesterday. ___ umbrella is blue.\n3. ___ sun rises in the east.\n4. It takes ___ hour to get there.\n5. ___ water is essential to life.\n6. We go swimming twice ___ week.\n\n**2. Traduis en anglais.**\n\n7. J'aime la musique.\n8. Les chats sont indépendants.","bareme":[{"critere":"Articles justes dans les six phrases à compléter (a / an / the / Ø)","points":12},{"critere":"Article zéro dans les deux traductions (music, cats au sens général)","points":8}],"dureeMin":7,"corrige":"**1.**\n1. *She is **an** engineer.* — métier → a/an ; *engineer* commence par un son voyelle → **an**.\n2. *I bought **an** umbrella yesterday. **The** umbrella is blue.* — première mention → *an* (son voyelle) ; déjà mentionné → *the*.\n3. ***The** sun rises in the east.* — objet unique → *the*.\n4. *It takes **an** hour…* — h muet, son voyelle → *an*.\n5. ***Ø** Water is essential to life.* — indénombrable au sens général → article zéro.\n6. *twice **a** week* — fréquence → *a*.\n\n**2.**\n7. *I like music.* (ou *I love music.*) — pas *the music* : sens général.\n8. *Cats are independent.* — pluriel au sens général → article zéro ; *The cats are independent* parlerait de chats précis.\n\nOn accepte *I love music*. Toute forme avec *the* devant *music* ou *cats* perd les points du critère 2."}$exo$::jsonb),
  ('16e9c918-98a3-5e99-a22f-d8e693511c64'::uuid, 2, 'traduction', $exo${"titre":"La chambre de Maya et Ethan","consigne":"Traduis le texte en anglais (thème). Soigne les articles, les possessifs et le génitif.","enonce":"**Thème : traduis en anglais.**\n\n> Maya et son frère Ethan partagent une chambre. Le lit de Maya est près de la fenêtre. Ethan est un musicien : sa guitare est sur le lit. Maya aime les livres et elle lit une heure par jour. Les jouets des enfants sont dans une boîte. La boîte est sous le bureau de leur père.\n\n*Aide : partager = to share ; jouet = toy ; bureau (meuble) = desk.*","bareme":[{"critere":"Articles justes : a musician, an hour, a day, a box / the box, Ø books","points":7},{"critere":"Possessifs accordés au possesseur (her brother, his guitar, their father)","points":5},{"critere":"Génitifs corrects (Maya's bed, the children's toys, their father's desk)","points":5},{"critere":"Sens général, ordre des mots et orthographe","points":3}],"dureeMin":11,"corrige":"**Traduction modèle**\n\n> *Maya and her brother Ethan share a room. Maya's bed is near the window. Ethan is a musician: his guitar is on the bed. Maya likes books and she reads an hour a day. The children's toys are in a box. The box is under their father's desk.*\n\n**Points attendus**\n- *her brother* : le possesseur est Maya → *her* ; *his guitar* : le possesseur est Ethan → *his* ; *their father* : deux possesseurs → *their*.\n- *Maya's bed* : génitif, le possesseur passe devant. *The children's toys* : pluriel irrégulier → *'s* (pas *childrens'*). *Their father's desk* : génitif singulier.\n- *a room*, *a box* : première mention d'un singulier dénombrable ; *the box* ensuite : déjà mentionné. *the window*, *the bed* : identifiés par le contexte.\n- *Ethan is a musician* : métier → *a*.\n- *likes books* : pluriel au sens général → article zéro (pas *the books*).\n- *an hour a day* : *an* devant h muet ; *a day* : fréquence.\n\nAccepté : *a bedroom*, *loves books*, *by the window*."}$exo$::jsonb),
  ('16e9c918-98a3-5e99-a22f-d8e693511c64'::uuid, 3, 'traduction', $exo${"titre":"Corriger la copie de Hugo","consigne":"Hugo a rendu un petit texte plein de fautes de déterminants. Repère les erreurs, corrige-les et justifie chaque correction par la règle du cours.","enonce":"**Voici le texte de Hugo :**\n\n> *The life in the Netherlands is pleasant. My cousin Lisa lives there with his husband. She is teacher and she works in an university. Its a big school. Lisa likes the nature and she goes cycling three times the week. Last summer, I visited Lisa's parents house. This days were the best days of my life.*\n\n1. Relève et corrige les **neuf** erreurs du texte.\n2. Pour chacune, donne en une phrase la règle qui justifie la correction.\n3. Réécris la dernière phrase en parlant d'une époque lointaine et révolue, puis explique le déterminant choisi.","bareme":[{"critere":"Les neuf erreurs repérées et corrigées","points":8},{"critere":"Une règle juste et précise pour chaque correction","points":7},{"critere":"Réécriture de la dernière phrase avec those et justification (distance)","points":3},{"critere":"Texte final correct et orthographe","points":2}],"dureeMin":17,"corrige":"**1 et 2. Les neuf erreurs**\n1. *The life* → ***Life*** : indénombrable au sens général → article zéro (« la vie en général »). *The Netherlands* est juste : pays au pluriel.\n2. *his husband* → ***her husband*** : le possessif s'accorde avec le possesseur, Lisa (féminin).\n3. *She is teacher* → *She is **a** teacher* : un métier prend *a/an*.\n4. *an university* → ***a** university* : on regarde le son (« you- »), un son de consonne → *a*.\n5. *Its a big school* → ***It's** a big school* : *it's* = *it is* ; *its* sans apostrophe est le possessif.\n6. *the nature* → ***nature*** : indénombrable au sens général → article zéro.\n7. *three times the week* → *three times **a** week* : la fréquence se dit avec *a*.\n8. *Lisa's parents house* → *Lisa's **parents'** house* : possesseur au pluriel en -s → apostrophe seule.\n9. *This days* → ***These** days* (ou *Those days*) : *this* est singulier, son pluriel est *these* (proche) ou *those* (éloigné).\n\n**3.** *Those days were the best days of my life.* *Those* : pluriel de *that*, il situe le nom **loin** dans le temps, une époque révolue ; *these* désignerait ce qui est proche, maintenant. *The best* reste : le superlatif prend toujours *the*.\n\n**Texte corrigé** : *Life in the Netherlands is pleasant. My cousin Lisa lives there with her husband. She is a teacher and she works in a university. It's a big school. Lisa likes nature and she goes cycling three times a week. Last summer, I visited Lisa's parents' house. Those days were the best days of my life.*"}$exo$::jsonb),
  ('700b1a90-893e-520a-8a66-331797e06f8c'::uuid, 1, 'traduction', $exo${"titre":"Choisir le bon modal","consigne":"Complète chaque phrase avec le modal qui convient et indique entre parenthèses ce qu'il exprime (capacité, obligation, conseil, possibilité, interdiction, déduction).","enonce":"**Complète avec : can, must, mustn't, should, might, must.**\n\n1. You look tired. You ___ go to bed earlier.\n2. Take an umbrella: it ___ rain this afternoon.\n3. My little sister is only five but she ___ read.\n4. You ___ smoke in the hospital: it is forbidden.\n5. He has worked all night. He ___ be exhausted.\n6. The rules are clear: you ___ wear a helmet on a motorbike.\n\n**7.** Trouve et corrige l'erreur : *She cans to swim.*","bareme":[{"critere":"Modal juste dans chacune des six phrases","points":12},{"critere":"Valeur du modal correctement nommée","points":5},{"critere":"Correction de She cans to swim (pas de -s, pas de to)","points":3}],"dureeMin":7,"corrige":"1. *You **should** go to bed earlier.* (conseil)\n2. *It **might** rain this afternoon.* (possibilité incertaine)\n3. *She **can** read.* (capacité)\n4. *You **mustn't** smoke in the hospital.* (interdiction)\n5. *He **must** be exhausted.* (déduction quasi certaine, valeur épistémique)\n6. *You **must** wear a helmet.* (obligation) — on accepte *have to* si l'élève l'écrit, puisque la règle vient des circonstances.\n\n7. *She **can swim**.* Deux fautes : un modal ne prend **jamais de -s** à la 3e personne, et il est suivi de la **base verbale sans to**."}$exo$::jsonb),
  ('700b1a90-893e-520a-8a66-331797e06f8c'::uuid, 2, 'traduction', $exo${"titre":"Le règlement du stage de voile","consigne":"Traduis le règlement en anglais, puis réponds à la question 2 en français.","enonce":"**1. Thème : traduis en anglais.**\n\n> Règlement du club de voile\n> - Vous devez porter un gilet de sauvetage.\n> - Vous ne devez pas nager seul après 18 h.\n> - Vous n'êtes pas obligés d'apporter votre matériel : le club le prête.\n> - Vous devriez boire de l'eau régulièrement.\n> - Il se peut que la sortie soit annulée s'il y a du vent.\n\n*Aide : gilet de sauvetage = life jacket ; prêter = to lend ; annuler = to cancel ; vent = wind.*\n\n**2.** Explique la différence de sens entre la phrase 2 et la phrase 3.","bareme":[{"critere":"Modaux justes : must, mustn't, don't have to, should, might/may","points":10},{"critere":"Forme correcte : base verbale sans to, pas de -s","points":4},{"critere":"Explication juste de mustn't (interdiction) et don't have to (absence d'obligation)","points":4},{"critere":"Vocabulaire et orthographe","points":2}],"dureeMin":11,"corrige":"**1. Traduction modèle**\n\n> *Sailing club rules*\n> - *You must wear a life jacket.*\n> - *You mustn't swim alone after 6 pm.*\n> - *You don't have to bring your equipment: the club lends it.*\n> - *You should drink water regularly.*\n> - *The trip might be cancelled if it is windy.* (ou *if there is wind* ; *may* accepté)\n\n**Points attendus** : *must* (obligation) ; *mustn't* (interdiction) ; *don't have to* (absence d'obligation) ; *should* (conseil) ; *might/may* (possibilité incertaine). Toujours la base verbale sans *to* après le modal. *If it is windy* : présent après *if*.\n\n**2.** *Mustn't* exprime une **interdiction** : « il ne faut pas » nager seul après 18 h. *Don't have to* exprime une **absence d'obligation** : ce n'est pas la peine d'apporter son matériel, mais on peut le faire. Les confondre changerait complètement le sens du règlement."}$exo$::jsonb),
  ('700b1a90-893e-520a-8a66-331797e06f8c'::uuid, 3, 'traduction', $exo${"titre":"Le mystère du vélo disparu","consigne":"Lis la situation, puis réponds en anglais aux questions 1 et 2, en français à la question 3.","enonce":"**Situation.** Ce matin, le vélo de Noah n'était plus devant le lycée. Voici ce qu'on sait :\n\n> Noah left his bike unlocked. The school gate was open all night. Noah's friend Jake says he saw the bike at 8 pm. Jake is very honest. The caretaker was on holiday.\n\n1. Écris **quatre phrases** au passé qui font des hypothèses ou des déductions, avec *must have*, *might have*, *can't have* et *should have* + participe passé. (Ex. : quelqu'un a pu le prendre la nuit ; Jake n'a pas pu mentir ; Noah aurait dû l'attacher…)\n2. Traduis : « Il se pourrait qu'il le retrouve. Il pourra prendre le bus en attendant. »\n3. Explique pourquoi on ne peut pas écrire *he will can take the bus*, et pourquoi *He must be sad* ne signifie pas une obligation.","bareme":[{"critere":"Quatre phrases modal + have + participe passé correctes et adaptées à la situation","points":8},{"critere":"Valeur juste de chaque structure (déduction, hypothèse, déduction négative, reproche)","points":4},{"critere":"Traduction : might find it / will be able to take","points":4},{"critere":"Explications justes (deux modaux impossibles ; must épistémique)","points":4}],"dureeMin":16,"corrige":"**1. Exemples de réponses attendues**\n- *Someone must have taken it during the night.* — déduction quasi certaine sur le passé (le portail était ouvert).\n- *A thief might have seen that it was unlocked.* — hypothèse.\n- *Jake can't have lied: he is very honest.* — déduction négative.\n- *Noah should have locked his bike.* — reproche sur le passé.\nToute phrase juste et cohérente avec la situation est acceptée. Structure obligatoire : modal + *have* + **participe passé** (*taken, seen, lied, locked*).\n\n**2.** *He might find it. He will be able to take the bus in the meantime.* (*may find it* accepté ; *meanwhile* accepté.)\n\n**3.** Deux modaux ne se suivent jamais : *will* est déjà un modal, on ne peut donc pas lui ajouter *can*. Pour dire « il pourra », on remplace *can* par *be able to* : *he will be able to*.\n*Must* a deux valeurs : **radicale** (un ordre : *you must go*) et **épistémique** (une déduction : *he must be sad*). C'est le contexte qui tranche : ici on ne donne pas d'ordre à Noah, on déduit son état d'après la situation — « il doit être triste », c'est-à-dire « il est sûrement triste »."}$exo$::jsonb),
  ('43fa045e-6cfe-5709-a514-fc92b7648b60'::uuid, 1, 'traduction', $exo${"titre":"Le samedi de Chloé","consigne":"Mets les verbes entre parenthèses au prétérit simple, puis transforme les deux dernières phrases comme demandé.","enonce":"**1. Mets au prétérit.**\n\n> Last Saturday, Chloé (get) ___ up at 9. She (play) ___ tennis with her brother, then they (go) ___ to the cinema. They (see) ___ a comedy. After that, she (study) ___ for two hours and she (take) ___ the bus home.\n\n**2.**\n- Mets à la forme négative : *She saw a comedy.*\n- Pose la question portant sur le mot souligné : *They went **to the cinema**.* (commence par *Where*)","bareme":[{"critere":"Six verbes au prétérit justes (réguliers et irréguliers)","points":12},{"critere":"Négative et interrogative avec did + base verbale","points":8}],"dureeMin":7,"corrige":"**1.** *Last Saturday, Chloé **got** up at 9. She **played** tennis with her brother, then they **went** to the cinema. They **saw** a comedy. After that, she **studied** for two hours and she **took** the bus home.*\n- *play → played* (régulier, base + -ed) ; *study → studied* (y après consonne → -ied).\n- Irréguliers : *get → got*, *go → went*, *see → saw*, *take → took*.\n- Marqueur *last Saturday* : passé révolu → prétérit.\n\n**2.**\n- *She didn't see a comedy.* — *did* porte le passé, le verbe revient à la base (pas *didn't saw*).\n- *Where did they go?* — auxiliaire *did* + sujet + base verbale (pas *Where did they went?*)."}$exo$::jsonb),
  ('43fa045e-6cfe-5709-a514-fc92b7648b60'::uuid, 2, 'traduction', $exo${"titre":"La panne d'électricité","consigne":"Complète le récit avec le prétérit simple ou le prétérit en BE + -ING, puis justifie deux de tes choix.","enonce":"**1. Complète le récit.**\n\n> It (rain) ___ and the wind (blow) ___. My parents (watch) ___ the news and I (do) ___ my homework when suddenly the lights (go) ___ out. My father (find) ___ a candle and we (play) ___ cards until midnight.\n\n**2.** Justifie le temps choisi pour *(watch)* et pour *(go)*.\n\n**3.** Traduis : « Il y a deux ans, nous vivions à Lyon. »","bareme":[{"critere":"Décor au prétérit BE + -ING (was raining, was blowing, were watching, was doing)","points":8},{"critere":"Événements au prétérit simple (went, found, played)","points":6},{"critere":"Justification décor / événement","points":3},{"critere":"Traduction avec ago et le prétérit","points":3}],"dureeMin":11,"corrige":"**1.** *It **was raining** and the wind **was blowing**. My parents **were watching** the news and I **was doing** my homework when suddenly the lights **went** out. My father **found** a candle and we **played** cards until midnight.*\n\n**2.** *Were watching* : c'est le **décor**, une action en cours au moment du récit (équivalent de l'imparfait « regardaient »). *Went* : c'est l'**événement** qui survient et interrompt le décor (passé simple ou composé « s'est éteinte »), donc prétérit simple.\n\n**3.** *Two years ago, we lived in Lyon.* (*we were living in Lyon* accepté). Fait situé dans un passé révolu avec *ago* → prétérit ; jamais *we have lived*."}$exo$::jsonb),
  ('43fa045e-6cfe-5709-a514-fc92b7648b60'::uuid, 3, 'traduction', $exo${"titre":"Un souvenir de vacances","consigne":"Rédige en anglais un court récit (80 à 100 mots), puis réponds aux questions de grammaire en français.","enonce":"**1. Production.** Raconte en anglais un souvenir de vacances (réel ou inventé) en 80 à 100 mots. Tu dois utiliser :\n- au moins **deux** verbes réguliers et **quatre** verbes irréguliers au prétérit ;\n- au moins **deux** verbes au prétérit en BE + -ING pour planter le décor ;\n- une phrase **négative** et une phrase **interrogative** au prétérit ;\n- un **marqueur** de temps passé (*last summer*, *two years ago*…).\n\n**2.** Souligne (ou recopie) une phrase où le décor est interrompu par un événement, et explique la répartition des deux temps.\n\n**3.** Un camarade a écrit *I have visited Rome last year*. Corrige et explique.","bareme":[{"critere":"Prétérit simple juste : 2 réguliers et 4 irréguliers corrects","points":6},{"critere":"Deux prétérits BE + -ING employés pour le décor","points":4},{"critere":"Négative et interrogative avec did + base verbale, marqueur de temps","points":4},{"critere":"Explication de la phrase décor / événement","points":3},{"critere":"Correction de I have visited Rome last year et justification","points":3}],"dureeMin":18,"corrige":"**1. Exemple de récit attendu**\n\n> *Last summer, I went to Spain with my cousins. On the first day, the sun was shining and people were swimming everywhere. We walked along the beach and we ate paella. One evening, we were walking in the old town when a man stopped us. He spoke English and he told us the history of the city. We didn't understand everything, but it was fantastic. Did I want to go home? Not at all!*\n\nÀ vérifier : réguliers (*walked, stopped*), irréguliers (*went, ate, spoke, told, was*), décor (*was shining, were swimming, were walking*), négative *didn't understand* (base verbale), interrogative *Did I want…?* (base verbale), marqueur *last summer*. Longueur 80 à 100 mots.\n\n**2.** *We were walking in the old town when a man stopped us* : *were walking* est le décor, l'action en cours (imparfait) ; *stopped* est l'événement bref qui survient et l'interrompt (passé simple / composé).\n\n**3.** *I visited Rome last year.* *Last year* date le fait dans un passé terminé : dès qu'un repère de temps passé est présent, c'est le **prétérit**, jamais le present perfect."}$exo$::jsonb),
  ('64a8db89-cb61-53a7-8b47-610efa443328'::uuid, 1, 'traduction', $exo${"titre":"Since ou for ?","consigne":"Complète avec since ou for, puis mets le verbe au present perfect.","enonce":"**1. Complète avec since ou for et mets le verbe au present perfect.**\n\n1. I (know) ___ Amir ___ 2020.\n2. She (live) ___ in London ___ ten years.\n3. We (not see) ___ our grandparents ___ Christmas.\n4. They (be) ___ friends ___ a long time.\n\n**2.** Complète avec *already, yet, ever, just*.\n\n5. Have you ___ been to Canada?\n6. I haven't finished my homework ___.\n7. The bus has ___ left: you can see it at the end of the street!","bareme":[{"critere":"Present perfect bien formé (have/has + participe passé)","points":8},{"critere":"Since (point de départ) et for (durée) justes","points":6},{"critere":"Marqueurs ever, yet, just/already bien placés","points":6}],"dureeMin":8,"corrige":"**1.**\n1. *I **have known** Amir **since** 2020.* (point de départ)\n2. *She **has lived** in London **for** ten years.* (durée)\n3. *We **haven't seen** our grandparents **since** Christmas.* (point de départ)\n4. *They **have been** friends **for** a long time.* (durée)\n\n**2.**\n5. *Have you **ever** been to Canada?* — expérience de vie.\n6. *I haven't finished my homework **yet**.* — *yet* en fin de phrase négative.\n7. *The bus has **just** left* — vient juste de partir (*already* accepté).\n\nRappel : situation commencée dans le passé et qui dure encore → present perfect, jamais le présent (*I know Amir since 2020* est faux)."}$exo$::jsonb),
  ('64a8db89-cb61-53a7-8b47-610efa443328'::uuid, 2, 'traduction', $exo${"titre":"Le message de Léna","consigne":"Traduis le message en anglais, puis réponds à la question 2 en français.","enonce":"**1. Thème : traduis en anglais.**\n\n> Salut Emma ! J'apprends l'anglais depuis six ans et je n'ai jamais visité l'Angleterre. Mon frère a déjà vu Londres trois fois. J'ai perdu mon passeport : je ne peux pas partir cet été ! Ma mère le cherche depuis ce matin.\n\n*Aide : passeport = passport ; chercher = to look for.*\n\n**2.** Explique pourquoi « J'ai perdu mon passeport » se met au present perfect ici, et pourquoi « Ma mère le cherche depuis ce matin » se met au present perfect en BE + -ING.","bareme":[{"critere":"Depuis traduit par present perfect + for/since (have been learning ou have learnt ; has been looking for)","points":7},{"critere":"Present perfect avec never, already, et have lost","points":6},{"critere":"Explications : résultat présent / durée qui continue","points":5},{"critere":"Vocabulaire et orthographe","points":2}],"dureeMin":12,"corrige":"**1. Traduction modèle**\n\n> *Hi Emma! I have been learning English for six years and I have never visited England. My brother has already seen London three times. I have lost my passport: I can't leave this summer! My mother has been looking for it since this morning.*\n\nAcceptés : *I have learnt/learned English for six years* ; *I've never been to England*.\n\n**Points attendus** : « depuis six ans » au présent en français → present perfect + **for** (durée) ; « depuis ce matin » → **since** (point de départ). *Never*, *already* : marqueurs du present perfect. Jamais *I learn English since…*.\n\n**2.** *I have lost my passport* : le present perfect fait le **bilan au présent** ; ce qui compte est le **résultat actuel** (je ne l'ai plus, donc je ne peux pas partir), pas le moment de la perte. *Has been looking for it* : la forme BE + -ING insiste sur la **durée** d'une action commencée ce matin et qui **continue encore**."}$exo$::jsonb),
  ('64a8db89-cb61-53a7-8b47-610efa443328'::uuid, 3, 'traduction', $exo${"titre":"Prétérit ou present perfect : l'entretien de Sofia","consigne":"Complète le dialogue avec le temps qui convient (prétérit, present perfect simple ou BE + -ING), puis justifie tes choix.","enonce":"**Sofia passe un entretien pour un job d'été.**\n\n> **Manager:** How long (you / work) ___ as a babysitter?\n> **Sofia:** I (work) ___ as a babysitter for two years. I (start) ___ in 2024.\n> **Manager:** (you / ever / work) ___ in a shop?\n> **Sofia:** Yes, last summer I (work) ___ in a bakery for a month.\n> **Manager:** Why are your hands so red?\n> **Sofia:** Oh, I (paint) ___ my bedroom all morning!\n> **Manager:** (you / finish) ___ it yet?\n> **Sofia:** No, I (not finish) ___ it yet.\n\n1. Complète les huit blancs.\n2. Justifie en une phrase chacun des temps choisis pour les blancs 2, 3, 5 et 6.\n3. Traduis : « Elle a écrit trois lettres ce matin (la matinée est finie). » puis « Elle a écrit trois lettres (elles sont prêtes). » et explique la différence.","bareme":[{"critere":"Huit formes verbales justes et bien construites","points":8},{"critere":"Justifications des blancs 2, 3, 5 et 6","points":6},{"critere":"Deux traductions justes (wrote / has written)","points":3},{"critere":"Explication récit daté / bilan au présent","points":3}],"dureeMin":18,"corrige":"**1.**\n1. *How long **have you been working** (ou **have you worked**) as a babysitter?*\n2. *I **have been working** (ou **have worked**) as a babysitter for two years.*\n3. *I **started** in 2024.*\n4. ***Have you ever worked** in a shop?*\n5. *Last summer I **worked** in a bakery for a month.*\n6. *I **have been painting** my bedroom all morning!*\n7. ***Have you finished** it yet?*\n8. *No, I **haven't finished** it yet.*\n\n**2.**\n- Blanc 2 : situation commencée dans le passé qui **dure encore**, avec *for* → present perfect (BE + -ING souligne la durée).\n- Blanc 3 : fait **daté** (*in 2024*) → prétérit ; un fait daté ne va jamais au present perfect.\n- Blanc 5 : *last summer* situe le fait dans un passé terminé → prétérit, même avec *for a month* (l'action est finie).\n- Blanc 6 : BE + -ING insiste sur la **durée** et ses **traces** visibles (les mains rouges).\n\n**3.** *She wrote three letters this morning.* (récit d'un moment passé et terminé → prétérit) / *She has written three letters.* (bilan : le **résultat** compte maintenant, les lettres sont écrites → present perfect). Le prétérit raconte un fait situé ; le present perfect fait le bilan au présent, sans repère daté."}$exo$::jsonb),
  ('4f60614a-1aca-5bbc-8509-05a30eda89a3'::uuid, 1, 'traduction', $exo${"titre":"Qu'est-ce qui s'est passé avant ?","consigne":"Mets un des deux verbes au past perfect et l'autre au prétérit, selon l'ordre réel des faits.","enonce":"**Conjugue les verbes : l'un au past perfect, l'autre au prétérit.**\n\n1. When we (arrive) ___ at the station, the train (already / leave) ___.\n2. She (be) ___ tired because she (not sleep) ___ well.\n3. After he (finish) ___ his homework, he (go) ___ out.\n4. I (recognise) ___ the town: I (visit) ___ it as a child.\n\n**5.** Dans *He'd gone* et *He'd go*, que remplace *'d* ? Explique comment tu le sais.","bareme":[{"critere":"Past perfect (had + participe passé) pour le fait le plus ancien","points":10},{"critere":"Prétérit juste pour le fait le plus récent","points":6},{"critere":"Distinction had / would après 'd expliquée","points":4}],"dureeMin":8,"corrige":"1. *When we **arrived** at the station, the train **had already left**.* — le départ du train est antérieur.\n2. *She **was** tired because she **hadn't slept** well.* — le mauvais sommeil est antérieur.\n3. *After he **had finished** his homework, he **went** out.* — *after* appelle le past perfect pour la première action.\n4. *I **recognised** the town: I **had visited** it as a child.* — la visite est antérieure.\n\n5. *He'd gone* : *'d* = **had**, car il est suivi d'un **participe passé** (*gone*). *He'd go* : *'d* = **would**, car il est suivi d'une **base verbale** (*go*)."}$exo$::jsonb),
  ('4f60614a-1aca-5bbc-8509-05a30eda89a3'::uuid, 2, 'traduction', $exo${"titre":"Ce que Tom a raconté","consigne":"Rapporte au discours indirect ce que Tom a dit, puis traduis la phrase de la question 2.","enonce":"**1. Tom a dit hier :**\n\n> « I have lost my phone. »\n> « I left it on the bus. »\n> « Nobody has called me since this morning. »\n\nRapporte ses paroles en commençant chaque phrase par *Tom said (that)…*\n\n**2. Traduis :** « Quand le médecin est arrivé, Paul était épuisé : il conduisait depuis dix heures. »\n\n**3.** Justifie le temps employé pour « il conduisait depuis dix heures ».","bareme":[{"critere":"Discours indirect : present perfect et prétérit transformés en past perfect","points":8},{"critere":"Pronoms et repères adaptés (he, his, it, that morning)","points":3},{"critere":"Traduction avec had been driving for ten hours","points":6},{"critere":"Justification : durée de l'action antérieure","points":3}],"dureeMin":11,"corrige":"**1.**\n- *Tom said (that) he **had lost** his phone.* (present perfect → past perfect)\n- *Tom said (that) he **had left** it on the bus.* (prétérit → past perfect)\n- *Tom said (that) nobody **had called** him since **that** morning.* (present perfect → past perfect ; *this morning* devient *that morning*, accepté aussi *since the morning*)\nPronoms : *I → he*, *my → his*, *me → him*.\n\n**2.** *When the doctor arrived, Paul was exhausted: he had been driving for ten hours.*\n\n**3.** *Had been driving* : past perfect en BE + -ING. Il marque une action **antérieure** à l'arrivée du médecin (déjà au passé) et insiste sur sa **durée** (*for ten hours*), qui explique l'épuisement."}$exo$::jsonb),
  ('4f60614a-1aca-5bbc-8509-05a30eda89a3'::uuid, 3, 'traduction', $exo${"titre":"Le soir du concert","consigne":"Traduis le récit en anglais, puis réponds aux questions en français.","enonce":"**1. Thème : traduis en anglais.**\n\n> Quand Inès est arrivée au stade, le concert avait déjà commencé. Elle avait attendu le bus pendant une heure et elle avait oublié son billet à la maison. Heureusement, son amie Zoé avait gardé une copie sur son téléphone. Si Inès avait su, elle serait partie plus tôt.\n\n*Aide : billet = ticket ; garder = to keep (kept, kept).*\n\n**2.** Classe dans l'ordre chronologique réel les cinq faits du récit (arrivée, début du concert, attente du bus, oubli du billet, copie gardée par Zoé — l'ordre des trois derniers entre eux importe peu, dis seulement qu'ils sont antérieurs à l'arrivée).\n\n**3.** Quelle structure emploie la dernière phrase ? Qu'exprime-t-elle ?","bareme":[{"critere":"Past perfect juste pour les faits antérieurs (had started, had forgotten, had kept)","points":6},{"critere":"Had been waiting ou had waited for an hour ; prétérit arrived","points":4},{"critere":"Irréel du passé : If Inès had known, she would have left earlier","points":4},{"critere":"Ordre chronologique expliqué","points":3},{"critere":"Structure et valeur de la dernière phrase","points":3}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n\n> *When Inès arrived at the stadium, the concert had already started. She had been waiting for the bus for an hour and she had forgotten her ticket at home. Luckily, her friend Zoé had kept a copy on her phone. If Inès had known, she would have left earlier.*\n\nAcceptés : *had waited for the bus for an hour* ; *Fortunately* ; *had begun*.\n\n**2.** L'attente du bus, l'oubli du billet et la copie gardée par Zoé sont **antérieurs** à l'arrivée ; le concert a commencé avant l'arrivée ; l'arrivée d'Inès est le dernier fait, au **prétérit**, qui sert de repère. Tous les faits antérieurs sont au **past perfect** : il correspond au plus-que-parfait français (« avait commencé », « avait oublié »).\n\n**3.** *If* + **past perfect**, *would have* + **participe passé** : c'est l'**irréel du passé**. Inès n'a pas su, elle n'est pas partie plus tôt : on imagine ce qui aurait pu se passer et qui ne s'est pas produit."}$exo$::jsonb),
  ('7a189379-c8b5-50df-abda-78236985070d'::uuid, 1, 'traduction', $exo${"titre":"Will ou be going to ?","consigne":"Complète chaque phrase avec la forme de futur qui convient, puis corrige l'erreur de la question 2.","enonce":"**1. Complète avec will, be going to, le présent en -ING ou le présent simple.**\n\n1. The phone is ringing! — Don't move, I ___ (answer) it.\n2. Look at those black clouds: it ___ (rain).\n3. We ___ (fly) to Dublin on Monday: the tickets are booked.\n4. Hurry up! The train ___ (leave) at 6:15.\n\n**2. Corrige :** *I'll call you when I will get home.*","bareme":[{"critere":"Forme de futur juste dans les quatre phrases","points":14},{"critere":"Correction : présent après when (when I get home)","points":6}],"dureeMin":6,"corrige":"**1.**\n1. *I**'ll answer** it.* — décision prise au moment où l'on parle → *will*.\n2. *It**'s going to rain**.* — prédiction fondée sur un indice visible → *be going to*.\n3. *We**'re flying** to Dublin on Monday.* — programme fixé, avec une date → présent en -ING.\n4. *The train **leaves** at 6:15.* — horaire officiel → présent simple.\n\n**2.** *I'll call you when I **get** home.* Après *when* (et *as soon as, until, before, after, if*), on emploie le **présent**, jamais *will*."}$exo$::jsonb),
  ('7a189379-c8b5-50df-abda-78236985070d'::uuid, 2, 'traduction', $exo${"titre":"Et si… ? Trois hypothèses","consigne":"Termine chaque phrase en respectant le type d'hypothèse, puis traduis les deux phrases de la question 2.","enonce":"**1. Complète en conjuguant le verbe entre parenthèses.**\n\n1. If it (rain) ___ tomorrow, we will stay at home.\n2. If I (have) ___ more money, I would travel around the world.\n3. If you had told me, I (help) ___ you.\n4. If I (be) ___ you, I would talk to her.\n\n**2. Traduis en anglais.**\n\n5. Si tu te dépêches, tu auras le bus.\n6. Si j'avais su, je serais venu.\n\n**3.** Pour les phrases 1, 2 et 3, indique le type (1, 2 ou 3) et ce qu'il exprime.","bareme":[{"critere":"Formes verbales justes dans les quatre phrases (rains, had, would have helped, were)","points":8},{"critere":"Deux traductions justes (type 1 et type 3)","points":6},{"critere":"Types identifiés avec leur valeur (possible, irréel du présent, irréel du passé)","points":6}],"dureeMin":11,"corrige":"**1.**\n1. *If it **rains** tomorrow…* — présent après *if* (jamais *will rain*).\n2. *If I **had** more money…* — prétérit dans la subordonnée.\n3. *…I **would have helped** you.* — *would have* + participe passé.\n4. *If I **were** you…* — *were* est la forme soignée à toutes les personnes (*was* toléré à l'oral, mais on attend *were*).\n\n**2.**\n5. *If you hurry, you will catch the bus.* (*you'll get the bus* accepté)\n6. *If I had known, I would have come.*\n\n**3.**\n- Phrase 1 : **type 1**, *if* + présent / *will* : le **possible**.\n- Phrase 2 : **type 2**, *if* + prétérit / *would* : l'**irréel du présent** (je n'ai pas assez d'argent).\n- Phrase 3 : **type 3**, *if* + past perfect / *would have* : l'**irréel du passé** (tu ne me l'as pas dit).\n\nJamais *would* dans la subordonnée en *if*."}$exo$::jsonb),
  ('7a189379-c8b5-50df-abda-78236985070d'::uuid, 3, 'traduction', $exo${"titre":"Les projets de Karim","consigne":"Rédige en anglais le texte demandé (70 à 90 mots), puis justifie tes choix en français.","enonce":"**Situation.** Karim, 16 ans, écrit à son correspondant anglais pour lui parler de ses projets d'été. Voici ses notes :\n\n> - Il a déjà décidé de chercher un petit boulot (intention ancienne).\n> - Son avion pour Londres part le 12 juillet à 10 h (horaire officiel), et il a réservé le vol avec son oncle pour ce jour-là (programme fixé).\n> - Il promet d'envoyer des photos.\n> - Il prévoit que la météo sera mauvaise, comme d'habitude.\n> - S'il gagnait au loto, il achèterait un scooter (il n'a aucune chance).\n> - Il lui téléphonera dès qu'il arrivera.\n\n1. Rédige la lettre de Karim en anglais (70 à 90 mots) en employant **toutes** les formes de l'avenir du cours et **une** hypothèse de type 2.\n2. Pour quatre phrases de ta lettre, explique en français pourquoi tu as choisi cette forme.","bareme":[{"critere":"Be going to pour l'intention, présent -ING pour le programme, présent simple pour l'horaire","points":6},{"critere":"Will pour la promesse et la prédiction","points":3},{"critere":"Hypothèse de type 2 correcte (If I won…, I would buy…)","points":3},{"critere":"Présent après as soon as (as soon as I arrive)","points":3},{"critere":"Justification de quatre choix, lettre cohérente et correcte","points":5}],"dureeMin":18,"corrige":"**1. Exemple de lettre attendue**\n\n> *Hi Jack,*\n> *This summer I'm going to look for a job. I'm flying to London with my uncle on 12th July: the plane leaves at 10 am. I'll send you lots of photos, I promise! I think the weather will be bad, as usual. If I won the lottery, I would buy a scooter, but I have no chance! I'll call you as soon as I arrive.*\n> *See you soon,*\n> *Karim*\n\n**Formes attendues** : *I'm going to look for* (intention déjà formée) ; *I'm flying… on 12th July* (programme fixé, daté) ; *the plane leaves at 10 am* (horaire officiel) ; *I'll send* (promesse) ; *the weather will be bad* (prédiction) ; *If I won…, I would buy* (type 2, irréel du présent : *if* + prétérit, *would* dans la principale) ; *as soon as I arrive* (présent après *as soon as*, jamais *will arrive*).\n\n**2.** L'élève justifie quatre choix en reprenant ces valeurs. Exemple : « *I'm going to* : Karim a déjà décidé, c'est une intention formée avant de parler. » / « *as soon as I arrive* : dans une subordonnée de temps, l'anglais met le présent pour parler de l'avenir. »"}$exo$::jsonb),
  ('12ec0d15-1040-5c5e-9f72-2924d445b300'::uuid, 1, 'traduction', $exo${"titre":"Poser les bonnes questions","consigne":"Pose la question qui porte sur le mot en gras, puis ajoute le question tag qui convient.","enonce":"**1. Pose la question portant sur le passage en gras.**\n\n1. She lives **in Manchester**.\n2. They arrived **yesterday**.\n3. He goes to the gym **twice a week**.\n4. The film lasts **two hours**.\n\n**2. Ajoute le question tag.**\n\n5. You're French, ___?\n6. She likes pizza, ___?\n7. He can't swim, ___?","bareme":[{"critere":"Questions justes : mot interrogatif + auxiliaire + sujet + base verbale","points":12},{"critere":"Question tags justes (polarité inversée, bon auxiliaire)","points":8}],"dureeMin":7,"corrige":"**1.**\n1. *Where does she live?* (pas *Where does she lives?*)\n2. *When did they arrive?*\n3. *How often does he go to the gym?*\n4. *How long does the film last?*\nL'auxiliaire *do/does/did* porte le temps et la personne, le verbe reste à la base.\n\n**2.**\n5. *You're French, **aren't you**?*\n6. *She likes pizza, **doesn't she**?* — pas d'auxiliaire dans la phrase → *do*.\n7. *He can't swim, **can he**?* — phrase négative → tag positif."}$exo$::jsonb),
  ('12ec0d15-1040-5c5e-9f72-2924d445b300'::uuid, 2, 'traduction', $exo${"titre":"L'interview d'une sportive","consigne":"Retrouve les questions du journaliste à partir des réponses de la championne, puis réponds à la question 2.","enonce":"**1. Voici les réponses de Maria, championne de natation. Écris les questions du journaliste.**\n\n1. — ___? — I started swimming **when I was six**.\n2. — ___? — I train **four hours a day**.\n3. — ___? — **My coach** taught me everything.\n4. — ___? — I admire **Laure Manaudou**.\n5. — ___? — She is **kind and very determined**.\n6. — ___? — The pool is **about two kilometres** from my house.\n\n**2.** Explique en français pourquoi les questions 3 et 4 ne se construisent pas de la même façon.","bareme":[{"critere":"Mots interrogatifs adaptés (when, how long, who, what... like, how far)","points":6},{"critere":"Ordre auxiliaire + sujet + base verbale dans les questions sur le complément","points":6},{"critere":"Question sur le sujet sans auxiliaire (Who taught you…?) et What is she like?","points":4},{"critere":"Explication question sur le sujet / sur le complément","points":4}],"dureeMin":12,"corrige":"**1.**\n1. *When did you start swimming?*\n2. *How long do you train (every day)?* (*How many hours a day do you train?* accepté)\n3. *Who taught you everything?* — pas de *did*.\n4. *Who do you admire?* (*Whom* accepté)\n5. *What is she like?* — on demande une description, son caractère (pas *How is she?*, qui demande comment elle va).\n6. *How far is the pool from your house?*\n\n**2.** Dans la question 3, *who* est le **sujet** du verbe (c'est l'entraîneur qui a appris) : on n'ajoute pas d'auxiliaire et le verbe garde le prétérit (*taught*). Dans la question 4, *who* est **complément** (Maria admire quelqu'un, le sujet est *you*) : il faut l'auxiliaire *do* devant le sujet, suivi de la base verbale."}$exo$::jsonb),
  ('12ec0d15-1040-5c5e-9f72-2924d445b300'::uuid, 3, 'traduction', $exo${"titre":"Enquête au CDI","consigne":"Corrige les questions fautives, puis rédige toi-même un questionnaire en anglais selon les consignes.","enonce":"**1. Un élève a préparé ces questions pour un sondage. Corrige chacune et explique la faute.**\n\n1. *Where you do study?*\n2. *Who did write this book?*\n3. *How often you read?*\n4. *Which book do you prefers?*\n5. *How is your best friend? — He's funny and generous.*\n\n**2. Rédige un questionnaire de six questions** sur les habitudes de lecture, en anglais. Il doit contenir :\n- une question avec *how much* ou *how many* ;\n- une question avec *which* (choix limité proposé) ;\n- une question avec *how long* ;\n- une question oui/non avec un modal ;\n- une question sur le **sujet** avec *who* ;\n- une affirmation suivie d'un **question tag**.","bareme":[{"critere":"Cinq questions fautives corrigées","points":5},{"critere":"Explication juste de chaque faute","points":5},{"critere":"Six questions produites conformes aux contraintes","points":7},{"critere":"Correction de la langue (ordre, base verbale, tag)","points":3}],"dureeMin":17,"corrige":"**1.**\n1. *Where **do you** study?* — l'auxiliaire se place **devant** le sujet.\n2. *Who **wrote** this book?* — *who* est sujet : pas d'auxiliaire *did*.\n3. *How often **do you** read?* — pas d'auxiliaire dans la phrase affirmative → on fabrique *do* devant le sujet.\n4. *Which book do you **prefer**?* — le verbe lexical reste à la base ; *do* porte la personne.\n5. *What is your best friend **like**?* — la réponse décrit un caractère : *What… like?* ; *How is he?* demande comment il va.\n\n**2. Exemple de questionnaire**\n1. *How many books do you read a month?*\n2. *Which do you prefer: novels, comics or magazines?*\n3. *How long do you read every day?*\n4. *Can you read in English?* (ou *Should the library open on Saturdays?*)\n5. *Who recommends books to you?* — question sur le sujet, sans *do*.\n6. *You like reading, don't you?* — tag de polarité inversée avec *do*.\n\nToute question juste qui respecte les contraintes est acceptée."}$exo$::jsonb),
  ('281d7cb6-be1f-5cfc-9607-4654a8469f0f'::uuid, 1, 'traduction', $exo${"titre":"Plus grand, plus cher, le meilleur","consigne":"Mets l'adjectif au comparatif ou au superlatif selon la consigne entre crochets.","enonce":"**Complète.**\n\n1. My brother is ___ than me. (tall) [comparatif]\n2. This phone is ___ than that one. (expensive) [comparatif]\n3. Today is ___ than yesterday. (hot) [comparatif]\n4. It's ___ film of the year. (good) [superlatif]\n5. This is ___ exercise in the book. (difficult) [superlatif]\n6. My marks are ___ than last term. (bad) [comparatif]\n7. Emma is ___ her sister. (tall) [égalité]","bareme":[{"critere":"Adjectifs courts et longs bien traités (-er / more, -est / the most)","points":8},{"critere":"Irréguliers justes (the best, worse) et doublement de consonne (hotter)","points":8},{"critere":"Égalité avec as … as","points":4}],"dureeMin":6,"corrige":"1. *taller than* — adjectif court → -er + *than*.\n2. *more expensive than* — adjectif long → *more … than*.\n3. *hotter than* — doublement de la consonne finale.\n4. *the best film* — *good* est irrégulier ; le superlatif prend toujours *the*.\n5. *the most difficult exercise* — adjectif long.\n6. *worse than* — *bad* est irrégulier.\n7. *as tall as* — égalité."}$exo$::jsonb),
  ('281d7cb6-be1f-5cfc-9607-4654a8469f0f'::uuid, 2, 'traduction', $exo${"titre":"Comparer deux villes","consigne":"Compare les deux villes en anglais à partir du tableau, en six phrases.","enonce":"**Données.**\n\n| | Brighton | York |\n| Habitants | environ 280 000 | environ 200 000 |\n| Prix moyen d'un repas | 18 £ | 15 £ |\n| Jours de pluie par an | 110 | 110 |\n| Distance de Londres | 85 km | 330 km |\n| Note des touristes | 4,5 / 5 | 4,7 / 5 |\n\nÉcris **six** phrases en anglais :\n1. une comparaison de supériorité avec un adjectif **court** ;\n2. une comparaison avec un adjectif **long** ;\n3. une comparaison d'**égalité** ;\n4. une comparaison avec *far* ;\n5. une phrase avec un **superlatif** (tu peux ajouter une ville de ton choix) ;\n6. une comparaison d'**infériorité** (*not as … as* ou *less … than*).","bareme":[{"critere":"Supériorité courte et longue justes et conformes au tableau","points":6},{"critere":"Égalité et infériorité justes","points":5},{"critere":"Farther/further et superlatif avec the","points":5},{"critere":"Phrases correctes et cohérentes avec les données","points":4}],"dureeMin":11,"corrige":"**Exemples de phrases attendues**\n1. *Brighton is bigger than York.* (*bigger* : doublement du g)\n2. *A meal is more expensive in Brighton than in York.*\n3. *Brighton is as rainy as York.* (110 jours dans les deux villes)\n4. *York is farther (further) from London than Brighton.*\n5. *York is the most popular of the two… / London is the biggest city in England.* On accepte un superlatif juste avec *the*.\n6. *York is not as big as Brighton.* ou *A meal in York is less expensive than in Brighton.*\n\nFautes pénalisées : *more bigger*, *the most big*, *very bigger*, superlatif sans *the*, comparaison contraire aux données."}$exo$::jsonb),
  ('281d7cb6-be1f-5cfc-9607-4654a8469f0f'::uuid, 3, 'traduction', $exo${"titre":"La publicité du nouveau téléphone","consigne":"Traduis la publicité en anglais, repère les fautes de la version d'un camarade, puis explique la structure des proportions.","enonce":"**1. Thème : traduis en anglais.**\n\n> Le nouveau Zéphyr est plus léger et beaucoup plus rapide que l'ancien modèle. Son écran est le plus lumineux du marché. Les téléphones sont de plus en plus chers, mais le Zéphyr coûte moins cher que ses rivaux. Plus vous l'utiliserez, plus vous l'aimerez !\n\n*Aide : léger = light ; lumineux = bright ; rival = rival.*\n\n**2.** Un camarade a écrit : *The new Zéphyr is more lighter and very faster than the old model. Its screen is brightest on the market.* Relève les trois fautes et corrige-les en citant la règle.\n\n**3.** Explique la construction de la dernière phrase de la publicité.","bareme":[{"critere":"Comparatifs justes : lighter, much faster, less expensive (cheaper accepté)","points":5},{"critere":"Superlatif the brightest et progression more and more expensive","points":4},{"critere":"Proportion the more … the more","points":3},{"critere":"Trois fautes du camarade corrigées et justifiées","points":6},{"critere":"Explication de la structure de proportion","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n> *The new Zéphyr is lighter and much faster than the old model. Its screen is the brightest on the market. Phones are more and more expensive, but the Zéphyr is less expensive than its rivals. The more you use it, the more you will love it!*\n\nAcceptés : *cheaper than its rivals* ; *costs less than its rivals* ; *the more you'll like it*. *Phones* : pluriel au sens général, sans article.\n\n**2.**\n- *more lighter* → *lighter* : jamais de **double marque** ; *light* est court → -er.\n- *very faster* → *much faster* : *very* ne se combine jamais avec un comparatif.\n- *is brightest* → *is **the** brightest* : le superlatif prend toujours *the*.\n\n**3.** *The more…, the more…* exprime la **proportion** : deux quantités augmentent ensemble. Chaque moitié commence par *the* + comparatif ; le verbe suit le sujet sans inversion (*the more you use it*)."}$exo$::jsonb),
  ('bc823270-45b7-5ce0-be09-68bb494b4aae'::uuid, 1, 'traduction', $exo${"titre":"Who, which ou whose ?","consigne":"Complète avec le pronom relatif qui convient, puis corrige l'erreur de la question 2.","enonce":"**1. Complète avec who, which, whose ou where.**\n\n1. The girl ___ won the race is my cousin.\n2. This is the book ___ I told you about.\n3. I have a friend ___ father is a pilot.\n4. That's the café ___ we met.\n5. My uncle, ___ lives in York, is a doctor.\n\n**2. Corrige :** *He said me that he was tired.*","bareme":[{"critere":"Relatifs justes dans les cinq phrases","points":14},{"critere":"Correction said / told me et règle","points":6}],"dureeMin":7,"corrige":"**1.**\n1. *who* — une personne (*that* accepté : relative déterminative).\n2. *which* — une chose (*that* ou pronom effacé acceptés : il est complément).\n3. *whose* — la possession, « dont le père ».\n4. *where* — un lieu.\n5. *who* — une personne, relative **appositive** entre virgules : *that* impossible.\n\n**2.** *He **told** me that he was tired.* ou *He **said** that he was tired.* *Tell* exige un complément de personne, *say* l'interdit : *He said me* est une faute lourde."}$exo$::jsonb),
  ('bc823270-45b7-5ce0-be09-68bb494b4aae'::uuid, 2, 'traduction', $exo${"titre":"Relier les idées","consigne":"Relie chaque paire de phrases en une seule, avec le mot demandé.","enonce":"**Relie les phrases avec le mot indiqué.**\n\n1. I met a woman. She speaks six languages. (*who*)\n2. Paris is a beautiful city. It attracts millions of tourists. (*which*, relative appositive)\n3. This is the student. Her project won a prize. (*whose*)\n4. He was tired. He went on working. (*although*)\n5. She spoke slowly. Everyone could understand. (*so that*)\n6. I'll wait here. You come back. (*until*)\n\n**7.** Dans quelle phrase la virgule est-elle obligatoire, et pourquoi ne peut-on pas y employer *that* ?","bareme":[{"critere":"Trois relatives justes (who, which avec virgules, whose)","points":8},{"critere":"Trois circonstancielles justes (although, so that, until + présent)","points":8},{"critere":"Explication relative appositive / that impossible","points":4}],"dureeMin":12,"corrige":"1. *I met a woman who speaks six languages.*\n2. *Paris, which attracts millions of tourists, is a beautiful city.*\n3. *This is the student whose project won a prize.*\n4. *Although he was tired, he went on working.* (ou *He went on working although he was tired.*)\n5. *She spoke slowly so that everyone could understand.* — but, avec un modal.\n6. *I'll wait here until you come back.* — présent après *until*, jamais *will come*.\n\n**7.** Phrase 2 : la relative est **appositive**, elle **ajoute** une information sur un nom déjà identifié (Paris). Elle est encadrée de virgules et *that* y est **impossible** ; il ne s'emploie que dans une relative déterminative, qui identifie le nom."}$exo$::jsonb),
  ('bc823270-45b7-5ce0-be09-68bb494b4aae'::uuid, 3, 'traduction', $exo${"titre":"La biographie d'une inventrice","consigne":"Traduis le texte en anglais, puis réponds aux questions d'analyse en français.","enonce":"**1. Thème : traduis en anglais.**\n\n> Hedy Lamarr, qui était une actrice célèbre, a aussi inventé un système de communication. Le système qu'elle a imaginé est utilisé aujourd'hui dans le wifi. Bien qu'elle fût connue pour ses films, peu de gens savaient qu'elle était inventrice. Elle a dit à un journaliste qu'elle trouvait les idées faciles.\n\n*Aide : inventer = to invent ; imaginer (concevoir) = to design ; peu de gens = few people.*\n\n**2.** Dans ta traduction, relève :\n- une relative appositive et une relative déterminative, en justifiant leur différence ;\n- une relative où le pronom peut s'effacer, et explique pourquoi ;\n- une complétive et une circonstancielle de concession.\n\n**3.** Pourquoi as-tu employé *told* et non *said* dans la dernière phrase ?","bareme":[{"critere":"Traduction juste des deux relatives (who… ; the system (that) she designed)","points":5},{"critere":"Concession avec although / even though et complétive avec that (ou that effacé)","points":4},{"critere":"Told a journalist (that)… correct","points":2},{"critere":"Analyse juste : appositive / déterminative, effacement du relatif complément","points":6},{"critere":"Explication say / tell","points":3}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n\n> *Hedy Lamarr, who was a famous actress, also invented a communication system. The system (that) she designed is used in wifi today. Although she was known for her films, few people knew (that) she was an inventor. She told a journalist (that) she found ideas easy.*\n\n**2.**\n- ***who was a famous actress*** : relative **appositive**, entre virgules, elle **ajoute** une information sur une personne déjà identifiée ; *that* impossible. ***(that) she designed*** : relative **déterminative**, sans virgule, elle **identifie** de quel système on parle.\n- Dans *the system (that) she designed*, le pronom est **complément** (le sujet est *she*) : il peut s'effacer. Un pronom **sujet** (*who was a famous actress*) ne s'efface jamais.\n- Complétive : *(that) she was an inventor* (ou *(that) she found ideas easy*), introduite par *that*, souvent omis. Concession : *Although she was known for her films* (*even though* accepté).\n\n**3.** « Dire à quelqu'un » : il y a un complément de personne (*a journalist*). *Tell* l'exige, *say* l'interdit (*she said to a journalist* serait possible, mais *she said a journalist* est faux)."}$exo$::jsonb),
  ('7cc235f0-30f9-5565-9466-48f86bad0f44'::uuid, 1, 'traduction', $exo${"titre":"For, since, ago, during, while","consigne":"Complète chaque phrase avec for, since, ago, during ou while.","enonce":"**Complète.**\n\n1. I have lived in Nantes ___ 2021.\n2. She has been a nurse ___ fifteen years.\n3. We moved here three years ___.\n4. My phone rang ___ the film.\n5. He fell asleep ___ he was reading.\n6. Nobody spoke ___ the meeting.\n7. They have known each other ___ they were children.","bareme":[{"critere":"For / since justes (durée / point de départ)","points":9},{"critere":"Ago placé après la durée avec le prétérit","points":3},{"critere":"During devant un nom, while devant une proposition","points":8}],"dureeMin":6,"corrige":"1. *since 2021* — point de départ.\n2. *for fifteen years* — durée.\n3. *three years ago* — point du passé compté à rebours, avec le prétérit (*moved*).\n4. *during the film* — *during* + nom.\n5. *while he was reading* — *while* + sujet et verbe.\n6. *during the meeting* — nom.\n7. *since they were children* — point de départ exprimé par une proposition."}$exo$::jsonb),
  ('7cc235f0-30f9-5565-9466-48f86bad0f44'::uuid, 2, 'traduction', $exo${"titre":"La carte postale de Jade","consigne":"Traduis la carte postale en anglais en choisissant bien les mots de la temporalité et les temps.","enonce":"**Thème : traduis en anglais.**\n\n> Coucou Nathan ! Je suis en Écosse depuis dix jours. Je suis arrivée il y a dix jours et j'ai déjà visité trois châteaux. Pendant la visite d'hier, il a plu. Pendant que nous marchions, un guide nous a raconté des légendes. Je dois rendre ma voiture de location d'ici vendredi. Je rentre dans deux semaines !\n\n*Aide : château = castle ; voiture de location = rental car ; rendre = to return ; raconter = to tell.*","bareme":[{"critere":"Depuis dix jours : present perfect + for ; il y a dix jours : prétérit + ago","points":6},{"critere":"During + nom et while + proposition","points":5},{"critere":"By Friday et in two weeks","points":5},{"critere":"Autres temps et vocabulaire corrects","points":4}],"dureeMin":11,"corrige":"**Traduction modèle**\n\n> *Hi Nathan! I have been in Scotland for ten days. I arrived ten days ago and I have already visited three castles. During yesterday's visit, it rained. While we were walking, a guide told us legends. I have to return my rental car by Friday. I'm coming back in two weeks!*\n\n**Points attendus**\n- « depuis dix jours » (situation qui dure) → *have been … for ten days* ; jamais *I am in Scotland since*.\n- « il y a dix jours » → *ten days ago*, avec le **prétérit** *arrived* (jamais *I have arrived ten days ago*).\n- « pendant la visite » → *during* + nom ; « pendant que nous marchions » → *while* + proposition.\n- « d'ici vendredi » → *by Friday* (au plus tard), pas *until*.\n- « dans deux semaines » → *in two weeks*.\n\nAcceptés : *during the visit yesterday* ; *I must return* ; *I'll be back in two weeks*."}$exo$::jsonb),
  ('7cc235f0-30f9-5565-9466-48f86bad0f44'::uuid, 3, 'traduction', $exo${"titre":"La chronologie d'une association","consigne":"Lis la fiche, rédige un court paragraphe en anglais, puis corrige et explique les fautes d'un camarade.","enonce":"**Fiche : l'association « Green Street » (nous sommes en 2026)**\n\n> - Créée en 2018 par Aya et Léo.\n> - Nettoie les parcs de la ville chaque dimanche depuis sa création.\n> - A planté 500 arbres pendant l'hiver 2023.\n> - Prépare un grand festival : il doit être prêt au plus tard le 1er juin, et il durera jusqu'au 3 juin.\n\n1. Rédige un paragraphe de 60 à 80 mots en anglais sur l'association. Tu dois employer : *for*, *since*, *ago*, *during*, *while*, *by*, *until*.\n\n2. Corrige ces phrases d'un camarade et explique chaque faute :\n- *The association exists since eight years.*\n- *It was created ago eight years.*\n- *They planted trees while the winter.*","bareme":[{"critere":"For et since avec le present perfect","points":4},{"critere":"Ago après la durée avec le prétérit","points":3},{"critere":"During + nom et while + proposition justes","points":3},{"critere":"By et until employés dans leur sens (au plus tard / jusqu'à)","points":4},{"critere":"Trois phrases corrigées et fautes expliquées","points":6}],"dureeMin":17,"corrige":"**1. Exemple de paragraphe attendu**\n\n> *Green Street was created eight years ago by Aya and Léo. It has existed for eight years, and its members have cleaned the city parks every Sunday since 2018. During the winter of 2023, they planted 500 trees. While they were planting, many neighbours came to help. Now they are preparing a big festival: it must be ready by 1st June, and it will last until 3rd June.*\n\nÀ vérifier : *eight years ago* + prétérit (*was created*) ; *for eight years* et *since 2018* avec le present perfect (situation qui dure) ; *during* + nom ; *while* + proposition ; *by 1st June* = au plus tard ; *until 3rd June* = jusqu'à.\n\n**2.**\n- *The association **has existed for** eight years.* — situation qui dure encore → present perfect ; une **durée** → *for* (*since* introduit un point de départ).\n- *It was created **eight years ago**.* — *ago* se place **après** la durée.\n- *They planted trees **during** the winter.* — *winter* est un nom : il faut la préposition *during* ; *while* exige un sujet et un verbe."}$exo$::jsonb),
  ('4f4e7bfd-3797-5aaf-adbb-7e0caa758574'::uuid, 1, 'traduction', $exo${"titre":"Because ou because of ?","consigne":"Complète chaque phrase avec l'expression qui convient.","enonce":"**Complète avec : because, because of, thanks to, to, for, so as not to.**\n\n1. The match was cancelled ___ the storm.\n2. I stayed at home ___ I was ill.\n3. I passed my exam ___ your help.\n4. I bought these flowers ___ my grandmother.\n5. She went to the library ___ borrow a book.\n6. He left early ___ be late.","bareme":[{"critere":"Cause : because / because of / thanks to selon ce qui suit","points":10},{"critere":"But et « pour » : for + nom, to + verbe, so as not to","points":10}],"dureeMin":6,"corrige":"1. *because of the storm* — suivi d'un **nom**.\n2. *because I was ill* — suivi d'une **proposition**.\n3. *thanks to your help* — cause positive + nom.\n4. *for my grandmother* — « pour » + nom → *for*.\n5. *to borrow a book* — « pour » + verbe → *to* (jamais *for to*).\n6. *so as not to be late* — but négatif (pas *to not be late*)."}$exo$::jsonb),
  ('4f4e7bfd-3797-5aaf-adbb-7e0caa758574'::uuid, 2, 'traduction', $exo${"titre":"Pourquoi Lucas fait du bénévolat","consigne":"Traduis le texte en anglais, puis réponds à la question 2.","enonce":"**1. Thème : traduis en anglais.**\n\n> Lucas est bénévole dans une association pour aider les personnes âgées. Comme il habite près du centre, il y va à pied. Il a commencé à cause de sa grand-mère, qui vivait seule. Il parle fort pour que tout le monde puisse l'entendre. Il a reçu un prix pour son engagement.\n\n*Aide : bénévole = volunteer ; personnes âgées = elderly people ; engagement = commitment ; prix = award.*\n\n**2.** Pour chaque mot anglais qui traduit « pour » dans ta traduction, explique pourquoi tu l'as choisi.","bareme":[{"critere":"But : to help ; so that everyone can/could hear him","points":5},{"critere":"Cause : as/since he lives ; because of his grandmother","points":5},{"critere":"For + -ING ou for + nom pour la justification du prix","points":3},{"critere":"Explication des choix de « pour »","points":4},{"critere":"Vocabulaire et orthographe","points":3}],"dureeMin":12,"corrige":"**1. Traduction modèle**\n\n> *Lucas is a volunteer in an association to help elderly people. As he lives near the centre, he walks there. He started because of his grandmother, who lived alone. He speaks loudly so that everyone can hear him. He received an award for his commitment.*\n\nAcceptés : *Since he lives…* ; *in order to help* ; *so that everyone could hear him* ; *He got an award*.\n\n**2.**\n- *to help* : « pour » suivi d'un **verbe** → *to* + base verbale (but).\n- *so that everyone can hear him* : but avec un **sujet différent** (*everyone*) → *so that* + proposition, avec un modal.\n- *for his commitment* : « pour » suivi d'un **nom** → *for* ; il justifie le prix.\n- *because of his grandmother* : cause suivie d'un nom → *because of* (pas *because*).\n- *As he lives* : cause déjà connue, suivie d'une proposition."}$exo$::jsonb),
  ('4f4e7bfd-3797-5aaf-adbb-7e0caa758574'::uuid, 3, 'traduction', $exo${"titre":"Défendre un projet de piste cyclable","consigne":"Rédige un court texte argumentatif en anglais, puis corrige les fautes d'un camarade en expliquant la règle.","enonce":"**1. Production (70 à 90 mots).** Le conseil municipal hésite à construire une piste cyclable devant ton lycée. Écris un message au maire pour défendre le projet. Tu dois employer :\n- deux expressions de **cause** suivies d'une proposition (*because*, *since* ou *as*) ;\n- deux expressions de **cause** suivies d'un nom (*because of*, *due to*, *thanks to*) ;\n- *to* + base verbale, *in order to* et *so that* ;\n- un but **négatif** avec *so as not to*.\n\n**2.** Corrige et explique :\n- *Many students are late because of the traffic is heavy.*\n- *We need a bike lane for to be safe.*\n- *We ride carefully to not have accidents.*","bareme":[{"critere":"Cause : proposition après because/since/as ; nom après because of/due to/thanks to","points":6},{"critere":"But : to, in order to, so that + modal, so as not to","points":6},{"critere":"Message argumenté cohérent et correct","points":2},{"critere":"Trois phrases corrigées avec la règle","points":6}],"dureeMin":18,"corrige":"**1. Exemple de message attendu**\n\n> *Dear Mayor,*\n> *We need a bike lane in front of our school because the road is dangerous. Since many students live nearby, they could cycle every day. At the moment, they take the car because of the rain or due to the lack of safe routes. A bike lane would help us to be more independent. The city could build it in order to reduce pollution, so that everyone could breathe better. Students would leave home earlier so as not to be late. Thanks to this project, our town would be greener.*\n\nÀ vérifier : *because / since* + proposition ; *because of / due to / thanks to* + nom ; *to be*, *in order to reduce*, *so that everyone could…* (modal après *so that*), *so as not to be late*.\n\n**2.**\n- *because of the traffic is heavy* → *because **the traffic is heavy*** (ou *because of the heavy traffic*) : après *because of*, un **nom**, jamais sujet + verbe.\n- *for to be safe* → ***to** be safe* : « pour » + verbe → *to* ; *for to* n'existe pas.\n- *to not have accidents* → ***so as not to** have accidents* : c'est la forme du but négatif."}$exo$::jsonb),
  ('56c94c94-6867-5648-b077-acdab790a0c5'::uuid, 1, 'traduction', $exo${"titre":"Although ou despite ?","consigne":"Complète chaque phrase avec l'expression qui convient.","enonce":"**Complète avec : although, despite, unless, whereas, in case.**\n\n1. ___ the rain, we went for a walk.\n2. ___ it was raining, we went for a walk.\n3. You will miss the bus ___ you hurry.\n4. He likes tea, ___ his sister prefers coffee.\n5. Take a coat ___ it gets cold.\n\n**6. Corrige :** *Unless you don't study, you will fail.*","bareme":[{"critere":"Concession : despite + nom, although + proposition","points":8},{"critere":"Unless, whereas et in case bien employés","points":8},{"critere":"Correction de unless you don't (double négation)","points":4}],"dureeMin":7,"corrige":"1. ***Despite** the rain* — préposition + nom (*In spite of* accepté).\n2. ***Although** it was raining* — conjonction + proposition (*Even though* accepté).\n3. *…**unless** you hurry* — « sauf si tu te dépêches ».\n4. *…**whereas** his sister prefers coffee* — opposition entre deux faits (*while* accepté).\n5. *…**in case** it gets cold* — au cas où, suivi du présent.\n\n6. *Unless you study, you will fail.* (ou *If you don't study, you will fail.*) *Unless* contient déjà la négation : *unless you don't* ferait une double négation et dirait le contraire."}$exo$::jsonb),
  ('56c94c94-6867-5648-b077-acdab790a0c5'::uuid, 2, 'traduction', $exo${"titre":"Le débat sur l'uniforme","consigne":"Traduis les arguments en anglais, puis nomme la relation exprimée dans chaque phrase.","enonce":"**1. Thème : traduis en anglais.**\n\n1. Bien que l'uniforme soit cher, il évite les inégalités.\n2. Malgré les critiques, le lycée l'a adopté.\n3. Les élèves de 2de l'aiment, alors que ceux de Terminale le détestent.\n4. Tu ne pourras pas entrer à moins que tu portes ta veste.\n5. Si je dirigeais le lycée, je supprimerais l'uniforme.\n\n*Aide : uniforme = uniform ; éviter = to prevent ; supprimer = to get rid of ; veste = jacket.*\n\n**2.** Pour chaque phrase, dis s'il s'agit d'une condition, d'une concession ou d'une opposition.","bareme":[{"critere":"Concession : although + proposition, despite + nom","points":6},{"critere":"Opposition avec whereas / while","points":3},{"critere":"Condition : unless sans négation ; type 2 (If I ran…, I would…)","points":6},{"critere":"Relations correctement identifiées","points":5}],"dureeMin":12,"corrige":"**1. Traduction modèle**\n1. *Although the uniform is expensive, it prevents inequalities.* (*Even though* accepté)\n2. *Despite the criticism, the school adopted it.* (*In spite of* accepté)\n3. *Students in 2de like it, whereas those in Terminale hate it.* (*while* accepté ; *Year 11 / Year 13* acceptés)\n4. *You won't be able to come in unless you wear your jacket.* (*You can't come in unless…* accepté)\n5. *If I ran the school, I would get rid of the uniform.* — type 2, *if* + prétérit, *would* dans la principale.\n\n**2.**\n1. Concession (obstacle reconnu sans changer d'avis).\n2. Concession.\n3. Opposition (deux faits mis en regard, sans obstacle).\n4. Condition (*unless* = sauf si).\n5. Condition, irréel du présent."}$exo$::jsonb),
  ('56c94c94-6867-5648-b077-acdab790a0c5'::uuid, 3, 'traduction', $exo${"titre":"Pour ou contre les écrans au collège ?","consigne":"Rédige un paragraphe argumenté en anglais, puis corrige les fautes d'un camarade en expliquant la règle.","enonce":"**1. Production (80 à 100 mots).** Donne ton avis sur l'usage des tablettes en classe. Tu dois employer :\n- une **concession** avec une conjonction et une autre avec une préposition suivie d'un -ING ;\n- une **opposition** avec *whereas* et un connecteur entre deux phrases (*however* ou *on the other hand*) ;\n- une **condition** avec *unless* et une autre avec *provided that* ou *as long as* ;\n- une hypothèse **irréelle** (type 2 ou type 3).\n\n**2.** Corrige et explique :\n- *Despite tablets are useful, they distract students.*\n- *Although the cost, schools buy them.*\n- *If teachers would allow phones, students would be happier.*","bareme":[{"critere":"Deux concessions justes (conjonction + proposition ; préposition + -ING)","points":4},{"critere":"Opposition : whereas et however / on the other hand bien employés","points":4},{"critere":"Conditions : unless sans négation, provided that / as long as, irréel correct","points":5},{"critere":"Trois fautes corrigées et règle expliquée","points":6},{"critere":"Paragraphe cohérent","points":1}],"dureeMin":20,"corrige":"**1. Exemple de paragraphe attendu**\n\n> *Although tablets are expensive, I think they are useful in class. In spite of being distracting sometimes, they help students find information quickly. Some students love them, whereas others prefer paper. However, screens can hurt our eyes. Students won't learn well unless teachers control their use. Tablets are a good tool as long as we use them for short periods. If our school had more tablets, we would work in groups more easily.*\n\nÀ vérifier : *although* + proposition ; *in spite of being* (préposition + -ING) ; *whereas* entre deux faits ; *however* en début de phrase ; *unless* sans négation ; *as long as / provided that* + présent ; type 2 (*if* + prétérit, *would*) ou type 3 (*if* + past perfect, *would have* + participe).\n\n**2.**\n- *Despite tablets are useful* → ***Although** tablets are useful* (ou *Despite **being** useful*, *Despite their usefulness*) : *despite* est une **préposition**, suivie d'un nom ou d'un -ING, jamais d'une proposition.\n- *Although the cost* → ***Despite** the cost* (ou *Although it is expensive*) : *although* est une **conjonction**, il lui faut une proposition complète.\n- *If teachers would allow* → *If teachers **allowed** phones, students would be happier* : la subordonnée en *if* ne prend jamais *would* ; au type 2, elle est au **prétérit**."}$exo$::jsonb),
  ('b92b5ad3-ba5c-5b83-9596-693daea921e7'::uuid, 1, 'traduction', $exo${"titre":"What ou how ?","consigne":"Complète chaque exclamation avec what, what a / an ou how.","enonce":"**Complète avec what, what a, what an ou how.**\n\n1. … beautiful day!\n2. … terrible weather!\n3. … strange!\n4. … fast he runs!\n5. … interesting idea!\n6. … nice people!\n7. … pity!\n\n**8.** Rappelle en français la règle qui permet de choisir entre *what* et *how*.","bareme":[{"critere":"Les sept exclamations justes (dont article a / an et absence d'article)","points":14},{"critere":"Règle : what + nom, how + adjectif ou adverbe","points":6}],"dureeMin":6,"corrige":"1. ***What a** beautiful day!* (nom singulier dénombrable : *a*)\n2. ***What** terrible weather!* (indénombrable : sans article)\n3. ***How** strange!* (adjectif)\n4. ***How** fast he runs!* (adverbe)\n5. ***What an** interesting idea!* (*an* devant une voyelle)\n6. ***What** nice people!* (pluriel : sans article)\n7. ***What a** pity!*\n\n8. ***What*** est suivi d'un **nom** (groupe nominal) ; ***how*** est suivi d'un **adjectif** ou d'un **adverbe**."}$exo$::jsonb),
  ('b92b5ad3-ba5c-5b83-9596-693daea921e7'::uuid, 2, 'traduction', $exo${"titre":"So, such et l'ordre des mots","consigne":"Transforme les phrases selon les consignes, puis traduis les exclamations en anglais.","enonce":"**A. Transforme avec so, such ou such a.**\n\n1. She is very kind. → She is …\n2. It was a very good film. → It was …\n3. They are very nice people. → They are …\n\n**B. Corrige l'ordre des mots.**\n\n4. How beautiful is this place!\n5. How is it expensive!\n\n**C. Traduis en anglais.**\n\n6. Quel dommage !\n7. Comme ta sœur chante bien !\n8. Quelle belle maison !","bareme":[{"critere":"Transformations justes avec so, such a, such","points":6},{"critere":"Deux phrases corrigées sans inversion","points":6},{"critere":"Trois traductions justes","points":8}],"dureeMin":10,"corrige":"**A.**\n1. *She is **so** kind!* (*so* + adjectif)\n2. *It was **such a** good film!* (*such a* + adjectif + nom singulier)\n3. *They are **such** nice people!* (*such* + adjectif + nom pluriel)\n\n**B.** L'anglais ne fait **pas d'inversion** dans l'exclamation : le sujet reste devant le verbe.\n4. *How beautiful **this place is**!*\n5. *How expensive **it is**!*\n\n**C.**\n6. ***What a pity!*** (ou *What a shame!*)\n7. ***How well** your sister sings!* (adverbe → *how*, sans inversion)\n8. ***What a beautiful house!***"}$exo$::jsonb),
  ('b92b5ad3-ba5c-5b83-9596-693daea921e7'::uuid, 3, 'traduction', $exo${"titre":"Carte postale d'Édimbourg","consigne":"Corrige le texte, puis rédige ta propre carte postale en anglais selon les contraintes.","enonce":"**A.** Ce message contient **cinq** erreurs sur l'exclamation. Recopie les phrases fautives corrigées et explique chaque correction en français.\n\n> Dear Grandma,\n> We are in Edinburgh! How a beautiful city! What old the castle is! Yesterday it rained all day: what a terrible weather! The people are so nice people. How is delicious the food here!\n> Love, Zoé\n\n**B. Production.** Écris une carte postale de 6 à 8 phrases racontant un voyage. Tu dois employer : *what a* + nom singulier, *what* + nom pluriel ou indénombrable, *how* + adjectif + sujet + verbe, *such a*, *so*, et une exclamation toute faite (*No way!*, *Well done!*, *How come?*…).","bareme":[{"critere":"Les cinq erreurs corrigées","points":7},{"critere":"Règle expliquée pour chaque correction","points":3},{"critere":"Les six structures imposées présentes et correctes","points":7},{"critere":"Carte postale cohérente et correcte","points":3}],"dureeMin":17,"corrige":"**A.**\n1. ***What a** beautiful city!* — devant un nom (*city*), c'est *what (a)*, pas *how*.\n2. ***How old** the castle is!* — devant un adjectif seul, c'est *how*.\n3. *What terrible weather!* — *weather* est **indénombrable** : **pas d'article**.\n4. *The people are **so nice**!* ou *They are **such nice people**!* — *so* + adjectif, *such* + adjectif + nom.\n5. *How delicious **the food is** here!* — **pas d'inversion** : sujet puis verbe.\n\n**B. Exemple attendu :**\n*Dear Tom,*\n*We're in Cornwall. **What a** lovely place! **What** beautiful beaches! **How** blue the sea is! We had **such a** good time at the surf school. I was **so** tired after the lesson. I stood up on the board: **Well done!** said the teacher.*\n\nLe correcteur vérifie : article *a* devant un singulier, pas d'article devant un pluriel ou un indénombrable, pas d'inversion après *how*, *such a* devant un nom singulier, *so* devant un adjectif seul."}$exo$::jsonb),
  ('365a65f2-f3de-5e28-8847-39105a05c01a'::uuid, 1, 'traduction', $exo${"titre":"Former le passif","consigne":"Mets chaque phrase à la voix passive en gardant le même temps.","enonce":"**Mets à la voix passive.** Garde le complément d'agent (*by…*) seulement quand il est utile.\n\n1. They build houses. *(présent)*\n2. Shakespeare wrote Hamlet. *(prétérit)*\n3. They have repaired the car. *(present perfect)*\n4. They will open the new pool next year. *(futur)*\n5. You can recycle this bottle. *(modal)*\n\n**6.** Rappelle en français comment se forme la voix passive.","bareme":[{"critere":"Les cinq phrases passives justes, au bon temps","points":15},{"critere":"Formation : be au temps voulu + participe passé, complément devenu sujet, by","points":5}],"dureeMin":7,"corrige":"1. *Houses **are built**.*\n2. *Hamlet **was written by** Shakespeare.* (l'auteur est intéressant : on garde *by*)\n3. *The car **has been repaired**.*\n4. *The new pool **will be opened** next year.*\n5. *This bottle **can be recycled**.*\n\n6. Voix passive : **be** conjugué au **temps** de la phrase active + **participe passé**. Le **complément d'objet** de l'actif devient **sujet** ; l'ancien sujet, si on le garde, est introduit par ***by***."}$exo$::jsonb),
  ('365a65f2-f3de-5e28-8847-39105a05c01a'::uuid, 2, 'traduction', $exo${"titre":"Un article de journal","consigne":"Transforme les phrases de l'article à la voix passive, puis justifie l'emploi du passif.","enonce":"**Article.**\n\n> Last night, someone stole a famous painting from the city museum. The police have arrested two men. Experts are examining the frame. The museum will reopen the gallery on Monday.\n\n1. Réécris les **quatre** phrases à la voix passive, sans complément d'agent quand l'auteur est inconnu ou évident.\n2. Pourquoi le passif est-il fréquent dans les articles de journaux ? Donne deux raisons en français.\n3. Traduis : « On m'a donné un prix. » Donne les deux passifs possibles et indique le plus courant.","bareme":[{"critere":"Quatre phrases passives justes, au bon temps","points":10},{"critere":"Complément d'agent omis quand il est inconnu ou évident","points":3},{"critere":"Deux raisons de l'emploi du passif","points":3},{"critere":"Double passif : I was given a prize (le plus courant) et A prize was given to me","points":4}],"dureeMin":11,"corrige":"1.\n- *Last night, a famous painting **was stolen** from the city museum.* (auteur inconnu : pas de *by someone*)\n- *Two men **have been arrested**.* (*by the police* est évident, on peut l'omettre)\n- *The frame **is being examined** by experts.* (présent en BE + -ING → *is being* + participe passé ; *by experts* accepté ou omis)\n- *The gallery **will be reopened** on Monday.*\n\n2. Le passif permet de **mettre en avant ce qui a été fait** plutôt que qui l'a fait ; l'auteur est souvent **inconnu** (le voleur) ou **évident** (la police). C'est pourquoi le complément d'agent est omis dans la grande majorité des phrases passives.\n\n3. ***I was given a prize.*** (le plus courant) ou ***A prize was given to me.***"}$exo$::jsonb),
  ('365a65f2-f3de-5e28-8847-39105a05c01a'::uuid, 3, 'traduction', $exo${"titre":"La construction du pont","consigne":"Corrige les erreurs, puis rédige un court texte informatif en anglais en employant le passif selon les contraintes.","enonce":"**A.** Chaque phrase contient une erreur sur le passif. Corrige-la et explique en français.\n\n1. The window broken by the storm.\n2. The bridge was build in 1894.\n3. English is speak in many countries.\n4. The letter has sent yesterday.\n\n**B. Production.** Rédige un texte informatif de 6 à 8 phrases sur un monument (réel ou inventé). Tu dois employer le passif à **quatre temps différents** (présent, prétérit, present perfect, futur ou modal), au moins un complément d'agent avec *by* justifié, et au moins un passif **sans** complément d'agent.\n\n**C.** Explique en français pourquoi tu as gardé *by* dans une phrase et pas dans une autre.","bareme":[{"critere":"Les quatre erreurs corrigées et expliquées","points":6},{"critere":"Passif à quatre temps différents, correctement formé","points":7},{"critere":"Usage justifié du complément d'agent (C)","points":4},{"critere":"Texte cohérent et correct","points":3}],"dureeMin":18,"corrige":"**A.**\n1. *The window **was** broken by the storm.* — il manque **be** : sans lui, pas de verbe conjugué.\n2. *The bridge was **built** in 1894.* — il faut le **participe passé** (*built*), pas la base verbale.\n3. *English is **spoken** in many countries.* — participe passé de *speak* : *spoken*.\n4. *The letter **was sent** yesterday.* — avec *yesterday* (moment passé précis), le **prétérit** : *was sent* ; et le passif demande *be* (*has been sent* serait incompatible avec *yesterday*).\n\n**B. Exemple attendu :**\n*Tower Bridge **was built** between 1886 and 1894. It **was designed by** Horace Jones. Today, it **is crossed** by thousands of cars every day. The bridge **has been painted** blue and white. It **can be visited** all year round. A new exhibition **will be opened** next spring.*\n\n**C.** On garde *by* quand l'auteur est **intéressant** ou nouveau (l'architecte) ; on l'omet quand il est **inconnu, évident ou sans intérêt** (ceux qui ont peint le pont) : s'il était important, on aurait gardé l'actif."}$exo$::jsonb),
  ('b14995b7-4d6a-5eaa-8cd0-71ba94a53e56'::uuid, 1, 'traduction', $exo${"titre":"Used to ou be used to ?","consigne":"Complète chaque phrase avec la bonne forme, puis traduis-la en français.","enonce":"**Complète avec used to, am / is used to ou is getting used to, et mets le verbe à la bonne forme.**\n\n1. When I was a child, I … (play) with dolls. *(ce n'est plus le cas)*\n2. I … (get up) early: I do it every day, it's easy for me.\n3. She has just moved to Canada. She … (live) in the cold.\n4. My grandfather … (smoke), but he stopped ten years ago.\n\n**5.** Explique en français la différence de forme du verbe après *used to* et après *be used to*.","bareme":[{"critere":"Les quatre formes justes","points":10},{"critere":"Traductions françaises justes","points":4},{"critere":"Règle : used to + base verbale, be used to + -ING","points":6}],"dureeMin":7,"corrige":"1. *I **used to play** with dolls.* — « Je jouais à la poupée (autrefois). »\n2. *I **am used to getting up** early.* — « J'ai l'habitude de me lever tôt. »\n3. *She **is getting used to living** in the cold.* — « Elle s'habitue à vivre dans le froid. »\n4. *My grandfather **used to smoke**.* — « Mon grand-père fumait (autrefois). »\n\n5. Après ***used to*** (habitude passée révolue) : **base verbale**. Après ***be / get used to*** (être habitué, s'habituer) : verbe en **-ING** ou nom."}$exo$::jsonb),
  ('b14995b7-4d6a-5eaa-8cd0-71ba94a53e56'::uuid, 2, 'traduction', $exo${"titre":"La vie d'avant de Grandpa Joe","consigne":"Exploite le document pour écrire des phrases avec used to, would et le présent simple.","enonce":"**Document – Grandpa Joe, 80 ans, raconte**\n\n| Autrefois | Aujourd'hui |\n|---|---|\n| went to school on foot | takes the bus to town |\n| was very shy | is very talkative |\n| every Sunday, went fishing with his father | watches football on TV |\n| didn't have a phone | calls his grandchildren every day |\n\n1. Écris **quatre** phrases sur la vie d'autrefois de Joe avec *used to* (dont une à la forme **négative**).\n2. Réécris la phrase sur la pêche avec *would*. Peut-on faire de même pour « was very shy » ? Justifie.\n3. Écris deux phrases sur sa vie d'aujourd'hui avec un adverbe de fréquence bien placé.\n4. Pose une question à Joe avec *used to*.","bareme":[{"critere":"Quatre phrases avec used to justes, dont la négative didn't use to","points":8},{"critere":"Would pour l'action répétée, impossible pour un état, justifié","points":5},{"critere":"Deux phrases au présent simple avec adverbe bien placé","points":4},{"critere":"Question Did you use to… ?","points":3}],"dureeMin":11,"corrige":"1. Exemples attendus :\n- *Joe **used to go** to school on foot.*\n- *He **used to be** very shy.*\n- *He **used to go** fishing with his father every Sunday.*\n- *He **didn't use to have** a phone.* (sans *-d* après *did*)\n\n2. *Every Sunday, he **would go** fishing with his father.* — *would* convient pour une **action répétée**. Pour « was very shy », **non** : c'est un **état** ; seul *used to* convient (*He used to be shy*, jamais *he would be shy*).\n\n3. Exemples : *He **usually takes** the bus to town.* / *He **always calls** his grandchildren.* / *He **is often** very talkative.* — l'adverbe se place **avant** le verbe lexical, **après** *be*.\n\n4. ***Did** you **use to** play football, Grandpa?*"}$exo$::jsonb),
  ('b14995b7-4d6a-5eaa-8cd0-71ba94a53e56'::uuid, 3, 'traduction', $exo${"titre":"Une nouvelle vie à Toronto","consigne":"Corrige les erreurs, puis rédige un texte en anglais qui oppose passé, présent et adaptation.","enonce":"**A.** Corrige chaque phrase et explique la règle en français.\n\n1. I am used to swim every morning.\n2. I didn't used to like vegetables.\n3. When I was young, I would be very shy.\n4. She is getting used to speak English.\n\n**B. Production.** Nadia vient de quitter Lyon pour Toronto. Rédige son journal intime (8 à 10 phrases) : ce qu'elle faisait autrefois, ce qu'elle fait maintenant, ce à quoi elle est déjà habituée et ce à quoi elle s'habitue peu à peu. Tu dois employer : *used to* (affirmatif et négatif), *would*, *be used to*, *get used to*, et le présent simple avec deux adverbes de fréquence.","bareme":[{"critere":"Les quatre erreurs corrigées et expliquées","points":6},{"critere":"Used to affirmatif et négatif, would pour une action répétée","points":5},{"critere":"Be used to et get used to suivis de -ING ou d'un nom","points":5},{"critere":"Présent simple et adverbes bien placés, texte cohérent","points":4}],"dureeMin":18,"corrige":"**A.**\n1. *I am used to **swimming** every morning.* — après *be used to* : **-ING**.\n2. *I didn't **use** to like vegetables.* — après *did*, pas de *-d* : *didn't use to*.\n3. *When I was young, I **used to be** very shy.* — *shy* est un **état** : *would* est impossible.\n4. *She is getting used to **speaking** English.* — après *get used to* : **-ING**.\n\n**B. Exemple attendu :**\n*In Lyon, I **used to walk** to school with my friends. Every Friday, we **would eat** crêpes together. I **didn't use to wear** a hat! Now I **always wear** one, because it's minus ten. I **usually take** the subway. I **am** already **used to speaking** English at school. But I **am** still **getting used to** the snow and to having dinner at six.*\n\nLe correcteur vérifie : base verbale après *used to*, *didn't use to*, *would* seulement pour une action, **-ING** ou nom après *be / get used to*, adverbes avant le verbe lexical."}$exo$::jsonb),
  ('92c7f3de-f6a1-502a-aa3e-188bd7873580'::uuid, 1, 'traduction', $exo${"titre":"Rapporter des paroles","consigne":"Mets chaque phrase au discours indirect après « He said » ou « She said ».","enonce":"**Mets au discours indirect.**\n\n1. « I am tired. » → He said …\n2. « I saw her. » → He said …\n3. « I will call you. » → She said …\n4. « I can swim. » → He said …\n5. « I have finished. » → She said …\n\n**6.** Explique en français ce qu'est le **recul des temps** et quand il ne s'applique pas.","bareme":[{"critere":"Les cinq phrases justes (temps reculé, pronoms adaptés)","points":15},{"critere":"Recul des temps défini, avec ses exceptions (verbe introducteur au présent, vérité générale)","points":5}],"dureeMin":7,"corrige":"1. *He said (that) he **was** tired.* (présent → prétérit)\n2. *He said (that) he **had seen** her.* (prétérit → past perfect)\n3. *She said (that) she **would** call me.* (*will* → *would* ; *you* → *me*)\n4. *He said (that) he **could** swim.* (*can* → *could*)\n5. *She said (that) she **had finished**.* (present perfect → past perfect)\n\n6. Quand le verbe introducteur est au **passé** (*said, told*), chaque temps **recule d'un cran**. Le recul ne s'applique **pas** quand le verbe introducteur est au **présent** (*He says he is tired*), ni quand le fait rapporté est **toujours vrai**."}$exo$::jsonb),
  ('92c7f3de-f6a1-502a-aa3e-188bd7873580'::uuid, 2, 'traduction', $exo${"titre":"Ce que le prof a dit","consigne":"Rapporte les paroles au discours indirect en adaptant temps, pronoms et repères.","enonce":"**Situation.** Hier, Mrs Cole a parlé à la classe. Aujourd'hui, Lucas raconte ce qu'elle a dit à Jade, qui était absente.\n\n1. « The test is tomorrow. »\n2. « I corrected your essays yesterday. »\n3. « Are you ready? »\n4. « Where do you usually revise? »\n5. « Close your books. »\n6. « Don't be late. »\n\nCommence chaque phrase par *She said*, *She told us* ou *She asked us*. Choisis bien entre *say* et *tell*.","bareme":[{"critere":"Phrases 1 et 2 : temps reculés et repères adaptés (the next day, the day before)","points":6},{"critere":"Questions 3 et 4 : if, ordre de l'affirmative","points":6},{"critere":"Ordres 5 et 6 : told us to / not to + base verbale","points":5},{"critere":"say et tell bien employés, pronoms adaptés","points":3}],"dureeMin":11,"corrige":"1. *She said (that) the test **was the next day**.* (*is* → *was* ; *tomorrow* → *the next day*)\n2. *She told us (that) she **had corrected our** essays **the day before**.* (prétérit → past perfect ; *your* → *our* ; *yesterday* → *the day before*)\n3. *She asked us **if / whether we were** ready.* (question fermée : *if / whether*, ordre de l'affirmative)\n4. *She asked us **where we usually revised**.* (question ouverte : pas de *do*, ordre de l'affirmative)\n5. *She told us **to close** our books.*\n6. *She told us **not to be** late.*\n\n***Say*** ne prend pas de complément de personne (*She said…*) ; ***tell*** en exige un (*She told **us**…*)."}$exo$::jsonb),
  ('92c7f3de-f6a1-502a-aa3e-188bd7873580'::uuid, 3, 'traduction', $exo${"titre":"Le témoin de l'accident","consigne":"Corrige les erreurs, puis réécris un dialogue entier au discours indirect.","enonce":"**A.** Corrige chaque phrase et explique la règle en français.\n\n1. He said me that he was tired.\n2. She asked me where did I live.\n3. He told that he would come.\n4. She asked me are you ready.\n\n**B. Dialogue.** Un policier interroge Ryan, témoin d'un accident.\n\n> **Policeman**: Where were you at 5 pm?\n> **Ryan**: I was waiting for the bus here.\n> **Policeman**: Did you see the car?\n> **Ryan**: Yes, it was going very fast. I have never seen that car before.\n> **Policeman**: Can you describe the driver?\n> **Ryan**: He was wearing a red cap. I will help you if I can.\n> **Policeman**: Don't leave the town.\n\nRéécris tout le dialogue au **discours indirect** dans un récit au passé (*The policeman asked Ryan…*, *Ryan said…*).","bareme":[{"critere":"Les quatre erreurs corrigées et expliquées","points":6},{"critere":"Recul des temps juste dans tout le dialogue","points":6},{"critere":"Questions rapportées (if, mot interrogatif, ordre affirmatif) et ordre rapporté","points":5},{"critere":"Pronoms, repères (here → there) et say / tell corrects","points":3}],"dureeMin":18,"corrige":"**A.**\n1. *He **told me** / He **said** that he was tired.* — *say* ne prend pas de complément de personne.\n2. *She asked me where **I lived**.* — la question rapportée reprend l'**ordre de l'affirmative**, sans *did*.\n3. *He **said** that he would come.* — *tell* exige un complément de personne (*He told me…*).\n4. *She asked me **if I was** ready.* — question fermée : *if / whether*, ordre affirmatif, temps reculé.\n\n**B. Réponse attendue :**\n*The policeman asked Ryan **where he had been** at 5 pm. Ryan said (that) **he had been waiting** for the bus **there**. The policeman asked him **if / whether he had seen** the car. Ryan said that **it had been going** very fast and that **he had never seen** that car before. The policeman asked him **if he could** describe the driver. Ryan said that the driver **had been wearing** a red cap and that **he would help** him if **he could**. Finally, the policeman **told him not to leave** the town.*\n\nLe correcteur vérifie : prétérit → past perfect (*were* → *had been*, *saw* → *had seen*), present perfect → past perfect, *will* → *would*, *can* → *could* ; *here* → *there* ; questions sans inversion ; ordre avec *told him not to*. Tolérer *he was waiting* / *it was going* (prétérit en BE + -ING non reculé), fréquent à l'oral, mais valoriser le past perfect."}$exo$::jsonb),
  ('22239202-eacb-5f3f-a12a-9151dbae046c'::uuid, 1, 'traduction', $exo${"titre":"Some, any, much, many","consigne":"Complète chaque phrase avec le quantifieur qui convient, puis réponds à la question 2.","enonce":"**1. Complète avec some, any, much ou many.**\n\n1. I have ___ money in my pocket.\n2. We don't have ___ bread.\n3. How ___ books have you got?\n4. How ___ water do you drink a day?\n5. Would you like ___ tea?\n6. Is there ___ milk in the fridge?\n\n**2.** Explique la différence de sens entre *I have a few friends* et *I have few friends*.","bareme":[{"critere":"Six quantifieurs justes","points":12},{"critere":"Différence a few (assez, rassurant) / few (trop peu) expliquée","points":8}],"dureeMin":7,"corrige":"**1. Réponses**\n1. **some** money — affirmative.\n2. **any** bread — négative.\n3. How **many** books — dénombrable pluriel.\n4. How **much** water — indénombrable.\n5. Would you like **some** tea? — offre polie : *some* même dans une question.\n6. Is there **any** milk — interrogative.\n\n**2. A few / few**\n*I have a few friends* : j'ai quelques amis, un nombre **suffisant** — le sens est positif, il rassure.\n*I have few friends* : j'ai **peu** d'amis, trop peu — le sens est négatif, il inquiète. L'article *a* change le sens."}$exo$::jsonb),
  ('22239202-eacb-5f3f-a12a-9151dbae046c'::uuid, 2, 'traduction', $exo${"titre":"La fête de Yanis","consigne":"Complète le dialogue, puis justifie trois de tes choix.","enonce":"> **Yanis**: I'm organising a party. Have we got (1) ___ crisps?\n> **Mum**: No, we haven't got (2) ___ crisps, but we've got (3) ___ lemonade.\n> **Yanis**: How (4) ___ bottles?\n> **Mum**: Only two. That's not (5) ___ for twenty people!\n> **Yanis**: And how (6) ___ cake is left?\n> **Mum**: Just (7) ___ cake, but we've got (8) ___ biscuits.\n\n*Mots possibles : any, some, many, much, enough, a little, a lot of.*\n\n1. Complète les huit blancs.\n2. Justifie tes choix pour les blancs 2, 4 et 6.","bareme":[{"critere":"Huit blancs corrects","points":10},{"critere":"Justifications : forme de la phrase (négative / interrogative)","points":4},{"critere":"Justifications : dénombrable / indénombrable (many / much)","points":4},{"critere":"Clarté des explications","points":2}],"dureeMin":10,"corrige":"**1. Réponses**\n(1) **any** — question.\n(2) **any** — négative.\n(3) **some** — affirmative.\n(4) How **many** bottles — dénombrable pluriel.\n(5) not **enough** — pas assez.\n(6) How **much** cake — *cake* est ici indénombrable (de la matière).\n(7) **a little** cake — un peu de, indénombrable.\n(8) **a lot of** biscuits (ou *some*) — affirmative, dénombrable.\n\n**2. Justifications**\n- Blanc 2 : la phrase est **négative** (*haven't got*) → *any*.\n- Blanc 4 : *bottles* est **dénombrable** pluriel → *how many*.\n- Blanc 6 : *cake* au singulier, sans article, désigne une quantité de gâteau : **indénombrable** → *how much*.\n\nAccepter (8) *some* ; refuser *much biscuits* ou *many cake*."}$exo$::jsonb),
  ('22239202-eacb-5f3f-a12a-9151dbae046c'::uuid, 3, 'traduction', $exo${"titre":"Le camp de vacances","consigne":"Traduis les six phrases en anglais, puis réponds à la question 2 en justifiant.","enonce":"**1. Thème : traduis en anglais.**\n\n1. Il n'y a pas de lait dans le frigo.\n2. Tu veux du jus d'orange ?\n3. Prends n'importe quel livre.\n4. Nous avons trop de devoirs et pas assez de temps.\n5. Peu d'élèves sont venus : c'était triste.\n6. J'ai quelques amis au camp, alors je suis content.\n\n*Aide : came = sont venus ; at the camp = au camp.*\n\n**2.** Les phrases 5 et 6 parlent toutes deux d'une petite quantité. Explique en quoi leur sens diffère, et comment l'anglais le marque.","bareme":[{"critere":"No / any, some pour l'offre, any au sens de n'importe quel","points":6},{"critere":"Too much / enough avec les bons noms (homework indénombrable)","points":4},{"critere":"Few / a few correctement choisis","points":4},{"critere":"Explication de la nuance few / a few","points":4},{"critere":"Correction de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n1. *There is no milk in the fridge.* (ou *There isn't any milk…*)\n2. *Would you like some orange juice?* — offre polie : *some*.\n3. *Take any book (you like).* — *any* en affirmative = n'importe quel.\n4. *We have too much homework and not enough time.* — *homework* est indénombrable → *too much* (pas *too many homeworks*) ; *enough* devant le nom.\n5. *Few students came: it was sad.* (*pupils* accepté)\n6. *I have a few friends at the camp, so I'm happy.*\n\n**2. La nuance**\nLes deux phrases parlent d'un petit nombre (*students*, *friends* sont dénombrables), mais :\n- *few* (sans article) = **trop peu**, sens négatif : on le regrette (« c'était triste ») ;\n- *a few* = **quelques-uns, assez**, sens positif : on s'en contente (« je suis content »).\nL'anglais marque cette différence par la seule présence de l'article *a*. Pour un indénombrable, on aurait *little* / *a little*."}$exo$::jsonb),
  ('30842fd7-d8cb-57a5-abfc-923120a821d0'::uuid, 1, 'traduction', $exo${"titre":"Bored ou boring ?","consigne":"Choisis la bonne forme de l'adjectif, puis traduis les deux groupes.","enonce":"**1. Entoure la bonne forme et recopie la phrase.**\n\n1. The film was very (bored / boring).\n2. I am (interested / interesting) in history.\n3. After the match, the players were (tired / tiring).\n4. The news was (surprised / surprising).\n5. The children were (frightened / frightening) by the storm.\n6. This book is really (interested / interesting).\n\n**2. Traduis :** une voiture rouge — deux voitures rouges.","bareme":[{"critere":"Six choix -ed / -ing justes","points":14},{"critere":"Traduction avec adjectif invariable placé avant le nom","points":6}],"dureeMin":6,"corrige":"**1. Réponses**\n1. The film was very **boring**. — le film provoque l'ennui.\n2. I am **interested** in history. — ce que je ressens.\n3. The players were **tired**. — ce qu'ils ressentent.\n4. The news was **surprising**. — la nouvelle provoque la surprise.\n5. The children were **frightened**. — ce qu'ils ressentent.\n6. This book is really **interesting**. — le livre provoque l'intérêt.\n\nRègle : **-ed** = ce que ressent la personne ; **-ing** = ce qui provoque le sentiment.\n\n**2. Traduction**\n*a red car* — *two red cars*. L'adjectif se place **avant** le nom et reste **invariable** : jamais *reds*."}$exo$::jsonb),
  ('30842fd7-d8cb-57a5-abfc-923120a821d0'::uuid, 2, 'traduction', $exo${"titre":"La brocante de Léon","consigne":"Remets les adjectifs dans l'ordre, puis traduis les groupes avec un adjectif composé.","enonce":"Léon vend des objets à une brocante. Aide-le à écrire ses étiquettes.\n\n**1. Remets les adjectifs dans le bon ordre.**\n\na. a (wooden / small / old) box\nb. a (French / beautiful / blue) vase\nc. (leather / black / big) boots\n\n**2. Traduis en anglais.**\n\na. une fille de dix ans\nb. un film de deux heures\nc. un trajet de trois kilomètres\n\n**3.** Complète : *Léon seems ___ (happy / happily).* Explique ton choix.","bareme":[{"critere":"Ordre des adjectifs juste dans les trois groupes","points":9},{"critere":"Adjectifs composés avec trait d'union et nom au singulier","points":7},{"critere":"Adjectif après le verbe d'état seem, choix expliqué","points":4}],"dureeMin":10,"corrige":"**1. Ordre** (opinion → taille → âge → forme → couleur → origine → matière)\na. *a small old wooden box* — taille, âge, matière.\nb. *a beautiful blue French vase* — opinion, couleur, origine.\nc. *big black leather boots* — taille, couleur, matière.\n\n**2. Adjectifs composés**\na. *a ten-year-old girl*\nb. *a two-hour film*\nc. *a three-kilometre journey* (ou *trip* ; *kilometer* accepté)\nTrait d'union, et le nom reste au **singulier** : jamais *ten-years-old* ni *two-hours*.\n\n**3.** *Léon seems **happy**.* — *seem* est un verbe d'état (comme be, look, feel) : il est suivi d'un **adjectif**, pas d'un adverbe."}$exo$::jsonb),
  ('30842fd7-d8cb-57a5-abfc-923120a821d0'::uuid, 3, 'traduction', $exo${"titre":"Une journée au musée","consigne":"Traduis le texte en anglais, puis justifie trois choix grammaticaux.","enonce":"**1. Thème : traduis en anglais.**\n\n> Hier, notre classe a visité un grand musée moderne. Le guide était intéressant, mais la visite de trois heures était fatigante. À la fin, nous étions fatigués. Dans une salle, il y avait une jolie petite table ronde en bois. Le musée aide les pauvres : l'entrée est gratuite pour eux.\n\n*Aide : visited = a visité ; room = salle ; free = gratuit ; entry = l'entrée ; to help = aider.*\n\n**2.** Justifie en une phrase chacun :\na) *interesting* / *tiring* / *tired* ;\nb) l'ordre des adjectifs devant *table* ;\nc) le verbe employé avec *the poor*.","bareme":[{"critere":"Adjectifs placés avant le nom, invariables, bon ordre","points":5},{"critere":"Choix -ed / -ing justes","points":4},{"critere":"Adjectif composé three-hour et adjectif substantivé the poor avec verbe au pluriel","points":4},{"critere":"Trois justifications exactes","points":5},{"critere":"Correction générale de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n> *Yesterday, our class visited a big modern museum. The guide was interesting, but the three-hour visit was tiring. At the end, we were tired. In one room, there was a lovely little round wooden table. The museum helps the poor: entry is free for them.*\n(*nice* ou *pretty little round wooden table* acceptés ; *large* accepté.)\n\n**2. Justifications**\na) *interesting* et *tiring* décrivent ce qui **provoque** le sentiment (le guide, la visite) → **-ing** ; *tired* décrit ce que **ressentent** les élèves → **-ed**. *We were tiring* voudrait dire « nous étions fatigants ».\nb) Ordre : opinion (*lovely*) → taille (*little*) → forme (*round*) → matière (*wooden*).\nc) *the poor* désigne un **groupe entier** de personnes : l'adjectif substantivé prend **the** et un sens pluriel (on le reprend par *them*, et un verbe dont il serait sujet serait au pluriel : *the poor are…*).\n\nAutres points : *three-hour* avec trait d'union et sans -s ; adjectifs jamais au pluriel."}$exo$::jsonb),
  ('19027263-3518-5881-9d17-724736f5d69c'::uuid, 1, 'traduction', $exo${"titre":"Repérer l'auxiliaire","consigne":"Pour chaque phrase, relève l'auxiliaire et le verbe lexical, puis donne une réponse courte.","enonce":"**1. Relève l'auxiliaire et le verbe lexical.**\n\na. She is working.\nb. I have finished.\nc. They don't know.\nd. You can go.\n\n**2. Réponds par une réponse courte (reprise).**\n\na. Do you like tea? — Yes, …\nb. Is she ready? — No, …\nc. Have you finished? — Yes, …\nd. Can he swim? — No, …","bareme":[{"critere":"Auxiliaire et verbe lexical correctement relevés dans les quatre phrases","points":10},{"critere":"Quatre réponses courtes avec le bon auxiliaire repris","points":10}],"dureeMin":7,"corrige":"**1. Repérage**\na. auxiliaire **is** (be, forme en -ING) — verbe lexical **working** (work).\nb. auxiliaire **have** (temps composé) — verbe lexical **finished** (finish).\nc. auxiliaire **do** (dans *don't*, négation) — verbe lexical **know**.\nd. auxiliaire **can** (modal) — verbe lexical **go**.\n\n**2. Réponses courtes**\na. Yes, **I do**.\nb. No, **she isn't**.\nc. Yes, **I have**.\nd. No, **he can't**.\n\nLa reprise courte répète l'**auxiliaire** de la question, jamais le verbe lexical (*Yes, I like* est faux)."}$exo$::jsonb),
  ('19027263-3518-5881-9d17-724736f5d69c'::uuid, 2, 'traduction', $exo${"titre":"Questions et négations","consigne":"Mets chaque phrase à la forme interrogative, puis à la forme négative.","enonce":"Mets chaque phrase **à la forme interrogative**, puis **à la forme négative**.\n\n1. You are ready.\n2. She has finished her homework.\n3. He works in London.\n4. They can speak Spanish.\n5. You have a car.\n\n**Question finale :** pourquoi les phrases 3 et 5 ne se construisent-elles pas comme les autres ?","bareme":[{"critere":"Questions avec l'auxiliaire placé devant le sujet","points":7},{"critere":"Négations avec not juste après l'auxiliaire","points":7},{"critere":"Do employé pour work et pour have lexical","points":4},{"critere":"Explication : verbe lexical seul, il faut un auxiliaire","points":2}],"dureeMin":10,"corrige":"**Réponses**\n1. *Are you ready?* — *You aren't ready.* (*You are not ready.*)\n2. *Has she finished her homework?* — *She hasn't finished her homework.*\n3. *Does he work in London?* — *He doesn't work in London.*\n4. *Can they speak Spanish?* — *They can't speak Spanish.* (*cannot*)\n5. *Do you have a car?* — *You don't have a car.*\n\n**Explication**\nDans les phrases 1, 2 et 4, il y a déjà un auxiliaire (*are*, *has*, *can*) : il passe devant le sujet pour la question et reçoit *not* pour la négation. Dans les phrases 3 et 5, il n'y a qu'un **verbe lexical** (*works*, *have* au sens de posséder) : seul, il ne sait former ni question ni négation, il faut donc l'auxiliaire **do** (*does* à la 3e personne, et le verbe revient à la base verbale : *does he work*)."}$exo$::jsonb),
  ('19027263-3518-5881-9d17-724736f5d69c'::uuid, 3, 'traduction', $exo${"titre":"L'interview d'une chanteuse","consigne":"Retrouve les questions de la journaliste, puis réponds aux questions 2 et 3.","enonce":"Une journaliste interroge la chanteuse Maya. Voici les réponses de Maya.\n\n1. (…?) — *Yes, I am. I'm very tired tonight.*\n2. (…?) — *Yes, I do. I love my fans.*\n3. (…?) — *No, I haven't. I haven't finished my new album yet.*\n4. (…?) — *Yes, I can. I can play the piano.*\n5. (…?) — *No, I don't. I don't have a dog.*\n\n**1.** Écris les cinq questions de la journaliste.\n**2.** Dans la réponse 1, *be* est-il auxiliaire ou verbe lexical ? Et *have* dans la réponse 5 ? Justifie.\n**3.** Explique pourquoi l'auxiliaire est « la clé de toute la grammaire anglaise ».","bareme":[{"critere":"Cinq questions correctes, auxiliaire devant le sujet","points":8},{"critere":"Auxiliaire de la question cohérent avec la reprise courte","points":4},{"critere":"Statut de be et de have justifié","points":5},{"critere":"Explication du rôle de l'auxiliaire (question, négation, reprise)","points":3}],"dureeMin":15,"corrige":"**1. Questions attendues**\n1. *Are you tired (tonight)?*\n2. *Do you love your fans?* (*Do you like your fans?* accepté)\n3. *Have you finished your new album (yet)?*\n4. *Can you play the piano?* (*Can you play an instrument?* accepté)\n5. *Do you have a dog?*\nLa reprise courte donne l'auxiliaire : *I am* → *Are you…?* ; *I do* → *Do you…?*, etc.\n\n**2. Statut**\n- Réponse 1 : *be* est **lexical** (verbe d'état, *I'm tired*), mais il **garde ses pouvoirs** d'auxiliaire : il passe lui-même devant le sujet (*Are you tired?*), sans *do*.\n- Réponse 5 : *have* est **lexical** (posséder) : il n'a pas ces pouvoirs, il faut **do** (*Do you have a dog?* / *I don't have a dog*).\n\n**3. La clé**\nL'auxiliaire construit la phrase : il passe **devant le sujet** pour la question, reçoit **not** pour la négation et sert à la **reprise courte**. Une fois l'auxiliaire repéré, question, négation et réponse courte se construisent toutes seules."}$exo$::jsonb),
  ('bd47bfd3-6bc0-5c8d-b855-b6963b1ec465'::uuid, 1, 'traduction', $exo${"titre":"Make ou let ?","consigne":"Complète avec make, made, let ou lets, puis corrige la phrase fautive.","enonce":"**1. Complète.**\n\n1. My parents ___ me do my homework every evening. (ils m'obligent)\n2. My sister ___ me borrow her bike yesterday. (elle m'a autorisé)\n3. The film ___ me cry. (il m'a fait pleurer)\n4. Our teacher ___ us use a calculator. (il nous autorise)\n\n**2. Corrige :** *My mum made me to tidy my room.*","bareme":[{"critere":"Quatre formes justes (sens et temps)","points":12},{"critere":"Correction : make + complément + base verbale, sans to","points":8}],"dureeMin":6,"corrige":"**1. Réponses**\n1. My parents **make** me do — obliger, présent.\n2. My sister **let** me borrow — autoriser ; *let* a la même forme au prétérit.\n3. The film **made** me cry — make = faire (provoquer), prétérit.\n4. Our teacher **lets** us use — autoriser, 3e personne du présent.\n\n**2. Correction**\n*My mum made me tidy my room.* — *make* + complément + **base verbale**, sans *to*. Le *to* ne réapparaît qu'au passif : *I was made to tidy my room*."}$exo$::jsonb),
  ('bd47bfd3-6bc0-5c8d-b855-b6963b1ec465'::uuid, 2, 'traduction', $exo${"titre":"Les courses de Mme Leroy","consigne":"Réécris chaque phrase avec la structure causative have (ou get), puis traduis les deux phrases de la question 2.","enonce":"Mme Leroy ne fait rien elle-même : elle fait tout faire par des professionnels.\n\n**1. Réécris avec have + complément + participe passé.**\n\na. A hairdresser cut her hair.\nb. A mechanic repaired her car.\nc. A painter painted her kitchen.\nd. Someone fixed her phone. (avec *get*)\n\n**2. Traduis en anglais.**\n\na. J'ai convaincu mon frère de m'aider.\nb. Je me suis fait couper les cheveux samedi.\n\n**3.** Pourquoi *I cut my hair* ne traduit-il pas « je me suis fait couper les cheveux » ?","bareme":[{"critere":"Quatre phrases causatives correctes (have / get + complément + participe passé)","points":8},{"critere":"Get + to pour convaincre, had my hair cut","points":6},{"critere":"Explication du piège I cut my hair","points":4},{"critere":"Correction de la langue","points":2}],"dureeMin":10,"corrige":"**1. Réponses**\na. *She had her hair cut.*\nb. *She had her car repaired.*\nc. *She had her kitchen painted.*\nd. *She got her phone fixed.*\nConstruction : *have / get* + complément + **participe passé**. Le sujet ne fait pas l'action : il la **commande**.\n\n**2. Traduction**\na. *I got my brother to help me.* — *get* + complément + **to** + verbe = convaincre.\nb. *I had my hair cut on Saturday.* (*I got my hair cut* accepté)\n\n**3. Le piège**\n*I cut my hair* signifie que je les ai coupés **moi-même**. « Se faire couper les cheveux » par un coiffeur se dit avec la structure causative : *I had my hair cut*."}$exo$::jsonb),
  ('bd47bfd3-6bc0-5c8d-b855-b6963b1ec465'::uuid, 3, 'traduction', $exo${"titre":"Le stage de voile","consigne":"Traduis le texte en anglais, puis réponds aux questions 2 et 3 en justifiant.","enonce":"**1. Thème : traduis en anglais.**\n\n> Au stage de voile, le moniteur nous faisait nager tous les matins, mais il nous laissait choisir notre bateau. Un jour, j'ai convaincu mon ami d'essayer le kayak. Ma planche était cassée, alors je l'ai fait réparer.\n\n*Aide : sailing camp = stage de voile ; instructor = moniteur ; board = planche ; to try = essayer.*\n\n**2.** Mets ces deux phrases au passif et explique ce qui change :\na. *The instructor made us swim.*\nb. *The instructor let us choose our boat.*\n\n**3.** Classe *make*, *let*, *have*, *get* selon leur sens (obliger, autoriser, faire faire, convaincre) et indique ce qui suit le complément pour chacun.","bareme":[{"critere":"Make et let + complément + base verbale au prétérit","points":5},{"critere":"Get + to (convaincre) et have + participe passé (faire réparer)","points":5},{"critere":"Passif de make avec to ; let remplacé par be allowed to","points":5},{"critere":"Tableau des quatre verbes juste","points":3},{"critere":"Correction de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n> *At the sailing camp, the instructor made us swim every morning, but he let us choose our boat. One day, I got my friend to try the kayak. My board was broken, so I had it repaired.* (*got it repaired* accepté)\n\n**2. Passif**\na. *We were made to swim.* — au passif, **to** réapparaît après *make*.\nb. *We were allowed to choose our boat.* — *let* n'a **pas de passif** : on emploie *be allowed to*.\n\n**3. Tableau**\n- **make** = obliger → complément + **base verbale** ;\n- **let** = autoriser → complément + **base verbale** ;\n- **have** = faire faire par un professionnel → complément + **participe passé** ;\n- **get** = convaincre → complément + **to** + verbe ; ou faire faire (familier) → complément + **participe passé**."}$exo$::jsonb),
  ('b9e46655-4ae2-5e9e-b036-051499ca3a40'::uuid, 1, 'traduction', $exo${"titre":"Les verbes à particule du brevet","consigne":"Complète chaque phrase avec le verbe qui convient, à la bonne forme.","enonce":"**Complète avec : give up, look after, look for, put on, find out, get up, run out of, grow up.**\n\n1. I ___ at 7 every morning.\n2. It's cold: ___ your coat!\n3. My grandma ___ my little sister on Wednesdays.\n4. I'm ___ my keys. Have you seen them?\n5. Don't ___! You can do it!\n6. We have ___ milk: can you buy some?\n7. I want to ___ the truth.\n8. She wants to be a vet when she ___.\n\n**Question :** pourquoi *look after* ne se traduit-il pas par « regarder après » ?","bareme":[{"critere":"Huit verbes justes et bien conjugués","points":16},{"critere":"Explication : le sens n'est pas la somme des deux mots","points":4}],"dureeMin":7,"corrige":"**Réponses**\n1. I **get up** at 7.\n2. **Put on** your coat! (*Put your coat on!*)\n3. My grandma **looks after** my little sister — 3e personne : -s.\n4. I'm **looking for** my keys.\n5. Don't **give up**!\n6. We have **run out of** milk.\n7. I want to **find out** the truth.\n8. when she **grows up**.\n\n**Explication**\nLe sens d'un verbe à particule ou prépositionnel n'est presque jamais la somme de ses deux mots : *look after* signifie « s'occuper de ». Ces verbes s'apprennent comme des **mots de vocabulaire entiers**."}$exo$::jsonb),
  ('b9e46655-4ae2-5e9e-b036-051499ca3a40'::uuid, 2, 'traduction', $exo${"titre":"La place du pronom","consigne":"Remplace le nom souligné par un pronom et réécris la phrase, puis réponds à la question 2.","enonce":"**1. Remplace le complément en gras par un pronom (it, them, her…).**\n\n1. Turn on **the light**.\n2. Take off **your shoes**.\n3. Look after **your sister**.\n4. Put on **your jacket**.\n5. Listen to **the teacher**. (*him*)\n6. Look up **these words** in the dictionary.\n\n**2.** Pour les phrases 1 et 3, dis s'il s'agit d'un verbe **à particule** ou d'un verbe **prépositionnel**, et explique le test qui permet de le savoir.","bareme":[{"critere":"Pronom placé avant la particule pour les verbes à particule","points":8},{"critere":"Pronom placé après la préposition pour les verbes prépositionnels","points":5},{"critere":"Nature des verbes 1 et 3 identifiée","points":3},{"critere":"Test de séparation expliqué","points":4}],"dureeMin":10,"corrige":"**1. Réponses**\n1. *Turn **it** on.* — jamais *turn on it*.\n2. *Take **them** off.*\n3. *Look after **her**.* — préposition : le pronom reste après.\n4. *Put **it** on.*\n5. *Listen to **him**.*\n6. *Look **them** up in the dictionary.*\n\nAvec un verbe **à particule**, un pronom se place **obligatoirement avant** la particule. Avec un verbe **prépositionnel**, le complément (nom ou pronom) est **toujours après** la préposition.\n\n**2. Le test**\n- *Turn on* : verbe **à particule** — on peut dire *turn the light on*.\n- *Look after* : verbe **prépositionnel** — on ne peut pas dire *look your sister after*.\nSi le complément peut se glisser entre le verbe et le petit mot, c'est une particule ; sinon, c'est une préposition."}$exo$::jsonb),
  ('b9e46655-4ae2-5e9e-b036-051499ca3a40'::uuid, 3, 'traduction', $exo${"titre":"Le premier voyage de Jules","consigne":"Lis le texte, traduis-le, puis réponds aux questions 2 et 3.","enonce":"> Jules got up at 5 a.m. He put on his jacket and looked for his passport. At the airport, he waited for his friends. The plane took off at 8. Jules was looking forward to seeing London. When he arrived, his phone had run out of battery, so he couldn't find out where his hotel was. But he didn't give up!\n\n1. Traduis le texte en français.\n2. Relève **deux verbes à particule** et **deux verbes prépositionnels**, et justifie ton classement avec le test du cours.\n3. Réécris deux phrases du texte en remplaçant le complément du verbe à particule par un pronom. Explique la règle de position.","bareme":[{"critere":"Traduction juste du sens de chaque verbe composé","points":7},{"critere":"Deux verbes à particule et deux prépositionnels bien classés","points":4},{"critere":"Classement justifié par le test de séparation","points":3},{"critere":"Deux réécritures avec pronom avant la particule, règle expliquée","points":4},{"critere":"Qualité du français","points":2}],"dureeMin":17,"corrige":"**1. Traduction modèle**\n> Jules s'est levé à 5 h. Il a mis sa veste et a cherché son passeport. À l'aéroport, il a attendu ses amis. L'avion a décollé à 8 h. Jules avait hâte de voir Londres. Quand il est arrivé, son téléphone n'avait plus de batterie, alors il n'a pas pu découvrir où était son hôtel. Mais il n'a pas abandonné !\n\nPoints de sens : *got up* = s'est levé ; *put on* = a mis (vêtement) ; *looked for* = a cherché ; *waited for* = a attendu ; *took off* = a décollé ; *looking forward to* = avait hâte de (suivi de -ING) ; *run out of* = être à court de ; *find out* = découvrir ; *give up* = abandonner.\n\n**2. Classement**\n- À particule : *put on*, *find out* (aussi *get up*, *take off*, *give up*) — on peut dire *put his jacket on*.\n- Prépositionnels : *look for*, *wait for* — impossible de dire *waited his friends for*.\n\n**3. Réécritures**\n- *He put it on.* — jamais *put on it*.\n- *He couldn't find it out.* (phrase possible, même si l'on garde plutôt le nom ici).\nRègle : avec un verbe à particule, un **pronom** se place **obligatoirement avant** la particule ; un nom peut se placer avant ou après."}$exo$::jsonb),
  ('b5079322-7f73-59e2-a08b-fb74fa97080d'::uuid, 1, 'traduction', $exo${"titre":"To + verbe ou -ING ?","consigne":"Mets le verbe entre parenthèses à la bonne forme (to + verbe, -ING ou base verbale).","enonce":"**Mets le verbe à la bonne forme.**\n\n1. I enjoy (read) comics.\n2. She decided (leave) early.\n3. You must (go) now.\n4. He left without (say) goodbye.\n5. I hope (see) you soon.\n6. We finished (work) at six.\n7. I avoid (eat) sugar.\n8. I'm looking forward to (meet) you.\n\n**Question :** pourquoi *look forward to* est-il suivi de -ING malgré son « to » ?","bareme":[{"critere":"Huit verbes à la bonne forme","points":16},{"critere":"Explication : to est ici une préposition","points":4}],"dureeMin":7,"corrige":"**Réponses**\n1. I enjoy **reading** — *enjoy* + -ING.\n2. She decided **to leave** — *decide* + to.\n3. You must **go** — après un modal : base verbale.\n4. without **saying** — après une préposition : -ING.\n5. I hope **to see** — *hope* + to.\n6. We finished **working** — *finish* + -ING.\n7. I avoid **eating** — *avoid* + -ING.\n8. looking forward to **meeting** — -ING.\n\n**Explication**\nDans *look forward to*, *to* n'est pas la marque de l'infinitif mais une **préposition** (comme dans *I look forward to the holidays*). Or, après une préposition, le verbe se met toujours en **-ING**."}$exo$::jsonb),
  ('b5079322-7f73-59e2-a08b-fb74fa97080d'::uuid, 2, 'traduction', $exo${"titre":"Stop, remember, try","consigne":"Traduis chaque paire de phrases en français, puis complète les phrases de la question 2.","enonce":"**1. Traduis en français et explique la différence de sens.**\n\na. *He stopped to smoke.* / *He stopped smoking.*\nb. *Remember to lock the door.* / *I remember locking the door.*\nc. *Try to open the window.* / *Try opening the window.*\n\n**2. Complète avec la bonne forme.**\n\n1. Grandpa is healthier since he stopped (drink) coffee.\n2. Did you remember (buy) bread?\n3. I went to the library (study).\n4. It's too hot. Try (open) the window, it might help.","bareme":[{"critere":"Trois paires traduites avec la bonne nuance","points":9},{"critere":"Quatre blancs justes","points":8},{"critere":"Infinitif de but avec to (et non for)","points":3}],"dureeMin":10,"corrige":"**1. Traductions**\na. « Il s'est arrêté **pour** fumer. » / « Il a **arrêté de** fumer. »\nb. « **Pense à** fermer la porte à clé. » (action à faire) / « Je **me souviens d'avoir** fermé la porte à clé. » (action déjà faite)\nc. « **Essaie d'**ouvrir la fenêtre. » (effort, peut-être difficile) / « Essaie **en** ouvrant la fenêtre, pour voir. » (tester une solution)\n\n**2. Réponses**\n1. since he stopped **drinking** coffee — il a arrêté d'en boire.\n2. Did you remember **to buy** bread? — penser à faire.\n3. I went to the library **to study** — infinitif de but ; jamais *for studying*.\n4. Try **opening** the window — essayer pour voir si ça aide."}$exo$::jsonb),
  ('b5079322-7f73-59e2-a08b-fb74fa97080d'::uuid, 3, 'traduction', $exo${"titre":"Le projet de Nina","consigne":"Traduis le texte en anglais, puis justifie quatre de tes choix.","enonce":"**1. Thème : traduis en anglais.**\n\n> Nina veut devenir pilote. Elle adore voyager et elle a appris à piloter l'an dernier. Elle est douée pour parler aux gens, mais elle déteste attendre. La semaine dernière, elle est allée à l'aéroport pour rencontrer un vrai pilote. Il lui a promis de l'aider. Elle a hâte de voler seule !\n\n*Aide : to fly = piloter / voler ; to become = devenir ; alone = seule ; she is good at = elle est douée pour.*\n\n**2.** Justifie la forme du verbe après : *want*, *good at*, *to meet* (pour rencontrer), *look forward to*.","bareme":[{"critere":"Verbes + to justes (want, learn, promise)","points":5},{"critere":"Verbes + -ING justes (love, hate, look forward to)","points":5},{"critere":"-ING après préposition et infinitif de but","points":3},{"critere":"Quatre justifications exactes","points":5},{"critere":"Correction générale de la langue","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n> *Nina wants to become a pilot. She loves travelling and she learnt to fly last year. She is good at talking to people, but she hates waiting. Last week, she went to the airport to meet a real pilot. He promised to help her. She is looking forward to flying alone!*\n(*learned* et *traveling* acceptés ; *loves to travel* accepté car *love* admet les deux, mais -ING est la forme du cours.)\n\n**2. Justifications**\n- *want* + **to** + verbe : *want* fait partie des verbes suivis de l'infinitif (comme decide, hope, promise, learn).\n- *good at* + **-ING** : *at* est une **préposition** ; après une préposition, toujours -ING.\n- *to meet* : **infinitif de but** (« pour rencontrer ») → *to* ou *in order to* ; jamais *for meeting*.\n- *look forward to* + **-ING** : *to* y est une préposition, pas la marque de l'infinitif."}$exo$::jsonb),
  ('fb2f1865-37c7-547f-83c3-77e39ae3badd'::uuid, 1, 'traduction', $exo${"titre":"Former les adverbes","consigne":"Donne l'adverbe correspondant à chaque adjectif, puis corrige la phrase fautive.","enonce":"**1. Donne l'adverbe.**\n\nslow · careful · happy · simple · good · fast · hard · late\n\n**2. Corrige :** *She speaks very good English and she sings good.*\n\n**3.** Que signifient *hardly* et *lately* ?","bareme":[{"critere":"Huit adverbes justes, irréguliers compris","points":12},{"critere":"Phrase corrigée (sings well)","points":4},{"critere":"Sens de hardly et lately","points":4}],"dureeMin":6,"corrige":"**1. Adverbes**\n- slow → **slowly**\n- careful → **carefully**\n- happy → **happily** (-y → -ily)\n- simple → **simply** (-le → -ly)\n- good → **well** (irrégulier)\n- fast → **fast** (identique)\n- hard → **hard** (identique)\n- late → **late** (identique)\n\n**2. Correction**\n*She speaks very good English and she sings **well**.* — *good English* est juste (adjectif devant un nom) ; mais pour modifier le verbe *sings*, il faut l'adverbe **well**.\n\n**3. Pièges**\n- *hardly* = **à peine** (pas « durement ») ;\n- *lately* = **récemment** (pas « tardivement »)."}$exo$::jsonb),
  ('fb2f1865-37c7-547f-83c3-77e39ae3badd'::uuid, 2, 'traduction', $exo${"titre":"Les habitudes de Farah","consigne":"Place l'adverbe entre parenthèses au bon endroit, puis réponds à la question 2.","enonce":"**1. Réécris chaque phrase avec l'adverbe à sa place.**\n\n1. Farah gets up early. (always)\n2. She is late. (never)\n3. She has been to Spain. (never)\n4. She plays tennis on Saturdays. (usually)\n5. She doesn't run fast. (enough → après l'adjectif / adverbe)\n6. She is tired after school. (very)\n\n**2.** Remets les compléments dans l'ordre habituel : *She sang (last night / at the concert / beautifully).* Donne la règle.","bareme":[{"critere":"Adverbes de fréquence placés avant le verbe lexical, après be ou l'auxiliaire","points":10},{"critere":"Enough après, very devant l'adjectif","points":4},{"critere":"Ordre manière, lieu, temps rétabli et règle donnée","points":6}],"dureeMin":10,"corrige":"**1. Réponses**\n1. *Farah always gets up early.* — avant le verbe lexical.\n2. *She is never late.* — après *be*.\n3. *She has never been to Spain.* — après l'auxiliaire.\n4. *She usually plays tennis on Saturdays.* — avant le verbe lexical.\n5. *She doesn't run fast enough.* — *enough* après l'adverbe / l'adjectif.\n6. *She is very tired after school.* — adverbe de degré devant l'adjectif.\n\n**2. Ordre**\n*She sang beautifully at the concert last night.* — ordre habituel en fin de phrase : **manière → lieu → temps**."}$exo$::jsonb),
  ('fb2f1865-37c7-547f-83c3-77e39ae3badd'::uuid, 3, 'traduction', $exo${"titre":"La critique de concert","consigne":"Lis le texte, corrige les fautes en justifiant, puis traduis les deux phrases de la question 3.","enonce":"> Last night, the band played very good. The singer sang loud the songs and the guitarist always was smiling. I could hard hear the drums, because I was at the back. The concert finished lately, at midnight. I have been to concerts often, but this one was really amazing!\n\n1. Le texte contient **six fautes** sur les adverbes. Relève-les et corrige-les.\n2. Justifie chaque correction par la règle du cours.\n3. Traduis : a) *I have hardly slept lately.* b) *She works hard and she is never late.*","bareme":[{"critere":"Six fautes relevées et corrigées","points":7},{"critere":"Justifications (irréguliers, place, sens de hardly / lately)","points":6},{"critere":"Traductions justes de hardly, lately, hard, late","points":5},{"critere":"Qualité de la rédaction","points":2}],"dureeMin":16,"corrige":"**1 et 2. Les six fautes**\n- *played very good* → **played very well** : l'adverbe de *good* est *well*.\n- *sang loud the songs* → **sang the songs loudly** (ou *loud*) : on n'intercale jamais un adverbe entre le verbe et son complément d'objet.\n- *always was smiling* → **was always smiling** : l'adverbe de fréquence se place **après** *be* / l'auxiliaire.\n- *could hard hear* → **could hardly hear** : « à peine » = *hardly* ; *hard* = dur.\n- *finished lately* → **finished late** : *late* reste identique ; *lately* signifie « récemment ».\n- *I have been to concerts often* → **I have often been to concerts** : fréquence entre l'auxiliaire et le participe passé.\n\n**3. Traductions**\na) « J'ai **à peine** dormi **ces derniers temps**. » (récemment)\nb) « Elle travaille **dur** et elle n'est **jamais en retard**. » — *hard* et *late* adverbes identiques à l'adjectif."}$exo$::jsonb),
  ('7b28d6ef-5f30-5b50-a1e4-50ce3f17773d'::uuid, 1, 'traduction', $exo${"titre":"Habituel ou en cours ?","consigne":"Mets le verbe au présent simple ou au présent en BE + -ING.","enonce":"**Mets le verbe à la bonne forme.**\n\n1. Look! It (rain).\n2. My brother (study) English every day.\n3. Water (boil) at 100 °C.\n4. Be quiet, I (do) my homework.\n5. She (not / like) fish.\n6. I (know) the answer.\n7. We (meet) Tom tonight at 8. (c'est organisé)\n8. He (watch) TV every evening.\n\n**Question :** pourquoi ne peut-on pas dire *I am knowing* ?","bareme":[{"critere":"Huit formes justes (temps, 3e personne, orthographe)","points":16},{"critere":"Explication des verbes d'état","points":4}],"dureeMin":7,"corrige":"**Réponses**\n1. It **is raining** — action en cours (*Look!*).\n2. My brother **studies** — habitude ; consonne + y → -ies.\n3. Water **boils** — vérité générale.\n4. I **am doing** — en cours.\n5. She **doesn't like** — présent simple, négation avec *doesn't*.\n6. I **know** — verbe d'état.\n7. We **are meeting** — projet organisé.\n8. He **watches** — habitude ; -ch → -es.\n\n**Explication**\n*Know* est un **verbe d'état** (comme like, love, want, need, understand, believe) : il n'accepte pas la forme en -ING. On dit *I know*, jamais *I am knowing*."}$exo$::jsonb),
  ('7b28d6ef-5f30-5b50-a1e4-50ce3f17773d'::uuid, 2, 'traduction', $exo${"titre":"La carte postale d'Ilan","consigne":"Conjugue les verbes entre parenthèses, puis justifie trois choix.","enonce":"> Dear Grandma,\n> I (1. write) to you from Edinburgh! I (2. stay) with my aunt this week. Every morning, she (3. go) to work by bike and I (4. visit) the city. Right now, it (5. rain) and my cousin (6. play) the piano. He (7. play) every day! Tonight we (8. have) dinner at a restaurant: my aunt booked a table. I (9. love) this city!\n> Ilan\n\n1. Conjugue les neuf verbes.\n2. Justifie les formes 2, 3 et 9.","bareme":[{"critere":"Formes en BE + -ING justes (en cours, temporaire, projet)","points":7},{"critere":"Présents simples justes, orthographe de la 3e personne","points":6},{"critere":"Verbe d'état love au présent simple","points":2},{"critere":"Trois justifications exactes","points":5}],"dureeMin":10,"corrige":"**1. Réponses**\n(1) **am writing** — en cours.\n(2) **am staying** — situation temporaire.\n(3) **goes** — habitude ; -o → -es.\n(4) **visit** — habitude.\n(5) **is raining** — en cours (*right now*).\n(6) **is playing** — en cours.\n(7) **plays** — habitude (*every day*).\n(8) **are having** — projet organisé.\n(9) **love** — verbe d'état.\n\n**2. Justifications**\n- (2) *this week* : une situation **temporaire** → BE + -ING.\n- (3) *every morning* : une **habitude** → présent simple, -es à la 3e personne.\n- (9) *love* est un **verbe d'état** : jamais à la forme en -ING."}$exo$::jsonb),
  ('7b28d6ef-5f30-5b50-a1e4-50ce3f17773d'::uuid, 3, 'traduction', $exo${"titre":"Le colocataire agaçant","consigne":"Traduis le texte en anglais, puis réponds à la question 2.","enonce":"**1. Thème : traduis en anglais.**\n\n> Mon frère aîné vit à Manchester. Il travaille dans une banque, mais ce mois-ci il travaille à Londres. D'habitude, il se lève à 7 h. En ce moment, il cherche un appartement. Son colocataire perd toujours ses clés, c'est énervant ! Samedi, nous prenons le train pour aller le voir : les billets sont achetés. Le train part à 9 h 15.\n\n*Aide : flatmate = colocataire ; flat = appartement ; to look for = chercher.*\n\n**2.** Pour cinq verbes de ta traduction, nomme le temps choisi et l'emploi du cours qui le justifie (habitude, état permanent, temporaire, en cours, projet organisé, programme fixe, agacement).","bareme":[{"critere":"Présent simple pour l'état permanent, l'habitude et l'horaire","points":5},{"critere":"BE + -ING pour le temporaire, l'action en cours et le projet organisé","points":5},{"critere":"Always + BE + -ING pour l'agacement","points":3},{"critere":"Cinq justifications exactes","points":5},{"critere":"Correction de la langue","points":2}],"dureeMin":17,"corrige":"**1. Traduction modèle**\n> *My older brother lives in Manchester. He works in a bank, but this month he is working in London. He usually gets up at 7. At the moment, he is looking for a flat. His flatmate is always losing his keys, it's annoying! On Saturday, we are taking the train to see him: the tickets are bought. The train leaves at 9.15.*\n\n**2. Justifications attendues**\n- *lives*, *works in a bank* : **état permanent** → présent simple.\n- *is working in London* (*this month*) : situation **temporaire** → BE + -ING.\n- *usually gets up* : **habitude** → présent simple.\n- *is looking for* (*at the moment*) : action **en cours** → BE + -ING.\n- *is always losing* : *always* + BE + -ING → **agacement**.\n- *are taking the train* : **projet organisé** (billets achetés) → BE + -ING.\n- *leaves at 9.15* : **programme fixe**, horaire → présent simple.\nCinq justifications suffisent."}$exo$::jsonb),
  ('8276dae0-32df-5f05-b2bc-df822d05522f'::uuid, 1, 'traduction', $exo${"titre":"Looks, norms and icons","consigne":"Réponds à chaque partie. Les traductions se font mot à mot ; les réponses de la partie 2 tiennent en une phrase en français.","enonce":"**1. Traduis en anglais.**\n\n1. l'estime de soi\n2. les canons de beauté\n3. se démarquer\n4. se conformer\n5. la tenue\n6. correspondre au stéréotype\n\n**2. Repères culturels.** Pour chaque repère, dis en une phrase ce qu'il montre sur l'apparence.\n\n7. Le concours Miss America (Atlantic City, 1921) et la manifestation de 1968.\n8. Le punk de Vivienne Westwood (années 1970).\n9. Les *Untitled Film Stills* de Cindy Sherman (1977-1980).","bareme":[{"critere":"Six traductions justes : self-esteem, beauty standards, to stand out, to conform, outfit, to fit the stereotype","points":12},{"critere":"Trois repères correctement expliqués (norme imposée et contestée, mode de contestation, stéréotypes mis en scène)","points":8}],"dureeMin":7,"corrige":"**1.**\n1. *self-esteem*\n2. *beauty standards*\n3. *to stand out*\n4. *to conform*\n5. *an outfit*\n6. *to fit the stereotype*\n(2 points par traduction ; l'oubli de *to* devant les verbes ne coûte qu'un demi-point.)\n\n**2.**\n7. Miss America est un *beauty pageant*, un concours qui **fixe une norme** de beauté et juge les femmes sur leur physique ; en 1968, des féministes manifestent devant le concours pour **dénoncer** cette norme.\n8. Le punk de Westwood montre qu'on peut **s'habiller pour contester** : la mode devient une forme de protestation contre la société.\n9. Cindy Sherman **se met en scène elle-même** dans des rôles de femmes **stéréotypés** : elle rend visibles les clichés imposés aux femmes par les images.\n(Environ 3 + 3 + 2 points ; toute formulation qui dit l'idée de norme / contestation / stéréotype est acceptée.)"}$exo$::jsonb),
  ('8276dae0-32df-5f05-b2bc-df822d05522f'::uuid, 2, 'traduction', $exo${"titre":"No filter today","consigne":"Lis le document (texte inventé pour le sujet), puis réponds en anglais aux questions 1 à 3.","enonce":"**Document — a post by Maddie, 16 (texte inventé)**\n\n> For two years, I never posted a picture without a filter. My skin had to look perfect, like the models in the ads. Every time I got a mean comment about my looks, my self-esteem went down. Today I'm posting a photo with no filter, no make-up, just my old green jumper. I don't want to fit the stereotype any more. Maybe I won't get many likes, but at least this is me.\n\n1. Who wrote this post and what has she decided to do today? (one or two sentences)\n2. Find in the text the English words for: **l'estime de soi** ; **l'apparence** ; **correspondre au stéréotype**.\n3. Does Maddie want to conform or to stand out? Answer in 40 to 60 words, quote the text once and link her choice to the body positivity movement.","bareme":[{"critere":"Question 1 : auteur (Maddie, 16) et décision (photo sans filtre ni maquillage)","points":5},{"critere":"Question 2 : self-esteem, looks, to fit the stereotype relevés dans le texte","points":6},{"critere":"Question 3 : réponse argumentée avec une citation et le lien avec body positivity","points":6},{"critere":"Correction de l'anglais (phrases complètes, temps, orthographe)","points":3}],"dureeMin":11,"corrige":"1. *The post was written by Maddie, a 16-year-old girl. Today she has decided to post a photo of herself with no filter and no make-up.*\n\n2. *self-esteem* ; *looks* (« my looks ») ; *to fit the stereotype* (« I don't want to fit the stereotype »).\n\n3. Réponse type : *Maddie no longer wants to conform to beauty standards. She writes: « I don't want to fit the stereotype any more. » By posting a natural photo, she stands out and accepts her body as it is. Her choice reflects the body positivity movement of the 2010s, which encourages people to accept all bodies on social media.*\n\nÉléments attendus : elle refuse de se conformer (*to conform*) et choisit de se montrer telle qu'elle est ; une citation exacte du texte ; le lien avec **body positivity** (accepter tous les corps sur les réseaux sociaux). On accepte « she wants to stand out » si l'élève explique qu'elle se démarque en refusant la norme."}$exo$::jsonb),
  ('8276dae0-32df-5f05-b2bc-df822d05522f'::uuid, 3, 'traduction', $exo${"titre":"Can fashion be a form of protest?","consigne":"Rédige en anglais un paragraphe argumenté de 120 à 150 mots. Appuie-toi sur au moins deux repères culturels du cours et sur les expressions d'argumentation étudiées.","enonce":"**Sujet.** *Can fashion be a form of protest?*\n\nTon paragraphe doit :\n\n1. présenter la question en une phrase ;\n2. donner **au moins deux exemples** tirés du cours (créateurs, artistes ou mouvements) et expliquer ce que chacun conteste ;\n3. nuancer avec *On the one hand… on the other hand…* : la mode peut aussi imposer une norme ;\n4. conclure par ton avis (*I'm convinced that… / I can't help thinking that…*).\n\nVocabulaire utile : *outfit, to stand out, to conform, beauty standards*.","bareme":[{"critere":"Deux repères du cours exacts et reliés à l'idée de contestation (Quant, Westwood, Bowie, Miss America 1968…)","points":6},{"critere":"Nuance : la mode peut aussi imposer une norme (On the one hand… on the other hand…)","points":4},{"critere":"Organisation : introduction, arguments reliés, avis personnel en conclusion","points":4},{"critere":"Vocabulaire du chapitre employé à bon escient (outfit, to stand out, to conform…)","points":3},{"critere":"Correction grammaticale et respect de la longueur (120-150 mots)","points":3}],"dureeMin":18,"corrige":"**Paragraphe modèle (environ 140 mots)** :\n\n*Can the clothes we wear be a way of fighting against society? On the one hand, fashion has often been a form of protest. In the 1960s, Mary Quant's miniskirt became the manifesto of a whole generation in London. In the 1970s, Vivienne Westwood's punk style used provocative outfits to reject conformity. David Bowie, with Ziggy Stardust in 1972, played with identities and gender and helped people stand out. On the other hand, fashion can also impose a single model: magazines and beauty pageants like Miss America fix beauty standards, and many teenagers feel they have to conform. In my opinion, fashion is a form of protest only when it is a free choice. I'm convinced that an outfit can say « no » as loudly as a demonstration.*\n\n**Ce que le correcteur vérifie** :\n- au moins **deux repères exacts** : Mary Quant et la minijupe (années 1960, manifeste d'une génération), le punk de Westwood (années 1970, s'habiller pour contester), Bowie / Ziggy Stardust (1972, jouer avec les identités et le genre), la manifestation féministe devant Miss America (1968) ;\n- une **nuance** : la mode peut aussi fixer une norme (concours, publicité, magazines) ;\n- une **conclusion** avec un avis introduit par une expression du cours ;\n- le vocabulaire du chapitre et une langue correcte. Une erreur de date ou d'attribution (ex. la minijupe attribuée à Westwood) fait perdre des points au critère 1."}$exo$::jsonb),
  ('df21aa72-719b-5a27-ae37-8fe4c3031612'::uuid, 1, 'traduction', $exo${"titre":"Family words and landmarks","consigne":"Réponds aux deux parties. En partie 2, une phrase courte en français suffit.","enonce":"**1. Traduis en anglais.**\n\n1. le frère ou la sœur\n2. la famille recomposée\n3. les personnes âgées\n4. hériter\n5. l'héritier\n6. le fossé des générations\n7. transmettre\n\n**2. Repères culturels.**\n\n8. Entre quelles années sont nés les *baby boomers* ?\n9. Que raconte *Bend It Like Beckham* (Gurinder Chadha, 2002) ?\n10. Quel est le rôle du *National Trust*, et quand a-t-il été fondé ?","bareme":[{"critere":"Sept traductions justes (sibling, blended family, the elderly, to inherit, heir, generation gap, to hand down)","points":12},{"critere":"Trois repères exacts (1946-1964 ; fille sikh qui veut jouer au football ; conserver maisons et paysages, 1895)","points":8}],"dureeMin":7,"corrige":"**1.**\n1. *a sibling*\n2. *a blended family*\n3. *the elderly* (avec l'article *the*)\n4. *to inherit*\n5. *an heir*\n6. *the generation gap*\n7. *to hand down*\n\n**2.**\n8. Les baby boomers sont nés entre **1946 et 1964**.\n9. Le film raconte l'histoire d'une **jeune fille sikh**, fille d'immigrés indiens en Angleterre, qui veut **jouer au football**, alors que ses parents veulent autre chose pour elle : elle vit entre deux cultures.\n10. Le National Trust est une association fondée en **1895** qui **conserve des maisons et des paysages pour les générations futures** : il protège un patrimoine transmis."}$exo$::jsonb),
  ('df21aa72-719b-5a27-ae37-8fe4c3031612'::uuid, 2, 'traduction', $exo${"titre":"Grandma Joan and Liam","consigne":"Lis le dialogue (texte inventé pour le sujet), puis réponds en anglais.","enonce":"**Document — a dialogue (texte inventé)**\n\n> **Grandma Joan:** When I was 25, I bought my first house in Leeds. It was small, but it was mine.\n> **Liam (19):** Grandma, I'm 19 and I share a flat with three friends. I will probably rent until I'm 35!\n> **Grandma Joan:** And you never stop talking about the climate…\n> **Liam:** Because it's our future! But I love your old recipes, and one day I want to hand them down to my own kids.\n\n1. What is the family link between Joan and Liam? Which generation does Liam belong to?\n2. Write **two sentences with *whereas*** comparing Joan's generation and Liam's (housing, climate).\n3. What does Liam want to inherit from his grandmother? Answer in one full sentence and explain why this example shows that the generation gap is not total.","bareme":[{"critere":"Question 1 : grandmother / grandson et Liam rattaché à la Gen Z (Joan : baby boomer accepté)","points":4},{"critere":"Question 2 : deux comparaisons justes construites avec whereas","points":8},{"critere":"Question 3 : les recettes, to hand down, et l'idée d'une transmission malgré le fossé","points":5},{"critere":"Correction de l'anglais","points":3}],"dureeMin":11,"corrige":"1. *Joan is Liam's grandmother; Liam is her grandson. Liam, who is 19, belongs to Gen Z* (on accepte aussi que Joan soit présentée comme une *baby boomer*).\n\n2. Exemples attendus :\n- *Joan bought a house when she was 25, whereas Liam will probably rent until he is 35.*\n- *Liam is very worried about the climate, whereas his grandmother does not seem to understand why.*\nChaque phrase : 4 points (comparaison juste d'après le texte + *whereas* bien placé entre deux propositions).\n\n3. *Liam wants to inherit his grandmother's old recipes, and he wants to hand them down to his own children.* Cela montre que le fossé des générations (*the generation gap*) n'est pas total : les deux générations s'opposent sur le logement et le climat, mais une partie du patrimoine **immatériel** (des recettes, des traditions) se transmet quand même."}$exo$::jsonb),
  ('df21aa72-719b-5a27-ae37-8fe4c3031612'::uuid, 3, 'traduction', $exo${"titre":"Between two cultures","consigne":"Rédige en anglais un paragraphe argumenté de 120 à 150 mots, en t'appuyant sur deux œuvres du cours.","enonce":"**Sujet.** *What do second-generation immigrants inherit from their parents?*\n\nTon paragraphe doit :\n\n1. définir en une phrase ce qu'est un enfant d'immigrés « de deuxième génération » (né dans le pays d'accueil) ;\n2. s'appuyer sur **deux œuvres du cours** : *Bend It Like Beckham* et *The Namesake* ;\n3. distinguer ce qui se transmet (langue, traditions, prénom…) et ce qui provoque des conflits ;\n4. employer au moins **trois mots** du vocabulaire du chapitre et une expression du cours (*Unlike their parents… / To some extent, I agree that…*).","bareme":[{"critere":"Définition juste de la deuxième génération","points":3},{"critere":"Les deux œuvres présentées avec exactitude (auteur ou réalisatrice, sujet)","points":6},{"critere":"Analyse : ce qui se transmet et ce qui oppose les générations","points":5},{"critere":"Vocabulaire du chapitre et expression d'argumentation du cours","points":3},{"critere":"Correction de la langue et longueur respectée","points":3}],"dureeMin":18,"corrige":"**Paragraphe modèle (environ 140 mots)** :\n\n*Second-generation immigrants are children born in the country where their parents settled. They often live between two cultures. In Bend It Like Beckham, directed by Gurinder Chadha in 2002, the heroine is a young Sikh girl in England who wants to play football, whereas her parents want something else for her. She inherits her family's traditions, but she also wants her own life. In The Namesake, written by Jhumpa Lahiri in 2003, the son of Bengali immigrants in the United States feels burdened by the name his parents gave him. Unlike their parents, these young people did not choose to leave a country: they were born in the new one. To some extent, I agree that they inherit a language, relatives and traditions, but they also inherit questions about who they are.*\n\n**Ce que le correcteur vérifie** :\n- la définition (nés dans le pays d'accueil de leurs parents) ;\n- *Bend It Like Beckham* : Gurinder Chadha, 2002, une fille sikh qui veut jouer au football contre l'avis de ses parents ; *The Namesake* : Jhumpa Lahiri, 2003, un fils d'immigrés bengalis aux États-Unis encombré par son prénom ;\n- ce qui se transmet (traditions, langue, prénom, famille) **et** ce qui crée des tensions (choix de vie) ;\n- trois mots du chapitre (*relatives, to inherit, generation gap, to hand down…*) et une expression du cours."}$exo$::jsonb),
  ('7c6c605c-72dc-58f6-ad1e-a0d14fbed7fd'::uuid, 1, 'traduction', $exo${"titre":"Facing the past: key facts","consigne":"Réponds en français aux questions de la partie 1 (une phrase chacune), puis traduis la partie 2 en anglais.","enonce":"**1. Repères.**\n\n1. Que désignent les *Stolen Generations* en Australie ?\n2. Qui a présenté les excuses officielles de l'État australien, et à quelle date ?\n3. Que s'est-il passé à Bristol le 7 juin 2020 ?\n4. Qui a présidé la Commission vérité et réconciliation d'Afrique du Sud (1996) ?\n\n**2. Traduis en anglais.**\n\n5. le patrimoine\n6. présenter ses excuses\n7. rendre hommage à\n8. les peuples autochtones\n9. déboulonner une statue","bareme":[{"critere":"Quatre repères exacts (enfants aborigènes retirés ; Kevin Rudd, 13 février 2008 ; statue de Colston ; Desmond Tutu)","points":10},{"critere":"Cinq traductions justes (heritage, to apologise, to pay tribute to, Indigenous peoples, to tear down a statue)","points":10}],"dureeMin":7,"corrige":"**1.**\n1. Les *Stolen Generations* sont les **enfants aborigènes retirés à leurs familles** en Australie, de la fin du XIXe siècle aux années 1970.\n2. Le Premier ministre **Kevin Rudd**, le **13 février 2008** (la *National Apology*).\n3. La **statue d'Edward Colston**, un marchand d'esclaves, a été **renversée et jetée dans le port** ; elle a ensuite été exposée au musée.\n4. **Desmond Tutu**.\n(2,5 points par réponse.)\n\n**2.**\n5. *heritage*\n6. *to apologise*\n7. *to pay tribute to*\n8. *Indigenous peoples*\n9. *to tear down a statue*\n(2 points par traduction.)"}$exo$::jsonb),
  ('7c6c605c-72dc-58f6-ad1e-a0d14fbed7fd'::uuid, 2, 'traduction', $exo${"titre":"The statue in Market Square","consigne":"Lis l'article (texte inventé pour le sujet ; la ville et le personnage sont fictifs), puis réponds en anglais.","enonce":"**Document — a local newspaper (texte inventé)**\n\n> In the small port of Hallbridge, a statue of Sir Thomas Wren, a rich 18th-century merchant, has stood in Market Square for 150 years. Last month, historians revealed that part of his fortune came from the slave trade. Some residents want the town council to tear the statue down. « We cannot pay tribute to a man like him », says Amara, 17. Others want to keep it: « It is part of our heritage. Let's add a sign that explains the truth », says Mr Hughes, a retired teacher.\n\n1. Why has the statue of Sir Thomas Wren become controversial? (one sentence)\n2. Sum up the two opinions in **one sentence** using *Some people argue that…, while others claim that…*\n3. Which real event studied in class does this situation remind you of? Give the place, the date and what happened to the statue afterwards.","bareme":[{"critere":"Question 1 : une partie de sa fortune vient de la traite des esclaves","points":4},{"critere":"Question 2 : les deux avis fidèlement résumés dans la structure demandée","points":7},{"critere":"Question 3 : Colston, Bristol, 7 juin 2020, statue exposée au musée","points":6},{"critere":"Correction de l'anglais","points":3}],"dureeMin":11,"corrige":"1. *The statue has become controversial because historians revealed that part of Sir Thomas Wren's fortune came from the slave trade.*\n\n2. *Some people argue that the town should tear the statue down because it pays tribute to a man who profited from slavery, while others claim that it is part of the town's heritage and should stay, with a sign explaining the truth.*\nLes deux avis doivent être présents : déboulonner (Amara) / garder avec une explication (Mr Hughes).\n\n3. *It reminds me of the statue of Edward Colston, a slave trader, which was torn down in Bristol on 7 June 2020 and thrown into the harbour. It was later displayed in a museum.*\nÉléments attendus : Colston, Bristol, 7 juin 2020, statue exposée ensuite au musée (lien possible avec la question : garder la trace du passé en l'expliquant)."}$exo$::jsonb),
  ('7c6c605c-72dc-58f6-ad1e-a0d14fbed7fd'::uuid, 3, 'traduction', $exo${"titre":"Can an apology repair the past?","consigne":"Rédige en anglais un paragraphe argumenté de 130 à 160 mots, en t'appuyant sur au moins trois repères du cours.","enonce":"**Sujet.** *Can an apology repair the past?*\n\nTon paragraphe doit :\n\n1. présenter la question ;\n2. s'appuyer sur **au moins trois repères** du cours, dont au moins un australien et un hors d'Australie (excuses officielles, commissions, décisions de justice, restitution d'un lieu…) ;\n3. montrer ce qu'une excuse **peut** faire et ce qu'elle **ne peut pas** faire ;\n4. employer *This event marked a turning point in…* et au moins trois mots du chapitre (*to apologise, reconciliation, legacy, Indigenous peoples…*) ;\n5. conclure par ton avis.","bareme":[{"critere":"Trois repères exacts et datés (Rudd 2008, Mabo 1992, Uluru 1985, commission sud-africaine 1996, commission canadienne 2008-2015…)","points":6},{"critere":"Analyse nuancée : ce qu'une excuse reconnaît, ce qu'elle n'efface pas, ce qui doit l'accompagner","points":6},{"critere":"Expression du cours (turning point) et vocabulaire du chapitre","points":3},{"critere":"Organisation et conclusion personnelle","points":2},{"critere":"Correction de la langue et longueur respectée","points":3}],"dureeMin":20,"corrige":"**Paragraphe modèle (environ 150 mots)** :\n\n*Can words heal the wounds of history? In 2008, the Australian Prime Minister Kevin Rudd apologised to the Stolen Generations, the Aboriginal children who had been taken from their families. This apology did not erase the past, but it acknowledged the suffering of thousands of families: this event marked a turning point in the relationship between the state and Indigenous peoples. However, an apology is not enough on its own. In 1992, the Mabo decision recognised Indigenous land rights, and in 1985 Uluru was returned to the Anangu: these were concrete acts. In South Africa, the Truth and Reconciliation Commission, chaired by Desmond Tutu from 1996, listened to both victims and perpetrators after apartheid. In my opinion, an apology cannot repair the past, but it can open the way to reconciliation if it is followed by actions that change the legacy of the past.*\n\n**Ce que le correcteur vérifie** :\n- trois repères exacts : National Apology de Kevin Rudd (13 février 2008) ; arrêt Mabo (1992, droits fonciers autochtones, rejet de la *terra nullius*) ; Uluru rendu aux Anangu (1985) ; Commission vérité et réconciliation (1996, Desmond Tutu) ; commission canadienne sur les *residential schools* (2008-2015) ;\n- l'idée qu'une excuse **reconnaît** la souffrance sans **effacer** le passé, et qu'elle prend son sens avec des actes (restitution, droits, écoute des victimes) ;\n- *This event marked a turning point in…* et le vocabulaire du chapitre ;\n- un avis personnel en conclusion."}$exo$::jsonb),
  ('69c95063-8975-5603-9f45-919a01de8058'::uuid, 1, 'traduction', $exo${"titre":"Protest and cities: the basics","consigne":"Traduis la partie 1 en anglais, puis associe chaque date de la partie 2 à l'événement qui lui correspond (réponds par exemple : 1834 → …).","enonce":"**1. Traduis en anglais.**\n\n1. le syndicat\n2. faire grève\n3. sensibiliser\n4. une manifestation\n5. l'étalement urbain\n6. la personne qui fait chaque jour le trajet domicile-travail\n\n**2. Associe chaque date à un événement.**\n\nDates : 1834 · 1863 · 1984-1985 · 2003 · 2009\n\nÉvénements (dans le désordre) : A. la grève des mineurs contre Margaret Thatcher — B. l'ouverture de la High Line à New York — C. la condamnation des Tolpuddle Martyrs — D. le premier métro du monde, à Londres — E. le péage urbain de Londres (*congestion charge*)","bareme":[{"critere":"Six traductions justes (trade union, to go on strike, to raise awareness, a demonstration, urban sprawl, commuter)","points":12},{"critere":"Cinq associations date / événement correctes","points":8}],"dureeMin":6,"corrige":"**1.**\n1. *a trade union*\n2. *to go on strike*\n3. *to raise awareness*\n4. *a demonstration*\n5. *urban sprawl*\n6. *a commuter*\n(2 points par traduction.)\n\n**2.**\n- 1834 → **C** : les Tolpuddle Martyrs, six ouvriers agricoles déportés pour avoir fondé un syndicat.\n- 1863 → **D** : le métro de Londres, premier chemin de fer souterrain du monde.\n- 1984-1985 → **A** : la grève des mineurs contre Margaret Thatcher.\n- 2003 → **E** : le péage urbain de Londres.\n- 2009 → **B** : la High Line, ancienne voie ferrée aérienne devenue jardin.\n(1,5 point par association, 2 points pour la dernière juste : total 8.)"}$exo$::jsonb),
  ('69c95063-8975-5603-9f45-919a01de8058'::uuid, 2, 'traduction', $exo${"titre":"Rethinking Milbrook","consigne":"Lis le document (texte inventé pour le sujet ; la ville est fictive), puis réponds en anglais.","enonce":"**Document — a leaflet from Milbrook town council (texte inventé)**\n\n> Every morning, 40,000 commuters drive into the centre of Milbrook. The traffic is terrible and the air is polluted. The council has two projects:\n> - **Project 1:** drivers will pay £10 a day to enter the city centre.\n> - **Project 2:** the old railway bridge above Station Road, closed since 1995, will become a garden with trees and benches.\n> Come and give your opinion at the town hall on Saturday!\n\n1. What are the two problems described at the beginning of the leaflet?\n2. For each project, name the **real example** studied in class that it copies (city, name, date).\n3. Write **two sentences** starting with *As a consequence,* to explain what each project could change.","bareme":[{"critere":"Question 1 : embouteillages dus aux commuters et pollution de l'air","points":4},{"critere":"Question 2 : congestion charge de Londres (2003) et High Line de New York (2009)","points":6},{"critere":"Question 3 : deux conséquences logiques introduites par As a consequence","points":7},{"critere":"Correction de l'anglais","points":3}],"dureeMin":11,"corrige":"1. *There are too many cars: 40,000 commuters drive into the city centre every morning, so the traffic is terrible. And the air is polluted.*\n\n2. *Project 1 copies London's congestion charge, introduced in 2003: drivers pay to enter the centre. Project 2 copies the High Line in New York (2009), an old elevated railway turned into a garden.*\n\n3. Exemples attendus :\n- *Project 1: fewer people will drive into the centre. As a consequence, there will be less traffic and less pollution.*\n- *Project 2: the old bridge will be useful again. As a consequence, people will have a green place to walk and relax in the city.*\nToute conséquence logique est acceptée (moins de gaz à effet de serre, plus de transports en commun, plus de nature en ville…) si elle est introduite par *As a consequence,* suivi d'une virgule."}$exo$::jsonb),
  ('69c95063-8975-5603-9f45-919a01de8058'::uuid, 3, 'traduction', $exo${"titre":"From trade unions to hashtags","consigne":"Rédige en anglais un paragraphe argumenté de 130 à 160 mots.","enonce":"**Sujet.** *From trade unions to hashtags: has protest changed?*\n\nTon paragraphe doit :\n\n1. comparer au moins **un exemple de mobilisation ancienne** (XIXe ou XXe siècle) et **un exemple de mobilisation récente** du cours, avec leurs dates ;\n2. montrer ce qui a changé (moyens, vitesse, nombre de personnes, risques) et ce qui reste identique (le but) ;\n3. employer *Nowadays, more and more people…*, *This shows that…* et *It remains to be seen whether…* ;\n4. utiliser au moins trois mots du chapitre (*trade union, to go on strike, to raise awareness, a demonstration*).","bareme":[{"critere":"Un exemple ancien et un exemple récent exacts et datés","points":6},{"critere":"Comparaison : ce qui change et ce qui demeure","points":5},{"critere":"Les trois expressions du cours employées correctement","points":3},{"critere":"Vocabulaire du chapitre","points":3},{"critere":"Correction de la langue et longueur respectée","points":3}],"dureeMin":18,"corrige":"**Paragraphe modèle (environ 150 mots)** :\n\n*In 1834, six farm workers from Tolpuddle were deported because they had formed a trade union. Joining a union was dangerous, and protest was slow and local. In 1984-1985, British miners went on strike against Margaret Thatcher's government; the strike marked the decline of the trade unions. Nowadays, more and more people protest online. The expression « Me Too », first used by Tarana Burke in 2006, became a worldwide movement in 2017, and #BlackLivesMatter, born in 2013, mobilised millions of people in 2020. This shows that social networks can raise awareness in a few hours. However, the goal has not changed: people still fight for their rights, and they still organise demonstrations in the streets. Protest has not disappeared: it has moved online. It remains to be seen whether a hashtag can change laws as deeply as a union did.*\n\n**Ce que le correcteur vérifie** :\n- un exemple ancien exact (Tolpuddle 1834, grève des mineurs 1984-1985 contre Thatcher) et un exemple récent exact (#MeToo 2017, expression de Tarana Burke dès 2006 ; #BlackLivesMatter 2013 puis 2020) ;\n- ce qui change (réseaux sociaux, rapidité, ampleur, moins de risques) et ce qui reste (défendre ses droits) ;\n- les trois expressions demandées et le vocabulaire du chapitre."}$exo$::jsonb),
  ('88ee4f8d-d674-51fe-8e9a-63141c33224d'::uuid, 1, 'traduction', $exo${"titre":"Old stories, key words","consigne":"Traduis la partie 1 en anglais, puis réponds en français à la partie 2 (une phrase par question).","enonce":"**1. Traduis en anglais.**\n\n1. l'intrigue\n2. raconter à nouveau\n3. une adaptation\n4. une nouvelle version d'un film\n5. l'art de raconter\n6. le Far West\n\n**2. Repères.**\n\n7. De quelle pièce de Shakespeare *West Side Story* est-il une réécriture, et où l'histoire est-elle transposée ?\n8. En quoi *Brokeback Mountain* (Ang Lee, 2005) remet-il en question le mythe du cowboy ?\n9. Que disait à l'origine le panneau Hollywood installé en 1923 ?","bareme":[{"critere":"Six traductions justes (plot, to retell, an adaptation, a remake, storytelling, the Wild West)","points":12},{"critere":"Trois repères exacts (Romeo and Juliet / New York ; deux cowboys amoureux ; Hollywoodland)","points":8}],"dureeMin":7,"corrige":"**1.**\n1. *the plot*\n2. *to retell*\n3. *an adaptation*\n4. *a remake*\n5. *storytelling*\n6. *the Wild West*\n(2 points par traduction.)\n\n**2.**\n7. *West Side Story* réécrit ***Romeo and Juliet*** (vers 1595) : Vérone devient le **New York des gangs**, avec les Jets et les Sharks.\n8. Le film montre **deux cowboys amoureux** : il bouscule l'image virile et héroïque du cowboy du western classique.\n9. Le panneau disait **« Hollywoodland »**.\n(3 + 3 + 2 points.)"}$exo$::jsonb),
  ('88ee4f8d-d674-51fe-8e9a-63141c33224d'::uuid, 2, 'traduction', $exo${"titre":"Robyn of the city","consigne":"Lis le résumé (texte inventé pour le sujet : cette série n'existe pas), puis réponds en anglais.","enonce":"**Document — the pitch of a new TV series (texte inventé)**\n\n> *Robyn* is a modern retelling of the legend of Robin Hood. Robyn is a 17-year-old girl who lives in a poor area of London. She is a brilliant hacker. At night, she takes money from the online accounts of dishonest billionaires and sends it to families who cannot pay their rent. Her friends, a group of teenagers from her estate, help her.\n\n1. Which legendary hero is this series based on, and what did he do in the legend?\n2. Give **one element** that is faithful to the original and **two elements** that depart from it. Use *faithful to* and *departs from*.\n3. In two sentences, explain how the director updates the story (*The director updates the story by…*).","bareme":[{"critere":"Question 1 : Robin Hood, qui vole aux riches pour donner aux pauvres","points":4},{"critere":"Question 2 : un élément fidèle et deux éléments modifiés, justes d'après le texte","points":8},{"critere":"Question 3 : la modernisation expliquée avec l'expression du cours","points":5},{"critere":"Correction de l'anglais","points":3}],"dureeMin":11,"corrige":"1. *The series is based on Robin Hood, a legendary hero who stole from the rich to give to the poor.*\n\n2. **Fidèle** (*faithful to the original*) : comme Robin Hood, elle prend l'argent des riches pour le donner aux pauvres (on accepte aussi : elle agit en justicière, hors la loi, avec l'aide d'une bande).\n**S'éloigne** (*departs from the original*) : le héros est une **fille** de 17 ans ; l'histoire se passe à **Londres aujourd'hui**, pas dans une forêt médiévale ; elle vole **en ligne**, comme hacker, pas avec un arc.\nExemple : *The series is faithful to the original because Robyn takes money from the rich and gives it to the poor. However, it departs from the original because the hero is a teenage girl and she steals online.*\n\n3. *The director updates the story by turning Robin Hood into a teenage girl hacker in modern London. The legend becomes a reflection on inequality today: the enemies are dishonest billionaires, and the victims are families who cannot pay their rent.*"}$exo$::jsonb),
  ('88ee4f8d-d674-51fe-8e9a-63141c33224d'::uuid, 3, 'traduction', $exo${"titre":"Why do we keep retelling the same stories?","consigne":"Rédige en anglais un paragraphe argumenté de 130 à 160 mots, appuyé sur au moins deux réécritures étudiées en cours.","enonce":"**Sujet.** *Why do we keep retelling the same stories?*\n\nTon paragraphe doit :\n\n1. s'appuyer sur **deux réécritures** du cours au moins (une œuvre d'origine et sa nouvelle version, ou deux visages d'un même mythe) ;\n2. montrer pour chacune ce qui est gardé et ce qui change, et quel changement de société elle reflète ;\n3. employer *This version is more faithful to / departs from the original* et *What strikes me is that…* ;\n4. conclure par ton avis sur la question.","bareme":[{"critere":"Deux réécritures du cours présentées avec exactitude (titres, dates, auteurs)","points":6},{"critere":"Analyse : ce qui est gardé, ce qui change, lien avec les changements de la société","points":6},{"critere":"Expressions du cours et vocabulaire du chapitre (plot, remake, to retell, myth…)","points":3},{"critere":"Organisation et avis personnel","points":2},{"critere":"Correction de la langue et longueur respectée","points":3}],"dureeMin":18,"corrige":"**Paragraphe modèle (environ 150 mots)** :\n\n*Old stories never die: they are retold again and again. West Side Story, a musical of 1957 adapted into films in 1961 and 2021, keeps the plot of Shakespeare's Romeo and Juliet: two young lovers from rival groups. But this version departs from the original, because the Montagues and the Capulets become two New York gangs, the Jets and the Sharks. The story becomes a reflection on racism and immigration. The myth of the cowboy has changed too. In Stagecoach, directed by John Ford in 1939, John Wayne is a heroic, manly cowboy. What strikes me is that Brokeback Mountain, by Ang Lee in 2005, shows two cowboys in love and questions this image of virility. In my opinion, we keep retelling the same stories because they are familiar, and each generation uses them to talk about its own problems.*\n\n**Ce que le correcteur vérifie** :\n- deux réécritures exactes (Roméo et Juliette → *West Side Story* ; le cowboy de Buffalo Bill ou de *Stagecoach* → *Brokeback Mountain* ; Robin Hood ou le roi Arthur sans cesse réinventés) ;\n- pour chacune, ce qui est gardé / changé et le **changement de société** reflété (racisme, immigration, image de la virilité…) ;\n- les expressions du cours et un avis en conclusion."}$exo$::jsonb),
  ('192f7341-41ff-5999-bcad-d340db74e803'::uuid, 1, 'traduction', $exo${"titre":"From Empire to Commonwealth: the timeline","consigne":"Associe chaque date à son étape (réponds par exemple : 1926 → …), puis réponds en français aux questions 6 et 7.","enonce":"**1. Associe chaque date à une étape.**\n\nDates : 1926 · 1947 · 1949 · 1957 · 2022\n\nÉtapes (dans le désordre) : A. l'indépendance du Ghana de Kwame Nkrumah — B. la déclaration de Londres : on peut être membre en étant une république — C. l'adhésion du Gabon et du Togo — D. la déclaration Balfour, qui reconnaît les dominions égaux au Royaume-Uni — E. l'indépendance de l'Inde et la partition avec le Pakistan\n\n**2. Questions.**\n\n6. Combien d'États compte le Commonwealth, et qui en est le chef symbolique depuis 2022 ?\n7. Qu'est-ce qu'un *Commonwealth realm* ? Donne deux exemples.","bareme":[{"critere":"Cinq associations date / étape correctes","points":10},{"critere":"Question 6 : 56 États et Charles III","points":4},{"critere":"Question 7 : définition du realm et deux exemples justes","points":6}],"dureeMin":7,"corrige":"**1.**\n- 1926 → **D** : déclaration Balfour.\n- 1947 → **E** : indépendance de l'Inde (15 août 1947) et partition avec le Pakistan.\n- 1949 → **B** : déclaration de Londres ; le mot « British » disparaît du nom.\n- 1957 → **A** : le Ghana, première colonie d'Afrique subsaharienne indépendante.\n- 2022 → **C** : le Gabon et le Togo, jamais colonisés par Londres, adhèrent.\n(2 points par association.)\n\n**2.**\n6. Le Commonwealth compte **56 États** membres ; son chef symbolique est le souverain britannique, **Charles III**, depuis 2022.\n7. Un *Commonwealth realm* est un pays membre qui a **gardé le souverain britannique comme chef d'État** (une quinzaine). Exemples : le **Canada**, l'**Australie**, la **Jamaïque**."}$exo$::jsonb),
  ('192f7341-41ff-5999-bcad-d340db74e803'::uuid, 2, 'traduction', $exo${"titre":"Right or wrong about the Commonwealth?","consigne":"Lis la fiche, puis, pour chaque affirmation de Tyler, dis en anglais si elle est juste ou fausse et corrige-la ou justifie-la en une phrase à l'aide de la fiche.","enonce":"**Fiche — the Commonwealth in facts**\n\n- 1931: the Statute of Westminster gives the dominions legislative independence.\n- 1949: the London Declaration — a republic can be a member.\n- 1961: apartheid South Africa leaves the Commonwealth; it comes back in 1994.\n- 2022: Gabon and Togo, never colonised by Britain, join.\n- Today: 56 member states, most of them republics; about fifteen realms (Canada, Australia, Jamaica…) keep the British king as head of state.\n- The Commonwealth Games: every four years; the first ones in Hamilton, Canada, in 1930.\n\nVoici ce qu'a écrit Tyler, un élève de ta classe, dans son exposé :\n\n1. *All the members of the Commonwealth were once British colonies.*\n2. *To be a member of the Commonwealth, a country must keep the British king as head of state.*\n3. *South Africa has always been a member of the Commonwealth.*\n4. *The Commonwealth Games take place every four years, and the first ones were held in Hamilton, Canada, in 1930.*\n5. *The Statute of Westminster (1931) gave the dominions legislative independence.*\n\nPour chaque phrase : écris *This is right* ou *This is wrong*, puis une phrase de justification.","bareme":[{"critere":"Phrase 1 : fausse, Gabon et Togo (2022) jamais colonisés","points":4},{"critere":"Phrase 2 : fausse, déclaration de Londres 1949 et majorité de républiques","points":4},{"critere":"Phrase 3 : fausse, départ en 1961 (apartheid) et retour en 1994","points":4},{"critere":"Phrases 4 et 5 : justes, justifiées","points":5},{"critere":"Correction de l'anglais","points":3}],"dureeMin":11,"corrige":"1. *This is wrong. Gabon and Togo joined the Commonwealth in 2022, although they were never colonised by Britain.*\n2. *This is wrong. Since the London Declaration of 1949, a republic can be a member, and today most member states are republics. Only about fifteen realms, like Canada or Jamaica, have kept the king as head of state.*\n3. *This is wrong. Apartheid South Africa left the Commonwealth in 1961 and came back in 1994.*\n4. *This is right. The Commonwealth Games are held every four years; the first ones took place in Hamilton, Canada, in 1930.*\n5. *This is right. In 1931, the Statute of Westminster gave the dominions legislative independence.*\n\nChaque phrase : 1 point pour le jugement juste, le reste pour la justification appuyée sur un fait exact du cours."}$exo$::jsonb),
  ('192f7341-41ff-5999-bcad-d340db74e803'::uuid, 3, 'traduction', $exo${"titre":"Why do former colonies stay?","consigne":"Rédige en anglais un paragraphe argumenté de 130 à 160 mots.","enonce":"**Sujet.** *The Commonwealth is a legacy of the British Empire. Why do former colonies choose to stay in it?*\n\nTon paragraphe doit :\n\n1. rappeler en deux ou trois étapes datées comment l'Empire est devenu le Commonwealth ;\n2. expliquer comment fonctionne le Commonwealth aujourd'hui (membres, chef, sommets, jeux) ;\n3. donner au moins **deux raisons** de rester membre ;\n4. employer *It is a legacy of the British Empire, yet…* et *What unites these countries is…*, ainsi que trois mots du chapitre (*to gain independence, decolonisation, member state, the Crown…*).","bareme":[{"critere":"Étapes datées exactes de l'Empire au Commonwealth","points":5},{"critere":"Fonctionnement juste (56 États libres et égaux, chef symbolique, CHOGM, Games)","points":4},{"critere":"Deux raisons de rester, cohérentes avec le cours (adhésion volontaire, commerce, éducation, sport…)","points":5},{"critere":"Expressions demandées et vocabulaire du chapitre","points":3},{"critere":"Correction de la langue et longueur respectée","points":3}],"dureeMin":18,"corrige":"**Paragraphe modèle (environ 150 mots)** :\n\n*The British Empire was the largest empire in history, but it broke up in a few decades. In 1926, the Balfour Declaration recognised the dominions as equal to Britain, and in 1947 India gained independence. In 1949, the London Declaration allowed republics to become members, and « British » disappeared from the name. Decolonisation went on, with Ghana in 1957. Today, the Commonwealth has 56 free and equal member states. Charles III is its symbolic head, leaders meet at the CHOGM about every two years, and the Commonwealth Games take place every four years. It is a legacy of the British Empire, yet membership is voluntary: countries stay for trade, education and sport, not out of loyalty to the Crown. Some countries, like Gabon and Togo in 2022, even joined without having been British colonies. What unites these countries is a shared language and the choice to cooperate.*\n\n**Ce que le correcteur vérifie** :\n- des étapes datées exactes (1926 Balfour, 1931 Westminster, 1947 Inde, 1949 déclaration de Londres, 1957 Ghana) ;\n- le fonctionnement (56 États libres et égaux, chef symbolique, CHOGM, Commonwealth Games) ;\n- au moins deux raisons de rester, dont l'idée d'**adhésion volontaire** ;\n- les deux expressions imposées et le vocabulaire du chapitre."}$exo$::jsonb),
  ('c7692654-4488-5d4b-aec4-c66465709bbf'::uuid, 1, 'traduction', $exo${"titre":"Commonwealth writers","consigne":"Complète le tableau en recopiant pour chaque œuvre l'auteur, le pays et la date, puis réponds en français à la question 6.","enonce":"**1. Complète : auteur, pays, date.**\n\n1. *Things Fall Apart*\n2. *Midnight's Children*\n3. *The God of Small Things*\n4. *Half of a Yellow Sun*\n5. *Long Walk to Freedom*\n\nAuteurs (dans le désordre) : Arundhati Roy · Nelson Mandela · Chinua Achebe · Chimamanda Ngozi Adichie · Salman Rushdie\n\n**2. Question.**\n\n6. Que veut dire l'expression *the Empire writes back* à propos de la littérature postcoloniale ?","bareme":[{"critere":"Cinq œuvres associées au bon auteur","points":8},{"critere":"Pays et dates exacts","points":7},{"critere":"Explication de the Empire writes back","points":5}],"dureeMin":8,"corrige":"**1.**\n1. *Things Fall Apart* — **Chinua Achebe**, Nigeria, **1958**.\n2. *Midnight's Children* — **Salman Rushdie**, Inde, **1981** (Booker Prize).\n3. *The God of Small Things* — **Arundhati Roy**, Inde, **1997** (Booker Prize).\n4. *Half of a Yellow Sun* — **Chimamanda Ngozi Adichie**, Nigeria, **2006**.\n5. *Long Walk to Freedom* — **Nelson Mandela**, Afrique du Sud, **1994**.\n(Auteur : 1,6 point chacun ; pays et date : 1,4 point chacun, arrondi au total.)\n\n**2.**\n6. La littérature postcoloniale « répond » à l'Empire : des écrivains des anciennes colonies écrivent **en anglais, la langue du colonisateur**, pour raconter l'histoire **du point de vue des colonisés**."}$exo$::jsonb),
  ('c7692654-4488-5d4b-aec4-c66465709bbf'::uuid, 2, 'traduction', $exo${"titre":"The British legacy","consigne":"Lis le document (texte inventé pour le sujet), puis réponds en anglais.","enonce":"**Document — Priya's blog, a student in Chennai, India (texte inventé)**\n\n> At home I speak Tamil with my grandparents, but at school and at university everything is in English. On Saturdays I play cricket with my cousins. My brother is studying law, and his teachers often talk about decisions made by judges a long time ago. Last month, our class watched a debate in Parliament: the Prime Minister answered questions from the leader of the opposition.\n\n1. Find in the text **four elements** of the British heritage shared by Commonwealth countries, and name each one with the words of the course.\n2. Which other language does Priya speak, and what does this show about English in the Commonwealth?\n3. In two sentences, explain what the *Commonwealth Charter* (2013) adds to this common heritage.","bareme":[{"critere":"Question 1 : langue anglaise, cricket, common law, système de Westminster, repérés et nommés","points":8},{"critere":"Question 2 : le tamoul ; l'anglais langue commune à côté des langues nationales","points":4},{"critere":"Question 3 : valeurs communes (démocratie, droits humains, État de droit)","points":5},{"critere":"Correction de l'anglais","points":3}],"dureeMin":12,"corrige":"1. Quatre éléments :\n- *The English language*: everything is in English at school and university.\n- *Sport*: she plays **cricket**.\n- *The common law*: her brother studies a law based on decisions made by judges.\n- *The Westminster system*: a Parliament, a Prime Minister and an official opposition.\n(2 points par élément repéré et nommé.)\n\n2. *Priya also speaks Tamil with her grandparents. This shows that English is the common language of the Commonwealth, but it is often used alongside national languages.*\n\n3. *The Commonwealth Charter, adopted in 2013, lists the values shared by all the members: democracy, human rights and the rule of law. These values are what unites countries that have neither the same religion, nor the same political system, nor the same continent.*"}$exo$::jsonb),
  ('c7692654-4488-5d4b-aec4-c66465709bbf'::uuid, 3, 'traduction', $exo${"titre":"Writing back in the Empire's language","consigne":"Rédige en anglais un paragraphe argumenté de 130 à 160 mots.","enonce":"**Sujet.** *Why did writers from former colonies choose to write in English to tell their own story?*\n\nTon paragraphe doit :\n\n1. expliquer ce qu'est la littérature **postcoloniale** et l'expression *the Empire writes back* ;\n2. présenter **deux œuvres** du cours, de deux pays différents, en disant ce qu'elles racontent ;\n3. analyser le paradoxe : écrire dans la langue du colonisateur pour raconter l'histoire des colonisés ;\n4. employer *Through this novel, the author gives a voice to…* et *Despite their differences, …*.","bareme":[{"critere":"Définition juste de la littérature postcoloniale et de the Empire writes back","points":4},{"critere":"Deux œuvres exactes de deux pays différents, avec leur sujet","points":6},{"critere":"Analyse du paradoxe de la langue","points":4},{"critere":"Expressions imposées et vocabulaire du chapitre (novelist, postcolonial, to shape an identity…)","points":3},{"critere":"Correction de la langue et longueur respectée","points":3}],"dureeMin":18,"corrige":"**Paragraphe modèle (environ 150 mots)** :\n\n*English was the language of the colonisers, but many writers from former colonies took it and used it to tell their own story. This is called postcolonial literature: the Empire writes back, because the colonised answer the Empire and tell history from their point of view. In Things Fall Apart (1958), the Nigerian novelist Chinua Achebe shows an Igbo society shaken by the arrival of the colonisers. Through this novel, the author gives a voice to the people who had no voice in the Empire's books. In Midnight's Children (1981), the Indian writer Salman Rushdie tells the story of children born at midnight on the day of India's independence. Despite their differences, these two novels turn the Empire's language into a tool to rewrite history. In my view, writing in English also allowed them to be read all over the world and to shape a new identity.*\n\n**Ce que le correcteur vérifie** :\n- la définition (répondre à l'Empire, raconter du point de vue des colonisés) ;\n- deux œuvres exactes de deux pays (Achebe, Nigeria, 1958 ; Rushdie ou Roy, Inde ; Adichie, Nigeria, 2006 ; Mandela, Afrique du Sud, 1994) et leur sujet ;\n- le paradoxe : la langue du colonisateur devient un outil pour réécrire l'histoire (et toucher un public mondial, argument accepté) ;\n- les deux expressions imposées."}$exo$::jsonb),
  ('90a049c5-9e96-5aec-9d98-dc55c26b72fb'::uuid, 1, 'traduction', $exo${"titre":"Myself, yourself, themselves","consigne":"Complète chaque phrase avec le pronom réfléchi qui convient.","enonce":"Complète avec *myself, yourself, himself, herself, itself, ourselves, yourselves* ou *themselves*.\n\n1. She introduced ___ to the new teacher.\n2. We really enjoyed ___ at the party.\n3. Be careful with that knife, Tom! You'll cut ___.\n4. The children looked at ___ in the mirror.\n5. I did all my homework ___, without any help.\n6. The cat is washing ___.\n7. Enjoy ___, kids!\n8. My grandfather lives by ___ in a small flat.","bareme":[{"critere":"Pronoms justes dans les phrases 1 à 4 (herself, ourselves, yourself, themselves)","points":10},{"critere":"Pronoms justes dans les phrases 5 à 8 (myself, itself, yourselves, himself)","points":10}],"dureeMin":6,"corrige":"1. *She introduced **herself** to the new teacher.* — sujet *she*.\n2. *We really enjoyed **ourselves** at the party.* — sujet *we*.\n3. *You'll cut **yourself**.* — on parle à une seule personne (Tom) : *yourself*.\n4. *The children looked at **themselves** in the mirror.* — chacun se regarde lui-même dans le miroir.\n5. *I did all my homework **myself**.* — emphase : moi-même, sans aide.\n6. *The cat is washing **itself**.* — sujet *it*.\n7. *Enjoy **yourselves**, kids!* — on parle à plusieurs personnes : pluriel *-selves*.\n8. *My grandfather lives by **himself**.* — *by + réfléchi* = tout seul.\n\n2,5 points par phrase. Toute forme fautive (*theirselves, ourself, hisself*) est comptée fausse."}$exo$::jsonb),
  ('90a049c5-9e96-5aec-9d98-dc55c26b72fb'::uuid, 2, 'traduction', $exo${"titre":"Each other or themselves?","consigne":"Partie 1 : choisis la bonne forme. Partie 2 : traduis en anglais en évitant les réfléchis inutiles.","enonce":"**1. Choisis : réfléchi, réciproque (*each other*) ou rien (Ø).**\n\n1. Lucy and Sam are best friends: they phone ___ every evening.\n2. After the match, the players were proud of ___.\n3. I woke ___ up at six this morning.\n4. The two sisters helped ___ with their homework.\n\n**2. Traduis en anglais.**\n\n5. Je me suis levé à sept heures.\n6. Dépêche-toi !\n7. Je ne me souviens pas de son nom.\n8. Ils se sont rencontrés à Londres.","bareme":[{"critere":"Partie 1 : each other, themselves, Ø, each other bien choisis","points":8},{"critere":"Partie 2 : verbes anglais sans réfléchi (get up, hurry, remember, meet)","points":8},{"critere":"Temps et orthographe corrects dans les traductions","points":4}],"dureeMin":10,"corrige":"**1.**\n1. *they phone **each other*** — action de l'un vers l'autre : réciproque.\n2. *proud of **themselves*** — chacun est fier de soi : réfléchi.\n3. *I woke **Ø** up* — *to wake up* n'a pas de réfléchi : **aucun pronom** (*I woke up*).\n4. *helped **each other*** — l'une aide l'autre : réciproque (*one another* accepté).\n\n**2.**\n5. *I got up at seven.* — jamais *I got myself up*.\n6. *Hurry (up)!*\n7. *I don't remember his name.* (ou *her name*) — *to remember*, sans réfléchi.\n8. *They met in London.* — *to meet* suffit : le sens réciproque est déjà dans le verbe.\n\nCritère 3 : prétérit juste en 5 et 8 (*got, met*), négation *don't* en 7, orthographe."}$exo$::jsonb),
  ('90a049c5-9e96-5aec-9d98-dc55c26b72fb'::uuid, 3, 'traduction', $exo${"titre":"The morning of the trip","consigne":"Traduis le texte en anglais (thème). Pour chaque « se » du texte français, demande-toi : réfléchi, réciproque, emphase… ou rien ?","enonce":"**Thème : traduis en anglais.**\n\n> Le jour du voyage, Emma s'est réveillée tôt. Elle s'est habillée et elle s'est dépêchée. Dans le bus, elle a retrouvé Léo : ils se sont souri et ils se sont assis ensemble. Léo s'est regardé dans la vitre et s'est trouvé ridicule avec son chapeau. « Je l'ai acheté moi-même ! » a-t-il dit. Pendant tout le voyage, ils se sont raconté des histoires et ils se sont bien amusés. Le soir, Emma se sentait bien.\n\n*Aide : retrouver quelqu'un = to meet ; sourire = to smile ; la vitre = the window ; un chapeau = a hat ; ridicule = silly.*","bareme":[{"critere":"Verbes pronominaux français rendus sans réfléchi (woke up, got dressed, hurried, sat down, felt good)","points":6},{"critere":"Réciproques justes (smiled at each other, told each other stories)","points":4},{"critere":"Réfléchis justes (looked at himself, enjoyed themselves) et emphase (I bought it myself)","points":6},{"critere":"Temps du passé, ordre des mots et orthographe","points":4}],"dureeMin":18,"corrige":"**Traduction modèle** :\n\n*On the day of the trip, Emma woke up early. She got dressed and hurried. On the bus, she met Léo: they smiled at each other and sat down together. Léo looked at himself in the window and thought he looked silly with his hat. « I bought it myself! » he said. During the whole trip, they told each other stories and really enjoyed themselves. In the evening, Emma felt good.*\n\n**Les « se » un par un** :\n- *s'est réveillée* → *woke up* ; *s'est habillée* → *got dressed* ; *s'est dépêchée* → *hurried* ; *se sont assis* → *sat down* ; *se sentait bien* → *felt good* : **aucun réfléchi** en anglais.\n- *se sont souri* → *smiled at each other* ; *se sont raconté des histoires* → *told each other stories* : l'action va de l'un à l'autre, **réciproque**.\n- *s'est regardé dans la vitre* → *looked at himself* : l'action revient sur le sujet, **réfléchi**.\n- *se sont bien amusés* → *enjoyed themselves* : *to enjoy* exige un complément, **réfléchi** pluriel.\n- *moi-même* → *myself* : **emphase**.\n- *s'est trouvé ridicule* : *thought he looked silly* (ou *found himself silly*, accepté).\n\nToute forme *got himself dressed, woke herself up, sat themselves* fait perdre des points au critère 1."}$exo$::jsonb),
  ('3ddb3dce-98f7-588b-9831-f891db437837'::uuid, 1, 'traduction', $exo${"titre":"A teacup, a ten-minute break","consigne":"Traduis chaque expression en anglais en utilisant un nom composé ou un adjectif composé.","enonce":"Traduis en anglais.\n\n1. une tasse à thé\n2. une voiture de sport\n3. un magasin de chaussures\n4. un livre pour enfants\n5. une pause de dix minutes\n6. une fille de dix ans\n7. un homme aux cheveux noirs\n8. un gâteau fait maison\n\n*Rappel : le nom principal se place toujours à droite.*","bareme":[{"critere":"Noms composés justes, nom principal à droite (a teacup, a sports car, a shoe shop, a children's book)","points":10},{"critere":"Adjectifs composés justes, avec traits d'union et sans -s (ten-minute, ten-year-old, black-haired, home-made)","points":10}],"dureeMin":7,"corrige":"1. *a teacup* (une tasse, faite pour le thé — pas *a cup of tea*, qui est le thé lui-même).\n2. *a sports car*.\n3. *a shoe shop* — le premier nom reste au singulier : pas *a shoes shop*.\n4. *a children's book* — génitif de catégorie.\n5. *a ten-minute break* — adjectif composé : pas de -s à *minute*.\n6. *a ten-year-old girl* — pas *ten-years-old*.\n7. *a black-haired man* — adjectif + nom + -ed.\n8. *a home-made cake* — nom + participe passé.\n\n2,5 points par expression. Un trait d'union oublié dans 5 à 8 retire 1 point ; un -s ajouté ou un ordre inversé (*a car sports*) rend l'expression fausse."}$exo$::jsonb),
  ('3ddb3dce-98f7-588b-9831-f891db437837'::uuid, 2, 'traduction', $exo${"titre":"What is it exactly?","consigne":"Partie 1 : explique en français ce que désigne chaque expression. Partie 2 : réécris chaque groupe en un adjectif composé.","enonce":"**1. Que désigne exactement… ?** (une phrase en français)\n\n1. *a teacup* / *a cup of tea*\n2. *a car park*\n3. *the Home Secretary*\n4. *a day's work*\n\n**2. Réécris avec un adjectif composé placé devant le nom.**\n\n5. a walk of two hours → a ___ walk\n6. a man who has blue eyes → a ___ man\n7. a story that breaks your heart → a ___ story\n8. a singer who is well known → a ___ singer\n9. a building of twenty floors → a ___ building","bareme":[{"critere":"Partie 1 : sens justes, en identifiant le nom principal à droite","points":8},{"critere":"Partie 2 : cinq adjectifs composés bien formés (tirets, singulier)","points":10},{"critere":"Orthographe et précision","points":2}],"dureeMin":11,"corrige":"**1.**\n1. *a teacup* est **une tasse** (à thé), vide ou pleine ; *a cup of tea* est **le thé** contenu dans la tasse.\n2. *a car park* est **un parc** (pour voitures) : un parking.\n3. *the Home Secretary* est **un ministre** : le ministre de l'Intérieur.\n4. *a day's work* est **du travail** : une journée de travail (génitif de catégorie).\n(2 points chacun.)\n\n**2.**\n5. *a two-hour walk*\n6. *a blue-eyed man*\n7. *a heart-breaking story*\n8. *a well-known singer*\n9. *a twenty-storey building* (*twenty-floor* accepté ; *twenty-story* en anglais américain)\n(2 points chacun ; *two-hours* ou l'oubli du trait d'union est compté faux.)"}$exo$::jsonb),
  ('3ddb3dce-98f7-588b-9831-f891db437837'::uuid, 3, 'traduction', $exo${"titre":"The waiting room","consigne":"Partie 1 : corrige les fautes et explique chaque correction. Partie 2 : traduis le texte en anglais en utilisant le plus possible de noms et d'adjectifs composés.","enonce":"**1. Chaque groupe contient une faute. Corrige-la et explique-la en une phrase.**\n\n1. a shoes shop\n2. a ten-years-old boy\n3. a break ten-minute\n4. a shop of shoes (pour dire « un magasin de chaussures »)\n\n**2. Thème : traduis en anglais.**\n\n> Dans une salle d'attente, une femme aux cheveux roux lit un roman policier. À côté d'elle, un garçon de douze ans aux yeux bleus mange un gâteau fait maison. Sur la table, il y a une paire de chaussures de sport et une tasse à café vide. Une voix annonce : « Le train de huit heures a un retard de vingt minutes. »\n\n*Aide : roux = red ; un roman policier = a detective novel ; un retard = a delay.*","bareme":[{"critere":"Partie 1 : quatre corrections justes et expliquées","points":6},{"critere":"Noms composés justes dans la traduction (waiting room, detective novel, coffee cup, sports shoes, pair of shoes)","points":5},{"critere":"Adjectifs composés justes (red-haired, twelve-year-old, blue-eyed, home-made, twenty-minute)","points":6},{"critere":"Correction générale de la traduction (temps, ordre des mots)","points":3}],"dureeMin":18,"corrige":"**1.**\n1. *a **shoe** shop* — le premier nom joue le rôle d'un adjectif : il reste au singulier.\n2. *a ten-**year**-old boy* — même règle dans l'adjectif composé : pas de -s.\n3. *a **ten-minute break*** — l'adjectif composé se place **devant** le nom.\n4. *a **shoe shop*** — *noun of noun* sert pour une quantité ou un contenu (*a pair of shoes*), pas pour un magasin.\n(1,5 point chacune.)\n\n**2. Traduction modèle** :\n*In a waiting room, a red-haired woman is reading a detective novel. Next to her, a blue-eyed twelve-year-old boy is eating a home-made cake. On the table, there is a pair of sports shoes and an empty coffee cup. A voice announces: « The eight o'clock train has a twenty-minute delay. »*\n\nPoints de contrôle :\n- *waiting room*, *detective novel*, *coffee cup* (une tasse à café, pas *a cup of coffee* puisqu'elle est vide), *a pair of sports shoes* (quantité → *of*) ;\n- *red-haired*, *blue-eyed*, *twelve-year-old*, *home-made*, *twenty-minute* (*is twenty minutes late* accepté) ;\n- présent en *-ing* pour la description accepté, présent simple toléré."}$exo$::jsonb),
  ('dd99cc2c-56ad-5449-b28f-86b0725d794d'::uuid, 1, 'traduction', $exo${"titre":"Most or most of?","consigne":"Complète chaque phrase avec most, most of, none of, both of ou half of.","enonce":"Complète chaque phrase.\n\n1. ___ people like music. (la plupart des gens, en général)\n2. ___ my friends play video games. (la plupart de mes amis)\n3. ___ us agree with the teacher. (la plupart d'entre nous)\n4. ___ them came to the party. (aucun d'eux)\n5. ___ us are from Leeds. (nous deux)\n6. ___ the class went on the trip. (la moitié de la classe)\n7. ___ teenagers use social media. (la plupart des ados, en général)\n8. ___ the students in my school wear a uniform. (la plupart des élèves de mon lycée)","bareme":[{"critere":"Most sans of devant un nom sans déterminant (phrases 1 et 7)","points":5},{"critere":"Most of devant un groupe précis ou un pronom (phrases 2, 3, 8)","points":8},{"critere":"None of, both of, half of justes (phrases 4, 5, 6)","points":7}],"dureeMin":7,"corrige":"1. ***Most** people like music.* — nom sans déterminant, sens général : pas de *of*.\n2. ***Most of** my friends play video games.* — possessif *my* : *of*.\n3. ***Most of** us agree with the teacher.* — pronom : *of*, et pronom complément *us*.\n4. ***None of** them came to the party.* — la négation est déjà dans *none*.\n5. ***Both of** us are from Leeds.* — devant un pronom, *of* est obligatoire.\n6. ***Half of** the class went on the trip.* (*Half the class* accepté.)\n7. ***Most** teenagers use social media.* — sens général : pas de *of*.\n8. ***Most of** the students in my school wear a uniform.* — groupe précis (*the… in my school*) : *of*.\n\nCritère 1 : 2,5 points par phrase (1 et 7). Critère 2 : 3 + 3 + 2 points (2, 3, 8). Critère 3 : 3 + 2 + 2 points (4, 5, 6). *The most* est toujours compté faux."}$exo$::jsonb),
  ('dd99cc2c-56ad-5449-b28f-86b0725d794d'::uuid, 2, 'traduction', $exo${"titre":"Our class survey","consigne":"Lis les résultats d'une enquête faite dans une classe (données inventées pour le sujet), puis écris une phrase en anglais par ligne du tableau, avec le partitif qui convient.","enonce":"**Enquête dans la classe de 2de B (30 élèves, données inventées)**\n\n| Question | Réponses « oui » |\n| Do you have a smartphone? | 30 élèves sur 30 |\n| Do you drink tea at breakfast? | 0 élève sur 30 |\n| Do you play a sport? | 15 élèves sur 30 |\n| Do you read before sleeping? | 4 élèves sur 30 |\n| Do you walk to school? | 24 élèves sur 30 |\n\n1. à 5. Écris une phrase par ligne en commençant par *All of us / None of us / Half of us / A few of us / Most of us* (utilise chaque début une fois).\n6. Écris une phrase **au sens général** sur les adolescents britanniques avec *most* (sans *of*).\n7. Traduis : « Les deux professeurs de la classe viennent à pied. »","bareme":[{"critere":"Partitifs bien choisis selon les chiffres (all, none, half, a few, most)","points":8},{"critere":"Of + pronom complément (of us) et verbe correct après none (sans not)","points":5},{"critere":"Phrase au sens général sans of","points":3},{"critere":"Traduction avec both (of) the teachers","points":4}],"dureeMin":11,"corrige":"1. *All of us have a smartphone.* (30/30)\n2. *None of us drinks / drink tea at breakfast.* (0/30) — **pas de *not*** : *none* porte déjà la négation. Singulier (soutenu) ou pluriel (courant) acceptés.\n3. *Half of us play a sport.* (15/30)\n4. *A few of us read before sleeping.* (4/30)\n5. *Most of us walk to school.* (24/30)\n\n6. Exemple : *Most British teenagers use a smartphone.* ou *Most teenagers play video games.* — nom sans déterminant → **pas de *of*** (*Most of teenagers* est faux).\n\n7. *Both (of) the teachers walk to school.* ou *Both teachers of the class walk to school.* — devant *the*, *of* est facultatif.\n\nToute phrase du type *None of us don't…* ou *Most of we…* perd les points du critère 2."}$exo$::jsonb),
  ('dd99cc2c-56ad-5449-b28f-86b0725d794d'::uuid, 3, 'traduction', $exo${"titre":"Tea, coffee and cousins","consigne":"Partie 1 : corrige les phrases fautives en expliquant la règle. Partie 2 : traduis le texte en anglais.","enonce":"**1. Chaque phrase contient une faute. Corrige-la et explique la règle.**\n\n1. The most of us agree.\n2. Most of people like holidays.\n3. None of them didn't come.\n4. Most of the cake were eaten.\n5. Both us are tired.\n\n**2. Thème : traduis en anglais.**\n\n> La plupart des Britanniques boivent du thé, mais aucun de mes cousins n'aime ça. La moitié d'entre nous préfère le café. Tous mes amis ont goûté le gâteau de ma grand-mère, et la plupart du gâteau a été mangée en dix minutes. Mes deux parents étaient contents.\n\n*Aide : goûter = to taste.*","bareme":[{"critere":"Partie 1 : cinq corrections justes","points":5},{"critere":"Partie 1 : règles correctement expliquées","points":5},{"critere":"Partie 2 : most sans of / avec of selon le cas, none of sans not, half of us","points":5},{"critere":"Partie 2 : all (of), both (of), accord du verbe (most of the cake was)","points":5}],"dureeMin":18,"corrige":"**1.**\n1. ***Most of us** agree.* — on ne met jamais *the* devant *most* dans ce sens.\n2. ***Most people** like holidays.* — nom sans déterminant, sens général : pas de *of*.\n3. ***None of them came.*** — la négation est déjà dans *none* : pas de *not*.\n4. *Most of the cake **was** eaten.* — le verbe s'accorde avec *cake*, indénombrable singulier.\n5. ***Both of us** are tired.* — devant un pronom, *of* est obligatoire.\n\n**2. Traduction modèle** :\n*Most British people drink tea, but none of my cousins likes it. Half of us prefer coffee. All (of) my friends tasted my grandmother's cake, and most of the cake was eaten in ten minutes. Both (of) my parents were happy.*\n\nPoints de contrôle : *Most British people* (général, sans *of*) ; *none of my cousins likes / like it* (sans *doesn't*) ; *half of us* ; *all (of) my friends* ; *most of the cake **was*** ; *both (of) my parents **were***."}$exo$::jsonb),
  ('0e158099-eb14-5afa-811b-414fd78f899e'::uuid, 1, 'traduction', $exo${"titre":"Yes, I do. No, she isn't.","consigne":"Réponds à chaque question par une réponse courte, positive ou négative selon l'indication.","enonce":"Réponds par une réponse courte (sujet + auxiliaire).\n\n1. Do you like tea? (+)\n2. Is she French? (−)\n3. Have they finished? (+)\n4. Can he swim? (−)\n5. Did you see the film? (+)\n6. Are you ready? (+)\n7. Will your parents come? (−)\n8. Does your sister play the piano? (+)","bareme":[{"critere":"Auxiliaire repris de la question dans les huit réponses","points":12},{"critere":"Sujet en pronom, pas de contraction dans les réponses positives, négations bien formées","points":8}],"dureeMin":6,"corrige":"1. *Yes, I do.*\n2. *No, she isn't.*\n3. *Yes, they have.*\n4. *No, he can't.*\n5. *Yes, I did.*\n6. *Yes, I am.* — jamais *Yes, I'm* : on ne contracte pas dans une réponse affirmative (*Yes, we are* accepté si l'élève comprend *you* comme un pluriel).\n7. *No, they won't.*\n8. *Yes, she does.*\n\nCritère 1 : 1,5 point par réponse avec le bon auxiliaire. Critère 2 : le sujet repris en pronom (*she, they*), aucune contraction dans les réponses positives, négations justes (*isn't, can't, won't*)."}$exo$::jsonb),
  ('0e158099-eb14-5afa-811b-414fd78f899e'::uuid, 2, 'traduction', $exo${"titre":"Me too, me neither, not me","consigne":"Réagis à chaque phrase comme demandé, en choisissant l'auxiliaire d'après la phrase de départ.","enonce":"**1. Réagis par « moi aussi » ou « moi non plus » (So / Neither + auxiliaire + I).**\n\n1. I love pizza.\n2. I can't swim.\n3. She has been to London. (réponds pour *I*)\n4. He went home early. (réponds pour *I*)\n5. They won't come. (réponds pour *we*)\n\n**2. Exprime ton désaccord (« Moi, si » / « Moi, non »).**\n\n6. I don't like horror films.\n7. I can drive.\n\n**3. Traduis.**\n\n8. Je crois que oui.\n9. J'espère que non.\n10. « Je viens de déménager à Leeds. — Ah bon ? »","bareme":[{"critere":"Partie 1 : So / Neither bien choisi et auxiliaire juste, inversion respectée","points":10},{"critere":"Partie 2 : désaccord avec sujet devant l'auxiliaire et polarité inversée","points":4},{"critere":"Partie 3 : I think so, I hope not, Have you?","points":6}],"dureeMin":10,"corrige":"**1.**\n1. *So do I.*\n2. *Neither can I.* (*Nor can I* accepté)\n3. *So have I.* — auxiliaire *has* → *have*.\n4. *So did I.* — prétérit *went* → *did*.\n5. *Neither will we.* — *won't* → *will*.\n(2 points chacune : 1 pour *So / Neither*, 1 pour l'auxiliaire et l'ordre auxiliaire + sujet.)\n\n**2.**\n6. *Oh, I do.* (Moi, si.)\n7. *Oh, I can't.* (Moi, non.)\n(2 points chacune.)\n\n**3.**\n8. *I think so.*\n9. *I hope not.* — pas *I don't hope so*.\n10. *I've just moved to Leeds. — Have you?*\n(2 points chacune.)"}$exo$::jsonb),
  ('0e158099-eb14-5afa-811b-414fd78f899e'::uuid, 3, 'traduction', $exo${"titre":"A conversation at the bus stop","consigne":"Complète le dialogue avec des réponses courtes, des reprises et des réactions, puis écris la suite en 4 répliques en employant au moins trois structures différentes du chapitre.","enonce":"**1. Complète le dialogue.**\n\n> **Zoe:** I'm going to the concert on Saturday.\n> **Ben:** (1) ___ ! (Moi aussi !) Is your brother coming?\n> **Zoe:** (2) ___ . (Non.) He doesn't like rock music.\n> **Ben:** (3) ___ . (Ma sœur non plus.) Did you buy your ticket online?\n> **Zoe:** (4) ___ . (Oui.) Will it rain on Saturday?\n> **Ben:** (5) ___ . (J'espère que non.) I've already been to that stadium twice.\n> **Zoe:** (6) ___ ? (Ah bon ?) I haven't. I can't wait!\n> **Ben:** (7) ___ . (Moi non plus, je ne peux pas attendre.)\n\n**2. Écris la suite du dialogue (4 répliques)** en employant au moins trois de ces structures : une réponse courte, *So… / Neither…*, un désaccord (*I do / I can't…*), *I think so / I'm afraid not*.","bareme":[{"critere":"Partie 1 : sept réponses justes, auxiliaire tiré de la phrase de départ","points":11},{"critere":"Partie 2 : trois structures différentes employées correctement","points":6},{"critere":"Partie 2 : cohérence du dialogue et correction de la langue","points":3}],"dureeMin":16,"corrige":"**1.**\n1. *So am I!* — la phrase de départ est au présent en *-ing* avec *am* : l'auxiliaire est *be*.\n2. *No, he isn't.* — la question est *Is your brother coming?*\n3. *Neither does my sister.* — *doesn't like* → *does*.\n4. *Yes, I did.*\n5. *I hope not.*\n6. *Have you?* — la réaction reprend l'auxiliaire de *I've already been* (*have*) et le sujet *you*.\n7. *Neither can I.* — attention : *I can't wait* est négatif, on répond donc par *Neither* (pas *So can I*).\n(Environ 1,5 point par réponse.)\n\n**2. Exemple de suite** :\n> **Zoe:** Do you know the band's new song?\n> **Ben:** Yes, I do. I love it.\n> **Zoe:** Oh, I don't. I prefer their old songs. Will your parents drive us home?\n> **Ben:** I'm afraid not. They're working that night.\n\nOn y trouve une réponse courte (*Yes, I do*), un désaccord (*Oh, I don't*) et *I'm afraid not*. Toute suite cohérente avec trois structures justes obtient les 6 points du critère 2."}$exo$::jsonb),
  ('3e702b92-f09f-59c2-8b97-33fe9de085e6'::uuid, 1, 'traduction', $exo${"titre":"Signposts for your ideas","consigne":"Classe les connecteurs selon leur rôle, puis complète les phrases.","enonce":"**1. Classe ces connecteurs dans le bon rôle** (ordonner, ajouter, illustrer, conséquence, opposer, conclure).\n\n*moreover · for instance · therefore · however · to sum up · first of all · as a result · on the other hand*\n\n**2. Complète chaque phrase avec un connecteur de la liste :** *so · however · such as · moreover*.\n\n1. It was raining, ___ we stayed at home.\n2. Cycling is good for your health. ___, it does not pollute.\n3. I love sports ___ rugby and tennis.\n4. The bus is cheap. ___, it is very slow.","bareme":[{"critere":"Huit connecteurs classés dans le bon rôle","points":12},{"critere":"Quatre phrases complétées correctement","points":8}],"dureeMin":7,"corrige":"**1.**\n- Ordonner : *first of all*\n- Ajouter : *moreover*\n- Illustrer : *for instance*\n- Conséquence : *therefore*, *as a result*\n- Opposer : *however*, *on the other hand*\n- Conclure : *to sum up*\n(1,5 point par connecteur bien classé.)\n\n**2.**\n1. *It was raining, **so** we stayed at home.* — conséquence, dans la même phrase.\n2. *Cycling is good for your health. **Moreover**, it does not pollute.* — on ajoute un argument dans le même sens.\n3. *I love sports **such as** rugby and tennis.* — exemple, sans virgule après.\n4. *The bus is cheap. **However**, it is very slow.* — opposition.\n(2 points par phrase.)"}$exo$::jsonb),
  ('3e702b92-f09f-59c2-8b97-33fe9de085e6'::uuid, 2, 'traduction', $exo${"titre":"Mind the false friends","consigne":"Le paragraphe suivant, écrit par un élève, contient cinq erreurs de connecteurs. Relève-les, corrige-les et explique chaque correction en français.","enonce":"**Paragraphe de Jules :**\n\n> In a first time, I would like to talk about school uniforms. Uniforms are practical. However, they are cheaper than fashionable clothes. Moreover, some students find them ugly. Actually, more and more schools in France are testing them. At last, I think uniforms are a good idea, because all students look equal.\n\n1. Relève et corrige les **cinq** connecteurs mal employés.\n2. Explique chaque erreur en une phrase.\n3. Recopie le paragraphe corrigé.","bareme":[{"critere":"Cinq erreurs repérées","points":5},{"critere":"Cinq corrections justes","points":5},{"critere":"Explications justes (calque, sens opposé, faux ami, soulagement)","points":6},{"critere":"Paragraphe corrigé cohérent et ponctué","points":4}],"dureeMin":12,"corrige":"1. et 2. Les cinq erreurs :\n- *In a first time* → ***First (of all)*** : calque du français « dans un premier temps ».\n- *However, they are cheaper…* → ***Moreover*** (ou *Besides, In addition, What is more*) : « moins cher » est un deuxième avantage, qui va dans le même sens que « pratique » ; *however* oppose, il fallait ajouter.\n- *Moreover, some students find them ugly* → ***However*** (ou *On the other hand*) : cette idée s'oppose aux avantages ; *moreover* ajoute, il n'oppose pas.\n- *Actually, more and more schools…* → ***Nowadays / Currently*** : *actually* veut dire « en fait », pas « actuellement ».\n- *At last* → ***Finally / To conclude / To sum up*** : *at last* exprime le soulagement (« enfin ! »), pas le dernier point.\n\n3. Paragraphe corrigé :\n*First of all, I would like to talk about school uniforms. Uniforms are practical. Moreover, they are cheaper than fashionable clothes. However, some students find them ugly. Nowadays, more and more schools in France are testing them. To conclude, I think uniforms are a good idea, because all students look equal.*\n\nVirgule après chaque connecteur en tête de phrase."}$exo$::jsonb),
  ('3e702b92-f09f-59c2-8b97-33fe9de085e6'::uuid, 3, 'traduction', $exo${"titre":"Should phones be banned at school?","consigne":"Rédige en anglais un paragraphe argumenté de 120 à 150 mots. Souligne (ou écris en gras) chaque connecteur utilisé.","enonce":"**Sujet.** *Should mobile phones be banned at school?*\n\nTon paragraphe doit :\n\n1. annoncer ton premier argument avec un connecteur d'**ordre** ;\n2. ajouter un deuxième argument dans le même sens (**ajout**) ;\n3. illustrer un argument par un **exemple** ;\n4. présenter une objection (**opposition**) ;\n5. en tirer une **conséquence** ;\n6. **conclure**.\n\nChaque rôle doit être rempli par un connecteur différent, bien ponctué. Évite les pièges du cours (*in a first time, at last, actually*).","bareme":[{"critere":"Les six rôles remplis par des connecteurs adaptés et différents","points":8},{"critere":"Ponctuation juste (virgule après les connecteurs en tête de phrase, pas après such as)","points":3},{"critere":"Argumentation cohérente : les connecteurs disent vraiment le lien entre les idées","points":5},{"critere":"Correction de la langue et longueur respectée","points":4}],"dureeMin":16,"corrige":"**Paragraphe modèle (environ 130 mots)** :\n\n*Should mobile phones be banned at school? **First of all**, phones distract students: a notification is enough to stop them listening to the teacher. **Moreover**, they can be used for cyberbullying during breaks. **For instance**, a student can take a photo of a classmate and post it without permission. **However**, phones can also be useful, **such as** when a teacher asks students to look up a word or to check a fact. **As a result**, a total ban may not be the best solution. **To sum up**, I think phones should be switched off in class, but students should be allowed to use them for specific activities.*\n\n**Ce que le correcteur vérifie** :\n- ordre (*first of all / first*), ajout (*moreover, besides, in addition, what is more*), exemple (*for instance, for example, such as*), opposition (*however, yet, on the other hand*), conséquence (*so, therefore, consequently, as a result*), conclusion (*to conclude, all in all, to sum up*) ;\n- chaque connecteur dit **vraiment** le lien (un *moreover* devant une objection est une faute) ;\n- ponctuation et longueur. L'avis de l'élève (pour ou contre) est libre."}$exo$::jsonb),
  ('fa8b32a2-289b-507d-98f7-01a8496951e8'::uuid, 1, 'traduction', $exo${"titre":"In, on or at?","consigne":"Complète chaque phrase avec in, on ou at.","enonce":"Complète avec *in*, *on* ou *at*.\n\n1. She lives ___ London.\n2. The picture is ___ the wall.\n3. I'll meet you ___ the station.\n4. My keys are ___ the kitchen.\n5. They live ___ 10 Downing Street.\n6. We were ___ the bus when it started to rain.\n7. There was nobody ___ home.\n8. He is sitting ___ a taxi.\n9. My flat is ___ the second floor.\n10. Wait for me ___ the corner.","bareme":[{"critere":"In pour un volume, une ville, un espace fermé (1, 4, 8)","points":6},{"critere":"On pour une surface, un étage, un bus (2, 6, 9)","points":6},{"critere":"At pour un point, une adresse précise, un lieu d'activité (3, 5, 7, 10)","points":8}],"dureeMin":6,"corrige":"1. *in London* — ville.\n2. *on the wall* — surface.\n3. *at the station* — point de rendez-vous.\n4. *in the kitchen* — espace fermé.\n5. *at 10 Downing Street* — adresse avec numéro.\n6. *on the bus* — transport dans lequel on peut se déplacer.\n7. *at home*.\n8. *in a taxi* — on y est assis, enfermé.\n9. *on the second floor* — étage.\n10. *at the corner* — point.\n\n2 points par réponse."}$exo$::jsonb),
  ('fa8b32a2-289b-507d-98f7-01a8496951e8'::uuid, 2, 'traduction', $exo${"titre":"Finding your way in town","consigne":"Partie 1 : corrige les phrases fausses. Partie 2 : traduis en anglais.","enonce":"**1. Chaque phrase contient une faute de préposition. Corrige-la.**\n\n1. We arrived to London at midnight.\n2. I go to home after school.\n3. She walked in the room and sat down.\n4. We arrived at France last week.\n\n**2. Traduis en anglais.**\n\n5. La banque est en face de l'église.\n6. Le café est entre la poste et la gare.\n7. Il habite non loin d'ici, juste au coin.\n8. Le musée est tout au bout de la rue.\n9. Mes amis sont là-bas, devant le cinéma.","bareme":[{"critere":"Partie 1 : quatre corrections justes (arrive in / go home / into / arrive in)","points":8},{"critere":"Partie 2 : prépositions de localisation justes (opposite, between… and, not far from, round the corner, at the far end of, over there, in front of)","points":10},{"critere":"Orthographe et construction des phrases","points":2}],"dureeMin":11,"corrige":"**1.**\n1. *We arrived **in** London at midnight.* — jamais *arrive to* ; ville → *in*.\n2. *I go **home** after school.* — *go home* sans *to*.\n3. *She walked **into** the room.* — pour entrer : *into*.\n4. *We arrived **in** France.* — pays → *in*.\n(2 points chacune.)\n\n**2.**\n5. *The bank is **opposite** the church.*\n6. *The café is **between** the post office **and** the station.*\n7. *He lives **not far from** here, just **round the corner**.*\n8. *The museum is **at the far end of** the street.*\n9. *My friends are **over there**, **in front of** the cinema.*\n(2 points par phrase.)"}$exo$::jsonb),
  ('fa8b32a2-289b-507d-98f7-01a8496951e8'::uuid, 3, 'traduction', $exo${"titre":"Describe the picture","consigne":"À partir de la description en français d'une photo, rédige en anglais une description de 90 à 120 mots comme à l'oral du bac, puis ajoute une phrase d'interprétation.","enonce":"**Description de la photo (en français)**\n\n> Au premier plan, une vieille dame est assise sur un banc, dans un parc. À côté d'elle, un chien dort sur l'herbe. Au centre, un jeune homme fait du vélo sur le chemin. À l'arrière-plan, tout au bout du chemin, on voit un bus rouge dans la rue. Dans le coin en haut à droite, il y a une grande horloge sur une tour. À gauche, deux enfants entrent en courant dans un café.\n\nRédige ta description en anglais en respectant la place de chaque élément. Emploie au moins **six** expressions de localisation différentes, et fais attention à *in / on / at* et au mouvement (*into*). Termine par une phrase d'interprétation (*This picture conveys the idea that…*).","bareme":[{"critere":"Expressions de description d'image justes (in the foreground, in the background, in the centre, on the left, in the top right-hand corner)","points":6},{"critere":"Prépositions de lieu justes (on a bench, in the park, on the grass, on the path, at the far end of, on a tower, next to)","points":6},{"critere":"Mouvement exprimé avec into et présent en -ing pour décrire","points":3},{"critere":"Phrase d'interprétation et correction générale, longueur respectée","points":5}],"dureeMin":16,"corrige":"**Description modèle** :\n\n*In the foreground, an old lady is sitting on a bench in the park. Next to her, a dog is sleeping on the grass. In the centre, a young man is riding a bike on the path. In the background, at the far end of the path, we can see a red bus in the street. In the top right-hand corner, there is a big clock on a tower. On the left, two children are running into a café. This picture conveys the idea that a city park is a place where different generations share the same space.*\n\n**Points de contrôle** :\n- *in the foreground, in the centre / in the middle, in the background, in the top right-hand corner, on the left* ;\n- *on a bench, in the park, next to / beside her, on the grass, on the path, at the far end of the path, in the street* (*on the street* accepté en anglais américain), *on a tower* ;\n- *running **into** a café* (mouvement vers l'intérieur) ;\n- le présent en *-ing* (*is sitting, is sleeping, is riding*) pour décrire ce qu'on voit ;\n- une interprétation cohérente, quelle qu'elle soit."}$exo$::jsonb),
  ('84e53897-195a-5d1b-a022-f2d4e6b71593'::uuid, 1, 'redaction', $exo${"titre":"Les quatre temps d'un projet","consigne":"Réponds à chaque question en quelques lignes, avec le vocabulaire du cours.","enonce":"**Questions de cours**\n\n1. Cite dans l'ordre les quatre temps d'un projet plastique et dis en une phrase ce qui se passe à chacun.\n2. Quelle différence y a-t-il entre une intention et un thème ? Donne un exemple d'intention.\n3. Pourquoi une production sans question posée reste-t-elle « illustrative » ?","bareme":[{"critere":"Quatre temps dans l'ordre (formuler, chercher, réaliser, présenter) avec leur contenu","points":10},{"critere":"Intention = une phrase qui vise un effet, pas un thème, avec un exemple","points":5},{"critere":"Production illustrative : montre un sujet au lieu de le travailler","points":5}],"dureeMin":7,"corrige":"1. - **Formuler une intention** : une phrase qui dit ce que je veux produire comme effet.\n- **Chercher** : essais, matériaux, échelles, références ; on a **le droit de rater**.\n- **Réaliser** : les choix plastiques **répondent à l'intention** ou la **déplacent** (et le déplacement se note).\n- **Présenter** : l'**accrochage** et le **texte d'intention** font partie de l'œuvre.\n2. Un **thème** est un sujet (« la mémoire ») ; une **intention** est une **phrase** qui vise un effet : « je veux rendre visible la disparition », « je veux que le spectateur hésite ».\n3. Sans question posée, la production **montre un sujet au lieu de le travailler** : elle illustre. Une vraie problématique **admet plusieurs réponses plastiques** ; si une seule est possible, c'est une **consigne**, pas une question."}$exo$::jsonb),
  ('84e53897-195a-5d1b-a022-f2d4e6b71593'::uuid, 2, 'redaction', $exo${"titre":"Le carnet de Maëlys","consigne":"Analyse la situation et conseille Maëlys en t'appuyant sur le cours.","enonce":"**Situation (inventée).** Maëlys prépare la présentation de son projet sur le thème de l'absence. Elle veut retirer de son carnet de recherche trois essais ratés et ne garder que la version finale, « pour faire propre ». Elle a aussi repris une silhouette peinte par un artiste célèbre, mais n'ose pas le dire de peur qu'on l'accuse de copier.\n\n1. Explique à Maëlys pourquoi elle ne doit pas retirer ses essais ratés. Que prouve chaque type de contenu du carnet au jury ?\n2. Reprendre la silhouette d'un artiste, est-ce copier ? Présente les trois relations légitimes à une référence et dis laquelle correspond à son geste.\n3. Son thème, « l'absence », est-il une intention ? Propose-lui une formulation d'intention.","bareme":[{"critere":"Garder les essais : c'est le cheminement qui est noté ; un échec documenté vaut mieux qu'une réussite inexpliquée","points":4},{"critere":"Ce que prouvent croquis, essais datés, références annotées, notes d'intention","points":5},{"critere":"Citer, prolonger, contredire expliqués ; son geste relève de la citation, à assumer comme emprunt","points":7},{"critere":"Thème ≠ intention, formulation d'intention pertinente","points":4}],"dureeMin":12,"corrige":"1. Au lycée, c'est la **démarche** qui est évaluée : **un échec documenté vaut mieux qu'une réussite inexpliquée**. Le carnet prouve : **croquis et variantes** → que des **choix ont été écartés** ; **essais ratés, datés** → que la **recherche a eu lieu** ; **références annotées** → que le travail **se situe** ; **notes d'intention** → que la démarche est **consciente**.\n2. Non, situer son travail par rapport à un artiste n'est pas copier, c'est **se positionner**, à condition que la relation soit **consciente** :\n- **Citer** : reprendre un motif et l'**assumer comme emprunt** ;\n- **Prolonger** : poursuivre une recherche là où l'artiste l'a laissée ;\n- **Contredire** : reprendre le dispositif pour en **renverser le sens**.\nMaëlys **cite** : elle doit le dire et l'assumer.\n3. « L'absence » est un **thème**. Une intention est une phrase : par exemple « je veux que le spectateur ressente un manque devant une place vide » ou « je veux rendre visible la disparition »."}$exo$::jsonb),
  ('84e53897-195a-5d1b-a022-f2d4e6b71593'::uuid, 3, 'redaction', $exo${"titre":"Défendre son projet devant un jury","consigne":"Rédige un texte organisé d'une vingtaine de lignes, comme si tu préparais l'oral de présentation d'un projet.","enonce":"**Sujet.** Tu as réalisé une installation à partir de l'intention : « je veux que le spectateur hésite entre entrer et rester dehors ». Au départ, tu pensais faire une peinture ; tes essais t'ont amené à construire un seuil avec des voilages.\n\n1. Explique en quoi ton intention pose une vraie problématique (et non une consigne).\n2. Montre comment ton carnet de recherche rend visible le passage de la peinture à l'installation, et pourquoi ce déplacement est valorisé.\n3. Choisis une référence (réelle ou décrite de façon générale) et précise ta relation à elle : citer, prolonger ou contredire.\n4. Explique pourquoi l'accrochage et le texte d'intention sont le « dernier acte plastique », et ce que signifie « défendre son travail ».","bareme":[{"critere":"Problématique justifiée : elle admet plusieurs réponses plastiques","points":4},{"critere":"Carnet : essais datés, variantes, choix écartés montrant le déplacement de l'intention","points":5},{"critere":"Relation à une référence nommée et justifiée","points":4},{"critere":"Présentation (accrochage, éclairage, ordre de lecture, texte) comme acte plastique","points":4},{"critere":"Défendre = expliciter les choix, pas justifier les manques","points":3}],"dureeMin":18,"corrige":"Éléments attendus :\n1. L'intention est une **phrase** qui vise un effet sur le spectateur. Elle pose une vraie **problématique** car elle **admet plusieurs réponses plastiques** (une peinture en trompe-l'œil, un passage étroit, un voilage, un jeu de lumière…). Si une seule réponse était possible, ce serait une **consigne**. Sans cette question, le travail serait **illustratif**.\n2. Le carnet montre la **phase de recherche** : croquis de la peinture, **essais ratés datés**, variantes d'échelle et de matériaux, photos du seuil. Ils prouvent que des **choix ont été écartés** et que la recherche a eu lieu. Pendant la réalisation, les choix plastiques **répondent à l'intention ou la déplacent** : ici, passer de la peinture à l'installation est un **déplacement**, et **le déplacement se note** — c'est le **cheminement** qui est évalué, pas la seule habileté.\n3. Toute référence pertinente est acceptée si la relation est **consciente** et justifiée : **citer** (reprendre un motif en l'assumant), **prolonger** (poursuivre la recherche d'un artiste) ou **contredire** (reprendre son dispositif pour en renverser le sens). Se situer n'est pas copier.\n4. **Accrochage, éclairage, ordre de lecture, texte d'intention** : la présentation est le **dernier acte plastique**, pas une formalité ; elle fait partie de l'œuvre (ici, placer le seuil pour que le spectateur doive choisir). **Défendre** son travail, c'est **expliciter ses choix** — jamais **justifier ses manques**."}$exo$::jsonb),
  ('e8e84a71-5070-5606-8dfd-02404884583a'::uuid, 1, 'redaction', $exo${"titre":"Les quatre déplacements de l'art contemporain","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Quelle question l'art contemporain a-t-il remplacée, et par laquelle ?\n2. Complète : l'œuvre passe de l'objet à l'…, de l'atelier au …, de l'objet au …, de l'unique au … . Donne pour chacun le mouvement ou la pratique qui correspond.\n3. Que signifie la phrase de Duchamp : « C'est le regardeur qui fait le tableau » ?","bareme":[{"critere":"De « est-ce beau ? » à « qu'est-ce que cela fait ? »","points":4},{"critere":"Quatre déplacements justes avec la pratique associée (art conceptuel, in situ/land art, performance, Pop art)","points":12},{"critere":"L'œuvre existe activée par l'interprétation ou la participation","points":4}],"dureeMin":7,"corrige":"1. On ne demande plus « **est-ce beau ?** » mais « **qu'est-ce que cela fait ?** ».\n2. - De l'objet à l'**idée** : l'**art conceptuel**, où le protocole vaut l'œuvre.\n- De l'atelier au **lieu** : l'**in situ** et le **land art**, où l'œuvre tient à son site.\n- De l'objet au **corps** : la **performance**, où l'œuvre est un temps vécu.\n- De l'unique au **reproductible** : le **Pop art** et la **sérigraphie**, où la copie n'est plus un défaut.\n3. Pour **Duchamp**, l'œuvre n'est pas complète sans celui qui la regarde : beaucoup d'œuvres contemporaines **n'existent qu'activées** — par une **interprétation**, une **participation** ou un **récit**."}$exo$::jsonb),
  ('e8e84a71-5070-5606-8dfd-02404884583a'::uuid, 2, 'redaction', $exo${"titre":"Quatre artistes, quatre gestes","consigne":"Associe et explique, en t'appuyant sur le cours.","enonce":"**Document – Quatre descriptions (sans nom)**\n\n- **A.** Un artiste reproduit en série, par sérigraphie, la même image d'une célébrité.\n- **B.** Un couple d'artistes enveloppe un monument entier de toile pendant quelques jours.\n- **C.** Une artiste suit un inconnu dans la rue et raconte son enquête par des textes et des photos.\n- **D.** Un artiste réalise des œuvres qui dénoncent la censure dans son pays.\n\n1. Retrouve l'artiste (ou les artistes) correspondant à chaque description, selon le cours.\n2. Pour chacun, dis ce que son geste « déplace ».\n3. Le street art, né dans l'illégalité, est-il resté en dehors du marché ? Explique.","bareme":[{"critere":"Quatre attributions justes : Warhol, Christo et Jeanne-Claude, Sophie Calle, Ai Weiwei","points":8},{"critere":"Ce que chaque geste déplace (unicité, éphémère et public, artiste narratrice, prise de position)","points":8},{"critere":"Street art : passé de la rue au marché, l'illégalité devenue valeur","points":4}],"dureeMin":11,"corrige":"1. **A** : **Andy Warhol** ; **B** : **Christo et Jeanne-Claude** ; **C** : **Sophie Calle** ; **D** : **Ai Weiwei**.\n2. - **Warhol**, reproduction sérielle : il déplace l'**unicité de l'œuvre**.\n- **Christo et Jeanne-Claude**, emballage monumental : l'œuvre devient **éphémère et publique**.\n- **Sophie Calle**, récit et enquête : l'**artiste devient narratrice**.\n- **Ai Weiwei**, art politique : l'œuvre comme **prise de position**.\n3. **Non** : le street art est passé de **la rue au marché** ; **l'illégalité est devenue valeur**. Galeries, foires et musées construisent aussi socialement la valeur d'une œuvre."}$exo$::jsonb),
  ('e8e84a71-5070-5606-8dfd-02404884583a'::uuid, 3, 'redaction', $exo${"titre":"« Mon petit frère pourrait le faire »","consigne":"Rédige une réponse argumentée et organisée d'une vingtaine de lignes, en t'appuyant sur des exemples précis du cours.","enonce":"**Situation (inventée).** Au musée, devant une œuvre faite d'objets du quotidien disposés au sol selon un protocole écrit, ton ami Nolan s'exclame : « Ce n'est même pas beau, mon petit frère pourrait le faire, et en plus ça coûte une fortune ! »\n\nRéponds à Nolan en montrant :\n1. que l'art contemporain a déplacé la question qu'on pose à une œuvre ;\n2. à quel déplacement appartient cette œuvre, et en quoi l'idée compte plus que l'habileté ;\n3. comment se construit la valeur d'une œuvre contemporaine ;\n4. quelle méthode adopter devant une œuvre qui déroute, et quel rôle y joue le regardeur.","bareme":[{"critere":"Question déplacée : de la beauté à ce que fait l'œuvre","points":4},{"critere":"Art conceptuel : l'idée prime sur l'objet, le protocole vaut l'œuvre, avec au moins un autre déplacement cité","points":5},{"critere":"Valeur construite aussi socialement : galeries, foires, biennales, musées","points":4},{"critere":"Méthode : demander ce que l'œuvre demande de faire ; Duchamp et le regardeur","points":5},{"critere":"Argumentation organisée qui répond à Nolan","points":2}],"dureeMin":18,"corrige":"Éléments attendus :\n1. Nolan juge avec la question « **est-ce beau ?** ». L'art contemporain l'a **déplacée** vers « **qu'est-ce que cela fait ?** » : l'œuvre ne cherche pas forcément la beauté ni l'habileté technique.\n2. Cette œuvre relève du passage **de l'objet à l'idée** : c'est l'**art conceptuel**, où **le protocole vaut l'œuvre**. Ce qui compte est l'idée et la décision de l'artiste, pas la difficulté de fabrication : « pouvoir le faire » n'est pas « l'avoir pensé ». On peut citer d'autres déplacements : vers le **lieu** (in situ, land art), le **corps** (performance), le **reproductible** (Warhol et le Pop art, où la copie n'est plus un défaut).\n3. Le prix n'est pas absurde si l'on comprend le circuit : **galeries, foires, biennales, musées** — la valeur d'une œuvre contemporaine se construit **aussi socialement**. Ignorer ce circuit condamne à trouver les prix absurdes ; le comprendre fait partie de la compréhension de l'œuvre (exemple du **street art**, passé de la rue au marché).\n4. Méthode : ne pas demander **ce que l'œuvre représente**, mais **ce qu'elle demande de faire**. Pour **Duchamp**, « **c'est le regardeur qui fait le tableau** » : beaucoup d'œuvres n'existent qu'**activées** par une interprétation, une participation ou un récit. Nolan, en réagissant, participe déjà à l'œuvre."}$exo$::jsonb),
  ('0fcd41b2-3329-5093-9c71-4e2b37f52c76'::uuid, 1, 'redaction', $exo${"titre":"Pixel ou vecteur ?","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Comment une image matricielle est-elle décrite ? Et une image vectorielle ? Que se passe-t-il quand on les agrandit ?\n2. Donne un usage typique de chacune.\n3. Quels sont les deux sens du mot « résolution » ? En quelle unité mesure-t-on la finesse d'impression ?","bareme":[{"critere":"Grille de pixels / formules géométriques ; pixellisation / netteté conservée","points":8},{"critere":"Usages : photographie ou peinture numérique / logo, typographie, pictogramme","points":5},{"critere":"Résolution en pixels (dimensions) et en ppp/dpi (impression)","points":7}],"dureeMin":6,"corrige":"1. Une image **matricielle** (bitmap) est une **grille de pixels colorés** : agrandie, elle **se dégrade, se pixellise**. Une image **vectorielle** est décrite par des **formules géométriques** : agrandie, elle **reste nette, sans perte**.\n2. Matricielle : **photographie**, peinture numérique. Vectorielle : **logo**, typographie, pictogramme.\n3. La résolution se lit deux fois : en **pixels** (les dimensions de l'image) et en **ppp / dpi** (points par pouce, sa **finesse à l'impression**)."}$exo$::jsonb),
  ('0fcd41b2-3329-5093-9c71-4e2b37f52c76'::uuid, 2, 'redaction', $exo${"titre":"Le bon format pour chaque usage","consigne":"Aide Ilyes à choisir ses formats en justifiant chaque choix avec le cours.","enonce":"**Situation (inventée).** Ilyes prépare l'affiche d'un festival de son lycée. Il doit produire :\n- **A.** le logo du festival, qui sera imprimé en petit sur les billets et en très grand sur une banderole ;\n- **B.** une photo du groupe de musique pour le site web ;\n- **C.** une image du chanteur détourée, à poser sur un fond coloré ;\n- **D.** un fichier de l'affiche finale en qualité maximale, à archiver et à envoyer à l'imprimeur.\n\n1. Pour chaque cas, choisis un format parmi JPEG, PNG, TIFF, SVG et justifie.\n2. Pour la photo du site, quel inconvénient présente le format choisi ?\n3. Pour poser le chanteur sur le fond, quels outils de montage Ilyes peut-il utiliser ?","bareme":[{"critere":"A SVG (vectoriel, net à toutes les tailles) justifié","points":4},{"critere":"B JPEG, C PNG (transparence), D TIFF justifiés","points":8},{"critere":"JPEG : compression avec perte d'information","points":4},{"critere":"Outils : calques, masques, détourage, fondus","points":4}],"dureeMin":10,"corrige":"1. - **A** : **SVG**, format **vectoriel** : le logo reste **net sans perte** du billet à la banderole (une image matricielle se pixelliserait).\n- **B** : **JPEG**, adapté à une **photo destinée au web** (fichier léger).\n- **C** : **PNG**, qui compresse **sans perte** et **garde la transparence** : idéal pour une **image détourée**.\n- **D** : **TIFF**, qui **conserve la qualité maximale** : **archivage** et **impression**.\n2. Le JPEG **compresse en perdant de l'information** : la qualité se dégrade, surtout si on l'enregistre plusieurs fois.\n3. Les **calques** (superposer et modifier les éléments indépendamment), les **masques**, le **détourage** et les **fondus**."}$exo$::jsonb),
  ('0fcd41b2-3329-5093-9c71-4e2b37f52c76'::uuid, 3, 'redaction', $exo${"titre":"Une photo qui n'a jamais eu lieu","consigne":"Rédige une réponse argumentée et organisée d'une vingtaine de lignes, en t'appuyant sur le cours.","enonce":"**Situation (inventée).** Une image circule sur les réseaux sociaux : on y voit une baleine nageant dans une rue inondée de Paris. Elle est parfaite, sans aucune trace visible de retouche. Des milliers de personnes la partagent, et personne ne sait qui l'a faite.\n\n1. Explique comment le montage numérique permet de produire une telle image (outils, notion d'image « sans référent réel »).\n2. Que devient la valeur de preuve de la photographie ? Une photographie numérique est-elle toujours une preuve fiable ?\n3. Explique la notion d'« aura » selon Walter Benjamin et montre comment le numérique pousse cette logique à l'extrême, à partir de l'exemple.\n4. Conclus : en quoi le numérique n'est-il « pas un pinceau de plus » ?","bareme":[{"critere":"Montage : calques, masques, détourage, fondus ; image sans référent réel, photographiquement parfaite","points":5},{"critere":"Valeur de preuve remise en question quand la retouche ne laisse plus de trace","points":4},{"critere":"Aura selon Benjamin (1935) : l'ici-et-maintenant perdu par la reproduction","points":4},{"critere":"Numérique extrême : copie parfaite, diffusion instantanée, auteur indéterminé, relié à l'exemple","points":4},{"critere":"Conclusion : le numérique change le statut de l'image (matière, copie, preuve)","points":3}],"dureeMin":18,"corrige":"Éléments attendus :\n1. Avec les **calques**, les **masques**, le **détourage** et les **fondus**, on combine plusieurs images (une baleine, une rue, de l'eau) en une seule. On obtient une image **sans référent réel** : une scène **qui n'a jamais eu lieu**, pourtant **photographiquement parfaite**.\n2. La photographie passait pour une **preuve** (« ça a eu lieu »). Quand **la retouche ne laisse plus de trace**, cette **valeur de preuve** est remise en question : une photographie numérique **n'est pas toujours une preuve fiable** ; il faut s'interroger sur sa source.\n3. **Walter Benjamin** l'anticipait dès **1935** : la **reproduction** fait perdre à l'œuvre son **« aura »**, son **ici-et-maintenant**. Le numérique pousse cette logique à l'extrême : **copie parfaite** (chaque partage est identique à l'original), **diffusion instantanée** (des milliers de partages), **auteur parfois indéterminé** (personne ne sait qui l'a faite).\n4. Le numérique n'est **pas un pinceau de plus** : il change le **statut** de l'image — sa **matière** (pixels ou vecteurs), sa **copie** (sans perte ni original) et sa **preuve** (plus garantie)."}$exo$::jsonb),
  ('c3ba5e5b-b29c-50b5-b5cb-9e66d44134ba'::uuid, 1, 'redaction', $exo${"titre":"Les trois conditions de l'État de droit","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Définis l'**État de droit**. Quel est son contraire ?\n2. Cite les **trois conditions** de l'État de droit.\n3. Classe ces normes de la plus haute à la plus basse : la loi, un contrat, la Constitution, un décret, un traité international.\n4. Qui a formulé le principe de la **séparation des pouvoirs**, et en quelle année ? Nomme les trois pouvoirs et leur fonction.","bareme":[{"critere":"Définition (tous soumis au droit, gouvernants comme gouvernés) et contraire : l'arbitraire","points":5},{"critere":"Hiérarchie des normes, séparation des pouvoirs, juges indépendants","points":4},{"critere":"Classement exact des cinq normes","points":5},{"critere":"Montesquieu, 1748, trois pouvoirs et leurs fonctions","points":6}],"dureeMin":7,"corrige":"1. L'État de droit est un État dans lequel **tous, gouvernants comme gouvernés, sont soumis au droit**. Son contraire n'est pas l'absence de lois (un État autoritaire en a beaucoup) mais l'**arbitraire** : un pouvoir qui n'est pas lié par les règles qu'il édicte.\n2. Une **hiérarchie des normes** respectée ; une **séparation des pouvoirs** effective ; des **juges indépendants**.\n3. **Constitution** → **traité international** → **loi** → **décret** → **contrat**.\n4. **Montesquieu**, en **1748** (« il faut que le pouvoir arrête le pouvoir »). Le pouvoir **législatif** fait la loi ; l'**exécutif** l'applique ; le **judiciaire** la fait respecter."}$exo$::jsonb),
  ('c3ba5e5b-b29c-50b5-b5cb-9e66d44134ba'::uuid, 2, 'redaction', $exo${"titre":"Le recours de Samir","consigne":"Lis la situation, puis réponds aux questions en t'appuyant sur le cours.","enonce":"**Situation.** Samir, 17 ans, voit sa demande de bourse refusée par l'administration, sans explication. Un décret récent, sur lequel s'appuie ce refus, lui semble contraire à la loi. Sa mère, elle, est poursuivie en justice sur le fondement d'une loi votée il y a trois ans, qu'elle estime contraire aux droits garantis par la Constitution.\n\n1. Samir peut-il contester le refus ? Devant quelle juridiction ? Que risque le décret s'il est contraire à la loi ? Justifie par la hiérarchie des normes.\n2. La loi étant déjà en vigueur, la mère de Samir peut-elle encore la contester ? Par quelle procédure, depuis quand, et quelle institution tranchera ?\n3. Si tous les recours nationaux échouent, quelle juridiction européenne pourrait condamner la France ? Où siège-t-elle ?\n4. Explique la phrase du cours : « Sans État de droit, ces recours n'existent pas. »","bareme":[{"critere":"Recours contre l'administration, Conseil d'État, annulation du décret contraire à la loi","points":6},{"critere":"QPC depuis 2010, contrôle par le Conseil constitutionnel d'une loi en vigueur","points":6},{"critere":"CEDH à Strasbourg","points":3},{"critere":"Lien entre juges indépendants, soumission de l'État au droit et recours du citoyen","points":5}],"dureeMin":11,"corrige":"1. **Oui** : dans un État de droit, chacun peut contester une décision publique. Le litige avec l'administration relève de la justice administrative, dont le **Conseil d'État** est la juridiction suprême. Le décret est un **règlement**, placé **sous la loi** dans la hiérarchie des normes : une norme inférieure qui contredit une norme supérieure peut être **annulée**.\n2. **Oui**, par la **question prioritaire de constitutionnalité (QPC)**, créée en **2010** : elle permet de contester une loi **déjà en vigueur**. C'est le **Conseil constitutionnel** qui contrôle la conformité de la loi à la Constitution ; si la loi est contraire, elle peut être écartée.\n3. La **Cour européenne des droits de l'homme (CEDH)**, à **Strasbourg**, qui peut condamner la France.\n4. Ces recours supposent que l'État soit **lui-même soumis au droit** et que des **juges indépendants** puissent le contrôler. Dans un régime arbitraire, le pouvoir n'est pas lié par ses propres règles : aucun juge ne pourrait annuler son décret ni écarter sa loi."}$exo$::jsonb),
  ('c3ba5e5b-b29c-50b5-b5cb-9e66d44134ba'::uuid, 3, 'redaction', $exo${"titre":"Beaucoup de lois, pas de droit ?","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, avec des exemples précis du cours.","enonce":"**Document**\n\n> « Le contraire de l'État de droit n'est pas l'absence de lois : un État autoritaire en a beaucoup. Son contraire, c'est l'arbitraire. »\n\n**Sujet.** Explique cette affirmation. Tu montreras :\n1. pourquoi le nombre de lois ne suffit pas à faire un État de droit ;\n2. comment la hiérarchie des normes empêche l'arbitraire (« ce n'est pas la force qui valide une règle ») ;\n3. comment la séparation des pouvoirs et les juges protègent le citoyen, avec des institutions précises ;\n4. ce que cela change concrètement pour un citoyen.","bareme":[{"critere":"Distinction entre avoir des lois et être soumis au droit (arbitraire défini)","points":4},{"critere":"Hiérarchie des normes exposée et principe de conformité expliqué","points":5},{"critere":"Séparation des pouvoirs (Montesquieu) et gardiens : Conseil constitutionnel et QPC, Conseil d'État, Cour de cassation, CEDH","points":5},{"critere":"Conséquences concrètes pour le citoyen (contester, demander réparation, écarter une loi)","points":4},{"critere":"Paragraphe argumenté et organisé","points":2}],"dureeMin":18,"corrige":"1. **Des lois ne suffisent pas** : un État autoritaire peut édicter beaucoup de règles, mais s'il n'est **pas lié** par elles, il reste **arbitraire**. L'État de droit exige que **gouvernants comme gouvernés** soient soumis au droit.\n2. **La hiérarchie des normes** : Constitution (et bloc de constitutionnalité : Déclaration de 1789, Préambule de 1946), traités et droit de l'UE, loi, règlements (décrets, arrêtés), contrats. Chaque règle doit être **conforme à celle du dessus** ; sinon elle peut être **annulée**. Une règle n'est donc pas valable parce qu'elle est imposée par la force, mais parce qu'elle est conforme.\n3. **Séparation et contrôle** : selon **Montesquieu** (1748), « il faut que le pouvoir arrête le pouvoir » : législatif, exécutif et judiciaire sont séparés. Des **gardiens** contrôlent : le **Conseil constitutionnel** vérifie la conformité des lois, y compris après leur entrée en vigueur par la **QPC** (2010) ; le **Conseil d'État** contrôle l'administration ; la **Cour de cassation** veille à l'interprétation du droit ; la **CEDH**, à Strasbourg, peut condamner la France.\n4. **Pour le citoyen** : il peut **contester un refus** de l'administration, **demander réparation** d'un dommage causé par l'État, **faire écarter une loi** contraire à la Constitution. Sans État de droit, ces recours n'existent pas.\n\n**Conclusion attendue** : c'est la soumission du pouvoir au droit, garantie par des juges, qui fait l'État de droit, pas la quantité de lois."}$exo$::jsonb),
  ('c30bf9d1-1f5f-542c-a395-2dc384c3a50d'::uuid, 1, 'redaction', $exo${"titre":"Une frise de l'État de droit","consigne":"Réponds à chaque question avec précision.","enonce":"1. Associe chaque date à son texte ou à son événement : 1215 ; 1679 ; 1789 ; 1901 ; 1944 ; 1948 ; 1981 ; 2010.\n2. Que dit l'**article 16** de la Déclaration de 1789, et pourquoi le cours en fait-il « la définition la plus courte de l'État de droit » ?\n3. Que se passe-t-il en **1971** pour le Conseil constitutionnel ?","bareme":[{"critere":"Huit associations date / texte ou événement exactes","points":10},{"critere":"Article 16 cité et rapproché de la garantie des droits et de la séparation des pouvoirs","points":5},{"critere":"1971 : valeur constitutionnelle donnée au Préambule, donc à la Déclaration de 1789","points":5}],"dureeMin":7,"corrige":"1. **1215** : Magna Carta anglaise. **1679** : habeas corpus. **1789** : Déclaration des droits de l'homme et du citoyen. **1901** : liberté d'association. **1944** : droit de vote des femmes. **1948** : Déclaration universelle des droits de l'homme. **1981** : abolition de la peine de mort. **2010** : question prioritaire de constitutionnalité.\n2. L'article 16 dit : « **Toute société dans laquelle la garantie des droits n'est pas assurée, ni la séparation des pouvoirs déterminée, n'a point de Constitution.** » Il réunit en une phrase ce qui fait l'État de droit : des droits garantis et des pouvoirs séparés.\n3. En 1971, le **Conseil constitutionnel** (créé en 1958) s'émancipe en donnant **valeur constitutionnelle au Préambule**, donc à la **Déclaration de 1789** : les lois doivent désormais respecter ces droits."}$exo$::jsonb),
  ('c30bf9d1-1f5f-542c-a395-2dc384c3a50d'::uuid, 2, 'redaction', $exo${"titre":"Après chaque crise, une garantie","consigne":"Lis les documents, puis réponds aux questions en t'appuyant sur le cours.","enonce":"**Document 1 – Magna Carta, 1215 (extrait)**\n\n> « Aucun homme libre ne sera arrêté ou emprisonné […] si ce n'est en vertu d'un jugement légal de ses pairs ou de la loi du pays. »\n\n**Document 2 – Déclaration des droits de l'homme et du citoyen, 1789, article 8 (extrait)**\n\n> « Nul ne peut être puni qu'en vertu d'une loi établie et promulguée antérieurement au délit. »\n\n1. Quelle limite chacun de ces textes impose-t-il au pouvoir ?\n2. Pourquoi, en France sous l'Ancien Régime, le pouvoir royal restait-il sans véritable contrôle malgré les « lois fondamentales du royaume » ?\n3. Après 1945, pourquoi la garantie des droits devient-elle **internationale** ? Cite deux textes datés.\n4. Le cours affirme que l'État de droit « s'est construit par étapes, presque toujours après une crise ». Montre-le avec un exemple.","bareme":[{"critere":"Doc. 1 : pas d'emprisonnement sans jugement ; doc. 2 : pas de peine sans loi antérieure","points":6},{"critere":"Ancien Régime : le roi n'est jugé par personne","points":3},{"critere":"États légaux mais criminels, DUDH 1948 et CEDH 1950","points":6},{"critere":"Exemple pertinent de garantie née d'une crise","points":5}],"dureeMin":11,"corrige":"1. **Document 1** : le roi ne peut **emprisonner un homme libre sans jugement** (première limite au pouvoir royal). **Document 2** : on ne peut être puni qu'en vertu d'une **loi antérieure** au délit : le pouvoir ne peut pas inventer une infraction après coup.\n2. L'Ancien Régime connaît des lois fondamentales du royaume, mais **le roi n'est jugé par personne** : aucun juge ne peut contrôler ses décisions.\n3. Parce que des États **légaux mais criminels** ont montré que le droit national pouvait servir le crime : il faut une garantie au-dessus des États. **1948** : **Déclaration universelle des droits de l'homme** ; **1950** : **Convention européenne des droits de l'homme**.\n4. Exemple attendu : après la Seconde Guerre mondiale et les crimes commis par des États, la garantie devient internationale (1948, 1950), et la Constitution de 1958 crée le Conseil constitutionnel. On accepte aussi 1789, rupture révolutionnaire qui pose la Déclaration. Le cours ajoute que rien n'est acquis : chaque état d'urgence rouvre la question de l'équilibre entre sécurité et libertés."}$exo$::jsonb),
  ('c30bf9d1-1f5f-542c-a395-2dc384c3a50d'::uuid, 3, 'redaction', $exo${"titre":"Huit siècles pour limiter le pouvoir","consigne":"Rédige un développement organisé d'une vingtaine de lignes, appuyé sur des dates et des textes précis.","enonce":"**Sujet.** « L'État de droit n'a pas été décrété : il s'est construit par étapes. Et rien n'est acquis. »\n\nMontre, en t'appuyant sur le cours :\n1. les premières limites posées au pouvoir, avant 1789 ;\n2. l'apport de la Déclaration de 1789 (au moins deux articles) ;\n3. les libertés conquises aux XIXe et XXe siècles (au moins trois dates) ;\n4. l'internationalisation et le renforcement du contrôle après 1945 et jusqu'à aujourd'hui ;\n5. pourquoi « rien n'est acquis ».","bareme":[{"critere":"Magna Carta 1215 et habeas corpus 1679 avec leur apport","points":3},{"critere":"Deux articles de 1789 exacts (1, 4, 8, 16) et leur portée","points":4},{"critere":"Trois libertés datées exactes (1881, 1884, 1901, 1905, 1944)","points":4},{"critere":"Après 1945 : 1948, 1950, 1958, 1971, puis 1981, 2010, 2011","points":5},{"critere":"Fragilité : états d'urgence et équilibre sécurité / libertés ; plan organisé","points":4}],"dureeMin":20,"corrige":"1. **Premières limites** : en **1215**, la **Magna Carta** anglaise interdit au roi d'emprisonner un homme libre sans jugement ; en **1679**, l'**habeas corpus** instaure le contrôle judiciaire de la détention. En France, l'Ancien Régime a des lois fondamentales, mais le roi n'est jugé par personne.\n2. **1789** : article **1** (les hommes naissent libres et égaux en droits), article **4** (la liberté consiste à faire tout ce qui ne nuit pas à autrui), article **8** (pas de peine sans loi antérieure), article **16** (sans garantie des droits ni séparation des pouvoirs, pas de Constitution : la définition la plus courte de l'État de droit).\n3. **XIXe et XXe siècles** : **1881** liberté de la presse et école ; **1884** liberté syndicale ; **1901** liberté d'association ; **1905** séparation des Églises et de l'État ; **1944** droit de vote des femmes.\n4. **Après 1945**, face à des États légaux mais criminels, la garantie devient internationale : **DUDH (1948)**, **Convention européenne des droits de l'homme (1950)**. La Constitution de **1958** crée le **Conseil constitutionnel**, qui en **1971** donne valeur constitutionnelle au Préambule, donc à la Déclaration de 1789. Puis : abolition de la peine de mort (**1981**), **QPC** (**2010**), **Défenseur des droits** (**2011**).\n5. **Rien n'est acquis** : chaque **état d'urgence** rouvre la question de l'équilibre entre **sécurité et libertés** ; une conquête peut reculer.\n\n**Conclusion attendue** : une construction lente, par étapes, souvent après des crises, et toujours à défendre."}$exo$::jsonb),
  ('11f62154-d6e1-5fee-b539-bac2fad85fc5'::uuid, 1, 'redaction', $exo${"titre":"Ordre public et proportionnalité","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Cite quatre **libertés fondamentales**.\n2. Quelles sont les composantes de l'**ordre public** ? Laquelle a été ajoutée par la jurisprudence ?\n3. Quels sont les trois critères du **test de proportionnalité** ? Formule la question que pose chacun.\n4. Une manifestation est-elle soumise à **autorisation** ? Explique.","bareme":[{"critere":"Quatre libertés fondamentales exactes","points":3},{"critere":"Sécurité, tranquillité, salubrité, et dignité ajoutée par la jurisprudence","points":5},{"critere":"Adaptée, nécessaire, proportionnée avec leur question","points":7},{"critere":"Déclaration préalable obligatoire, pas d'autorisation","points":5}],"dureeMin":7,"corrige":"1. Par exemple : aller et venir, conscience, expression, réunion, association, manifestation, vie privée, propriété, procès équitable, liberté d'entreprendre (quatre suffisent).\n2. La **sécurité** (des personnes et des biens), la **tranquillité** (le calme public), la **salubrité** (la santé publique) ; la **dignité de la personne humaine** a été **ajoutée par la jurisprudence**.\n3. **Adaptée** : la mesure sert-elle bien le but invoqué ? **Nécessaire** : une mesure moins sévère suffirait-elle ? **Proportionnée** : l'atteinte est-elle excessive par rapport au bénéfice ?\n4. **Non** : la manifestation est soumise à une **déclaration préalable**, obligatoire, mais **pas à une autorisation**. Une interdiction doit être justifiée par un **risque précis de trouble**, pas par une gêne."}$exo$::jsonb),
  ('11f62154-d6e1-5fee-b539-bac2fad85fc5'::uuid, 2, 'redaction', $exo${"titre":"L'arrêté du maire de Bellerive","consigne":"Lis la situation, puis réponds aux questions en appliquant la méthode du cours.","enonce":"**Situation (inventée).** Après quelques dégradations nocturnes dans une rue du centre, le maire de Bellerive prend un arrêté : « Tout rassemblement de plus de deux personnes est interdit sur l'ensemble de la commune, à toute heure, jusqu'à nouvel ordre. » Clara, 16 ans, et ses amis veulent contester. Une association locale veut aussi saisir le juge en urgence.\n\n1. Quel motif le maire peut-il invoquer ? Quelle composante de l'ordre public est en jeu ?\n2. Applique les trois critères du test de proportionnalité à cet arrêté.\n3. Quel sort le juge réserve-t-il en général à une interdiction de ce type ? Pourquoi ?\n4. Quelle procédure d'urgence l'association peut-elle utiliser ? Dans quel délai le juge statue-t-il, et à quelle condition ?","bareme":[{"critere":"Motif d'ordre public identifié (sécurité, tranquillité) et devant être prouvé","points":4},{"critere":"Test appliqué : adaptée discutable, non nécessaire, disproportionnée","points":7},{"critere":"Interdiction générale et absolue presque toujours annulée ; la règle est la liberté","points":4},{"critere":"Référé-liberté, 48 heures, liberté fondamentale gravement et manifestement atteinte","points":5}],"dureeMin":12,"corrige":"1. Le maire invoque l'**ordre public**, ici la **sécurité** des biens (dégradations) et la **tranquillité** publique. Mais l'ordre public est un **motif qui doit être prouvé**, et la mesure doit être **proportionnée**.\n2. **Adaptée ?** En partie : limiter les rassemblements peut réduire les dégradations dans la rue concernée, mais interdire tout rassemblement partout ne cible pas le problème. **Nécessaire ?** **Non** : une mesure moins sévère suffirait (une rue, la nuit, une durée limitée, plus de patrouilles). **Proportionnée ?** **Non** : l'atteinte à la liberté de réunion et d'aller et venir de toute la population, à toute heure et sans limite de durée, est excessive par rapport au bénéfice.\n3. C'est une interdiction **générale et absolue** : elle est **presque toujours annulée**, car la **règle est la liberté** (l'autorisation), l'**exception est l'interdiction**.\n4. Le **référé-liberté** : le juge administratif doit statuer en **48 heures** lorsqu'une **liberté fondamentale** est **gravement et manifestement atteinte**."}$exo$::jsonb),
  ('11f62154-d6e1-5fee-b539-bac2fad85fc5'::uuid, 3, 'redaction', $exo${"titre":"Sécurité contre libertés ?","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, avec des exemples précis du cours.","enonce":"**Document**\n\n> « Aucune liberté n'est absolue, mais aucune limitation n'est libre. »\n\n**Sujet.** Explique cette affirmation. Tu montreras :\n1. pourquoi l'État peut limiter une liberté fondamentale, et au nom de quoi ;\n2. comment le droit encadre cette limitation (motif, test de proportionnalité, exemple de la manifestation) ;\n3. le rôle du juge, notamment en urgence ;\n4. les risques propres aux régimes d'exception, avec l'exemple de l'état d'urgence.","bareme":[{"critere":"Ordre public et ses composantes comme motif de limitation","points":4},{"critere":"Test de proportionnalité expliqué et manifestation (déclaration, pas d'autorisation)","points":5},{"critere":"Rôle du juge : annulation des interdictions générales, référé-liberté en 48 heures","points":4},{"critere":"État d'urgence (loi de 1955, 2015-2017) et risque de passage dans le droit commun","points":5},{"critere":"Paragraphe argumenté et organisé","points":2}],"dureeMin":18,"corrige":"1. **Aucune liberté n'est absolue** : les libertés fondamentales (aller et venir, expression, réunion, manifestation…) peuvent être limitées au nom de l'**ordre public** : **sécurité**, **tranquillité**, **salubrité**, et **dignité** de la personne humaine (ajoutée par la jurisprudence).\n2. **Aucune limitation n'est libre** : l'ordre public est un **motif qui doit être prouvé** et une mesure qui doit passer le **test de proportionnalité** : **adaptée** (sert-elle le but ?), **nécessaire** (une mesure moins sévère suffirait-elle ?), **proportionnée** (l'atteinte est-elle excessive ?). Exemple : la manifestation n'exige qu'une **déclaration préalable**, pas d'autorisation ; une interdiction doit reposer sur un risque précis de trouble, pas sur une gêne.\n3. **Le juge** : une interdiction **générale et absolue** est presque toujours annulée (la règle est la liberté). Par le **référé-liberté**, le juge administratif statue en **48 heures** quand une liberté fondamentale est gravement et manifestement atteinte.\n4. **Les régimes d'exception** : l'**état d'urgence**, prévu par la **loi de 1955** et appliqué de **2015 à 2017**, élargit les pouvoirs de police, sous contrôle du juge et du Parlement. Le risque principal : que des mesures d'exception **passent peu à peu dans le droit commun**.\n\n**Conclusion attendue** : la sécurité justifie des limites, mais seulement encadrées, prouvées, proportionnées et contrôlées par un juge."}$exo$::jsonb),
  ('52823780-bb9b-56dd-b2e7-c6006a612e39'::uuid, 1, 'redaction', $exo${"titre":"La loi de 1881 et ses limites","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quelle loi est le texte de référence de la liberté de la presse ? Que pose-t-elle ?\n2. Distingue **contrôle a priori** et **contrôle a posteriori**. Lequel est en vigueur ?\n3. Distingue la **diffamation** et l'**injure**.\n4. Qu'est-ce que la **clause de conscience** ? Depuis quand la **protection des sources** est-elle dans la loi ?","bareme":[{"critere":"Loi du 29 juillet 1881 : l'imprimerie et la librairie sont libres","points":4},{"critere":"A priori (censure, supprimé) et a posteriori (tribunal après publication, en vigueur)","points":6},{"critere":"Diffamation (fait précis) et injure (sans imputation de fait) distinguées","points":5},{"critere":"Clause de conscience expliquée et loi de 2010","points":5}],"dureeMin":7,"corrige":"1. La **loi du 29 juillet 1881** : elle pose que **l'imprimerie et la librairie sont libres**.\n2. Le **contrôle a priori** est une autorisation préalable, une censure administrative avant publication : il est **supprimé**. Le **contrôle a posteriori** consiste à **répondre devant un tribunal** de ce qu'on a publié : c'est le **régime actuel**. On ne juge pas un journal avant qu'il paraisse, mais après.\n3. La **diffamation** impute un **fait précis** qui porte atteinte à l'honneur d'une personne ; l'**injure** est une **expression outrageante sans imputation de fait**.\n4. La **clause de conscience** permet à un journaliste de **quitter un journal qui change de ligne** éditoriale. La **protection des sources** est inscrite dans la loi depuis **2010** ; elle ne cède que devant un impératif prépondérant d'intérêt public."}$exo$::jsonb),
  ('52823780-bb9b-56dd-b2e7-c6006a612e39'::uuid, 2, 'redaction', $exo${"titre":"L'enquête du Courrier de l'Est","consigne":"Lis la situation, puis réponds aux questions en t'appuyant sur le cours.","enonce":"**Situation (inventée).** Le journal *Le Courrier de l'Est* publie une enquête : « Le directeur de l'usine Valtor a falsifié les rapports de pollution en 2024. » Le directeur porte plainte. Dans le même temps, un lecteur traite le journaliste d'« ordure » dans un commentaire public. La police demande au journaliste le nom de la personne qui lui a donné les rapports. Enfin, l'entreprise lance cinq procès coûteux contre le petit journal, qui peine à payer ses avocats.\n\n1. De quel abus le directeur accuse-t-il le journal ? Justifie par la définition.\n2. De quel abus le lecteur s'est-il rendu coupable ? Quelle différence avec le cas précédent ?\n3. Le journaliste doit-il révéler le nom de sa source ? Justifie.\n4. Comment appelle-t-on la stratégie de l'entreprise ? Pourquoi est-ce une menace pour la liberté de la presse ?\n5. Pourquoi le cours dit-il que cette liberté « protège d'abord le lecteur » ?","bareme":[{"critere":"Diffamation : imputation d'un fait précis portant atteinte à l'honneur","points":4},{"critere":"Injure : expression outrageante sans fait, différence expliquée","points":4},{"critere":"Protection des sources (loi de 2010) et sa seule limite","points":4},{"critere":"Procédure-bâillon : épuiser financièrement un média","points":4},{"critere":"Liberté de la presse comme droit du public d'être informé","points":4}],"dureeMin":12,"corrige":"1. **Diffamation** : le journal impute au directeur un **fait précis** (avoir falsifié des rapports en 2024) qui porte **atteinte à son honneur**. Le journal devra répondre **a posteriori** devant le tribunal de ce qu'il a publié.\n2. **Injure** : « ordure » est une **expression outrageante**, **sans imputation d'un fait**. La diffamation, elle, reproche un fait précis.\n3. **Non, en principe** : la **protection des sources** est garantie par la **loi de 2010** ; elle ne cède que devant un **impératif prépondérant d'intérêt public**.\n4. C'est une **procédure-bâillon** : multiplier les actions en justice pour **épuiser financièrement** un média, même sans gagner. Elle menace la liberté de la presse en dissuadant les journaux, surtout les plus fragiles, d'enquêter.\n5. Parce que la liberté de la presse n'est pas un privilège de journaliste : c'est le **droit du public d'être informé**, ici de savoir si une usine pollue."}$exo$::jsonb),
  ('52823780-bb9b-56dd-b2e7-c6006a612e39'::uuid, 3, 'redaction', $exo${"titre":"Une liberté menacée autrement","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, avec des exemples précis du cours.","enonce":"**Document**\n\n> « Aujourd'hui, la presse française n'est plus censurée. Mais une liberté peut s'éteindre sans être interdite. »\n\n**Sujet.** Discute cette affirmation. Tu montreras :\n1. ce que garantit le régime issu de la loi de 1881 ;\n2. que cette liberté a des limites fixées par la loi, et lesquelles (au moins trois abus, deux lois de renforcement) ;\n3. quelles garanties protègent le métier et qui régule ;\n4. quelles menaces contemporaines pèsent sur elle sans passer par la censure (au moins trois).","bareme":[{"critere":"Loi de 1881, fin du contrôle a priori, régime a posteriori","points":4},{"critere":"Trois abus définis et lois Pleven (1972) et Gayssot (1990)","points":4},{"critere":"Garanties (sources 2010, clause de conscience, loi Bloche 2016) et régulateurs (juge, Arcom 2022)","points":5},{"critere":"Trois menaces contemporaines expliquées (concentration, publicité, procédures-bâillons, danger, économie)","points":5},{"critere":"Réponse argumentée à l'affirmation","points":2}],"dureeMin":18,"corrige":"1. **Le régime de 1881** : la **loi du 29 juillet 1881** pose que l'imprimerie et la librairie sont libres ; le **contrôle a priori** (autorisation, censure) est **supprimé** ; on répond **a posteriori**, devant un tribunal, de ce qu'on a publié.\n2. **Des limites légales** : **diffamation** (fait précis portant atteinte à l'honneur), **injure** (expression outrageante sans fait), **provocation** à la haine ou à la violence, **apologie** de crimes, **fausses nouvelles** qui troublent l'ordre public. Les lois **Pleven (1972)** et **Gayssot (1990)** ont renforcé la répression du racisme et de la négation des crimes contre l'humanité.\n3. **Garanties** : **protection des sources** (loi de 2010), **clause de conscience**, **indépendance des rédactions** (loi Bloche, 2016). **Régulation** : le **juge** tranche les abus ; l'**Arcom**, née en **2022** de la fusion du CSA et de l'Hadopi, régule l'audiovisuel et les plateformes ; conseils de déontologie et sociétés de journalistes.\n4. **Menaces sans censure** : la **concentration** des médias (peu de propriétaires), la dépendance à la **publicité** (contenu orienté par l'audience), les **procédures-bâillons** (épuiser financièrement un média), le **danger physique** pour les reporters, la **difficulté économique** de l'information de qualité face aux contenus gratuits.\n\n**Conclusion attendue** : l'affirmation est juste ; la liberté est garantie en droit, mais elle peut s'affaiblir par l'argent, la pression judiciaire ou la violence ; or c'est le droit du public d'être informé qui est en jeu."}$exo$::jsonb),
  ('9683105d-f114-5d2c-ade7-fa4371b506c0'::uuid, 1, 'redaction', $exo${"titre":"Ce que protège l'article 11","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quels textes reconnaissent la **liberté d'expression** ? Cite les articles.\n2. Selon la Cour européenne, quelles idées cette liberté protège-t-elle ?\n3. Que prévoit l'article 11 au sujet des **abus** ?\n4. Cite trois propos ou comportements sanctionnés par la loi.","bareme":[{"critere":"Article 11 de la Déclaration de 1789 et article 10 de la CEDH","points":5},{"critere":"Idées qui heurtent, choquent ou inquiètent","points":5},{"critere":"Chacun répond des abus dans les cas déterminés par la loi","points":4},{"critere":"Trois propos ou actes sanctionnés exacts","points":6}],"dureeMin":6,"corrige":"1. L'**article 11 de la Déclaration de 1789** (« La libre communication des pensées et des opinions est un des droits les plus précieux de l'homme ») et l'**article 10 de la Convention européenne des droits de l'homme**.\n2. Elle protège aussi les idées qui **heurtent, choquent ou inquiètent**, et pas seulement celles qui plaisent : caricature, satire, critique des institutions et des religions.\n3. Chacun **répond de l'abus** de cette liberté « **dans les cas déterminés par la loi** ».\n4. Trois parmi : l'**injure** et la **diffamation**, la **provocation** à la haine, à la violence ou à la discrimination, l'**apologie du terrorisme**, la **négation** de crimes contre l'humanité, le **harcèlement** en ligne et les **menaces**, l'atteinte à la **vie privée** et au droit à l'image."}$exo$::jsonb),
  ('9683105d-f114-5d2c-ade7-fa4371b506c0'::uuid, 2, 'redaction', $exo${"titre":"Débat ou délit ?","consigne":"Pour chaque situation, dis si le propos relève du débat ou du délit, et justifie par la ligne de partage du cours.","enonce":"**Situations (inventées)**\n\n- **A.** Yanis publie sur son blog une caricature du ministre de l'Éducation en clown.\n- **B.** Sur un réseau social, sous pseudonyme, un compte public écrit : « Il faut chasser les gens de telle origine de notre ville. »\n- **C.** Lucie écrit dans le journal du lycée un article qui critique vivement une religion et ses dogmes.\n- **D.** Plusieurs élèves envoient chaque jour des messages humiliants à une camarade sur un groupe de discussion.\n\n1. Classe chaque situation (débat ou délit) et justifie.\n2. Pour la situation B, l'auteur peut-il échapper aux poursuites grâce à son pseudonyme ? Explique.\n3. Pour la situation C, dans quel cadre s'exerce la liberté d'expression des lycéens ?","bareme":[{"critere":"A et C classés dans le débat (caricature, critique d'une idée ou d'une religion)","points":5},{"critere":"B et D classés comme délits (provocation à la haine contre des personnes, harcèlement)","points":5},{"critere":"Pseudonyme : message public = publication, identification judiciaire possible","points":5},{"critere":"Cadre du lycée : pluralisme, neutralité, sans injure ni diffamation","points":5}],"dureeMin":11,"corrige":"1. **A. Débat** : la **caricature** d'un responsable politique est protégée ; on a le droit de se moquer. **B. Délit** : **provocation à la haine** contre des **personnes en raison de leur origine** : ce n'est plus une idée qui est visée, ce sont des personnes pour ce qu'elles sont. **C. Débat** : **critiquer une religion** est licite ; une idée, une doctrine, une religion sont critiquables. **D. Délit** : **harcèlement** en ligne contre une personne.\n\nLa ligne de partage : on peut critiquer une **idée** (débat), on ne peut pas attaquer des **personnes** en raison de leur origine, religion, sexe, orientation sexuelle ou handicap (délit).\n2. **Non** : un message **public** sur un réseau est une **publication**, qui peut fonder des poursuites, et l'**anonymat** d'un pseudonyme **ne protège pas d'une identification judiciaire**.\n3. Les lycéens ont une liberté d'expression **individuelle et collective**, dans le respect du **pluralisme** et de la **neutralité** du service public, **sans propos injurieux ni diffamatoires** ; elle s'exerce notamment par les délégués, le CVL et les **journaux lycéens**. L'article de Lucie critique des dogmes : il est admis tant qu'il ne vise pas les croyants eux-mêmes."}$exo$::jsonb),
  ('9683105d-f114-5d2c-ade7-fa4371b506c0'::uuid, 3, 'redaction', $exo${"titre":"Dire ce qu'on veut, répondre de ce qu'on dit","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, avec des exemples précis du cours.","enonce":"**Document**\n\n> Emma : « Si la liberté d'expression a des limites, ce n'est plus une liberté. Soit on peut tout dire, soit on ne peut rien dire. »\n\n**Sujet.** Réponds à Emma. Tu montreras :\n1. que cette liberté est très large, avec des exemples ;\n2. qu'elle est responsable, et ce que la loi sanctionne ;\n3. où passe la ligne de partage, et pourquoi elle protège la liberté elle-même ;\n4. comment ces règles s'appliquent en ligne et au lycée.","bareme":[{"critere":"Liberté large : article 11, CEDH, idées qui heurtent, caricature, satire, critique","points":4},{"critere":"Responsabilité : article 11 et au moins trois abus sanctionnés","points":4},{"critere":"Ligne de partage idée / personnes expliquée et justifiée","points":5},{"critere":"En ligne (publication, pseudonyme) et au lycée (pluralisme, neutralité)","points":5},{"critere":"Réponse argumentée à l'alternative d'Emma","points":2}],"dureeMin":18,"corrige":"1. **Une liberté large** : reconnue par l'**article 11** de la Déclaration de 1789 et l'**article 10** de la CEDH, elle protège les idées qui **heurtent, choquent ou inquiètent** : la **caricature**, la **satire**, la **critique** des institutions et des religions.\n2. **Une liberté responsable** : l'article 11 prévoit lui-même que chacun **répond de l'abus** « dans les cas déterminés par la loi ». Sont sanctionnés : l'**injure** et la **diffamation**, la **provocation** à la haine, à la violence, à la discrimination, l'**apologie du terrorisme**, la **négation** de crimes contre l'humanité, le **harcèlement** et les **menaces**, l'atteinte à la **vie privée** et au droit à l'image.\n3. **La ligne de partage** : une **idée**, une doctrine, une religion, un parti sont critiquables (**débat**) ; des **personnes**, attaquées en raison de leur origine, religion, sexe, orientation sexuelle ou handicap, relèvent du **délit**. Cette limite ne supprime pas la liberté : elle protège la liberté et la dignité de ceux qui seraient visés, et laisse intact le débat d'idées.\n4. **En ligne**, un message public est une **publication**, et le **pseudonyme** n'empêche pas l'identification judiciaire ; des textes de 2018 et 2022 ont renforcé la lutte contre le cyberharcèlement. **Au lycée**, la liberté est individuelle et collective, dans le respect du **pluralisme** et de la **neutralité**, sans injure ni diffamation (délégués, CVL, journaux lycéens).\n\n**Conclusion attendue** : l'alternative d'Emma est fausse ; on peut presque tout dire, mais on répond de ce qu'on dit."}$exo$::jsonb),
  ('e0f45b58-fa55-5bca-80a1-99f073ef6717'::uuid, 1, 'redaction', $exo${"titre":"Réguler les plateformes","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Cite trois obstacles qui rendent la régulation des réseaux sociaux difficile.\n2. Sur quoi les **algorithmes de recommandation** sont-ils optimisés ? Définis **bulle de filtres** et **chambre d'écho**.\n3. Associe chaque texte à sa date et à ce qu'il impose : **LCEN**, **RGPD**, **Digital Services Act**.\n4. Que signalent **Pharos** et le **3018** ?","bareme":[{"critere":"Trois obstacles exacts (volume, vitesse, transnational, règles privées)","points":4},{"critere":"Attention et engagement ; bulle de filtres et chambre d'écho définies","points":6},{"critere":"Trois textes avec dates et obligations justes","points":6},{"critere":"Pharos : contenus illicites ; 3018 : cyberharcèlement","points":4}],"dureeMin":7,"corrige":"1. Trois parmi : le **volume** (des millions de contenus par heure), la **vitesse** (la diffusion précède la vérification), le caractère **transnational** (une plateforme, des dizaines de droits nationaux), la modération par **algorithmes** et sous-traitants selon des **règles privées**, non votées.\n2. Sur ce qui **retient l'attention** (l'engagement), pas sur ce qui est vrai. **Bulle de filtres** : on ne voit plus que ce qui nous ressemble. **Chambre d'écho** : on croit que tout le monde pense comme soi.\n3. **LCEN (2004)** : les hébergeurs ne sont pas responsables a priori mais doivent **retirer promptement** un contenu manifestement illicite signalé. **RGPD (2018)** : l'usage des **données personnelles**, contrôlé par la **CNIL**. **Digital Services Act** (applicable depuis **2023-2024**) : transparence des algorithmes, analyse des risques, signalement facilité, audit indépendant pour les très grandes plateformes.\n4. **Pharos** : le signalement des **contenus illicites** en ligne. **3018** : le **cyberharcèlement**."}$exo$::jsonb),
  ('e0f45b58-fa55-5bca-80a1-99f073ef6717'::uuid, 2, 'redaction', $exo${"titre":"Le fil d'actualité de Hugo","consigne":"Lis la situation, puis réponds aux questions en t'appuyant sur le cours.","enonce":"**Situation (inventée).** Depuis qu'il a regardé quelques vidéos sur un sujet polémique, Hugo ne voit plus sur son fil que des vidéos du même avis, souvent indignées. Il en conclut que « tout le monde pense comme lui ». Un jour, il repère une vidéo qui menace de mort un journaliste ; il la signale à la plateforme, mais elle reste en ligne une semaine. Sa sœur Jade, elle, voit un de ses posts humoristiques, parfaitement légal, supprimé sans explication.\n\n1. Quels phénomènes décrits par le cours Hugo vit-il ? Explique leur lien avec les algorithmes de recommandation.\n2. Que devait faire la plateforme après le signalement de Hugo, selon la LCEN ? Où Hugo pouvait-il aussi signaler la vidéo ?\n3. Comment s'appelle ce qui est arrivé au post de Jade ? Pourquoi une régulation stricte peut-elle le favoriser ?\n4. Quelle question centrale ces deux cas posent-ils, selon le cours ?","bareme":[{"critere":"Bulle de filtres et chambre d'écho, algorithmes optimisés sur l'attention","points":6},{"critere":"Retrait prompt d'un contenu manifestement illicite signalé (LCEN) et Pharos","points":5},{"critere":"Surcensure : retrait préventif de contenus légaux par peur de l'amende","points":5},{"critere":"Qui décide, selon quelles règles, avec quel recours","points":4}],"dureeMin":11,"corrige":"1. Hugo vit une **bulle de filtres** (il ne voit plus que ce qui lui ressemble) et une **chambre d'écho** (il croit que tout le monde pense comme lui). Les **algorithmes de recommandation** ne choisissent pas ce qui est vrai mais ce qui **retient l'attention**, souvent ce qui **indigne** : ils lui proposent toujours plus du même contenu.\n2. Selon la **LCEN (2004)**, l'hébergeur n'est pas responsable a priori, mais doit **retirer promptement** un contenu **manifestement illicite** qui lui est signalé : une menace de mort l'est, la laisser une semaine est un manquement. Hugo pouvait aussi la signaler sur **Pharos**.\n3. C'est de la **surcensure** : une plateforme menacée d'amende retire **par précaution** des contenus **légaux**. Une régulation trop stricte pousse à supprimer dans le doute, selon des règles privées.\n4. La question centrale : **qui décide, selon quelles règles, et avec quel recours pour l'utilisateur ?** Le problème n'est pas seulement ce qui est publié, mais ce qui est **mis en avant**."}$exo$::jsonb),
  ('e0f45b58-fa55-5bca-80a1-99f073ef6717'::uuid, 3, 'redaction', $exo${"titre":"Trop ou trop peu réguler ?","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, avec des exemples précis du cours.","enonce":"**Document**\n\n> « Les réseaux sociaux sont des entreprises privées, régies par des conditions d'utilisation, qui organisent une part majeure du débat public. »\n\n**Sujet.** Faut-il réguler davantage les réseaux sociaux ? Tu montreras :\n1. pourquoi leur régulation est un problème inédit et difficile ;\n2. en quoi le fonctionnement des algorithmes pose un problème démocratique ;\n3. quels leviers juridiques et non juridiques existent (au moins deux de chaque) ;\n4. les risques d'un excès dans un sens comme dans l'autre, et la question centrale qui en découle.","bareme":[{"critere":"Problème inédit : entreprises privées, volume, vitesse, transnational, règles privées","points":4},{"critere":"Algorithmes : attention, indignation, bulle, chambre d'écho, faux plus rapide","points":4},{"critere":"Leviers juridiques (LCEN, DSA, RGPD) et autres (modération, éducation, fact-checking, signalement)","points":5},{"critere":"Surcensure contre haine et désinformation, question qui décide / quel recours","points":5},{"critere":"Paragraphe argumenté et organisé","points":2}],"dureeMin":18,"corrige":"1. **Un problème inédit** : des **entreprises privées** organisent le débat public selon leurs **conditions d'utilisation**. La régulation se heurte au **volume** (des millions de contenus par heure), à la **vitesse** (la diffusion précède la vérification), au caractère **transnational** et à une modération par algorithmes et sous-traitants, selon des **règles privées**, non votées.\n2. **Les algorithmes** ne choisissent pas le vrai mais ce qui **retient l'attention**, souvent ce qui indigne ; ils produisent **bulles de filtres** et **chambres d'écho**, et les contenus faux circulent en moyenne plus vite que les vrais. Le problème n'est pas seulement ce qui est publié, mais ce qui est **mis en avant**.\n3. **Leviers juridiques** : la **LCEN** (2004, retrait prompt du manifestement illicite signalé), le **Digital Services Act** (depuis 2023-2024 : transparence des algorithmes, analyse des risques, audit), le **RGPD** (2018, données personnelles, contrôle de la **CNIL**). **Autres leviers** : la **modération** par les plateformes, l'**éducation aux médias**, le **fact-checking**, le **signalement** (Pharos, 3018).\n4. **Le débat** : trop réguler, c'est risquer la **surcensure** (retrait par précaution de contenus légaux) ; trop peu, c'est laisser **haine et désinformation** prospérer. D'où la question centrale : **qui décide, selon quelles règles, et avec quel recours pour l'utilisateur ?**\n\n**Conclusion attendue** : une position nuancée et justifiée (réguler davantage mais avec transparence et recours, par exemple)."}$exo$::jsonb),
  ('fe688608-fb41-590d-80ef-5dbea17dfe23'::uuid, 1, 'redaction', $exo${"titre":"La Charte et ses principes","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. En quelle année la **Charte de l'environnement** a-t-elle été adossée à la Constitution ? Quelle est sa valeur ? Que proclame-t-elle ?\n2. Définis les quatre principes : **prévention**, **précaution**, **pollueur-payeur**, **participation**.\n3. Associe chaque date à son texte : 1992 ; 1998 ; 2015.","bareme":[{"critere":"2005, même valeur que la Déclaration de 1789, droit et devoir proclamés","points":6},{"critere":"Quatre principes définis exactement, prévention et précaution distinguées","points":8},{"critere":"Rio 1992, Aarhus 1998, accord de Paris et ODD 2015","points":6}],"dureeMin":7,"corrige":"1. En **2005**. Elle a la **même valeur que la Déclaration de 1789** (valeur constitutionnelle). Elle proclame le **droit** de vivre dans un environnement équilibré et respectueux de la santé, et le **devoir** de prendre part à sa préservation.\n2. **Prévention** : agir en amont pour éviter les atteintes **connues**. **Précaution** : face à un risque **incertain** mais grave et irréversible, prendre des mesures provisoires **sans attendre la certitude scientifique**. **Pollueur-payeur** : celui qui pollue supporte le coût de la réparation. **Participation** : chacun accède à l'information et participe aux décisions.\n3. **1992** : sommet de **Rio** (développement durable). **1998** : convention d'**Aarhus** (information, participation, accès à la justice). **2015** : **accord de Paris** (contenir le réchauffement bien en dessous de 2 °C) et **objectifs de développement durable** de l'ONU (cap commun à l'horizon 2030)."}$exo$::jsonb),
  ('fe688608-fb41-590d-80ef-5dbea17dfe23'::uuid, 2, 'redaction', $exo${"titre":"Quel principe s'applique ?","consigne":"Pour chaque situation, identifie le principe de la Charte en jeu et justifie par sa définition.","enonce":"**Situations (inventées)**\n\n- **A.** Une usine chimique a déversé des produits toxiques dans une rivière ; l'autorité exige qu'elle finance entièrement la dépollution.\n- **B.** Un nouveau pesticide pourrait, selon des études encore discutées, provoquer des dommages graves et irréversibles aux abeilles ; il est suspendu en attendant des résultats.\n- **C.** On sait qu'un carrefour pollué dépasse les seuils d'une substance dangereuse ; la ville y limite la circulation avant les pics de chaleur.\n- **D.** Avant la construction d'une route, les habitants reçoivent les études et peuvent donner leur avis.\n\n1. Nomme le principe en jeu dans chaque situation et justifie.\n2. Explique la différence entre les situations B et C.\n3. Dans l'Affaire du siècle (2021), qu'a reconnu la justice ? Pourquoi le cours dit-il que le contentieux climatique est devenu « un levier réel » ?","bareme":[{"critere":"A pollueur-payeur, B précaution, C prévention, D participation, chacun justifié","points":10},{"critere":"Différence risque connu / risque incertain","points":4},{"critere":"Responsabilité de l'État pour carence fautive, justice administrative, levier réel","points":6}],"dureeMin":11,"corrige":"1. **A. Pollueur-payeur** : celui qui pollue supporte le coût de la réparation. **B. Précaution** : le risque est **incertain** (études discutées) mais **grave et irréversible** ; on prend une mesure **provisoire** sans attendre la certitude scientifique. **C. Prévention** : le risque est **connu** (seuils dépassés) ; on agit en amont pour l'éviter. **D. Participation** : chacun accède à l'**information** et **participe** aux décisions.\n2. La **prévention** (C) vise un risque **connu** ; la **précaution** (B) vise un risque encore **incertain**. Ce ne sont pas la même chose.\n3. La **justice administrative** a reconnu la **responsabilité de l'État** pour **carence fautive** dans la lutte contre le changement climatique. Des décisions comparables ont été rendues aux Pays-Bas et en Allemagne : le juge peut obliger l'État à répondre de ses engagements, d'où un **levier réel** pour les citoyens et les associations."}$exo$::jsonb),
  ('fe688608-fb41-590d-80ef-5dbea17dfe23'::uuid, 3, 'redaction', $exo${"titre":"L'environnement entre dans le droit","consigne":"Rédige un développement organisé d'une vingtaine de lignes, avec des dates et des exemples précis.","enonce":"**Sujet.** « Le droit de l'environnement est récent, mais il est devenu un droit qui oblige vraiment. »\n\nMontre, en t'appuyant sur le cours :\n1. la naissance et la constitutionnalisation de ce droit (date, valeur, contenu de la Charte) ;\n2. les principes qui l'organisent, en distinguant soigneusement prévention et précaution ;\n3. son inscription dans des textes internationaux (au moins trois) ;\n4. qu'il oblige vraiment : le rôle du juge et le nouveau vocabulaire pénal.","bareme":[{"critere":"Années 1970, Charte de 2005, valeur constitutionnelle, droit et devoir","points":4},{"critere":"Quatre principes, prévention (connu) et précaution (incertain) distinguées","points":5},{"critere":"Trois textes internationaux datés (Rio, Aarhus, Paris, ODD)","points":4},{"critere":"Affaire du siècle 2021 et loi Climat et résilience 2021 (pollution des milieux, écocide)","points":5},{"critere":"Développement organisé et argumenté","points":2}],"dureeMin":20,"corrige":"1. **Un droit récent** : il naît dans les **années 1970**. En **2005**, la **Charte de l'environnement** est adossée à la Constitution, avec la **même valeur que la Déclaration de 1789**. Elle proclame un **droit** (vivre dans un environnement équilibré et respectueux de la santé) et un **devoir** (prendre part à sa préservation).\n2. **Quatre principes** : **prévention** (éviter les atteintes **connues**), **précaution** (face à un risque **incertain** mais grave et irréversible, agir sans attendre la certitude scientifique), **pollueur-payeur**, **participation**. Prévention et précaution ne se confondent pas : la première vise un risque connu, la seconde un risque incertain.\n3. **Textes internationaux** : **Rio (1992)**, le développement durable ; **Aarhus (1998)**, information, participation, accès à la justice ; **accord de Paris (2015)**, contenir le réchauffement bien en dessous de 2 °C ; **objectifs de développement durable** de l'ONU (2015), cap à l'horizon 2030.\n4. **Un droit qui oblige** : dans l'**Affaire du siècle (2021)**, la justice administrative reconnaît la responsabilité de l'État pour **carence fautive** ; des décisions comparables existent aux Pays-Bas et en Allemagne. La loi **Climat et résilience (2021)** crée un **délit général de pollution des milieux** et un délit d'**écocide** pour les atteintes les plus graves et durables, commises intentionnellement.\n\n**Conclusion attendue** : en une cinquantaine d'années, l'environnement est passé de préoccupation à norme constitutionnelle, contrôlée par le juge et sanctionnée pénalement."}$exo$::jsonb),
  ('3c245a26-2036-5157-80f5-622fb7cf9929'::uuid, 1, 'redaction', $exo${"titre":"Les trois piliers d'Aarhus","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Sur quelle idée repose la **démocratie environnementale** ?\n2. De quelle convention sont issus ses **trois piliers** ? Nomme-les.\n3. Cite trois **outils français** de participation et dis à quel moment ils interviennent.\n4. Qui composait la **Convention citoyenne pour le climat** ? Combien de propositions a-t-elle formulées ?","bareme":[{"critere":"Associer aux décisions ceux qui les subiront","points":4},{"critere":"Aarhus 1998 : information, participation, accès à la justice","points":6},{"critere":"Trois outils avec leur moment ou rôle exacts","points":6},{"critere":"150 citoyens tirés au sort, 149 propositions","points":4}],"dureeMin":7,"corrige":"1. Les décisions qui modifient durablement un territoire ou un climat doivent **associer ceux qui les subiront**.\n2. De la convention d'**Aarhus** (**1998**) : l'**accès à l'information** environnementale et compréhensible, la **participation** au processus décisionnel, l'**accès à la justice** pour contester une décision.\n3. Trois parmi : l'**enquête publique** (avant les grands projets), la **Commission nationale du débat public** (elle organise les débats sur les projets d'ampleur), l'**étude d'impact** (elle évalue les effets d'un aménagement), la **consultation en ligne** (pour réagir à un projet de décret), l'action des **associations agréées** (elles peuvent agir en justice).\n4. **150 citoyens tirés au sort** (2019-2020) ; elle a formulé **149 propositions**, dont une partie a nourri la loi Climat et résilience de 2021."}$exo$::jsonb),
  ('3c245a26-2036-5157-80f5-622fb7cf9929'::uuid, 2, 'redaction', $exo${"titre":"Le parc éolien de Saint-Aubin","consigne":"Lis la situation, puis réponds aux questions en t'appuyant sur le cours.","enonce":"**Situation (inventée).** Un parc éolien est prévu près de Saint-Aubin. Une enquête publique est ouverte : beaucoup d'habitants s'y opposent, mais le projet est finalement autorisé. Certains crient au « mépris de la démocratie ». Une association agréée de protection de l'environnement envisage un recours. Un groupe d'opposants propose, lui, de bloquer le chantier et de saboter les engins. Au lycée, Nour, éco-déléguée, veut organiser un débat sur le projet.\n\n1. Le projet peut-il être autorisé malgré une majorité d'avis défavorables à l'enquête publique ? Justifie par une phrase clé du cours.\n2. Que peut faire l'association agréée ? À quel pilier d'Aarhus cela correspond-il ?\n3. Le projet oppose-t-il deux intérêts légitimes ? Nomme une des tensions du cours qui s'applique.\n4. Que penser du projet de sabotage, selon le cours ?\n5. En quoi l'initiative de Nour correspond-elle à ce que demande le programme ?","bareme":[{"critere":"Participer n'est pas décider : la consultation éclaire sans remplacer la décision","points":5},{"critere":"Action en justice, pilier de l'accès à la justice","points":4},{"critere":"Tension pertinente identifiée et expliquée","points":4},{"critere":"Désobéissance civile : une cause n'exonère pas du respect de la loi","points":4},{"critere":"Engagement comme compétence à exercer (éco-délégués)","points":3}],"dureeMin":12,"corrige":"1. **Oui** : « **participer n'est pas décider** ». La consultation **éclaire** la décision, elle **ne la remplace pas** — et c'est là que naissent la plupart des conflits. L'enquête publique n'est pas un référendum.\n2. L'association agréée peut **agir en justice** pour contester l'autorisation : c'est le pilier de l'**accès à la justice**.\n3. **Oui**. Plusieurs tensions du cours peuvent s'appliquer : **propriété contre intérêt général** (des riverains et leur cadre de vie contre la production d'énergie), **urgence contre concertation** (agir vite pour le climat ou prendre le temps du débat), voire **emploi contre protection**. Une seule, bien expliquée, suffit.\n4. Le sabotage pose la question des limites de la **désobéissance civile** : **agir pour une cause n'exonère pas de la loi**. Les formes légales d'engagement existent : pétition, manifestation, action en justice, adhésion associative.\n5. Le programme fait de l'engagement une **compétence à exercer**, pas seulement une notion : les **éco-délégués**, les projets d'établissement et la semaine du développement durable en sont les moyens."}$exo$::jsonb),
  ('3c245a26-2036-5157-80f5-622fb7cf9929'::uuid, 3, 'redaction', $exo${"titre":"Décider ensemble, vraiment ?","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, avec des exemples précis du cours.","enonce":"**Document**\n\n> Deux avis sur la Convention citoyenne pour le climat : « Une expérience démocratique inédite » ; « Des promesses non tenues ».\n\n**Sujet.** La démocratie environnementale permet-elle vraiment de décider ensemble ? Tu montreras :\n1. ce qu'elle garantit (les trois piliers) et avec quels outils en France ;\n2. ce que fut la Convention citoyenne pour le climat, et pourquoi son bilan est débattu ;\n3. les formes d'engagement ouvertes au citoyen et leurs limites légales ;\n4. les tensions qui rendent la décision difficile.","bareme":[{"critere":"Trois piliers d'Aarhus et au moins trois outils français","points":5},{"critere":"Convention citoyenne : dates, 150 tirés au sort, mission, 149 propositions, loi de 2021, bilan débattu","points":5},{"critere":"Formes d'engagement et limite de la désobéissance civile","points":4},{"critere":"Tensions (emploi / protection, propriété / intérêt général, urgence / concertation) et « participer n'est pas décider »","points":4},{"critere":"Paragraphe argumenté et nuancé","points":2}],"dureeMin":18,"corrige":"1. **Ce qu'elle garantit** : issus de la convention d'**Aarhus (1998)**, l'**accès à l'information**, la **participation** au processus décisionnel, l'**accès à la justice**. En France : **enquête publique**, **Commission nationale du débat public**, **étude d'impact**, **consultation en ligne**, action des **associations agréées**.\n2. **La Convention citoyenne pour le climat** (**2019-2020**) : **150 citoyens tirés au sort**, chargés de proposer des mesures de réduction des émissions dans un esprit de justice sociale ; **149 propositions**, dont une partie a nourri la **loi Climat et résilience de 2021**. Bilan **débattu** : expérience démocratique inédite pour les uns, promesses non tenues pour les autres, car toutes les propositions n'ont pas été reprises.\n3. **L'engagement** : vote, engagement politique, adhésion associative, bénévolat, **pétition**, **manifestation**, consommation responsable, lancement d'alerte, **action en justice**. Limite : occupations, blocages, dégradations posent la question de la **désobéissance civile** ; agir pour une cause n'exonère pas de la loi.\n4. **Les tensions** : **emploi contre protection** (deux intérêts légitimes), **propriété contre intérêt général** (deux droits), **urgence contre concertation** (deux temporalités). Surtout, « **participer n'est pas décider** » : la consultation éclaire la décision sans la remplacer.\n\n**Conclusion attendue** : la démocratie environnementale associe davantage les citoyens, mais la décision finale reste aux autorités ; d'où les conflits et le bilan débattu."}$exo$::jsonb),
  ('88781286-2838-5796-be60-916c0bb0de6d'::uuid, 1, 'redaction', $exo${"titre":"Ni chose, ni personne","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Associe chaque date à son texte et à ce qu'il pose : **1850**, **1976**, **2015**.\n2. Que dit l'**article 515-14** du Code civil ? L'animal est-il pour autant une personne ?\n3. Définis le **welfarisme** et l'**antispécisme**.\n4. Que régule la convention **CITES** (1973) ? Qu'est-ce que le réseau **Natura 2000** ?","bareme":[{"critere":"Loi Grammont 1850, être sensible 1976, Code civil 2015","points":6},{"critere":"Article 515-14 cité, animal soumis au régime des biens, catégorie intermédiaire","points":5},{"critere":"Welfarisme et antispécisme définis exactement","points":5},{"critere":"CITES : commerce des espèces menacées ; Natura 2000 : sites protégés","points":4}],"dureeMin":7,"corrige":"1. **1850**, loi **Grammont** : elle punit les mauvais traitements infligés **publiquement** aux animaux domestiques. **1976** : une loi reconnaît l'animal comme **être sensible**. **2015** : l'**article 515-14 du Code civil**.\n2. « **Les animaux sont des êtres vivants doués de sensibilité** » — mais ils restent **soumis au régime des biens**. L'animal n'est plus un meuble, mais **pas une personne** : le droit a créé une **catégorie intermédiaire**.\n3. **Welfarisme** : réduire la souffrance animale, **sans remettre en cause l'usage** des animaux. **Antispécisme** : contester la légitimité même d'une **hiérarchie morale entre les espèces**.\n4. La **CITES** (convention de Washington, 1973) régule le **commerce international des espèces menacées**. **Natura 2000** est un réseau européen de **sites naturels protégés**."}$exo$::jsonb),
  ('88781286-2838-5796-be60-916c0bb0de6d'::uuid, 2, 'redaction', $exo${"titre":"Quatre positions autour d'une table","consigne":"Lis le document, puis réponds aux questions en t'appuyant sur le cours.","enonce":"**Document – Un débat organisé en classe (propos inventés)**\n\n> **Inès** : « Je mange de la viande, mais je veux que les élevages et les abattoirs réduisent au maximum la souffrance des bêtes. »\n> **Théo** : « Certains animaux devraient avoir des droits fondamentaux, comme ne pas être tués pour notre usage. »\n> **Mona** : « Placer l'humain au-dessus des autres espèces n'a aucune justification morale. »\n> **Paul** : « La chasse et l'élevage font partie de nos traditions et font vivre des régions entières. »\n\n1. Associe chaque élève à une position du débat philosophique présenté dans le cours. Justifie.\n2. Quelle règle de droit, depuis 2021, pourrait citer Inès pour montrer que la loi va dans son sens ? Donne deux exemples.\n3. Mona propose d'interdire toute régulation des sangliers. En t'appuyant sur la « tension à assumer » du cours, explique pourquoi protéger l'animal et protéger l'espèce peuvent s'opposer.","bareme":[{"critere":"Inès welfarisme, Théo droits des animaux (Regan), Mona antispécisme, Paul continuité des usages, justifiés","points":8},{"critere":"Loi de 2021 : sanctions aggravées, vente en ligne encadrée, fin progressive du cirque itinérant et des delphinariums","points":6},{"critere":"Tension animal individuel / espèce expliquée avec la régulation d'une espèce","points":6}],"dureeMin":12,"corrige":"1. **Inès : welfarisme** — réduire la souffrance sans remettre en cause l'usage. **Théo : droits des animaux** (Tom Regan) — reconnaître des droits fondamentaux à certains animaux. **Mona : antispécisme** — contester la légitimité même de la hiérarchie entre espèces. **Paul : continuité des usages** — défendre élevage et chasse au nom de traditions et d'équilibres économiques.\n2. La **loi de 2021** contre la maltraitance animale : **sanctions aggravées** contre les sévices graves, actes de cruauté et abandon ; **vente en ligne encadrée** ; **fin progressive** des animaux sauvages en **cirque itinérant** et des **delphinariums**. Le bien-être en élevage, transport et abattoir relève largement du droit européen.\n3. **Protéger un animal individuel** et **protéger une espèce** ou un milieu ne demandent pas les mêmes règles et peuvent **s'opposer** : réguler une population (par exemple une espèce invasive, dit le cours) sacrifie des individus pour préserver d'autres espèces et les équilibres d'un milieu. Interdire toute régulation protégerait chaque animal, mais pourrait nuire à la biodiversité."}$exo$::jsonb),
  ('88781286-2838-5796-be60-916c0bb0de6d'::uuid, 3, 'redaction', $exo${"titre":"Quels droits pour les animaux ?","consigne":"Rédige un développement organisé d'une vingtaine de lignes, avec des dates et des exemples précis.","enonce":"**Sujet.** « L'animal n'est plus un meuble, mais il n'est pas une personne : le droit lui a créé une catégorie intermédiaire, et personne ne s'accorde sur ce qu'elle devrait devenir. »\n\nExplique cette affirmation. Tu montreras :\n1. comment le statut juridique de l'animal a évolué (trois dates) ;\n2. ce que la loi protège aujourd'hui ;\n3. pourquoi ce statut reste discuté (les positions du débat) ;\n4. comment le droit protège aussi les animaux sauvages et la biodiversité, et la tension que cela crée.","bareme":[{"critere":"1850 (Grammont), 1976 (être sensible), 2015 (article 515-14, régime des biens)","points":5},{"critere":"Protections actuelles : sévices, cruauté, abandon, loi de 2021, droit européen","points":4},{"critere":"Quatre positions du débat philosophique exposées","points":4},{"critere":"Instruments de protection de la biodiversité et tension individu / espèce","points":5},{"critere":"Développement organisé et argumenté","points":2}],"dureeMin":20,"corrige":"1. **L'évolution du statut** : longtemps rangé parmi les biens, l'animal est protégé en **1850** par la loi **Grammont** (mauvais traitements infligés **publiquement** aux animaux domestiques) ; en **1976**, la loi le reconnaît comme **être sensible** ; en **2015**, l'**article 515-14 du Code civil** dispose que « les animaux sont des êtres vivants doués de sensibilité », tout en restant **soumis au régime des biens**. Ni meuble ni personne : une **catégorie intermédiaire**.\n2. **Ce que la loi protège** : **sévices graves**, **actes de cruauté**, **abandon** sont punis par le Code pénal, avec des peines aggravées par la loi de **2021**, qui encadre aussi la vente en ligne et interdit progressivement les animaux sauvages en cirque itinérant et les delphinariums. Le **bien-être animal** en élevage, transport et abattoir relève largement du **droit européen**.\n3. **Un statut discuté** : le **welfarisme** veut réduire la souffrance sans remettre en cause l'usage ; les **droits des animaux** (Tom Regan) veulent des droits fondamentaux pour certains animaux ; l'**antispécisme** conteste la hiérarchie entre espèces ; la **continuité des usages** défend élevage, chasse et recherche (traditions, économie, statut particulier de l'humain).\n4. **Animaux sauvages et biodiversité** : la **CITES** (1973) régule le commerce des espèces menacées ; les directives **Oiseaux** et **Habitats** protègent espèces et milieux ; le réseau **Natura 2000** des sites ; les **listes rouges** de l'UICN mesurent l'état des espèces ; l'**Office français de la biodiversité** assure police et expertise. **Tension** : protéger un animal individuel et protéger une espèce peuvent s'opposer, par exemple lors de la régulation d'une espèce invasive.\n\n**Conclusion attendue** : un statut en mouvement, entre protection croissante et désaccord de fond sur sa finalité."}$exo$::jsonb),
  ('00ce64fb-084e-5285-93f2-e8883a782347'::uuid, 1, 'redaction', $exo${"titre":"Les piliers de la laïcité","consigne":"Réponds à chaque question en phrases complètes.","enonce":"1. La laïcité est-elle une croyance ? Définis-la en une phrase.\n2. Cite et explique les **trois piliers** de la laïcité.\n3. Quelles sont les **deux faces** de la loi de 1905 ?\n4. Qui est tenu à la **neutralité religieuse** : les agents publics ou les usagers ? Précise dans quel cadre.","bareme":[{"critere":"Principe d’organisation de l’État, pas une croyance","points":4},{"critere":"Trois piliers cités et expliqués","points":6},{"critere":"Libre exercice des cultes et neutralité de l’État","points":5},{"critere":"Agents publics dans l’exercice de leurs fonctions ; usagers libres","points":5}],"dureeMin":7,"corrige":"1. Non. La laïcité n’est pas une croyance : c’est un **principe d’organisation de l’État**.\n\n2. Les trois piliers :\n- la **liberté de conscience** : croire, ne pas croire, changer, pratiquer ou non ;\n- la **séparation** : l’État ne reconnaît, ne salarie ni ne subventionne aucun culte ;\n- l’**égalité** : tous les citoyens sont égaux devant la loi, quelle que soit leur croyance.\n\n3. La loi de 1905 garantit à la fois le **libre exercice des cultes** et la **neutralité de l’État** : ce sont les deux faces du même texte.\n\n4. Ce sont les **agents publics** (enseignants, policiers, employés de mairie) qui doivent la neutralité, **dans l’exercice de leurs fonctions** (pas dans leur vie privée). Les **usagers** d’un service public sont **libres**, sauf exception prévue par la loi."}$exo$::jsonb),
  ('00ce64fb-084e-5285-93f2-e8883a782347'::uuid, 2, 'redaction', $exo${"titre":"Qui peut porter quoi, et où ?","consigne":"Pour chaque situation, dis si le port du signe religieux est autorisé et justifie avec le cours.","enonce":"**Situations.**\n\n- **A.** Amira, élève de 3e dans un collège public, veut venir en cours avec un grand voile.\n- **B.** Sa sœur Leïla, étudiante à l’université, porte le même voile en amphithéâtre.\n- **C.** M. Levy, professeur de mathématiques au collège public, souhaite porter une kippa pendant ses cours.\n- **D.** Paul porte une grande croix en pendentif dans la rue et à la mairie, où il vient chercher un papier.\n- **E.** Élise est élève dans un lycée privé sous contrat et porte une croix visible.\n\n1. Pour chaque situation, indique si c’est autorisé et pourquoi.\n2. Quelle loi s’applique dans la situation A ? Donne sa date exacte.","bareme":[{"critere":"A interdit (élève d’établissement public, signe ostensible)","points":4},{"critere":"B et E autorisés (université, privé sous contrat hors loi de 2004)","points":4},{"critere":"C interdit : agent public neutre dans ses fonctions","points":4},{"critere":"D autorisé : usager et espace public libres","points":4},{"critere":"Loi du 15 mars 2004 citée","points":4}],"dureeMin":10,"corrige":"1.\n- **A** : **interdit**. Dans les écoles, collèges et lycées **publics**, les signes religieux **ostensibles** sont interdits **aux élèves**.\n- **B** : **autorisé**. La loi de 2004 ne s’applique **pas à l’université**.\n- **C** : **interdit**. M. Levy est un **agent public** : il doit être **neutre dans l’exercice de ses fonctions** (il reste libre dans sa vie privée).\n- **D** : **autorisé**. On peut porter un signe religieux **dans la rue** ; à la mairie, Paul est un **usager**, et les usagers sont libres.\n- **E** : **autorisé**. La loi de 2004 ne s’applique pas aux **établissements privés sous contrat**.\n\n2. La **loi du 15 mars 2004**, qui interdit les signes religieux ostensibles aux élèves des écoles, collèges et lycées publics."}$exo$::jsonb),
  ('00ce64fb-084e-5285-93f2-e8883a782347'::uuid, 3, 'redaction', $exo${"titre":"La laïcité, contre les religions ?","consigne":"Lis le document, réponds aux questions puis rédige un paragraphe argumenté.","enonce":"**Document — Un commentaire lu sur un forum**\n\n> « La laïcité, c’est l’athéisme officiel de la France : l’État veut faire disparaître les religions de l’espace public. D’ailleurs, c’est pareil partout en France. »\n\n1. Relève dans ce commentaire **trois affirmations fausses** et corrige chacune avec le cours.\n2. Quelle est la première face de la loi de 1905, souvent oubliée ?\n3. Explique l’exception de l’**Alsace-Moselle** : pourquoi existe-t-elle et que permet-elle ?\n4. **Paragraphe argumenté** (une dizaine de lignes) : explique la phrase du cours « La laïcité ne protège pas la République contre les religions. Elle protège chaque croyant du pouvoir des autres croyances — et l’incroyant de toutes. »","bareme":[{"critere":"Trois affirmations fausses corrigées (athéisme, effacement, uniformité)","points":6},{"critere":"Libre exercice des cultes cité","points":2},{"critere":"Alsace-Moselle : allemande en 1905, Concordat, cultes reconnus","points":4},{"critere":"Paragraphe : liberté de conscience et égalité reliées à la protection de chacun","points":5},{"critere":"Paragraphe : rôle de la séparation et de la neutralité de l’État","points":3}],"dureeMin":17,"corrige":"1.\n- « L’athéisme officiel » : faux. **L’État n’a pas d’opinion sur Dieu** ; la laïcité n’est pas l’athéisme d’État.\n- « Faire disparaître les religions de l’espace public » : faux. On peut **porter un signe religieux dans la rue**, exprimer sa foi, se réunir. Seuls les agents publics (dans leurs fonctions) et, par la loi de 2004, les élèves des établissements publics ont des obligations.\n- « Pareil partout en France » : faux. En **Alsace-Moselle**, le **Concordat** est toujours en vigueur.\n\n2. Le **libre exercice des cultes** (l’autre face étant la neutralité de l’État).\n\n3. En 1905, l’Alsace-Moselle était **allemande** : la loi de séparation ne s’y est pas appliquée. Le **Concordat** y est toujours en vigueur : **certains cultes sont reconnus** et des **enseignements religieux** sont organisés. La laïcité française n’est donc pas parfaitement uniforme.\n\n4. Paragraphe attendu :\n- la laïcité garantit la **liberté de conscience** : chacun peut croire, ne pas croire, changer de religion ;\n- par la **séparation**, l’État ne soutient aucun culte : aucune religion ne peut se servir de l’État pour s’imposer aux autres ; c’est ce qui protège **chaque croyant du pouvoir des autres croyances** ;\n- l’incroyant est protégé lui aussi : aucune croyance ne peut lui être imposée ;\n- l’**égalité** devant la loi, quelle que soit la croyance, et la **neutralité** des agents publics assurent que chacun est traité de la même façon ;\n- conclusion : la laïcité n’est pas une arme contre les religions mais un **mode d’organisation** qui vise l’égalité et la liberté de tous."}$exo$::jsonb)
) AS v (chapter_id, difficulte, style, contenu)
JOIN public.chapters c ON c.id = v.chapter_id
ON CONFLICT (id) DO UPDATE
  SET style      = EXCLUDED.style,
      contenu    = EXCLUDED.contenu,
      difficulte = EXCLUDED.difficulte,
      origine    = 'catalogue';

DO $$
DECLARE
  n INT;
BEGIN
  SELECT count(*) INTO n
